-- =============================================================================
-- 404 — LE CATALOGUE DES CONTRÔLES BLANCS : 2de (espagnol, francais, grec, histoire-geo, latin)
--
-- 357 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 404 --niveau 2de --matieres espagnol,francais,grec,histoire-geo,latin
--
--   espagnol.11r                  9 sujets · 3 fiches
--   espagnol.jumelles           102 sujets · 34 fiches
--   espagnol.m1                  36 sujets · 12 fiches
--   francais.16ra                36 sujets · 12 fiches
--   francais.16rb                33 sujets · 11 fiches
--   francais.jumelles             3 sujets · 1 fiches
--   grec.15r                      9 sujets · 3 fiches
--   histoire-geo.14a             45 sujets · 15 fiches
--   histoire-geo.14ra            24 sujets · 8 fiches
--   histoire-geo.14rb            21 sujets · 7 fiches
--   histoire-geo.15ra            15 sujets · 5 fiches
--   histoire-geo.15rb            15 sujets · 5 fiches
--   latin.15r                     9 sujets · 3 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('794c4be9-76d7-57d8-990b-ad3c6a37a92b'::uuid, 1, 'traduction', $exo${"titre":"Indefinido, imperfecto ou perfecto ?","consigne":"Conjugue chaque verbe au temps du passé qui convient, en t'appuyant sur le marqueur de temps.","enonce":"**Conjugue le verbe entre parenthèses.**\n\n1. Ayer yo (comer) ___ paella con mis padres.\n2. Cuando era pequeña, mi hermana (jugar) ___ al fútbol todos los días.\n3. Hoy nosotros (estudiar) ___ mucho.\n4. En 2019, mis tíos (viajar) ___ a México.\n5. Antes, mi abuelo (ser) ___ profesor.\n6. Esta semana, Lucía (terminar) ___ su libro.","bareme":[{"critere":"Temps juste choisi d'après le marqueur (indefinido, imperfecto, perfecto)","points":12},{"critere":"Terminaisons et formes correctes (dont era, he/ha + participe)","points":8}],"dureeMin":7,"corrige":"1. *Ayer yo **comí** paella.* — *ayer* coupe du présent → **indefinido**.\n2. *Mi hermana **jugaba** al fútbol todos los días.* — habitude passée → **imperfecto**.\n3. *Hoy nosotros **hemos estudiado** mucho.* — *hoy*, passé relié au présent → **perfecto** (*haber* au présent + participe).\n4. *En 2019, mis tíos **viajaron** a México.* — date → **indefinido** (-aron).\n5. *Antes, mi abuelo **era** profesor.* — description, habitude → **imperfecto** ; *ser* est irrégulier (*era*).\n6. *Esta semana, Lucía **ha terminado** su libro.* — *esta semana* → **perfecto**."}$exo$::jsonb),
  ('794c4be9-76d7-57d8-990b-ad3c6a37a92b'::uuid, 2, 'traduction', $exo${"titre":"Una tarde de tormenta","consigne":"Complète le récit avec l'imperfecto ou l'indefinido, puis justifie deux de tes choix en français.","enonce":"**1. Complète le récit.**\n\n> Era sábado. (Llover) ___ mucho y mis padres (ver) ___ la televisión. Yo (leer) ___ un cómic cuando, de repente, (sonar) ___ el teléfono. Mi prima Carmen (llegar) ___ a casa media hora después y todos (cenar) ___ juntos.\n\n**2.** Justifie le temps choisi pour *(llover)* et pour *(sonar)*.\n\n**3. Traduis :** « Hier, je suis sorti avec mes amis. » puis « Aujourd'hui, je suis sorti avec mes amis. »","bareme":[{"critere":"Décor à l'imperfecto (llovía, veían, leía)","points":6},{"critere":"Événements à l'indefinido (sonó, llegó, cenamos)","points":6},{"critere":"Justification décor / événement","points":4},{"critere":"Traductions : salí / he salido","points":4}],"dureeMin":11,"corrige":"**1.** *Era sábado. **Llovía** mucho y mis padres **veían** la televisión. Yo **leía** un cómic cuando, de repente, **sonó** el teléfono. Mi prima Carmen **llegó** a casa media hora después y todos **cenamos** juntos.*\n\n- *veían* : *ver* est l'un des trois irréguliers de l'imparfait.\n- *cenamos* : *todos* inclut le narrateur → nous (*cenaron* accepté si l'élève exclut le narrateur).\n\n**2.** *Llovía* : c'est le **décor**, ce qui durait → imperfecto. *Sonó* : l'**événement** qui survient et rompt le décor (*de repente*) → indefinido.\n\n**3.** *Ayer salí con mis amigos.* — *ayer* coupe du présent → indefinido (jamais *ayer he salido*).\n*Hoy he salido con mis amigos.* — *hoy* relie au présent → perfecto."}$exo$::jsonb),
  ('794c4be9-76d7-57d8-990b-ad3c6a37a92b'::uuid, 3, 'traduction', $exo${"titre":"Mi primer día en el instituto","consigne":"Rédige un récit en espagnol, puis réponds aux questions d'analyse en français.","enonce":"**1. Production (70 à 90 mots).** Raconte en espagnol ton premier jour au lycée (réel ou inventé). Tu dois employer :\n- au moins **trois** verbes à l'imperfecto pour le décor (dont un des trois irréguliers : *ser, ir, ver*) ;\n- au moins **trois** verbes à l'indefinido pour les événements ;\n- **une** phrase au pretérito perfecto avec *hoy* ou *esta semana*, pour faire le lien avec aujourd'hui ;\n- un marqueur de chaque temps.\n\n**2.** Recopie une phrase de ton texte où le décor est interrompu par un événement et explique la répartition des temps.\n\n**3.** Un camarade a écrit : *El año pasado he visitado Madrid y era muy bonito. Un día fui al museo y vi un cuadro.* Relève l'erreur, corrige-la et explique-la.","bareme":[{"critere":"Trois imperfectos justes pour le décor, dont un irrégulier","points":5},{"critere":"Trois indefinidos justes pour les événements","points":5},{"critere":"Perfecto correct (haber + participe) relié au présent","points":3},{"critere":"Analyse de la phrase décor / événement","points":3},{"critere":"Erreur du camarade corrigée et expliquée","points":4}],"dureeMin":18,"corrige":"**1. Exemple de récit attendu**\n\n> *El primer día de clase, hacía sol y yo estaba muy nervioso. El instituto era enorme y había muchos alumnos que no conocía. Mientras buscaba mi clase, una chica me habló y me ayudó. Se llamaba Ana. A las ocho, el profesor llegó y nos presentó el programa. Por la tarde, volví a casa muy contento. Hoy, Ana y yo hemos comido juntos en la cantina: ¡es mi mejor amiga!*\n\nÀ vérifier : imperfecto (*hacía, estaba, era, buscaba, conocía*) ; indefinido (*habló, ayudó, llegó, presentó, volví*) ; perfecto (*hemos comido*) avec *hoy* ; marqueurs (*el primer día, mientras, hoy*).\n\n**2.** *Mientras buscaba mi clase, una chica me habló* : *buscaba* (imperfecto) plante le **décor**, l'action en cours ; *habló* (indefinido) est l'**événement** qui survient. Inverser les temps raconterait autre chose.\n\n**3.** *El año pasado he visitado* → *El año pasado **visité** Madrid.* *El año pasado* situe l'action dans un passé coupé du présent : il faut l'**indefinido** ; le perfecto est réservé à ce qui touche encore au présent (*hoy, esta semana, ya*). Le reste est juste : *era muy bonito* (description → imperfecto), *fui* et *vi* (événements → indefinido)."}$exo$::jsonb),
  ('8eafb2f8-b2cd-58a7-9796-3dd902c65eef'::uuid, 1, 'traduction', $exo${"titre":"Ser ou estar ?","consigne":"Complète chaque phrase avec ser ou estar conjugué au présent, puis corrige l'erreur de la question 2.","enonce":"**1. Complète avec ser ou estar au présent.**\n\n1. Mi madre ___ médica.\n2. Hoy nosotros ___ muy cansados.\n3. Sevilla ___ en Andalucía.\n4. Pablo ___ de Colombia.\n5. ___ las cinco de la tarde.\n6. La sopa ___ fría: la tengo que calentar.\n\n**2. Corrige :** *Me gusta las películas de terror.*","bareme":[{"critere":"Choix juste de ser / estar dans les six phrases","points":12},{"critere":"Conjugaison au présent correcte","points":4},{"critere":"Correction : me gustan (accord avec ce qui plaît)","points":4}],"dureeMin":7,"corrige":"**1.**\n1. *Mi madre **es** médica.* — profession → *ser*.\n2. *Hoy nosotros **estamos** muy cansados.* — état passager → *estar*.\n3. *Sevilla **está** en Andalucía.* — localisation → *estar*.\n4. *Pablo **es** de Colombia.* — origine → *ser*.\n5. ***Son** las cinco de la tarde.* — l'heure → *ser* (pluriel : *son las cinco*).\n6. *La sopa **está** fría.* — résultat d'un changement (elle a refroidi) → *estar*.\n\n**2.** *Me **gustan** las películas de terror.* *Gustar* s'accorde avec **ce qui plaît** (*las películas*, pluriel), pas avec la personne."}$exo$::jsonb),
  ('8eafb2f8-b2cd-58a7-9796-3dd902c65eef'::uuid, 2, 'traduction', $exo${"titre":"La presentación de Martina","consigne":"Traduis la présentation en espagnol, puis réponds à la question 2.","enonce":"**1. Thème : traduis en espagnol.**\n\n> Je m'appelle Martina, je suis argentine et je suis étudiante. J'étudie le français depuis deux ans. Aujourd'hui, je suis à Paris et je suis très contente. Dans ma chambre, il y a deux lits. J'aime beaucoup les musées, mais je n'aime pas le métro.\n\n*Aide : étudiante = estudiante ; musée = museo ; lit = cama.*\n\n**2.** Explique la différence de sens entre *Martina es aburrida* et *Martina está aburrida*.","bareme":[{"critere":"Ser pour l'origine et la profession, estar pour le lieu et l'humeur","points":6},{"critere":"Hace dos años que estudio et hay invariable","points":5},{"critere":"Gustar construit et accordé (me gustan los museos, no me gusta el metro)","points":5},{"critere":"Différence ser aburrido / estar aburrido expliquée","points":4}],"dureeMin":11,"corrige":"**1. Traduction modèle**\n\n> *Me llamo Martina, soy argentina y soy estudiante. Hace dos años que estudio francés. Hoy estoy en París y estoy muy contenta. En mi habitación hay dos camas. Me gustan mucho los museos, pero no me gusta el metro.*\n\nAcceptés : *Estudio francés desde hace dos años* ; *mi cuarto*.\n\n**Points attendus** : *soy argentina* (origine), *soy estudiante* (profession) → *ser* ; *estoy en París* (localisation), *estoy contenta* (humeur) → *estar* ; *hace dos años que* + présent ; *hay* invariable même au pluriel ; *me gustan los museos* (pluriel) mais *no me gusta el metro* (singulier).\n\n**2.** *Martina es aburrida* : c'est ce qu'elle **est**, sa nature — elle est **ennuyeuse**. *Martina está aburrida* : c'est **comment elle va** — elle **s'ennuie** en ce moment. Le verbe change le sens, pas seulement le style."}$exo$::jsonb),
  ('8eafb2f8-b2cd-58a7-9796-3dd902c65eef'::uuid, 3, 'traduction', $exo${"titre":"El restaurante de la abuela","consigne":"Lis le texte, corrige les erreurs et explique chaque choix, puis rédige une courte suite en espagnol.","enonce":"**Voici le texte d'un élève :**\n\n> *Mi abuela está de Valencia. Es muy simpática y es cocinera. Su restaurante es en el centro. Hoy es enferma: está mala. Ayer comí su paella: ¡era muy rica! Me gusta mucho sus platos. En el restaurante hay muchas mesas y hace cuarenta años que lo tiene.*\n\n1. Relève les **quatre** erreurs, corrige-les et justifie chaque correction.\n2. Dans la phrase *¡era muy rica!*, le verbe est-il bien choisi ? Qu'aurait signifié l'autre verbe ?\n3. Écris une suite de **quatre** phrases en espagnol sur le restaurant, qui emploient : *ser* pour une caractéristique, *estar* pour un état passager, *hay*, et *gustar* au pluriel.","bareme":[{"critere":"Quatre erreurs repérées et corrigées","points":6},{"critere":"Justification de chaque correction par la règle","points":5},{"critere":"Analyse de era rica / estaba rica","points":3},{"critere":"Quatre phrases de suite justes et conformes aux contraintes","points":6}],"dureeMin":18,"corrige":"**1. Les quatre erreurs**\n1. *está de Valencia* → ***es** de Valencia* : l'origine → *ser*.\n2. *Su restaurante es en el centro* → ***está** en el centro* : la localisation → *estar*.\n3. *Hoy es enferma* → *Hoy **está** enferma* : un état passager → *estar*. (*está mala* est juste : « elle est malade ».)\n4. *Me gusta mucho sus platos* → *Me **gustan** mucho sus platos* : *gustar* s'accorde avec ce qui plaît, ici pluriel.\n\nSont justes : *es simpática*, *es cocinera* (caractère, profession), *hay muchas mesas* (invariable), *hace cuarenta años que lo tiene* (temps écoulé).\n\n**2.** L'élève parle de la paella qu'il a goûtée : il faut ***estaba** muy rica* (« elle était délicieuse ») — *estar rico* = être délicieux. *Ser rico* signifie « être riche » : *era muy rica* serait un contresens. On accepte que l'élève explique que *ser* décrit une nature et *estar* un état constaté.\n\n**3. Exemple de suite**\n> *El restaurante es muy antiguo. Hoy está lleno de turistas. Hay una terraza con flores. A los clientes les gustan los postres de mi abuela.*\n\nToute phrase juste qui respecte chaque contrainte est acceptée."}$exo$::jsonb),
  ('edd32eaf-5f53-54c3-bf0f-641af757fff8'::uuid, 1, 'traduction', $exo${"titre":"Repères du monde hispanique","consigne":"Réponds en français, en une ou deux phrases pour chaque question.","enonce":"1. Combien de personnes environ parlent espagnol dans le monde, et quelle place cette langue occupe-t-elle parmi les langues maternelles ?\n2. Qu'est-ce que le *voseo* ? Donne un pays où on l'emploie et un exemple. Est-ce une faute ?\n3. Donne les dates de la guerre civile espagnole et de la fin du franquisme.\n4. Associe chaque œuvre ou courant à son auteur : *Guernica* ; *Don Quijote* ; le réalisme magique.","bareme":[{"critere":"Chiffres et place de l'espagnol exacts ; voseo défini avec pays et exemple, norme régionale","points":10},{"critere":"Dates justes et associations œuvres / auteurs justes","points":10}],"dureeMin":7,"corrige":"1. Plus de **500 millions** de personnes, dans une vingtaine de pays ; c'est la **deuxième langue maternelle du monde**.\n2. Le *voseo* consiste à employer *vos* à la place de *tú* : *vos tenés* au lieu de *tú tienes*. On l'emploie en **Argentine**, en Uruguay, en Amérique centrale. Ce n'est **pas une faute** : c'est une **norme régionale**.\n3. Guerre civile : **1936-1939** ; le franquisme dure de 1939 à **1975**, date de la mort de Franco et de la fin du régime ; puis vient la *transición* (Constitution de 1978).\n4. *Guernica* → **Picasso** ; *Don Quijote* → **Cervantes** ; le réalisme magique → **García Márquez**."}$exo$::jsonb),
  ('edd32eaf-5f53-54c3-bf0f-641af757fff8'::uuid, 2, 'traduction', $exo${"titre":"Mémoire et démocratie","consigne":"Lis le document, puis réponds aux questions en français en t'appuyant sur le texte et sur tes connaissances.","enonce":"**Document (texte inventé, inspiré de témoignages)**\n\n> *Todos los jueves, desde 1977, unas mujeres con pañuelos blancos caminan en la Plaza de Mayo, en Buenos Aires. Sus hijos desaparecieron durante la dictadura. Hoy, algunas de ellas son muy mayores, pero siguen caminando: no quieren olvidar.*\n\n*Aide : pañuelo = foulard ; desaparecer = disparaître ; seguir + gérondif = continuer à.*\n\n1. Traduis la première phrase du document.\n2. Qui sont ces femmes et à quelle période de l'histoire argentine le texte renvoie-t-il (dates) ?\n3. Cite une autre dictature d'Amérique latine et une dictature en Espagne, avec leurs dates.\n4. À quel axe du programme ce document se rattache-t-il ? Justifie en une phrase.","bareme":[{"critere":"Traduction juste de la première phrase","points":5},{"critere":"Madres de Plaza de Mayo et dictature argentine 1976-1983 identifiées","points":6},{"critere":"Pinochet 1973-1990 et franquisme 1939-1975 exacts","points":5},{"critere":"Axe mémoire identifié et justifié","points":4}],"dureeMin":12,"corrige":"1. « Tous les jeudis, depuis 1977, des femmes portant des foulards blancs marchent sur la place de Mai, à Buenos Aires. » (*avec des foulards blancs* accepté.)\n\n2. Ce sont les ***Madres de Plaza de Mayo*** : des mères dont les enfants ont **disparu** pendant la **dictature argentine (1976-1983)**. Elles marchent pour réclamer la vérité sur leurs enfants.\n\n3. Au Chili, la **dictature de Pinochet (1973-1990)**. En Espagne, le **franquisme (1939-1975)**, après la guerre civile (1936-1939), suivi de la *transición* et de la Constitution de 1978.\n\n4. L'axe **mémoire** (et démocratie / citoyenneté accepté) : le texte montre des femmes qui refusent l'oubli (*no quieren olvidar*) et entretiennent le souvenir des victimes d'une dictature."}$exo$::jsonb),
  ('edd32eaf-5f53-54c3-bf0f-641af757fff8'::uuid, 3, 'traduction', $exo${"titre":"Una lengua, muchas voces","consigne":"Rédige en espagnol un court texte argumenté, puis réponds en français à la question d'analyse.","enonce":"**Situation.** Ton correspondant Diego, de Buenos Aires, t'écrit :\n\n> *En mi clase de Madrid, un compañero se ríe de mí porque digo « vos tenés » y « carro ». Dice que hablo mal español. ¿Qué piensas tú?*\n\n1. Réponds à Diego en espagnol (70 à 90 mots). Tu dois :\n- expliquer ce qu'est le *voseo* et dire qu'il n'est pas une faute ;\n- citer une autre variante (le *seseo* ou le lexique mexicain) avec un exemple ;\n- donner **deux** chiffres ou faits qui montrent que l'espagnol est une langue mondiale ;\n- citer une langue co-officielle en Espagne.\n\n2. En français : explique pourquoi traiter ces variantes comme des « fautes » est un contresens sur ce qu'est une langue mondiale.","bareme":[{"critere":"Voseo expliqué avec exemple et présenté comme norme régionale","points":5},{"critere":"Autre variante juste avec exemple (seseo ou carro / coche, platicar / hablar)","points":3},{"critere":"Deux faits exacts (500 millions, 2e langue maternelle, une vingtaine de pays, 2e langue aux États-Unis) et une langue co-officielle","points":5},{"critere":"Espagnol correct (ser / estar, accords, conjugaisons)","points":3},{"critere":"Explication du contresens : norme régionale et langue mondiale","points":4}],"dureeMin":18,"corrige":"**1. Exemple de réponse attendue**\n\n> *Hola Diego:*\n> *¡Tu compañero se equivoca! Decir « vos tenés » en vez de « tú tienes » se llama voseo: es normal en Argentina, en Uruguay y en América Central. No es un error, es una norma regional. En México dicen « carro » y no « coche », y en Andalucía y en toda América la z se pronuncia s: es el seseo. El español lo hablan más de 500 millones de personas en unos veinte países: es la segunda lengua materna del mundo. Y en España también se hablan el catalán, el vasco y el gallego.*\n> *Un abrazo*\n\nÀ vérifier : *voseo* défini (*vos* à la place de *tú*) ; une autre variante exacte ; deux faits exacts (500 millions, 2e langue maternelle du monde, une vingtaine de pays, 2e langue parlée aux États-Unis) ; une langue co-officielle (catalan, basque, galicien).\n\n**2.** Une langue parlée par plus de 500 millions de personnes dans une vingtaine de pays n'a pas **une seule** façon correcte d'être parlée : chaque grande région a sa **norme**, aussi légitime que celle de Madrid. Le *voseo* ou le *seseo* ne sont pas des écarts par rapport à un modèle, ce sont des usages installés et reconnus. Les juger comme des fautes, c'est confondre la variété d'une langue mondiale avec une erreur."}$exo$::jsonb),
  ('375d03b8-101a-5812-918c-4832e77c8445'::uuid, 1, 'traduction', $exo${"titre":"Les formes de l’imparfait","consigne":"Écris chaque forme en entier, avec ses accents. Puis indique l’emploi de l’imparfait dans chaque phrase.","enonce":"**1. Conjugue** à l’imparfait :\n\na) *hablar* (yo)\nb) *comer* (nosotros)\nc) *vivir* (ellos)\nd) *ser* (tú)\ne) *ir* (nosotros)\nf) *ver* (ella)\ng) *jugar* (vosotros)\nh) *tener* (yo)\n\n**2. Indique l’emploi** de l’imparfait (description, habitude, action en cours interrompue ou politesse) :\n\na) *Hacía frío y la calle estaba desierta.*\nb) *Cuando era pequeña, iba a la playa cada verano.*\nc) *Quería pedirle un favor.*","bareme":[{"critere":"Les huit formes justes (hablaba, comíamos, vivían, eras, íbamos, veía, jugabais, tenía)","points":10},{"critere":"Accents écrits présents sur -ía, -íamos, -ían et sur íbamos","points":4},{"critere":"Les trois emplois bien identifiés (description, habitude, politesse)","points":6}],"dureeMin":7,"corrige":"**1.**\na) *hablaba* (verbe en -ar : -aba)\nb) *comíamos* (verbe en -er : -íamos, accent sur le í)\nc) *vivían* (verbe en -ir : -ían)\nd) *eras* (ser est irrégulier : era, eras, era…)\ne) *íbamos* (ir est irrégulier : iba, ibas… ; accent sur íbamos)\nf) *veía* (ver se forme sur l’ancien infinitif *veer*)\ng) *jugabais* (-ar, régulier)\nh) *tenía* (-er, régulier)\n\nSeuls *ser*, *ir* et *ver* sont irréguliers ; l’accent sur toutes les formes en -ía est obligatoire.\n\n**2.**\na) **Description** : le décor, sans début ni fin.\nb) **Habitude** passée (*cada verano*, *cuando era pequeña*).\nc) **Politesse** : « je voudrais vous demander un service »."}$exo$::jsonb),
  ('375d03b8-101a-5812-918c-4832e77c8445'::uuid, 2, 'traduction', $exo${"titre":"Le village de l’abuelo","consigne":"Complète le souvenir de Mateo à l’imparfait, puis traduis et justifie.","enonce":"**Situation.** Mateo raconte à sa classe un souvenir d’enfance.\n\n> Cuando (1. ser) pequeño, (2. vivir) en un pueblo de Asturias. Todos los días, mi abuelo me (3. llevar) al colegio. Nosotros (4. ir) a pie y (5. ver) las montañas. Por la tarde, mi abuela (6. hacer) pan y yo la (7. ayudar).\n\n1. Écris les **sept verbes** à l’imparfait.\n2. **Traduis** en espagnol : *Quand j’étais petite, je jouais au football avec mes cousins.*\n3. Explique en une phrase pourquoi tout ce texte est à l’imparfait.","bareme":[{"critere":"Les sept formes justes : era, vivía, llevaba, íbamos, veíamos, hacía, ayudaba","points":10},{"critere":"Accents écrits justes (vivía, íbamos, veíamos, hacía)","points":3},{"critere":"Traduction juste : Cuando era pequeña, jugaba al fútbol con mis primos","points":4},{"critere":"Justification : habitudes passées et description, sans début ni fin","points":3}],"dureeMin":10,"corrige":"**1.**\n1) *era* (ser, irrégulier)\n2) *vivía*\n3) *llevaba*\n4) *íbamos* (ir, irrégulier, accent)\n5) *veíamos* (ver, sur *veer* ; sujet *nosotros*)\n6) *hacía*\n7) *ayudaba*\n\n**2.** *Cuando era pequeña, jugaba al fútbol con mis primos.* — *era* (ser irrégulier), *jugaba* (-ar), *pequeña* au féminin. On accepte *con mis primas*.\n\n**3.** Le texte ne raconte aucun événement unique : il décrit un **cadre** et des **habitudes passées** (*todos los días*, *por la tarde*), sans début ni fin. C’est exactement l’emploi de l’imparfait."}$exo$::jsonb),
  ('375d03b8-101a-5812-918c-4832e77c8445'::uuid, 3, 'traduction', $exo${"titre":"La nuit de l’orage","consigne":"Choisis le bon temps, justifie tes choix, puis rédige un court souvenir en espagnol.","enonce":"**Document.** Récit de Sara, avec deux formes proposées à chaque fois.\n\n> Aquella noche (a. hacía / hizo) frío. Las calles (b. estaban / estuvieron) desiertas y (c. llovía / llovió). Yo (d. leía / leí) en mi habitación cuando, de repente, (e. sonaba / sonó) el teléfono. (f. Era / Fue) mi hermano.\n\n1. Recopie le récit avec la **bonne forme** à chaque fois.\n2. **Justifie** tes choix pour (c), (d) et (e) : quel temps pose le décor, lequel fait avancer le récit ?\n3. Explique la différence de sens entre *Ayer llovió* et *Ayer llovía*.\n4. **Production** (5 lignes environ) : raconte en espagnol un souvenir de tes vacances. Utilise au moins **trois imparfaits** avec trois emplois différents (description, habitude, action en cours interrompue).","bareme":[{"critere":"Les six choix justes : hacía, estaban, llovía, leía, sonó, Era","points":5},{"critere":"Justification : l’imparfait suspend le temps (décor), le passé simple fait avancer (événement)","points":5},{"critere":"Différence Ayer llovió / Ayer llovía expliquée (fait arrivé / contexte)","points":3},{"critere":"Production : trois imparfaits justes, trois emplois différents, accents corrects","points":7}],"dureeMin":16,"corrige":"**1.** *Aquella noche **hacía** frío. Las calles **estaban** desiertas y **llovía**. Yo **leía** en mi habitación cuando, de repente, **sonó** el teléfono. **Era** mi hermano.*\n\n**2.**\n- (c) *llovía* : la pluie est le **décor**, sans début ni fin → imparfait.\n- (d) *leía* : action **en cours**, qui va être interrompue → imparfait.\n- (e) *sonó* : l’**événement** qui interrompt et fait avancer le récit (*de repente*) → passé simple.\n(*Era mi hermano* : on identifie la personne, c’est une description.)\n\n**3.** *Ayer llovió* : il a plu, c’est un fait arrivé, achevé (événement). *Ayer llovía* : il pleuvait, c’était le contexte d’autre chose (décor).\n\n**4.** Exemple attendu : *Cuando era pequeño, iba a la playa con mis padres cada verano* (habitude). *El agua estaba fría y hacía mucho sol* (description). *Un día, nadaba tranquilamente cuando vi un delfín* (action en cours interrompue). Le correcteur vérifie trois imparfaits justes (formes, accents, irréguliers *ser/ir/ver*) et trois emplois distincts ; une phrase au passé simple pour l’interruption est bienvenue."}$exo$::jsonb),
  ('52eb160f-7140-53d6-a0fd-c56e58c7b441'::uuid, 1, 'traduction', $exo${"titre":"Haber et le participe","consigne":"Conjugue au passé composé, puis indique le temps qu’appelle chaque marqueur.","enonce":"**1. Conjugue** au passé composé (*pretérito perfecto*) :\n\na) *comer* (yo)\nb) *hablar* (tú)\nc) *vivir* (ella)\nd) *viajar* (nosotros)\ne) *terminar* (vosotros)\nf) *llegar* (ellos)\n\n**2.** Pour chaque marqueur, indique s’il appelle le **passé composé** ou le **passé simple** :\n\na) *hoy* · b) *ayer* · c) *este año* · d) *en 1990* · e) *nunca* · f) *el año pasado*","bareme":[{"critere":"Formes de haber justes : he, has, ha, hemos, habéis, han","points":6},{"critere":"Participes justes et invariables : comido, hablado, vivido, viajado, terminado, llegado","points":6},{"critere":"Les six marqueurs bien classés","points":8}],"dureeMin":7,"corrige":"**1.**\na) *he comido*\nb) *has hablado*\nc) *ha vivido*\nd) *hemos viajado*\ne) *habéis terminado*\nf) *han llegado*\n\n*haber* au présent + participe passé, qui **ne s’accorde jamais** (pas de « hemos viajados »).\n\n**2.**\na) *hoy* → **passé composé** (période non achevée)\nb) *ayer* → **passé simple**\nc) *este año* → **passé composé** (contient *este*)\nd) *en 1990* → **passé simple** (une date)\ne) *nunca* → **passé composé** (bilan de vie)\nf) *el año pasado* → **passé simple**"}$exo$::jsonb),
  ('52eb160f-7140-53d6-a0fd-c56e58c7b441'::uuid, 2, 'traduction', $exo${"titre":"Le message du soir de Pablo","consigne":"Complète le message au passé composé, corrige les fautes, puis traduis.","enonce":"**Situation.** Pablo écrit le soir à sa cousine Inés.\n\n> Hoy me (1. levantar) a las siete. Esta mañana (2. desayunar) con mi padre. Esta semana (3. trabajar) mucho y todavía no (4. terminar) mis deberes. ¿Tú (5. visitar) alguna vez Granada? Yo nunca (6. estar) allí.\n\n1. Écris les **six verbes** au passé composé.\n2. Inés répond : *« Yo he nunca estado en Granada, pero mis padres y yo hemos comidos allí una vez. »* Trouve et **corrige les deux fautes**, en expliquant la règle.\n3. **Traduis** : *Cette année, nous avons beaucoup voyagé.*","bareme":[{"critere":"Les six formes justes : me he levantado, he desayunado, he trabajado, he terminado, has visitado, he estado","points":9},{"critere":"Fautes corrigées : nunca he estado ; hemos comido","points":4},{"critere":"Règles énoncées : rien entre haber et le participe ; participe invariable","points":3},{"critere":"Traduction juste : Este año hemos viajado mucho","points":4}],"dureeMin":10,"corrige":"**1.**\n1) *me he levantado* (le pronom se place devant *haber*)\n2) *he desayunado*\n3) *he trabajado*\n4) *he terminado* (*todavía no* appelle le passé composé)\n5) *has visitado* (*alguna vez* : bilan)\n6) *he estado* (*nunca* : bilan de vie)\n\nTous les marqueurs (*hoy, esta mañana, esta semana, todavía no, alguna vez, nunca*) appellent le passé composé.\n\n**2.**\n- *He nunca estado* → **Nunca he estado** : rien ne s’intercale entre *haber* et le participe.\n- *hemos comidos* → **hemos comido** : le participe ne s’accorde jamais.\n\n**3.** *Este año hemos viajado mucho.* — *este año* est une période non achevée, donc passé composé."}$exo$::jsonb),
  ('52eb160f-7140-53d6-a0fd-c56e58c7b441'::uuid, 3, 'traduction', $exo${"titre":"Le journal de bord de Nuria","consigne":"Choisis le bon temps et justifie, réponds à la question sur l’usage, puis rédige ton bilan.","enonce":"**Document.** Journal de Nuria, deux formes proposées.\n\n> Ayer (a. he ido / fui) al cine con Marta. Hoy (b. he estado / estuve) en casa todo el día. El año pasado (c. hemos viajado / viajamos) a Portugal, pero este año no (d. hemos salido / salimos) de España. En 2020 mi hermano (e. se ha roto / se rompió) la pierna ; esta mañana yo (f. me he roto / me rompí) el brazo, y todavía llevo la escayola.\n\n1. Recopie avec la **bonne forme** et **justifie** chaque choix par le marqueur ou le sens.\n2. Ton correspondant mexicain Diego écrit : *« Hoy comí tacos. »* Est-ce une faute ? Explique, et dis ce que tu écrirais, toi, en épreuve.\n3. **Production** (5 lignes environ) : fais le bilan de ta semaine et de ta vie. Utilise au moins **quatre verbes** au passé composé avec trois marqueurs différents (*esta semana, hoy, ya, todavía no, nunca, alguna vez*).","bareme":[{"critere":"Les six choix justes : fui, he estado, viajamos, hemos salido, se rompió, me he roto","points":6},{"critere":"Justifications : marqueur ayer/date → passé simple ; este/hoy ou effets qui durent → passé composé","points":4},{"critere":"Variation géographique expliquée : usage courant en Amérique latine, norme castillane en épreuve","points":3},{"critere":"Production : quatre passés composés justes, trois marqueurs, participe invariable","points":7}],"dureeMin":16,"corrige":"**1.**\na) **fui** — *ayer* coupe le fait du présent → passé simple.\nb) **he estado** — *hoy*, période non achevée → passé composé.\nc) **viajamos** — *el año pasado* → passé simple.\nd) **hemos salido** — *este año*, période non achevée → passé composé.\ne) **se rompió** — une date, *en 2020* → passé simple.\nf) **me he roto** — *esta mañana* (période non achevée) et les **effets durent** (elle a encore le plâtre) → passé composé.\n\n**2.** Ce n’est **pas une faute** au Mexique : en Amérique latine (et dans le nord-ouest de l’Espagne), le passé simple absorbe largement le passé composé. Mais la norme scolaire française suit l’usage **castillan** : en épreuve, on écrit *Hoy he comido tacos*.\n\n**3.** Exemple : *Esta semana he trabajado mucho. Hoy he comido paella con mis amigos. Ya he terminado mis deberes, pero todavía no he preparado el examen. Nunca he estado en México.* Le correcteur vérifie *haber* bien conjugué, participes invariables, rien entre l’auxiliaire et le participe, et des marqueurs cohérents avec le passé composé."}$exo$::jsonb),
  ('011d6570-2a67-57da-bdfc-6af575b04591'::uuid, 1, 'traduction', $exo${"titre":"Réguliers et prétérits forts","consigne":"Conjugue au passé simple, avec les accents, puis réponds à la question.","enonce":"**1. Conjugue** au passé simple (*pretérito indefinido*) :\n\na) *hablar* (yo)\nb) *comer* (él)\nc) *vivir* (ellos)\nd) *tener* (yo)\ne) *hacer* (ella)\nf) *decir* (ellos)\ng) *ir* (nosotros)\nh) *dormir* (él)\n\n**2.** Quelle différence de sens y a-t-il entre *hablo* et *habló* ? Et entre *Fui a Madrid* et *Fui profesor* ?","bareme":[{"critere":"Formes régulières justes avec accent : hablé, comió, vivieron","points":6},{"critere":"Formes irrégulières justes : tuve, hizo, dijeron, fuimos, durmió","points":9},{"critere":"Explications : accent distinctif (présent / passé simple) ; ser et ir ont la même forme","points":5}],"dureeMin":8,"corrige":"**1.**\na) *hablé*\nb) *comió*\nc) *vivieron*\nd) *tuve* (prétérit fort, radical *tuv-*, **sans accent**)\ne) *hizo* (radical *hic-*, mais *hizo* à la 3e personne)\nf) *dijeron* (radical en -j : pas de i, jamais « dijieron »)\ng) *fuimos* (même forme pour *ser* et *ir*)\nh) *durmió* (affaiblissement o → u à la 3e personne)\n\n**2.** *hablo* est un **présent** (je parle) ; *habló* est un **passé simple** (il/elle parla, a parlé) : l’accent change le temps. *Fui a Madrid* = je suis allé à Madrid (*ir*) ; *Fui profesor* = j’ai été professeur (*ser*) : seul le contexte tranche."}$exo$::jsonb),
  ('011d6570-2a67-57da-bdfc-6af575b04591'::uuid, 2, 'traduction', $exo${"titre":"Une semaine à Madrid","consigne":"Mets le récit de Lucía au passé simple, puis réponds aux questions.","enonce":"**Situation.** Lucía raconte ses dernières vacances.\n\n> El verano pasado, mis padres y yo (1. ir) a Madrid. (2. Estar : nosotros) allí una semana. El primer día, (3. visitar : nosotros) el Museo del Prado. Mi padre (4. hacer) muchas fotos y mi madre (5. comprar) un libro. Yo (6. pedir) un helado. Por la noche, mis padres (7. dormir) muy poco.\n\n1. Écris les **sept verbes** au passé simple.\n2. Relève les **deux marqueurs** qui appellent le passé simple dans ce texte.\n3. Pourquoi écrit-on *pedí* (yo) mais *pidió* (él) ? Donne aussi la 3e personne du pluriel de *pedir*.","bareme":[{"critere":"Les sept formes justes : fuimos, Estuvimos, visitamos, hizo, compró, pedí, durmieron","points":11},{"critere":"Accents justes (compró, pedí) et aucun accent sur les formes fortes","points":3},{"critere":"Marqueurs relevés : el verano pasado, el primer día (ou por la noche)","points":2},{"critere":"Affaiblissement expliqué (3es personnes seulement) et pidieron donné","points":4}],"dureeMin":11,"corrige":"**1.**\n1) *fuimos* (ir)\n2) *Estuvimos* (radical fort *estuv-*)\n3) *visitamos*\n4) *hizo*\n5) *compró* (accent obligatoire à la 3e personne)\n6) *pedí* (1re personne : pas de changement de voyelle)\n7) *durmieron* (affaiblissement o → u)\n\n**2.** *El verano pasado* et *el primer día* (ou *por la noche*) : des moments passés et coupés du présent.\n\n**3.** Les verbes en -ir du type *pedir* ne changent de voyelle (e → i) **qu’aux deux troisièmes personnes** : *pedí, pediste, pidió, pedimos, pedisteis, **pidieron***."}$exo$::jsonb),
  ('011d6570-2a67-57da-bdfc-6af575b04591'::uuid, 3, 'traduction', $exo${"titre":"La visite surprise","consigne":"Choisis entre imparfait et passé simple, conjugue, justifie, puis traduis.","enonce":"**Document.** Récit d’Álvaro, verbes à l’infinitif.\n\n> Era de noche y (1. llover). De repente, (2. sonar) el timbre. Yo (3. abrir) la puerta : allí estaban mis tíos. (4. Traer : ellos) una tarta y me (5. decir) : « ¡Feliz cumpleaños! ». Mi tía (6. pedir) un café y mi tío (7. sentir) frío. Aquella noche, mis tíos (8. dormir) en casa.\n\n1. Conjugue les **huit verbes** au temps qui convient (imparfait ou passé simple).\n2. **Justifie** le temps choisi pour (1) et pour (2).\n3. Explique pourquoi on écrit *dijeron* et non « dijieron ».\n4. **Traduis** : *Hier, j’ai eu un problème : je n’ai pas pu venir.*","bareme":[{"critere":"Formes justes : llovía, sonó, abrí, Trajeron, dijeron, pidió, sintió, durmieron","points":8},{"critere":"Justification : imparfait = décor ; passé simple = événement qui fait avancer (de repente)","points":4},{"critere":"Règle du radical en -j expliquée (la 3e personne du pluriel perd son i)","points":3},{"critere":"Traduction juste : Ayer tuve un problema: no pude venir","points":5}],"dureeMin":17,"corrige":"**1.**\n1) *llovía* (imparfait : décor)\n2) *sonó* (passé simple, accent)\n3) *abrí*\n4) *Trajeron* (fort, radical *traj-*, sans i)\n5) *dijeron* (fort, *dij-*, sans i)\n6) *pidió* (affaiblissement e → i)\n7) *sintió* (affaiblissement e → i)\n8) *durmieron* (affaiblissement o → u)\n\n**2.** (1) *llovía* : la pluie pose le **décor** de la scène, sans début ni fin. (2) *sonó* : c’est l’**événement** qui surgit (*de repente*) et fait avancer le récit.\n\n**3.** Après un radical en **-j** (*dij-, traj-, conduj-*), la 3e personne du pluriel perd son i : *dijeron, trajeron, condujeron*.\n\n**4.** *Ayer tuve un problema: no pude venir.* — *ayer* appelle le passé simple ; *tener* → *tuve*, *poder* → *pude*, formes fortes **sans accent**."}$exo$::jsonb),
  ('ded51a4b-4bf7-59ab-8427-9b2b75fd51c4'::uuid, 1, 'traduction', $exo${"titre":"Futur et conditionnel","consigne":"Conjugue au futur puis au conditionnel, en écrivant les accents.","enonce":"**1. Conjugue** au futur simple :\n\na) *hablar* (yo)\nb) *comer* (nosotros)\nc) *vivir* (ellos)\nd) *tener* (tú)\ne) *hacer* (ella)\nf) *decir* (yo)\ng) *poder* (vosotros)\nh) *salir* (ellos)\n\n**2. Conjugue** au conditionnel : *tener* (yo) · *poder* (ella) · *hacer* (nosotros).","bareme":[{"critere":"Formes régulières justes : hablaré, comeremos, vivirán","points":5},{"critere":"Radicaux irréguliers justes : tendrás, hará, diré, podréis, saldrán","points":8},{"critere":"Accents justes (partout sauf nosotros)","points":2},{"critere":"Conditionnels justes sur le même radical : tendría, podría, haríamos","points":5}],"dureeMin":7,"corrige":"**1.**\na) *hablaré*\nb) *comeremos* (nosotros : pas d’accent)\nc) *vivirán*\nd) *tendrás* (un d remplace la voyelle : *tendr-*)\ne) *hará* (radical raccourci *har-*)\nf) *diré* (radical raccourci *dir-*)\ng) *podréis* (le e de l’infinitif tombe : *podr-*)\nh) *saldrán* (*saldr-*)\n\nLe futur se construit sur l’infinitif entier + *-é, -ás, -á, -emos, -éis, -án*.\n\n**2.** Même radical que le futur + terminaisons *-ía* : *tendría*, *podría*, *haríamos*."}$exo$::jsonb),
  ('ded51a4b-4bf7-59ab-8427-9b2b75fd51c4'::uuid, 2, 'traduction', $exo${"titre":"L’été de Carmen","consigne":"Complète les projets de Carmen au futur, corrige la phrase piège, puis explique.","enonce":"**Situation.** Carmen écrit à sa correspondante française.\n\n> El verano que viene (1. ir : yo) a México. (2. Tener : yo) mucho tiempo libre. Mis amigos (3. venir) conmigo y (4. hacer : nosotros) muchas excursiones. (5. Poner : yo) fotos en internet y te (6. decir : yo) todo.\n\n1. Écris les **six verbes** au futur simple.\n2. Carmen ajoute : *« Cuando llegaré a México, te llamaré. »* Corrige la faute et énonce la règle.\n3. Explique le sens de *Serán las tres* et de *Voy a estudiar*.","bareme":[{"critere":"Les six futurs justes : iré, Tendré, vendrán, haremos, Pondré, diré","points":9},{"critere":"Correction : Cuando llegue a México, te llamaré","points":3},{"critere":"Règle : après cuando à valeur de futur, subjonctif présent","points":3},{"critere":"Sens : probabilité sur le présent ; intention ou imminence avec ir a","points":5}],"dureeMin":11,"corrige":"**1.**\n1) *iré* (régulier : infinitif *ir* + *-é*)\n2) *Tendré* (*tendr-*)\n3) *vendrán* (*vendr-*)\n4) *haremos* (*har-*, sans accent à nosotros)\n5) *Pondré* (*pondr-*)\n6) *diré* (*dir-*)\n\n**2.** *Cuando **llegue** a México, te llamaré.* Dans une subordonnée de temps à valeur de futur, l’espagnol met le **subjonctif présent**, jamais le futur (le français dit « quand j’arriverai »).\n\n**3.** *Serán las tres* : futur de **probabilité**, une supposition sur le **présent** (« il doit être trois heures »). *Voy a estudiar* : *ir a* + infinitif, l’**intention** ou l’imminence (« je vais étudier »), très fréquent à l’oral."}$exo$::jsonb),
  ('ded51a4b-4bf7-59ab-8427-9b2b75fd51c4'::uuid, 3, 'traduction', $exo${"titre":"Ma vie dans dix ans","consigne":"Traduis, corrige le message, puis rédige ta projection dans l’avenir.","enonce":"**1. Traduis** en espagnol :\n\na) Demain, il pleuvra.\nb) Quand tu arriveras, appelle-moi.\nc) Il doit être trois heures (supposition).\nd) Pourrais-tu m’aider ?\ne) Nous le saurons demain.\n\n**2. Corrige** les trois fautes du message de Hugo :\n\n> *Cuando llegarás, te diceré la verdad. Mañana poderé salir.*\n\n**3. Production** (5 lignes environ) : comment sera ta vie dans dix ans ? Utilise au moins **quatre futurs irréguliers** différents et **une** phrase avec *cuando* + subjonctif présent.","bareme":[{"critere":"Traductions justes : lloverá, Cuando llegues llámame, Serán las tres, ¿Podrías ayudarme?, Lo sabremos","points":7},{"critere":"Les trois fautes corrigées : llegues, diré, podré","points":4},{"critere":"Production : quatre futurs irréguliers justes avec accents","points":6},{"critere":"Production : cuando suivi du subjonctif présent, sans futur","points":3}],"dureeMin":18,"corrige":"**1.**\na) *Mañana lloverá.*\nb) *Cuando llegues, llámame.* (subjonctif présent après *cuando*)\nc) *Serán las tres.* (futur de probabilité)\nd) *¿Podrías ayudarme?* (conditionnel, même radical *podr-*)\ne) *Lo sabremos mañana.* (*sabr-*, pas d’accent à nosotros)\n\n**2.** *Cuando **llegues**, te **diré** la verdad. Mañana **podré** salir.* — pas de futur après *cuando* ; *decir* → *dir-* ; *poder* → *podr-*.\n\n**3.** Exemple : *Dentro de diez años, tendré veinticinco años. Viviré en Madrid y seré médico. Podré viajar mucho y haré muchos amigos. Cuando tenga tiempo, volveré a ver a mi familia.* Le correcteur vérifie au moins quatre irréguliers justes (*tendré, podré, haré, saldré, vendré, pondré, sabré, querré, diré…*), les accents, et l’absence de futur après *cuando*."}$exo$::jsonb),
  ('00c82ee7-60a1-546f-a17c-161399cf400b'::uuid, 1, 'traduction', $exo${"titre":"Les bons mots pour interroger","consigne":"Recopie chaque question en entier, avec ses deux signes et ses accents. Puis traduis les phrases demandées.","enonce":"**1. Complète** avec le mot interrogatif qui convient, sans oublier les signes ¿ et ? :\n\na) … te llamas? (comment)\nb) … vives? (où)\nc) … años tienes? (combien)\nd) … es tu color favorito? (on choisit dans un ensemble)\ne) … no vienes a la fiesta? (pourquoi)\n\n**2. Traduis** en espagnol :\n\na) Je ne sais pas où il est.\nb) Pourquoi pleures-tu ? — Parce que je suis triste.","bareme":[{"critere":"Les cinq mots interrogatifs justes (cómo, dónde, cuántos, cuál, por qué), avec leur accent","points":10},{"critere":"Les signes ¿ et ? présents à l'ouverture et à la fermeture de chaque question","points":4},{"critere":"Traductions justes : accent gardé dans dónde sans signes, por qué / porque distingués","points":6}],"dureeMin":7,"corrige":"**1.**\na) **¿Cómo** te llamas?\nb) **¿Dónde** vives?\nc) **¿Cuántos** años tienes? (*años* est masculin pluriel, donc *cuántos*)\nd) **¿Cuál** es tu color favorito? (un choix dans un ensemble de couleurs)\ne) **¿Por qué** no vienes a la fiesta? (en deux mots, avec accent)\n\nChaque question s'ouvre par **¿** et se ferme par **?** ; tous les mots interrogatifs portent un accent écrit.\n\n**2.**\na) *No sé dónde está.* — interrogation indirecte : pas de signes ¿ ?, mais l'accent de **dónde** reste.\nb) *¿Por qué lloras? — Porque estoy triste.* — **por qué** (deux mots, accent) pour la question, **porque** (un mot, sans accent) pour la réponse."}$exo$::jsonb),
  ('00c82ee7-60a1-546f-a17c-161399cf400b'::uuid, 2, 'traduction', $exo${"titre":"L'interview du nouvel élève","consigne":"Retrouve les questions à partir des réponses, puis rapporte-les au style indirect.","enonce":"**Situation.** Lucía, journaliste du journal du collège, interroge Diego, un nouvel élève. Voici les réponses de Diego ; les questions ont été effacées.\n\n> — Me llamo Diego.\n> — Tengo catorce años.\n> — Vivo en Sevilla, cerca del río.\n> — Porque mi padre trabaja aquí ahora.\n> — Entre el fútbol y el baloncesto, prefiero el fútbol.\n\n1. Écris les **cinq questions** de Lucía (tutoiement), avec les signes et les accents.\n2. Lucía raconte l'interview à son professeur. Transforme les questions 1 et 3 au style indirect en commençant par *Le pregunté…*\n3. Explique en une phrase pourquoi *dónde* garde son accent dans ta réponse à la question 2.","bareme":[{"critere":"Cinq questions correctes : cómo, cuántos, dónde, por qué, cuál","points":10},{"critere":"Signes ¿ ? et accents des interrogatifs justes partout","points":4},{"critere":"Interrogation indirecte juste : accent gardé, signes supprimés","points":4},{"critere":"Explication : l'accent distingue l'interrogatif du relatif, même sans signes","points":2}],"dureeMin":10,"corrige":"**1.**\n- *¿Cómo te llamas?*\n- *¿Cuántos años tienes?*\n- *¿Dónde vives?*\n- *¿Por qué vives aquí?* (ou *¿Por qué has venido a Sevilla?*) — question en **por qué**, la réponse est en **porque**.\n- *¿Cuál prefieres, el fútbol o el baloncesto?* — **cuál** car on choisit entre deux éléments. (*¿Qué deporte prefieres?* est accepté : devant un nom on emploie *qué*.)\n\n**2.**\n- *Le pregunté cómo se llamaba* (ou *cómo se llama*).\n- *Le pregunté dónde vivía* (ou *dónde vive*).\nPas de signes ¿ ?, mais **cómo** et **dónde** gardent leur accent. On accepte le présent ou l'imparfait, seule la forme interrogative est évaluée.\n\n**3.** *Dónde* reste un mot **interrogatif**, même sans point d'interrogation : l'accent le distingue du relatif *donde* (*la casa donde vivo*)."}$exo$::jsonb),
  ('00c82ee7-60a1-546f-a17c-161399cf400b'::uuid, 3, 'traduction', $exo${"titre":"Le message à la correspondante","consigne":"Corrige les erreurs en les justifiant, puis rédige toi-même un court message en espagnol.","enonce":"**Document.** Tom a écrit ce message à sa correspondante de Salamanca. Il contient **cinq erreurs** liées aux questions.\n\n> Hola Marta, Como estás? Yo estoy bien. Cuál día llegas a París? Porque no me escribes más? No sé cuando vienes. Quieres visitar el Louvre?\n\n1. Recopie le message corrigé.\n2. Pour **trois** des erreurs, explique la règle en une phrase.\n3. Rédige un message de 4 questions à Marta (40 mots environ) sur ses loisirs. Tu dois employer : une question avec **qué** devant un nom, une avec **cuál**, une avec **por qué**, et une **interrogation indirecte** (*Me pregunto…* ou *No sé…*).","bareme":[{"critere":"Message corrigé : signes ¿ ?, cómo, qué día, por qué, cuándo","points":6},{"critere":"Trois règles expliquées avec justesse","points":5},{"critere":"Production : qué + nom, cuál, por qué et interrogation indirecte employés correctement","points":7},{"critere":"Message compréhensible, orthographe et accents soignés","points":2}],"dureeMin":15,"corrige":"**1.** *Hola Marta, **¿Cómo** estás? Yo estoy bien. **¿Qué día** llegas a París? **¿Por qué** no me escribes más? No sé **cuándo** vienes. **¿**Quieres visitar el Louvre?*\n\n**2.** Règles attendues (trois parmi) :\n- Toute question s'ouvre par **¿** et se ferme par **?** (oubli dans toutes les questions).\n- Les mots interrogatifs portent **tous un accent** : *cómo*, *cuándo*.\n- Devant un **nom**, on emploie **qué** et non *cuál* : *¿Qué día…?*\n- La question se pose avec **por qué** (deux mots, accent) ; *porque* sert à répondre.\n- Dans l'interrogation indirecte, l'accent **reste** même sans signes : *No sé cuándo vienes*.\n\n**3.** Exemple de production :\n*Hola Marta: ¿Qué deporte practicas? ¿Cuál es tu película favorita? ¿Por qué te gusta tanto la música? Me pregunto qué haces los domingos. ¡Escríbeme pronto!*\nOn vérifie : *qué* + nom, *cuál* + verbe *ser*, *por qué* en deux mots, interrogation indirecte sans signes mais avec accent (*qué*)."}$exo$::jsonb),
  ('09443324-0712-5e5e-881c-d9fe7f73f382'::uuid, 1, 'traduction', $exo${"titre":"Tout mettre à la forme négative","consigne":"Transforme chaque phrase à la forme négative, puis réécris-la de la seconde façon possible quand on te le demande.","enonce":"**1. Mets à la forme négative** en employant le mot négatif qui convient :\n\na) Veo algo en la calle.\nb) Alguien llama a la puerta.\nc) Siempre como carne.\nd) Tengo algún problema.\ne) Hablo español.\n\n**2.** Pour les phrases b) et c), écris la **deuxième** construction possible (mot négatif avant ou après le verbe).\n\n**3.** Traduis : *Moi non plus, je n'aime pas le thé.*","bareme":[{"critere":"Cinq négations justes (nada, nadie, nunca, ningún, no) avec la double négation quand le mot suit le verbe","points":10},{"critere":"Deuxième construction juste pour b) et c) : le no disparaît quand le mot négatif passe devant","points":6},{"critere":"Traduction avec tampoco juste","points":4}],"dureeMin":7,"corrige":"**1.**\na) *No veo nada en la calle.* (double négation obligatoire)\nb) *No llama nadie a la puerta.* ou *Nadie llama a la puerta.*\nc) *No como carne nunca.* ou *Nunca como carne.*\nd) *No tengo ningún problema.* (*ninguno* s'apocope en **ningún** devant un masculin singulier)\ne) *No hablo español.* (*no* juste devant le verbe)\n\n**2.**\nb) *Nadie llama a la puerta.* / *No llama nadie a la puerta.*\nc) *Nunca como carne.* / *No como carne nunca.*\nQuand le mot négatif passe **devant** le verbe, le *no* disparaît ; s'il est **après**, le *no* est obligatoire.\n\n**3.** *A mí tampoco me gusta el té.* ou *Tampoco me gusta el té.*"}$exo$::jsonb),
  ('09443324-0712-5e5e-881c-d9fe7f73f382'::uuid, 2, 'traduction', $exo${"titre":"Sino, pero et ne… plus","consigne":"Complète, puis traduis les phrases en respectant les règles de la négation espagnole.","enonce":"**1. Complète** avec *sino*, *sino que* ou *pero* :\n\na) No es francés … español.\nb) No es rico … es feliz.\nc) No canta … grita.\nd) No quiero té … café.\n\n**2. Situation.** Álvaro a changé depuis le début de l'année. Traduis ce que dit sa sœur :\n\na) Il ne joue plus au football.\nb) Il n'a pas encore fini ses devoirs.\nc) Il ne voit personne et ne dit rien.\nd) Il n'aime ni la musique ni le cinéma.","bareme":[{"critere":"Sino, sino que et pero justement choisis dans les quatre phrases","points":8},{"critere":"Ya no et todavía no (ou aún no) employés correctement","points":6},{"critere":"Double négation (no… nadie, no… nada) et ni… ni justes","points":6}],"dureeMin":10,"corrige":"**1.**\na) *No es francés **sino** español.* — on rectifie après une négation.\nb) *No es rico **pero** es feliz.* — on oppose sans rectifier.\nc) *No canta **sino que** grita.* — rectification devant un verbe conjugué.\nd) *No quiero té **sino** café.* — rectification.\n\n**2.**\na) *Ya no juega al fútbol.* (*ya no* = ne… plus)\nb) *Todavía no ha terminado sus deberes.* (ou *Aún no…* ; accepté aussi *Todavía no termina…*)\nc) *No ve a nadie y no dice nada.* — double négation : le *no* est obligatoire devant le verbe quand *nadie* et *nada* suivent ; *a* devant *nadie* COD de personne.\nd) *No le gusta ni la música ni el cine.* (ou *No le gustan ni la música ni el cine*)"}$exo$::jsonb),
  ('09443324-0712-5e5e-881c-d9fe7f73f382'::uuid, 3, 'traduction', $exo${"titre":"Le journal d'un jour sans","consigne":"Traduis le texte en espagnol, puis justifie trois de tes choix grammaticaux.","enonce":"**Texte à traduire.**\n\n> Aujourd'hui, rien ne va. Personne ne m'a appelé et je n'ai reçu aucun message. Je ne sors plus le soir et je ne vais jamais au cinéma. Mon frère non plus. Ce n'est pas de la tristesse, c'est de la fatigue. Je n'ai pas encore mangé et je ne veux rien.\n\n1. Traduis le texte (tu peux employer le présent pour *ne m'a appelé* et *n'ai reçu* : *nadie me llama*, *no recibo*).\n2. Pour **trois** phrases de ta traduction, explique la règle appliquée : double négation, place du mot négatif, apocope de *ninguno*, *sino*, *tampoco*…\n3. Réécris la phrase *Je ne vais jamais au cinéma* des **deux** façons possibles.","bareme":[{"critere":"Nada, nadie, ningún, ya no, nunca, tampoco, todavía no employés correctement","points":8},{"critere":"Double négation respectée partout où le mot négatif suit le verbe","points":4},{"critere":"No es… sino… pour la rectification","points":2},{"critere":"Trois justifications exactes","points":4},{"critere":"Les deux constructions de nunca justes","points":2}],"dureeMin":15,"corrige":"**1.** Traduction attendue :\n*Hoy nada va bien (No va bien nada). Nadie me ha llamado (Nadie me llama) y no he recibido ningún mensaje. Ya no salgo por la noche y no voy nunca al cine (nunca voy al cine). Mi hermano tampoco. No es tristeza sino cansancio. Todavía no he comido y no quiero nada.*\n\n**2.** Justifications possibles :\n- *Nadie me ha llamado* : le mot négatif est **avant** le verbe, donc pas de *no*.\n- *No quiero nada* : *nada* suit le verbe, donc le *no* est **obligatoire** (les deux négations se renforcent).\n- *ningún mensaje* : *ninguno* s'apocope devant un masculin singulier.\n- *No es tristeza sino cansancio* : **sino** rectifie après une négation.\n- *Mi hermano tampoco* : *tampoco* = non plus.\n- *Ya no* = ne… plus ; *todavía no* = pas encore.\n\n**3.** *No voy nunca al cine.* / *Nunca voy al cine.*"}$exo$::jsonb),
  ('92361de8-0e35-5522-909b-3b9527863bee'::uuid, 1, 'traduction', $exo${"titre":"La virgule qui change tout","consigne":"Réponds en une ou deux phrases, puis traduis.","enonce":"**1.** Compare ces deux phrases :\n\n> A. Los alumnos que estudian aprueban.\n> B. Los alumnos, que estudian, aprueban.\n\na) Dans quelle phrase **tous** les élèves réussissent-ils ?\nb) Comment s'appellent les deux types de relatives ?\n\n**2. Traduis :**\na) la maison dans laquelle je vis\nb) le garçon dont je parle\nc) Il est arrivé en retard, ce qui m'a dérangé.","bareme":[{"critere":"Différence de sens expliquée : B = tous les élèves, A = seulement ceux qui étudient","points":6},{"critere":"Types nommés : déterminative sans virgules, explicative entre virgules","points":4},{"critere":"Traductions justes : préposition devant le relatif et lo que pour une idée entière","points":10}],"dureeMin":7,"corrige":"**1.**\na) Dans la phrase **B** : la relative entre virgules ajoute une information sur **tous** les élèves (ils étudient tous, et ils réussissent tous). Dans A, seuls **ceux qui étudient** réussissent.\nb) A contient une relative **déterminative** (elle restreint l'antécédent, sans virgules) ; B une relative **explicative** (elle ajoute une information, entre virgules).\n\n**2.**\na) *la casa en la que vivo* — la préposition se place **devant** le relatif, jamais à la fin (« la casa que vivo en » est faux).\nb) *el chico del que hablo* (de + el que).\nc) *Llegó tarde, lo que me molestó.* — une idée entière se reprend par le neutre **lo que**, jamais par *el que*."}$exo$::jsonb),
  ('92361de8-0e35-5522-909b-3b9527863bee'::uuid, 2, 'traduction', $exo${"titre":"Indicatif ou subjonctif dans la relative","consigne":"Conjugue le verbe entre parenthèses au présent de l'indicatif ou du subjonctif, et justifie chaque choix.","enonce":"**Situation.** Nerea cherche un appartement et un colocataire à Valencia.\n\na) Busco un piso que (tener) terraza.\nb) Vivo en un piso que (tener) terraza.\nc) No conozco a nadie que (saber) cocinar paella.\nd) Tengo un amigo que (hablar) valenciano.\ne) Necesito un compañero que (poder) pagar la mitad.\n\n1. Conjugue les cinq verbes.\n2. Pour chaque phrase, écris si l'antécédent est **connu**, **indéfini** ou **nié**.\n3. Traduis : *Je cherche la secrétaire qui parle anglais* (tu la connais).","bareme":[{"critere":"Cinq formes justes : tenga, tiene, sepa, habla, pueda","points":10},{"critere":"Nature de l'antécédent correctement identifiée pour chaque phrase","points":6},{"critere":"Traduction à l'indicatif avec la préposition a : Busco a la secretaria que habla inglés","points":4}],"dureeMin":10,"corrige":"**1 et 2.**\na) *Busco un piso que **tenga** terraza.* — antécédent **indéfini** (n'importe quel appartement, encore à trouver) : subjonctif.\nb) *Vivo en un piso que **tiene** terraza.* — antécédent **connu**, réel : indicatif.\nc) *No conozco a nadie que **sepa** cocinar paella.* — antécédent **nié** : subjonctif.\nd) *Tengo un amigo que **habla** valenciano.* — antécédent **connu** : indicatif.\ne) *Necesito un compañero que **pueda** pagar la mitad.* — antécédent **indéfini** : subjonctif (*poder* diphtongue : *pueda*).\n\n**3.** *Busco a la secretaria que habla inglés.* — la secrétaire est connue, donc **indicatif** ; *a* devant un COD de personne déterminée. À comparer avec *Busco una secretaria que hable inglés* (n'importe laquelle)."}$exo$::jsonb),
  ('92361de8-0e35-5522-909b-3b9527863bee'::uuid, 3, 'traduction', $exo${"titre":"L'annonce du club de théâtre","consigne":"Corrige les phrases fautives en justifiant, puis rédige une petite annonce en espagnol.","enonce":"**1. Chaque phrase contient une erreur.** Corrige-la et explique la règle.\n\na) El chico que hablo de es mi primo.\nb) Buscamos actores que tienen experiencia.\nc) No vino a clase, el que me sorprendió.\n\n**2. Production (50 mots environ).** Le club de théâtre du collège de Toledo cherche de nouveaux membres. Rédige l'annonce, qui commence par *Buscamos chicos y chicas que…*. Tu dois employer :\n- deux relatives au **subjonctif** (antécédent indéfini) ;\n- une relative avec **préposition** (*en el que*, *con el que*…) ;\n- une relative **explicative** entre virgules ;\n- **lo que**.","bareme":[{"critere":"Trois corrections justes : del que hablo, que tengan, lo que","points":6},{"critere":"Trois règles expliquées (préposition, mode, idée entière)","points":3},{"critere":"Deux relatives au subjonctif correctes dans l'annonce","points":4},{"critere":"Relative avec préposition, relative explicative et lo que correctement employées","points":5},{"critere":"Annonce claire, compréhensible, accords soignés","points":2}],"dureeMin":16,"corrige":"**1.**\na) *El chico **del que** hablo es mi primo.* — la préposition ne se rejette jamais à la fin : elle précède le relatif (*de + el que = del que*).\nb) *Buscamos actores que **tengan** experiencia.* — les acteurs sont encore à trouver (antécédent indéfini) : subjonctif.\nc) *No vino a clase, **lo que** me sorprendió.* — une phrase entière se reprend par le neutre *lo que*.\n\n**2.** Exemple d'annonce :\n*Buscamos chicos y chicas que quieran hacer teatro y que no tengan miedo al público. Los ensayos, que son los miércoles, tienen lugar en la sala en la que trabajamos desde hace diez años. Lo que buscamos es gente motivada. ¡Te esperamos!*\nOn vérifie : *quieran*, *tengan* (subjonctif, antécédent indéfini) ; *en la que* (préposition devant le relatif) ; *, que son los miércoles,* (explicative entre virgules) ; *lo que* (idée) ."}$exo$::jsonb),
  ('1d154947-e80a-5112-8751-3821163edf36'::uuid, 1, 'traduction', $exo${"titre":"Indicatif ou subjonctif après que","consigne":"Conjugue le verbe entre parenthèses au présent de l'indicatif ou du subjonctif.","enonce":"**1. Complète :**\n\na) Creo que Pablo (venir) mañana.\nb) No creo que Pablo (venir) mañana.\nc) Quiero que tú (estudiar) más.\nd) Veo que (estar, él) cansado.\ne) Es necesario que vosotros (llegar) a las ocho.\nf) Ojalá (hacer) buen tiempo el sábado.\n\n**2. Traduis** en faisant attention au sujet :\na) Je veux venir.\nb) Je veux que tu viennes.","bareme":[{"critere":"Six formes justes : viene, venga, estudies, está, lleguéis, haga","points":12},{"critere":"Infinitif quand le sujet est le même, que + subjonctif quand il change","points":8}],"dureeMin":7,"corrige":"**1.**\na) *Creo que Pablo **viene** mañana.* — opinion affirmée : indicatif.\nb) *No creo que Pablo **venga** mañana.* — certitude niée : subjonctif.\nc) *Quiero que **estudies** más.* — volonté : subjonctif.\nd) *Veo que **está** cansado.* — perception : indicatif.\ne) *Es necesario que **lleguéis** a las ocho.* — jugement impersonnel : subjonctif (*llegar* : g devient **gu** devant e).\nf) *Ojalá **haga** buen tiempo el sábado.* — souhait : *ojalá* est toujours suivi du subjonctif.\n\n**2.**\na) *Quiero venir.* — même sujet : infinitif, sans *que*.\nb) *Quiero que vengas.* — sujets différents : *que* + subjonctif."}$exo$::jsonb),
  ('1d154947-e80a-5112-8751-3821163edf36'::uuid, 2, 'traduction', $exo${"titre":"Les conseils de la mère de Carmen","consigne":"Transforme les phrases comme demandé et justifie le mode choisi.","enonce":"**Situation.** Carmen part en voyage scolaire à Granada. Sa mère lui parle.\n\n> «Estudias mucho, lo sé. Pero tienes que descansar. Llevas el móvil. Me llamas cada noche. Estás contenta.»\n\n1. Réécris ces phrases en commençant par le verbe indiqué :\na) *Quiero que…* (tienes que descansar → descansar)\nb) *Espero que…* (me llamas cada noche)\nc) *Me alegro de que…* (estás contenta)\nd) *Es importante que…* (llevas el móvil)\n\n2. Transforme à la forme négative : *Creo que el viaje es caro.* Quel changement de mode se produit ?\n\n3. Complète la phrase de Carmen : *Sé que mi madre…* (preocuparse). Justifie le mode.","bareme":[{"critere":"Quatre subjonctifs justes : descanses, me llames, estés, lleves","points":10},{"critere":"Bascule juste : No creo que el viaje sea caro, avec explication","points":6},{"critere":"Sé que mi madre se preocupa, indicatif justifié par la certitude","points":4}],"dureeMin":10,"corrige":"**1.**\na) *Quiero que descanses.* — volonté : subjonctif.\nb) *Espero que me llames cada noche.* — souhait : subjonctif ; le *que* ne se supprime jamais.\nc) *Me alegro de que estés contenta.* — sentiment : subjonctif (*estar* : *esté, estés*…).\nd) *Es importante que lleves el móvil.* — jugement impersonnel : subjonctif.\n\n**2.** *No creo que el viaje **sea** caro.* — l'opinion affirmée (*creo que* + indicatif) devient une certitude **niée** : on passe au **subjonctif**. Le verbe principal n'a pas changé, sa polarité si.\n\n**3.** *Sé que mi madre **se preocupa**.* — *saber* exprime une **certitude** : indicatif."}$exo$::jsonb),
  ('1d154947-e80a-5112-8751-3821163edf36'::uuid, 3, 'traduction', $exo${"titre":"Ce que voulait le professeur","consigne":"Traduis, transpose au passé et justifie tes choix de mode.","enonce":"**1. Traduis** ces phrases d'un professeur à sa classe :\n\na) Je veux que vous lisiez ce livre.\nb) Je pense que c'est un bon roman.\nc) Je ne pense pas qu'il soit difficile.\nd) Il faut que vous travailliez en groupe.\n\n**2. Transpose au passé** les phrases a) et d) : *Quería que…*, *Era necesario que…* (imparfait du subjonctif en *-ra*).\n\n**3.** En deux ou trois phrases, explique pourquoi b) et c) n'emploient pas le même mode alors que le verbe principal est le même.\n\n**4.** Écris une phrase de ton choix avec *ojalá* et une autre avec *dudo que*.","bareme":[{"critere":"Quatre traductions justes : leáis, es, sea, trabajéis","points":8},{"critere":"Concordance au passé juste : leyerais, trabajarais (ou -seis)","points":4},{"critere":"Explication de la bascule opinion affirmée / niée","points":4},{"critere":"Phrases avec ojalá et dudo que au subjonctif correct","points":4}],"dureeMin":16,"corrige":"**1.**\na) *Quiero que leáis este libro.* — volonté, sujets différents : subjonctif.\nb) *Creo (pienso) que es una buena novela.* — opinion affirmée : indicatif.\nc) *No creo que sea difícil.* — opinion niée : subjonctif.\nd) *Es necesario que trabajéis en grupo.* (ou *Hace falta que…*) — jugement impersonnel : subjonctif.\n\n**2.**\na) *Quería que leyerais (leyeseis) este libro.*\nd) *Era necesario que trabajarais (trabajaseis) en grupo.*\nQuand le verbe principal passe au passé, le subjonctif présent devient **imparfait du subjonctif** ; les formes en *-ra* et *-se* sont équivalentes.\n\n**3.** Dans b), le professeur **affirme** une opinion : indicatif. Dans c), il **nie** cette opinion : ce n'est plus une certitude, on passe au **subjonctif**. Le verbe *creer* est le même, seule la négation change le mode.\n\n**4.** Exemples : *Ojalá apruebe el examen.* / *Dudo que venga esta tarde.* — *ojalá* et le doute exigent le subjonctif."}$exo$::jsonb),
  ('da34d672-e099-5ad0-8d04-77b6cb7f2f6e'::uuid, 1, 'traduction', $exo${"titre":"Le bon article, le bon pluriel","consigne":"Écris chaque nom avec son article défini au singulier, puis au pluriel.","enonce":"**1.** Écris l'article défini (*el* ou *la*) devant chaque nom, puis le groupe au **pluriel** :\n\na) … problema\nb) … canción\nc) … ciudad\nd) … leche\ne) … color\nf) … lápiz\ng) … examen\nh) … lunes\n\n**2.** Donne le féminin de : *el profesor*, *el francés*, *el estudiante*.","bareme":[{"critere":"Genre juste pour les huit noms, notamment el problema, la leche, el color","points":8},{"critere":"Pluriels justes : -s, -es, z en -ces, invariable, accent de exámenes","points":8},{"critere":"Trois féminins justes : la profesora, la francesa, la estudiante","points":4}],"dureeMin":7,"corrige":"**1.**\na) *el problema* → *los problemas* (masculin : -ma d'origine grecque)\nb) *la canción* → *las canciones* (féminin en -ción ; l'accent disparaît au pluriel)\nc) *la ciudad* → *las ciudades* (féminin en -dad ; consonne : -es)\nd) *la leche* → *las leches* (féminin en espagnol, masculin en français)\ne) *el color* → *los colores* (masculin en espagnol)\nf) *el lápiz* → *los lápices* (z devient **-ces**)\ng) *el examen* → *los exámenes* (l'accent écrit apparaît pour garder la prononciation)\nh) *el lunes* → *los lunes* (-s non accentué : invariable)\n\n**2.** *la profesora* (on ajoute -a), *la francesa* (on ajoute -a, l'accent disparaît), *la estudiante* (invariable : seul l'article change)."}$exo$::jsonb),
  ('da34d672-e099-5ad0-8d04-77b6cb7f2f6e'::uuid, 2, 'traduction', $exo${"titre":"Les fautes de genre de Hugo","consigne":"Corrige le texte, puis classe les noms corrigés et explique ce qui a trompé Hugo.","enonce":"**Document.** Hugo a écrit ce texte sur son voyage. Il contient **six erreurs** de genre ou de pluriel.\n\n> En el viaje a Madrid tuve una problema: me dolía el nariz. Compré el leche y la sal en una tienda. Visité dos ciudads y tres museos. Me gustó mucho la color del cielo. Los examenes empiezan el lunes.\n\n1. Recopie le texte corrigé.\n2. Explique pourquoi Hugo s'est trompé sur *problema*, *nariz* et *color*.\n3. Donne une règle de pluriel pour *ciudad* et une pour *examen*.","bareme":[{"critere":"Six corrections justes : un problema, la nariz, la leche, ciudades, el color, exámenes","points":10},{"critere":"Explication : calque du genre français, -ma grec masculin","points":6},{"critere":"Règles de pluriel justes : consonne + -es, accent qui suit la prononciation","points":4}],"dureeMin":10,"corrige":"**1.** *En el viaje a Madrid tuve **un** problema: me dolía **la** nariz. Compré **la** leche y la sal en una tienda. Visité dos **ciudades** y tres museos. Me gustó mucho **el** color del cielo. Los **exámenes** empiezan el lunes.*\n\n**2.**\n- *problema* finit par -a mais est **masculin** : c'est un nom en **-ma d'origine grecque** (*el problema, el tema, el idioma*).\n- *nariz* et *leche* sont **féminins** en espagnol alors que « nez » et « lait » sont masculins en français : Hugo a recopié le genre français.\n- *color* est **masculin** en espagnol, « couleur » féminin en français. Ces noms s'apprennent avec leur article.\n\n**3.**\n- *ciudad* finit par une consonne : on ajoute **-es** → *ciudades*.\n- *examen* → *exámenes* : l'accent écrit **apparaît** au pluriel pour garder l'accent tonique sur la même syllabe (l'accent suit la prononciation)."}$exo$::jsonb),
  ('da34d672-e099-5ad0-8d04-77b6cb7f2f6e'::uuid, 3, 'traduction', $exo${"titre":"La fête du village","consigne":"Traduis le texte, puis justifie le genre et le pluriel de cinq noms de ta traduction.","enonce":"**Texte à traduire.**\n\n> Dans mon village, la tradition est ancienne. Chaque été, les jeunes chantent des chansons sur la place. Les artistes arrivent le vendredi avec leurs crayons pour dessiner les arbres et les ponts. Le voyage coûte peu et le climat est doux. C'est une coutume que j'adore.\n\nVocabulaire : *village* = pueblo, *place* = plaza, *dessiner* = dibujar, *doux* = suave, *coûter peu* = costar poco.\n\n1. Traduis le texte.\n2. Choisis **cinq** noms de ta traduction et justifie leur genre ou leur pluriel par une règle du cours (terminaison, piège du francophone, pluriel en -ces, nom invariable…).","bareme":[{"critere":"Genres justes : la tradición, la canción, el árbol, el puente, el viaje, el clima, la costumbre","points":8},{"critere":"Pluriels justes : canciones, lápices, árboles, puentes ; los artistas","points":5},{"critere":"Cinq justifications exactes","points":5},{"critere":"Traduction compréhensible et accords soignés","points":2}],"dureeMin":16,"corrige":"**1.** *En mi pueblo, la tradición es antigua. Cada verano, los jóvenes cantan canciones en la plaza. Los artistas llegan el viernes con sus lápices para dibujar los árboles y los puentes. El viaje cuesta poco y el clima es suave. Es una costumbre que me encanta (que adoro).*\n\n**2.** Justifications possibles :\n- *la tradición* : féminin en **-ción**.\n- *las canciones* : féminin en -ción ; au pluriel on ajoute **-es** et l'accent écrit **disparaît**.\n- *los artistas* : nom **invariable en genre**, seul l'article change (*el / la artista*).\n- *los lápices* : **z** devient **-ces** au pluriel.\n- *el árbol, el puente, el viaje* : **masculins** en espagnol, féminins en français (pièges du francophone) ; *el viaje* : terminaison **-aje** masculine.\n- *el clima* : **-ma** d'origine grecque, masculin.\n- *la costumbre* : féminin en **-umbre**.\n- *los jóvenes* : consonne → -es, l'accent apparaît."}$exo$::jsonb),
  ('7f8f8f76-4dab-58a4-8111-44e372d0a7a8'::uuid, 1, 'traduction', $exo${"titre":"El, al, del ou lo ?","consigne":"Complète avec l'article qui convient et justifie en quelques mots.","enonce":"**1. Complète** avec *el, la, un, una, al, del* ou *lo* :\n\na) … agua está fría.\nb) Voy … cine con mis amigos.\nc) Es la casa … profesor.\nd) Vi … águila en la montaña.\ne) … importante es participar.\nf) Vivo en … avenida principal.\n\n**2. Traduis :** a) Je suis professeur. b) un autre jour.","bareme":[{"critere":"Six articles justes : el, al, del, un, lo, la","points":12},{"critere":"Deux traductions justes : Soy profesor, otro día","points":8}],"dureeMin":7,"corrige":"**1.**\na) ***El** agua está fría.* — nom féminin commençant par un **a- tonique** : *el*, mais l'adjectif reste au féminin (*fría*).\nb) *Voy **al** cine.* — contraction *a + el = al*.\nc) *La casa **del** profesor.* — contraction *de + el = del*.\nd) *Vi **un** águila.* — a- tonique : *un*, pas *una*.\ne) ***Lo** importante es participar.* — neutre *lo* + adjectif = une qualité abstraite.\nf) *Vivo en **la** avenida principal.* — l'accent tonique de *avenida* ne tombe pas sur le *a* initial : article normal.\n\n**2.**\na) *Soy profesor.* — pas d'article devant une profession en attribut.\nb) *otro día* — jamais d'article indéfini devant *otro*."}$exo$::jsonb),
  ('7f8f8f76-4dab-58a4-8111-44e372d0a7a8'::uuid, 2, 'traduction', $exo${"titre":"Le carnet de voyage de Salomé","consigne":"Traduis les phrases, puis explique trois de tes choix d'article.","enonce":"**Situation.** Salomé tient un carnet pendant son séjour en Andalousie. Traduis ses notes :\n\na) Nous allons au marché avec quelques amis.\nb) L'eau de la fontaine est froide.\nc) Les salles de classe du collège sont grandes.\nd) Ma correspondante est espagnole ; son père est médecin.\ne) Je ne comprends pas ce que dit le guide.\nf) Le plus difficile, c'est la chaleur.\n\nExplique ensuite **trois** de tes choix d'article.","bareme":[{"critere":"Al, unos amigos et del justement employés","points":5},{"critere":"El agua fría et las aulas : règle du a tonique et pluriel","points":5},{"critere":"Absence d'article devant la profession et la nationalité en attribut","points":3},{"critere":"Lo que et lo + adjectif justes","points":4},{"critere":"Trois explications exactes","points":3}],"dureeMin":10,"corrige":"a) *Vamos al mercado con unos amigos.* — *a + el = al* ; *unos* = quelques.\nb) *El agua de la fuente está fría.* — *agua* est féminin mais commence par un a- tonique : **el** ; l'adjectif reste féminin.\nc) *Las aulas del colegio son grandes.* — au **pluriel**, l'article féminin revient : *las aulas*.\nd) *Mi correspondiente (amiga por correspondencia) es española; su padre es médico.* — pas d'article devant une nationalité ou une profession en attribut.\ne) *No entiendo lo que dice el guía.* — *lo que* = « ce que ».\nf) *Lo más difícil es el calor.* — *lo* + adjectif = qualité abstraite ; *el calor* est masculin.\n\nExplications attendues : trois parmi les justifications ci-dessus (contraction, a tonique, pluriel *las*, absence d'article en attribut, neutre *lo*)."}$exo$::jsonb),
  ('7f8f8f76-4dab-58a4-8111-44e372d0a7a8'::uuid, 3, 'traduction', $exo${"titre":"Tu ne sais pas comme je suis fatigué","consigne":"Corrige les erreurs en justifiant, puis rédige un court texte en espagnol.","enonce":"**1. Chaque phrase contient une erreur d'article.** Corrige-la et explique la règle.\n\na) La agua del mar está fría.\nb) Voy a el colegio en bici.\nc) Mi hermano es un médico.\nd) Quiero un otro helado.\ne) No sabes el cansado que estoy.\n\n**2. Production (40 à 50 mots).** Raconte la fin d'une journée de randonnée difficile. Tu dois employer : *el* devant un nom féminin à a- tonique (*el agua*, *el hambre*…), une contraction, **lo** + adjectif, **lo** + adjectif + **que** (intensité) et **otro**.","bareme":[{"critere":"Cinq corrections justes","points":6},{"critere":"Cinq règles expliquées","points":5},{"critere":"Production : a tonique, contraction et otro sans article justes","points":4},{"critere":"Production : lo + adjectif et lo + adjectif + que justes","points":4},{"critere":"Texte compréhensible et accords soignés","points":1}],"dureeMin":16,"corrige":"**1.**\na) ***El** agua del mar está fría.* — féminin singulier à a- tonique : *el*, l'adjectif reste féminin.\nb) *Voy **al** colegio.* — *a + el* se contracte toujours en *al* (sauf devant un nom propre).\nc) *Mi hermano es médico.* — pas d'article devant une profession en attribut (sauf si elle est qualifiée : *un médico excelente*).\nd) *Quiero **otro** helado.* — jamais d'article indéfini devant *otro*.\ne) *No sabes **lo** cansado que estoy.* — *lo* + adjectif + *que* exprime l'intensité (le neutre, jamais *el*).\n\n**2.** Exemple :\n*Después de ocho horas de marcha, llegamos al refugio. Tenía un hambre terrible y bebí toda el agua de mi botella. Lo peor fue la bajada. ¡No sabes lo cansada que estaba! Mañana haremos otra ruta, más corta.*\nOn vérifie : *un hambre, el agua* (a tonique), *al* (contraction), *lo peor* (lo + adjectif), *lo cansada que* (intensité), *otra* sans article."}$exo$::jsonb),
  ('aeb7f4d5-a5d8-5188-8ab4-8e3e608a5306'::uuid, 1, 'traduction', $exo${"titre":"Ici, là, là-bas","consigne":"Complète avec le démonstratif qui convient selon la distance indiquée.","enonce":"**1. Complète :**\n\na) … libro (près de moi) es muy interesante.\nb) ¿Me das … revista (près de toi)?\nc) … montañas (loin de nous deux) son los Pirineos.\nd) … chicos (près de moi) son mis primos.\ne) … casa (loin de nous deux) es de mi abuela.\n\n**2.** Traduis : *Qu'est-ce que c'est ?* et *Ce n'est pas vrai.*\n\n**3.** Quelle est la particularité du masculin singulier de la troisième série ?","bareme":[{"critere":"Cinq démonstratifs justes, accordés en genre et en nombre","points":12},{"critere":"Neutres justes : ¿Qué es esto? et Eso no es verdad","points":5},{"critere":"Aquel sans -o","points":3}],"dureeMin":7,"corrige":"**1.**\na) ***Este** libro es muy interesante.* (près de moi, masculin singulier)\nb) *¿Me das **esa** revista?* (près de toi, féminin singulier)\nc) ***Aquellas** montañas son los Pirineos.* (loin, féminin pluriel)\nd) ***Estos** chicos son mis primos.* (près de moi, masculin pluriel)\ne) ***Aquella** casa es de mi abuela.* (loin, féminin singulier)\n\n**2.** *¿Qué es esto?* (chose non identifiée, proche : neutre **esto**) — *Eso no es verdad.* (reprend ce qui vient d'être dit : **eso**). Les neutres sont invariables, sans accent, jamais suivis d'un nom.\n\n**3.** Le masculin singulier est **aquel**, sans -o (et non « aquelo »)."}$exo$::jsonb),
  ('aeb7f4d5-a5d8-5188-8ab4-8e3e608a5306'::uuid, 2, 'traduction', $exo${"titre":"Au marché de Valencia","consigne":"Complète le dialogue avec les démonstratifs et les adverbes de lieu, puis réponds aux questions.","enonce":"**Situation.** Iker fait les courses au marché avec sa grand-mère. La marchande est derrière son étal, Iker tient un panier.\n\n> **Iker:** Quiero … naranjas que tiene usted ahí, al lado de su mano.\n> **Vendedora:** ¿… ? Muy bien. ¿Y … melón que tiene en su cesta? ¿Es de aquí?\n> **Iker:** Sí, … melón lo compré aquí el sábado.\n> **Abuela:** ¿Y … tomates, al fondo del mercado, allí?\n> **Vendedora:** … son de otra tienda. ¡… no es asunto mío!\n\n1. Complète les six trous.\n2. Pour trois trous, explique la distance (près de qui ?).\n3. Associe chaque série à son adverbe : *aquí, ahí, allí*.","bareme":[{"critere":"Six démonstratifs justes et accordés","points":10},{"critere":"Trois distances expliquées correctement","points":5},{"critere":"Adverbes associés : este-aquí, ese-ahí, aquel-allí ; neutre eso pour une idée","points":5}],"dureeMin":10,"corrige":"**1.**\n> Iker: Quiero **esas** naranjas que tiene usted ahí. (près de la marchande = de l'interlocuteur)\n> Vendedora: ¿**Estas**? (près d'elle-même, qui parle) Muy bien. ¿Y **ese** melón que tiene en su cesta? (près d'Iker, son interlocuteur)\n> Iker: Sí, **este** melón… (près de lui, qui parle)\n> Abuela: ¿Y **aquellos** tomates, al fondo del mercado, allí? (loin des deux)\n> Vendedora: **Aquellos** son de otra tienda. ¡**Eso** no es asunto mío! (neutre : reprend une idée)\n\n**2.** Trois explications parmi celles données entre parenthèses : la distance se mesure par rapport à **celui qui parle** (*este*), à **celui qui écoute** (*ese*), ou **loin des deux** (*aquel*).\n\n**3.** *este* → **aquí** ; *ese* → **ahí** ; *aquel* → **allí**."}$exo$::jsonb),
  ('aeb7f4d5-a5d8-5188-8ab4-8e3e608a5306'::uuid, 3, 'traduction', $exo${"titre":"Les souvenirs du grand-père","consigne":"Traduis le texte, puis justifie le choix de chaque démonstratif.","enonce":"**Texte à traduire.** Le grand-père de Lola lui montre une vieille photo.\n\n> — Tu vois cette maison, là-bas, au fond de la photo ? C'était notre maison. À cette époque-là, nous n'avions pas d'argent. Ces années-là furent difficiles, mais tout cela m'a rendu fort.\n> — Et ce garçon, à côté de toi sur la photo ?\n> — Celui-là, c'est mon frère. Ce livre que tu tiens, c'est lui qui l'a écrit.\n\n1. Traduis le dialogue.\n2. Justifie chaque démonstratif employé (distance dans l'espace, dans le temps ou dans le discours ; neutre).\n3. Pourquoi écrit-on aujourd'hui *este* et *aquel* sans accent, même quand ils sont pronoms ?","bareme":[{"critere":"Aquella casa, en aquel entonces, aquellos años justes : distance temporelle","points":6},{"critere":"Neutre aquello ou eso pour reprendre une idée (tout cela)","points":3},{"critere":"Ese chico et ese libro justes : près de l'interlocuteur","points":4},{"critere":"Justifications exactes pour chaque démonstratif","points":5},{"critere":"Règle de la RAE de 2010 sur l'accent des pronoms","points":2}],"dureeMin":15,"corrige":"**1.** Traduction attendue :\n> — ¿Ves aquella casa, allí, al fondo de la foto? Era nuestra casa. En aquel entonces, no teníamos dinero. Aquellos años fueron difíciles, pero todo aquello me hizo fuerte.\n> — ¿Y ese chico, a tu lado en la foto?\n> — Ese es mi hermano. Ese libro que tienes, lo escribió él.\n\n**2.**\n- *aquella casa* : loin des deux, au fond de la photo (espace).\n- *en aquel entonces*, *aquellos años* : un passé lointain (temps) : c'est le domaine de *aquel*.\n- *todo aquello* : neutre qui reprend un ensemble de souvenirs lointains (*todo eso* accepté).\n- *ese chico* : Lola en parle, désigné sur la photo proche d'elle (accepté aussi *este* si le grand-père tient la photo) ; *ese* reprend aussi ce dont on parle.\n- *ese libro que tienes* : près de l'interlocuteur (Lola le tient).\n- *Ese es mi hermano* : pronom démonstratif.\n\n**3.** Depuis la réforme de la **RAE en 2010**, le pronom démonstratif ne prend **plus d'accent écrit** : on écrit *este*, *ese*, *aquel* comme l'adjectif. L'ancienne graphie *éste* n'est plus la norme."}$exo$::jsonb),
  ('cb080d6b-609d-56b7-9e70-a035083c823e'::uuid, 1, 'traduction', $exo${"titre":"Accorder et placer l'adjectif","consigne":"Accorde l'adjectif entre parenthèses et place-le correctement.","enonce":"**1. Accorde** l'adjectif :\n\na) una chica (alto)\nb) unos chicos (inteligente)\nc) una profesora (español)\nd) una mujer (trabajador)\ne) un chico y una chica (simpático)\n\n**2. Place** l'adjectif avant ou après le nom et accorde-le :\na) un coche (rojo)\nb) un día (bueno)\nc) la lengua (francés)\n\n**3.** Quelle est la place de l'adjectif par défaut ?","bareme":[{"critere":"Cinq accords justes : alta, inteligentes, española, trabajadora, simpáticos","points":10},{"critere":"Trois places justes : coche rojo, buen día, lengua francesa","points":6},{"critere":"Règle : après le nom par défaut","points":4}],"dureeMin":7,"corrige":"**1.**\na) *una chica **alta*** — adjectif en -o : quatre formes.\nb) *unos chicos **inteligentes*** — adjectif en -e : invariable en genre, pluriel en -s.\nc) *una profesora **española*** — adjectif de nationalité : il forme un féminin.\nd) *una mujer **trabajadora*** — adjectif en -or : il forme un féminin.\ne) *un chico y una chica **simpáticos*** — plusieurs noms dont un masculin : masculin pluriel.\n\n**2.**\na) *un coche rojo* — la couleur reste toujours après le nom.\nb) *un buen día* — appréciation, avant le nom, avec apocope (*bueno* → *buen*). *Un día bueno* est possible mais moins courant.\nc) *la lengua francesa* — nationalité : toujours après.\n\n**3.** Par défaut, l'adjectif se place **après** le nom : il classe, il distingue objectivement."}$exo$::jsonb),
  ('cb080d6b-609d-56b7-9e70-a035083c823e'::uuid, 2, 'traduction', $exo${"titre":"Grand homme ou homme grand ?","consigne":"Traduis chaque expression en choisissant la bonne place de l'adjectif, puis explique la différence de sens.","enonce":"**Situation.** Pour un exposé, Maëlys traduit des phrases sur des personnages.\n\n**1. Traduis :**\na) Cervantes est un grand homme.\nb) Mon oncle est un homme grand (de grande taille).\nc) Ce pauvre homme a perdu son chien.\nd) C'est un homme pauvre : il n'a pas d'argent.\ne) Lucas est un vieil ami (je le connais depuis longtemps).\nf) J'ai lu différents livres sur ce sujet.\n\n**2.** Explique en deux phrases pourquoi la place de l'adjectif compte autant en espagnol.","bareme":[{"critere":"Gran hombre / hombre grande et pobre hombre / hombre pobre justes","points":8},{"critere":"Viejo amigo et diferentes libros justes","points":6},{"critere":"Explication : devant = regard du locuteur, derrière = classement ; le sens change","points":6}],"dureeMin":10,"corrige":"**1.**\na) *Cervantes es un gran hombre.* — devant : important (avec apocope *gran*).\nb) *Mi tío es un hombre grande.* — derrière : de grande taille.\nc) *Este pobre hombre ha perdido a su perro.* — devant : à plaindre.\nd) *Es un hombre pobre: no tiene dinero.* — derrière : sans argent.\ne) *Lucas es un viejo amigo.* — devant : de longue date (*un amigo viejo* = un ami âgé).\nf) *He leído diferentes libros sobre este tema.* — devant : plusieurs (*libros diferentes* = dissemblables).\n\n**2.** Placé **après** le nom, l'adjectif classe objectivement ; placé **avant**, il exprime le regard de celui qui parle. Pour certains adjectifs (*gran, pobre, viejo, diferente, cierto*), la place **change le sens** du mot : ce n'est pas une nuance de style mais une information."}$exo$::jsonb),
  ('cb080d6b-609d-56b7-9e70-a035083c823e'::uuid, 3, 'traduction', $exo${"titre":"Le portrait d'une idole","consigne":"Corrige les erreurs en justifiant, puis rédige un portrait en espagnol.","enonce":"**1. Chaque phrase contient une erreur.** Corrige-la et explique.\n\na) Tengo una amiga inglés.\nb) Mis padres y mi hermana son simpáticas.\nc) Es un grande actor.\nd) Tiene los ojos azul.\n\n**2. Production (50 à 60 mots).** Fais le portrait d'une personne que tu admires (réelle ou inventée). Tu dois employer :\n- au moins quatre adjectifs accordés, dont un de nationalité ;\n- un adjectif **avant** le nom qui exprime une appréciation ;\n- un adjectif dont le **sens change** selon la place (*gran, pobre, viejo…*), en expliquant son sens entre parenthèses en français ;\n- une apocope (*buen, gran, mal*).","bareme":[{"critere":"Quatre corrections justes : inglesa, simpáticos, gran actor, azules","points":6},{"critere":"Quatre explications exactes","points":4},{"critere":"Production : adjectifs accordés, dont un de nationalité","points":4},{"critere":"Production : adjectif antéposé, adjectif à sens changeant et apocope corrects","points":5},{"critere":"Portrait cohérent et compréhensible","points":1}],"dureeMin":16,"corrige":"**1.**\na) *una amiga **inglesa*** — les adjectifs de nationalité forment un féminin.\nb) *son **simpáticos*** — plusieurs noms dont l'un est masculin : accord au masculin pluriel.\nc) *un **gran** actor* — *grande* s'apocope en *gran* devant un nom singulier ; devant, il signifie « important ».\nd) *los ojos **azules*** — l'adjectif s'accorde en nombre (consonne → -es) ; la couleur reste après le nom.\n\n**2.** Exemple :\n*Mi abuela Carmen es una mujer argentina, alegre y muy trabajadora. Es una gran persona (importante, admirable) y una buena cocinera. Tiene los ojos verdes y el pelo blanco. Es mi querida abuela y también mi vieja amiga (amie de longue date).*\nOn vérifie : accords (*argentina, alegre, trabajadora, verdes, blanco*), nationalité, antéposition affective (*querida*), sens changeant (*gran persona*, *vieja amiga*), apocope (*gran*, *buena* non apocopé au féminin)."}$exo$::jsonb),
  ('23ea32b2-8f74-57ff-9810-a31145e27299'::uuid, 1, 'traduction', $exo${"titre":"Le pronom sujet : utile ou lourd ?","consigne":"Réponds aux questions et corrige les phrases.","enonce":"**1.** Dans ces phrases, supprime le pronom sujet s'il est inutile :\n\na) Yo hablo español y yo estudio inglés.\nb) Nosotros vivimos en Bilbao.\nc) Tú trabajas y él duerme.\n\n**2.** Conjugue au présent :\na) ¿Usted (hablar) francés?\nb) ¿Ustedes (querer) café?\n\n**3.** Traduis : *pour moi*, *avec toi*, *entre toi et moi*.","bareme":[{"critere":"Pronoms inutiles supprimés en a et b, gardés en c pour l'opposition","points":7},{"critere":"Usted et ustedes conjugués à la 3e personne : habla, quieren","points":6},{"critere":"Para mí, contigo, entre tú y yo justes","points":7}],"dureeMin":7,"corrige":"**1.**\na) *Hablo español y estudio inglés.* — la terminaison suffit à identifier la personne.\nb) *Vivimos en Bilbao.*\nc) *Tú trabajas y él duerme.* — on **garde** les pronoms : ils servent à **opposer** deux personnes.\n\n**2.**\na) *¿Usted **habla** francés?*\nb) *¿Ustedes **quieren** café?* (*querer* diphtongue)\n*Usted* et *ustedes* se conjuguent à la **3e personne** (ils viennent de *vuestra merced*, « votre grâce »).\n\n**3.** *para mí* (accent sur *mí*, pronom après préposition) ; *contigo* (forme soudée avec *con*) ; *entre tú y yo* (après *entre*, on garde *tú* et *yo*)."}$exo$::jsonb),
  ('23ea32b2-8f74-57ff-9810-a31145e27299'::uuid, 2, 'traduction', $exo${"titre":"Du tu au vous à la réception","consigne":"Transforme le dialogue comme demandé, puis réponds aux questions.","enonce":"**Situation.** Julia travaille à l'accueil d'un hôtel de Cádiz. Elle parle d'abord à son collègue, puis doit dire la même chose à un client.\n\n> ¿Tienes tu pasaporte? ¿Quieres una habitación con vistas al mar? Puedes dejar tu maleta aquí. ¿Necesitas ayuda?\n\n1. Réécris ces phrases en **vouvoyant** un client (*usted*).\n2. Réécris-les pour **un groupe de clients** (*ustedes*).\n3. Pourquoi un Mexicain dirait-il *ustedes* même à un groupe d'amis ?\n4. Un Argentin dit : *¿Vos tenés hambre?* Comment s'appelle cet usage ? Est-ce une faute ?","bareme":[{"critere":"Vouvoiement singulier juste : tiene, quiere, puede, necesita, su maleta","points":8},{"critere":"Vouvoiement pluriel juste : tienen, quieren, pueden, necesitan, sus maletas","points":6},{"critere":"Vosotros n'existe pas en Amérique latine","points":3},{"critere":"Voseo identifié comme norme régionale, pas une faute","points":3}],"dureeMin":10,"corrige":"**1.** *¿Tiene (usted) su pasaporte? ¿Quiere una habitación con vistas al mar? Puede dejar su maleta aquí. ¿Necesita ayuda?* — verbe à la **3e personne du singulier** ; le possessif devient *su*.\n\n**2.** *¿Tienen (ustedes) sus pasaportes? ¿Quieren una habitación (unas habitaciones) con vistas al mar? Pueden dejar sus maletas aquí. ¿Necesitan ayuda?* — **3e personne du pluriel**.\n\n**3.** En **Amérique latine**, *vosotros* n'existe pas : le pluriel familier est *ustedes*, même entre amis.\n\n**4.** C'est le **voseo** : *vos* remplace *tú*, avec ses formes propres (*vos tenés*, *vos sos*). Ce n'est **pas une faute**, c'est une norme régionale (Argentine, Uruguay, Paraguay, Amérique centrale)."}$exo$::jsonb),
  ('23ea32b2-8f74-57ff-9810-a31145e27299'::uuid, 3, 'traduction', $exo${"titre":"Moi, je ne l'ai pas dit","consigne":"Traduis le dialogue en choisissant quand exprimer le pronom sujet, puis justifie tes choix.","enonce":"**Texte à traduire.** Deux frères se disputent devant leur mère.\n\n> — Maman, c'est lui qui a cassé le vase ! Moi, je ne l'ai pas touché.\n> — Ce n'est pas vrai ! Toi, tu joues au ballon dans le salon, et moi, je lis.\n> — Madame, vous voulez un café ? demande la voisine, qui entre.\n> — Oui, merci. Viens avec moi, Pablo. Et toi, reste avec ton frère : entre toi et moi, ce n'est pas grave.\n\n1. Traduis le dialogue.\n2. Relève **trois** pronoms sujets que tu as exprimés et donne la raison (insister, opposer, lever une ambiguïté).\n3. Justifie la forme de *vous* (voisine → la mère) et celle de *avec moi*.","bareme":[{"critere":"Pronoms sujets exprimés seulement pour insister ou opposer, omis ailleurs","points":6},{"critere":"Usted avec verbe à la 3e personne : ¿Quiere usted un café?","points":4},{"critere":"Conmigo et entre tú y yo justes","points":4},{"critere":"Trois justifications exactes","points":4},{"critere":"Traduction compréhensible","points":2}],"dureeMin":15,"corrige":"**1.** Traduction attendue :\n> — Mamá, ¡él ha roto el jarrón! Yo no lo he tocado.\n> — ¡No es verdad! Tú juegas al balón en el salón y yo leo.\n> — Señora, ¿quiere (usted) un café? —pregunta la vecina, que entra.\n> — Sí, gracias. Ven conmigo, Pablo. Y tú, quédate con tu hermano: entre tú y yo, no es grave.\n\n**2.** Justifications :\n- *él ha roto* : **insister** sur le coupable (et lever l'ambiguïté).\n- *Yo no lo he tocado* : **insister** (« moi, je… »).\n- *Tú juegas… y yo leo* : **opposer** deux personnes.\n- *Y tú, quédate* : opposition avec Pablo.\nAilleurs (*entra*, *quiere*), le pronom est omis : la terminaison suffit.\n\n**3.** *¿Quiere usted…?* : le vouvoiement d'une personne se fait avec *usted* et le verbe à la **3e personne**. *Conmigo* : avec *con*, le pronom se soude de façon irrégulière. *Entre tú y yo* : après *entre*, on garde *tú* et *yo*."}$exo$::jsonb),
  ('2cafa044-bdf8-5fce-ac68-14ba52d3f122'::uuid, 1, 'traduction', $exo${"titre":"Remplacer par un pronom","consigne":"Remplace les mots soulignés (en gras) par le pronom complément qui convient.","enonce":"**1. Remplace** le complément en gras par un pronom :\n\na) Veo **a María** cada día.\nb) Hablo **a Juan** por teléfono.\nc) Compro **los libros**.\nd) Escribo **a mis abuelos**.\n\n**2. Remplace les deux compléments** :\na) Doy **el libro a Juan**.\nb) Digo **la verdad a mis padres**.\n\n**3.** Dans quel ordre se placent le COI et le COD ?","bareme":[{"critere":"COD et COI simples justes : la veo, le hablo, los compro, les escribo","points":8},{"critere":"Double pronom juste avec le changement de le en se : se lo doy, se la digo","points":8},{"critere":"Ordre COI puis COD","points":4}],"dureeMin":7,"corrige":"**1.**\na) ***La** veo cada día.* — COD féminin : *la*.\nb) ***Le** hablo por teléfono.* — COI : *le*.\nc) ***Los** compro.* — COD masculin pluriel.\nd) ***Les** escribo.* — COI pluriel.\nLe pronom se place **devant** le verbe conjugué.\n\n**2.**\na) ***Se lo** doy.* — *le* devant *lo* devient **se** (« le lo doy » est impossible).\nb) ***Se la** digo.* — *les* devant *la* devient **se**.\n\n**3.** Toujours le **COI avant le COD** : *me lo da*, *te la doy*, *se lo doy*."}$exo$::jsonb),
  ('2cafa044-bdf8-5fce-ac68-14ba52d3f122'::uuid, 2, 'traduction', $exo${"titre":"Donne-le-moi, ne me le donne pas","consigne":"Réécris les phrases en remplaçant les compléments par des pronoms placés correctement.","enonce":"**Situation.** Chez Andrea, on prépare le repas de dimanche.\n\n1. Remplace les compléments en gras par des pronoms :\na) ¡Da **la sal a tu hermano**! (impératif affirmatif)\nb) ¡No des **la sal a tu hermano**! (impératif négatif)\nc) Voy a preparar **la tortilla**. (donne les deux constructions)\nd) Estoy cortando **las cebollas**. (gérondif)\ne) Quiero decir **la noticia a vosotros**.\n\n2. Pourquoi écrit-on *dásela* et *cortándolas* avec un accent ?","bareme":[{"critere":"Impératif affirmatif et négatif justes : dásela, no se la des","points":6},{"critere":"Deux constructions avec semi-auxiliaire : la voy a preparar / voy a prepararla","points":4},{"critere":"Gérondif et infinitif avec enclise justes : cortándolas, decírosla","points":6},{"critere":"Accent expliqué : garder la syllabe tonique d'origine","points":4}],"dureeMin":10,"corrige":"**1.**\na) *¡**Dásela**!* — impératif affirmatif : pronoms **soudés** derrière ; COI avant COD ; *le* devant *la* devient *se*.\nb) *¡No **se la** des!* — impératif négatif : pronoms **devant** le verbe.\nc) *La voy a preparar.* = *Voy a prepararla.* — avec un verbe conjugué + infinitif, les deux places sont admises.\nd) *Estoy **cortándolas**.* (ou *Las estoy cortando.*) — gérondif : pronom soudé derrière.\ne) *Quiero **decírosla**.* (ou *Os la quiero decir.*) — infinitif : pronoms soudés, COI *os* avant COD *la*.\n\n**2.** L'enclise allonge le mot : on ajoute un **accent écrit** pour garder la **syllabe tonique** du verbe d'origine (*da* → *dásela*, *cortando* → *cortándolas*)."}$exo$::jsonb),
  ('2cafa044-bdf8-5fce-ac68-14ba52d3f122'::uuid, 3, 'traduction', $exo${"titre":"Le cadeau d'anniversaire","consigne":"Traduis le dialogue, puis justifie la place et la forme de chaque pronom.","enonce":"**Texte à traduire.** Nora et son père préparent l'anniversaire de la grand-mère.\n\n> — Tu as acheté le cadeau pour mamie ?\n> — Oui, je l'ai acheté hier. Je vais le lui donner ce soir.\n> — Montre-le-moi !\n> — Non, ne le touche pas ! Je suis en train de l'emballer.\n> — Tu lui as dit que nous venons dîner ?\n> — Oui, je le lui ai dit ce matin.\n\n1. Traduis le dialogue (utilise *mamie* = la abuela, *emballer* = envolver).\n2. Pour **quatre** pronoms, justifie la place (proclise ou enclise) et la forme (*se* à la place de *le*, ordre COI-COD).\n3. Explique le rôle de *le* dans : *Le doy el regalo a la abuela.* Est-ce une lourdeur ?","bareme":[{"critere":"Se lo voy a dar / voy a dárselo et se lo he dicho justes","points":5},{"critere":"Impératifs justes : enséñamelo, no lo toques","points":4},{"critere":"Gérondif juste : estoy envolviéndolo ou lo estoy envolviendo","points":3},{"critere":"Quatre justifications exactes","points":5},{"critere":"Redoublement du COI expliqué comme la norme","points":3}],"dureeMin":16,"corrige":"**1.** Traduction attendue :\n> — ¿Has comprado el regalo para la abuela?\n> — Sí, lo compré ayer (lo he comprado ayer). Se lo voy a dar esta noche (Voy a dárselo esta noche).\n> — ¡Enséñamelo! (¡Muéstramelo!)\n> — ¡No, no lo toques! Estoy envolviéndolo (Lo estoy envolviendo).\n> — ¿Le has dicho que venimos a cenar?\n> — Sí, se lo he dicho esta mañana.\n\n**2.** Justifications :\n- *lo compré* : verbe conjugué, pronom **devant**.\n- *se lo voy a dar* / *voy a dárselo* : deux places admises ; *le* devant *lo* devient **se** ; ordre COI puis COD.\n- *enséñamelo* : impératif affirmatif, **soudé** ; accent pour garder la syllabe tonique.\n- *no lo toques* : impératif négatif (subjonctif), pronom **devant**.\n- *envolviéndolo* : gérondif, soudé, accent ajouté.\n- *se lo he dicho* : bloc *haber* + participe, pronoms devant l'auxiliaire.\n\n**3.** *Le* reprend le COI *a la abuela* : c'est le **redoublement** du COI, très fréquent en espagnol. Ce n'est pas une lourdeur, c'est la **norme**."}$exo$::jsonb),
  ('89d5db39-01e2-53c6-ab3a-a84bec2714c6'::uuid, 1, 'traduction', $exo${"titre":"Mi, mío, el mío","consigne":"Complète avec le possessif qui convient.","enonce":"**1. Complète avec un possessif atone** (devant le nom) :\n\na) (mes) … libros\nb) (notre) … casa\nc) (ton) … hermano\nd) (leurs) … padres\n\n**2. Complète avec un possessif tonique :**\na) Este libro es … (à moi).\nb) Es un amigo … (à moi).\nc) Tu bici es roja; … (la mienne) es azul.\n\n**3.** Avec quoi s'accorde le possessif espagnol ?","bareme":[{"critere":"Quatre possessifs atones justes : mis, nuestra, tu, sus","points":8},{"critere":"Trois possessifs toniques justes : mío, mío, la mía","points":8},{"critere":"Accord avec l'objet possédé","points":4}],"dureeMin":6,"corrige":"**1.**\na) ***mis** libros*\nb) ***nuestra** casa* — *nuestro* varie en genre : féminin car *casa*.\nc) ***tu** hermano* (sans accent : *tú* est le pronom sujet)\nd) ***sus** padres* — *su(s)* sert aussi pour « leur(s) ».\n\n**2.**\na) *Este libro es **mío**.* — attribut.\nb) *Es un amigo **mío**.* — après le nom, pour insister (« un ami à moi »).\nc) *La **mía** es azul.* — avec l'article, comme pronom ; accordé avec *bici* (féminin).\n\n**3.** Le possessif s'accorde avec **ce qui est possédé**, pas avec le possesseur : *mis libros* (plusieurs livres, un seul possesseur)."}$exo$::jsonb),
  ('89d5db39-01e2-53c6-ab3a-a84bec2714c6'::uuid, 2, 'traduction', $exo${"titre":"Le matin chez les García","consigne":"Traduis les phrases en faisant attention à l'emploi de l'article ou du possessif.","enonce":"**Situation.** C'est la course du matin chez les García.\n\n1. Traduis :\na) Je me lave les mains.\nb) Mon petit frère a mal à la tête.\nc) Papa enlève son manteau.\nd) Ma sœur se brosse les dents.\n\n2. La mère dit : *Su mochila está en la cocina.* Donne **trois** sens possibles de *su* ici, et réécris la phrase pour qu'il soit clair que c'est le sac de Clara.\n\n3. La grand-mère s'exclame en voyant son petit-fils : « Mon fils ! » Traduis.","bareme":[{"critere":"Quatre traductions avec l'article défini pour le corps et les vêtements","points":10},{"critere":"Ambiguïté de su expliquée et levée par de ella / de Clara","points":6},{"critere":"Vocatif juste : ¡Hijo mío!","points":4}],"dureeMin":10,"corrige":"**1.**\na) *Me lavo las manos.*\nb) *A mi hermano pequeño le duele la cabeza.*\nc) *Papá se quita el abrigo.*\nd) *Mi hermana se lava los dientes.*\nQuand la possession est évidente (corps, vêtements), l'espagnol emploie **l'article défini** : le pronom réfléchi porte déjà l'information.\n\n**2.** *Su mochila* peut signifier **son** sac (à lui), **son** sac (à elle), **leur** sac ou **votre** sac (de *usted*). Pour lever l'ambiguïté : *La mochila de Clara está en la cocina* (ou *la mochila de ella*).\n\n**3.** *¡Hijo mío!* — au vocatif, le possessif tonique suit le nom."}$exo$::jsonb),
  ('89d5db39-01e2-53c6-ab3a-a84bec2714c6'::uuid, 3, 'traduction', $exo${"titre":"Les objets trouvés","consigne":"Corrige les erreurs en justifiant, puis rédige un court dialogue en espagnol.","enonce":"**1. Chaque phrase contient une erreur.** Corrige-la et explique.\n\na) Me lavo mis manos antes de comer.\nb) Nuestro casa está cerca del mar.\nc) Este paraguas es mi.\nd) Es un mi amigo.\n\n**2. Production (6 à 8 répliques).** Au bureau des objets trouvés du collège, deux élèves cherchent leurs affaires. Écris le dialogue en employant :\n- deux possessifs atones, dont *nuestro* ou *vuestro* accordé ;\n- un possessif tonique en attribut (*es mío*) ;\n- un possessif pronom (*el mío, la tuya…*) ;\n- une phrase où l'on emploie l'article et non le possessif (corps ou vêtement) ;\n- *su* suivi d'une précision avec *de*.","bareme":[{"critere":"Quatre corrections justes : las manos, nuestra casa, es mío, un amigo mío","points":6},{"critere":"Quatre explications exactes","points":4},{"critere":"Possessifs atones, toniques et pronoms justes et accordés dans le dialogue","points":6},{"critere":"Article pour le corps ou le vêtement et su précisé par de","points":3},{"critere":"Dialogue cohérent","points":1}],"dureeMin":16,"corrige":"**1.**\na) *Me lavo **las** manos.* — le pronom réfléchi indique déjà la possession : article défini.\nb) ***Nuestra** casa* — *nuestro* s'accorde en genre avec *casa*.\nc) *Este paraguas es **mío**.* — en attribut, on emploie la forme tonique.\nd) *Es **un amigo mío**.* — la forme tonique se place après le nom ; l'atone ne suit jamais un article.\n\n**2.** Exemple :\n> — Buenos días, busco mi mochila y mis guantes.\n> — ¿Es esta mochila azul?\n> — No, la mía es negra. Esta es de Leo, creo.\n> — Y esta chaqueta, ¿es tuya?\n> — ¡Sí, es mía! Me la quité en el patio.\n> — ¿Y este estuche? Es su estuche… el estuche de Marta, tiene su nombre.\n> — Nuestra profesora dice que hay muchas cosas aquí.\nOn vérifie : *mi, mis, nuestra* (atones), *es mía, tuya* (attribut), *la mía* (pronom), *me la quité* (article sous-entendu, pas de possessif), *su estuche… de Marta*."}$exo$::jsonb),
  ('68d2953f-6ab0-5bef-912d-f25f6db333f8'::uuid, 1, 'traduction', $exo${"titre":"Que, quien, cuyo, lo que","consigne":"Complète avec le pronom relatif qui convient.","enonce":"**1. Complète** avec *que, quien, cuyo / cuya / cuyos / cuyas* ou *lo que* :\n\na) El libro … leo es muy bonito.\nb) La persona con … hablo es mi tía.\nc) El escritor … novela leí es colombiano.\nd) Llegó tarde, … me molestó.\ne) La casa … muros son blancos es de mis abuelos.\n\n**2.** Comment demande-t-on « À qui est-ce ? » en espagnol ?","bareme":[{"critere":"Cinq relatifs justes : que, quien, cuya, lo que, cuyos","points":14},{"critere":"¿De quién es? et non cuyo en question","points":6}],"dureeMin":7,"corrige":"**1.**\na) *El libro **que** leo* — cas général : *que*.\nb) *La persona con **quien** hablo* — personne, après une préposition : *quien* (*con la que* accepté).\nc) *El escritor **cuya** novela leí* — *cuyo* s'accorde avec ce qui est possédé : *novela*, féminin singulier.\nd) *Llegó tarde, **lo que** me molestó.* — reprend une idée entière.\ne) *La casa **cuyos** muros son blancos* — accordé avec *muros*, masculin pluriel ; jamais d'article après *cuyo*.\n\n**2.** *¿De quién es?* — *cuyo* ne s'emploie **jamais** en question (« ¿Cuyo es? » est faux)."}$exo$::jsonb),
  ('68d2953f-6ab0-5bef-912d-f25f6db333f8'::uuid, 2, 'traduction', $exo${"titre":"Deux phrases en une","consigne":"Relie chaque paire de phrases avec un pronom relatif, puis justifie ton choix.","enonce":"**Situation.** Pour la page « Découvertes » du journal du collège, Inès présente des lieux et des personnes de Barcelone.\n\n1. Relie les deux phrases avec un relatif :\na) Visité un museo. El museo tiene obras de Picasso.\nb) Conocí a un artista. Los cuadros del artista están en el museo.\nc) Esta es la plaza. Paseé por la plaza.\nd) Mi guía se llama Jordi. Jordi vive en Barcelona. (relative explicative, personne)\ne) El museo cerró temprano. Eso nos sorprendió.\n\n2. Pour chaque phrase obtenue, nomme le relatif employé et dis pourquoi.","bareme":[{"critere":"Que et cuyos justes en a et b, cuyos accordé avec cuadros","points":6},{"critere":"Préposition devant le relatif en c : por la que","points":4},{"critere":"Quien en relative explicative en d et lo que en e","points":5},{"critere":"Justifications exactes","points":5}],"dureeMin":10,"corrige":"**1.**\na) *Visité un museo **que** tiene obras de Picasso.* — cas général.\nb) *Conocí a un artista **cuyos** cuadros están en el museo.* — « dont » possessif ; accord avec *cuadros* (masculin pluriel), sans article.\nc) *Esta es la plaza **por la que** paseé.* — la préposition précède toujours le relatif ; on ajoute l'article (*por donde* accepté).\nd) *Mi guía, **quien** vive en Barcelona, se llama Jordi.* — personne, relative explicative entre virgules (*que* accepté).\ne) *El museo cerró temprano, **lo que** nos sorprendió.* — reprise d'une idée entière (*lo cual* accepté).\n\n**2.** Justifications : celles données après chaque phrase."}$exo$::jsonb),
  ('68d2953f-6ab0-5bef-912d-f25f6db333f8'::uuid, 3, 'traduction', $exo${"titre":"Le village dont je rêve","consigne":"Traduis le texte, puis justifie chaque relatif employé.","enonce":"**Texte à traduire.**\n\n> Le village dont je rêve est un village dont les maisons sont blanches. Les gens qui y vivent sont accueillants. Mon ami Marcos, qui est né là-bas, m'a montré la rue dans laquelle il jouait enfant. Celui qui veut connaître l'Espagne doit visiter ces villages, ce que je fais chaque été.\n\nVocabulaire : *rêver de* = soñar con, *accueillant* = acogedor.\n\n1. Traduis le texte.\n2. Justifie **chaque** relatif (que, quien, cuyo, el que avec préposition, lo que).\n3. Pourquoi ne peut-on pas écrire *cuyas las casas* ?","bareme":[{"critere":"Con el que sueño et cuyas casas justes","points":5},{"critere":"Que, quien (ou que) et en la que justes","points":5},{"critere":"El que (ou quien) sans antécédent et lo que justes","points":4},{"critere":"Justifications exactes","points":4},{"critere":"Règle : cuyo jamais suivi d'un article","points":2}],"dureeMin":16,"corrige":"**1.** Traduction attendue :\n*El pueblo con el que sueño es un pueblo cuyas casas son blancas. La gente que vive allí es acogedora. Mi amigo Marcos, quien (que) nació allí, me enseñó la calle en la que jugaba de niño. El que (Quien) quiere conocer España debe visitar estos pueblos, lo que hago cada verano.*\n\n**2.**\n- *con el que sueño* : le verbe se construit avec *con* ; la préposition précède le relatif, avec l'article.\n- *cuyas casas* : « dont » possessif, accordé avec *casas* (féminin pluriel).\n- *que vive allí* : cas général, relative déterminative.\n- *, quien nació allí,* : personne, relative explicative.\n- *en la que jugaba* : préposition devant le relatif.\n- *El que quiere* : antécédent implicite (« celui qui »).\n- *lo que hago* : reprend une idée entière (visiter ces villages).\n\n**3.** *Cuyo* n'est **jamais** suivi d'un article : il joue lui-même le rôle de déterminant."}$exo$::jsonb),
  ('95448687-5aa2-5519-863b-9f293e43cc79'::uuid, 1, 'traduction', $exo${"titre":"Quelqu'un, personne, quelque chose, rien","consigne":"Complète avec l'indéfini qui convient.","enonce":"**1. Complète** avec *alguien, nadie, algo, nada, algún, ningún* :\n\na) ¿Hay … en casa? — No, no hay …\nb) ¿Quieres … de beber? — No, no quiero …\nc) ¿Tienes … libro de Borges? — No, no tengo … libro de él.\n\n**2. Traduis :**\na) Je ne vois personne.\nb) tous les élèves\nc) chaque jour","bareme":[{"critere":"Six indéfinis justes : alguien, nadie, algo, nada, algún, ningún","points":12},{"critere":"No veo a nadie avec la préposition a","points":4},{"critere":"Todos los alumnos et cada día justes","points":4}],"dureeMin":7,"corrige":"**1.**\na) *¿Hay **alguien** en casa? — No, no hay **nadie**.* (personne)\nb) *¿Quieres **algo** de beber? — No, no quiero **nada**.* (chose)\nc) *¿Tienes **algún** libro de Borges? — No, no tengo **ningún** libro de él.* — *alguno* et *ninguno* s'apocopent devant un masculin singulier.\n\n**2.**\na) *No veo a nadie.* — avec un COD de personne, la préposition *a* est obligatoire ; double négation.\nb) *todos los alumnos* — *todo* exige l'article.\nc) *cada día* — *cada* est invariable."}$exo$::jsonb),
  ('95448687-5aa2-5519-863b-9f293e43cc79'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de la colonie","consigne":"Corrige les erreurs du règlement, puis traduis les phrases demandées.","enonce":"**Document.** Voici le règlement d'une colonie de vacances à Asturias. Il contient **cinq erreurs** d'indéfinis.\n\n> Todos días, cada uno hace su cama. Cadas dos horas, hay una pausa. Ningunos chicos pueden salir solos. Cualquiera día puedes llamar a tus padres. Un otro monitor vigila la piscina.\n\n1. Recopie le règlement corrigé.\n2. Traduis :\na) N'importe qui peut participer.\nb) Les autres sont à la plage.\nc) Je n'ai aucun doute (en plaçant l'indéfini après le nom).","bareme":[{"critere":"Cinq corrections justes : todos los días, cada, ningún chico, cualquier, otro","points":10},{"critere":"Cualquiera puede participar et los demás justes","points":5},{"critere":"No tengo duda alguna, sens négatif de alguno postposé","points":5}],"dureeMin":10,"corrige":"**1.** *Todos **los** días, cada uno hace su cama. **Cada** dos horas, hay una pausa. **Ningún chico puede** salir solo. **Cualquier** día puedes llamar a tus padres. **Otro** monitor vigila la piscina.*\n- *todo* exige l'article ;\n- *cada* est invariable, jamais de pluriel ;\n- *ninguno* s'emploie presque toujours au **singulier** et s'apocope devant un masculin ;\n- *cualquiera* s'apocope en *cualquier* devant un nom ;\n- jamais d'article indéfini devant *otro*.\n\n**2.**\na) *Cualquiera puede participar.* — seul, *cualquiera* garde le -a.\nb) *Los demás están en la playa.*\nc) *No tengo duda alguna.* — placé **après** le nom, *alguno* prend un sens **négatif renforcé**."}$exo$::jsonb),
  ('95448687-5aa2-5519-863b-9f293e43cc79'::uuid, 3, 'traduction', $exo${"titre":"Un jour de pluie à la maison","consigne":"Traduis le texte, puis justifie cinq indéfinis de ta traduction.","enonce":"**Texte à traduire.**\n\n> Il pleut toute la journée. Personne ne sort. Quelqu'un frappe à la porte, mais ce n'est personne d'important : c'est un voisin qui cherche quelque chose. Chacun lit un livre. Mes deux sœurs jouent aux cartes ; les autres regardent un film. N'importe quel film nous va. Je n'ai aucune envie de travailler.\n\nVocabulaire : *frapper* = llamar, *envie* = ganas (féminin pluriel : *tener ganas de*).\n\n1. Traduis le texte.\n2. Justifie **cinq** indéfinis (accord, apocope, préposition, double négation, place).\n3. Quelle différence de sens y a-t-il entre *cada día* et *todos los días* ?","bareme":[{"critere":"Todo el día, nadie, alguien, algo, cada uno justes","points":6},{"critere":"Ambas (las dos), los demás, cualquier película justes","points":4},{"critere":"Double négation avec ningunas ganas ou ninguna gana (no tengo…)","points":3},{"critere":"Cinq justifications exactes","points":5},{"critere":"Nuance cada día / todos los días","points":2}],"dureeMin":16,"corrige":"**1.** Traduction attendue :\n*Llueve todo el día. Nadie sale (No sale nadie). Alguien llama a la puerta, pero no es nadie importante: es un vecino que busca algo. Cada uno lee un libro. Mis dos hermanas (ambas) juegan a las cartas; los demás ven una película. Cualquier película nos vale. No tengo ningunas ganas de trabajar (No tengo ninguna gana de trabajar).*\n\n**2.** Justifications possibles :\n- *todo el día* : *todo* s'accorde et exige l'article.\n- *Nadie sale* : mot négatif avant le verbe, pas de *no* ; *no es nadie* : double négation.\n- *alguien*, *algo* : invariables.\n- *cada uno* : « chacun », *cada* invariable.\n- *los demás* : les autres, le reste.\n- *cualquier película* : apocope devant un nom, même féminin.\n- *ningunas ganas* : accord avec *ganas* (féminin pluriel, nom toujours pluriel), double négation.\n\n**3.** *Cada día* **détaille** jour après jour ; *todos los días* insiste sur **l'ensemble** des jours."}$exo$::jsonb),
  ('1118b44c-8aea-534d-a58d-1858819ac4b3'::uuid, 1, 'traduction', $exo${"titre":"Plus, moins, aussi, autant","consigne":"Complète avec la structure de comparaison qui convient.","enonce":"**1. Complète :**\n\na) Pablo es … alto … Luis. (plus… que)\nb) Tengo … dinero … tú. (moins… que)\nc) Marta es … simpática … su hermana. (aussi… que)\nd) Tengo … libros … tú. (autant de… que)\ne) Trabaja … yo. (autant que)\n\n**2.** Donne le comparatif irrégulier de : *bueno*, *malo*.\n\n**3.** Corrige : *Este helado es más mejor.*","bareme":[{"critere":"Cinq comparaisons justes : más que, menos que, tan como, tantos como, tanto como","points":12},{"critere":"Mejor et peor","points":4},{"critere":"Correction : es mejor, jamais más mejor","points":4}],"dureeMin":7,"corrige":"**1.**\na) *Pablo es **más** alto **que** Luis.*\nb) *Tengo **menos** dinero **que** tú.*\nc) *Marta es **tan** simpática **como** su hermana.* — *tan* devant un adjectif.\nd) *Tengo **tantos** libros **como** tú.* — *tanto* devant un nom, accordé (*libros*, masculin pluriel).\ne) *Trabaja **tanto como** yo.* — après un verbe, *tanto como* invariable.\n\n**2.** *bueno* → **mejor** ; *malo* → **peor**.\n\n**3.** *Este helado es **mejor**.* — les comparatifs irréguliers ne s'emploient **jamais** avec *más*."}$exo$::jsonb),
  ('1118b44c-8aea-534d-a58d-1858819ac4b3'::uuid, 2, 'traduction', $exo${"titre":"Pablo contre Inés","consigne":"Lis le tableau et rédige les comparaisons demandées en espagnol.","enonce":"**Document.** Deux élèves de 3e comparent leur semaine.\n\n| | Pablo | Inés |\n| Âge | 15 ans | 14 ans |\n| Heures de sport | 6 h | 6 h |\n| Livres lus ce mois-ci | 2 | 5 |\n| Taille | 1,70 m | 1,70 m |\n| Note en maths | 12 | 16 |\n\n1. Écris **cinq phrases** de comparaison, une par ligne du tableau. Emploie au moins : *más… que*, *menos… que*, *tan… como*, *tanto(s)… como* et *mayor* ou *menor*.\n2. Traduis : *Inés a lu plus de quatre livres.*","bareme":[{"critere":"Supériorité et infériorité justes avec que","points":5},{"critere":"Égalité juste : tan alto como et tanto deporte ou tantas horas como","points":6},{"critere":"Mayor ou menor pour l'âge","points":4},{"critere":"Más de devant un nombre","points":5}],"dureeMin":10,"corrige":"**1.** Exemples de phrases attendues :\n- Âge : *Pablo es **mayor que** Inés.* / *Inés es menor que Pablo.* — *mayor* et *menor* pour l'âge.\n- Sport : *Pablo hace **tantas horas** de deporte **como** Inés.* (ou *Pablo hace deporte **tanto como** Inés*) — égalité avec un nom : *tanto* accordé ; avec un verbe : *tanto como*.\n- Livres : *Pablo lee **menos** libros **que** Inés.* / *Inés lee más libros que Pablo.*\n- Taille : *Pablo es **tan** alto **como** Inés.* — égalité avec un adjectif : *tan… como*.\n- Maths : *Inés tiene una nota **mejor que** Pablo.* (ou *más alta que*) — jamais « más mejor ».\n\n**2.** *Inés ha leído **más de** cuatro libros.* — devant un nombre, on emploie **de** et non *que*."}$exo$::jsonb),
  ('1118b44c-8aea-534d-a58d-1858819ac4b3'::uuid, 3, 'traduction', $exo${"titre":"Plus difficile qu'il n'y paraît","consigne":"Traduis, puis explique les pièges de chaque phrase.","enonce":"**1. Traduis** ces phrases d'un article sur le brevet :\n\na) L'examen est plus difficile qu'il n'y paraît.\nb) Je n'ai que dix euros pour acheter les livres.\nc) Je n'ai pas plus de dix euros.\nd) Il fait de plus en plus chaud en juin.\ne) Les élèves ont plus de temps qu'ils ne le disent.\nf) Mon frère aîné travaille autant que moi, mais il a de moins bonnes notes.\n\n**2.** Explique la différence de sens entre b) et c) et la construction qui les distingue.\n\n**3.** Explique pourquoi on écrit *de lo que* en a) et *del que* en e).","bareme":[{"critere":"Más difícil de lo que parece et más tiempo del que dicen justes","points":5},{"critere":"No tengo más que diez euros et no tengo más de diez euros justes","points":5},{"critere":"Cada vez más calor, hermano mayor, tanto como, peores notas justes","points":5},{"critere":"Différence de sens b / c expliquée","points":3},{"critere":"De lo que (idée) / del que (nom masculin) expliqué","points":2}],"dureeMin":16,"corrige":"**1.**\na) *El examen es más difícil **de lo que** parece.*\nb) *No tengo **más que** diez euros para comprar los libros.*\nc) *No tengo **más de** diez euros.*\nd) *Hace **cada vez más** calor en junio.*\ne) *Los alumnos tienen más tiempo **del que** dicen.*\nf) *Mi hermano **mayor** trabaja **tanto como** yo, pero tiene **peores** notas.*\n\n**2.** b) *no… más que* + nombre = **seulement** (« je n'ai que dix euros ») ; c) *no… más de* + nombre = **pas plus de** (plafond). La seule différence, *que* ou *de*, change le sens.\n\n**3.** Quand le second terme de la comparaison est une **proposition**, on emploie *de lo que*, *del que*, *de la que* : *de lo que* reprend une idée ou un adjectif (a : *difícil*) ; *del que* s'accorde avec un nom masculin exprimé (e : *tiempo*)."}$exo$::jsonb),
  ('2bd4b6df-bb1f-53fb-b7ff-cd33dad0cf60'::uuid, 1, 'traduction', $exo${"titre":"Le suffixe -ísimo","consigne":"Forme le superlatif absolu en -ísimo, puis traduis.","enonce":"**1. Forme le superlatif absolu** en *-ísimo* :\n\na) guapo\nb) rico\nc) largo\nd) feliz\ne) blanco\nf) fácil\n\n**2. Traduis :** *C'est le plus grand pays d'Amérique du Sud.* (le pays = el país)\n\n**3.** Corrige : *Es muy guapísimo.*","bareme":[{"critere":"Six formes justes avec les changements orthographiques (qu, gu, c)","points":12},{"critere":"Superlatif relatif avec de : el país más grande de","points":5},{"critere":"Correction : muy et -ísimo ne se cumulent pas","points":3}],"dureeMin":7,"corrige":"**1.**\na) *guapísimo*\nb) *riquísimo* — c devient **qu** pour garder le son.\nc) *larguísimo* — g devient **gu**.\nd) *felicísimo* — z devient **c**.\ne) *blanquísimo* — c devient **qu**.\nf) *facilísimo* — l'accent se déplace sur *-ísimo*.\n\n**2.** *Es el país más grande **de** América del Sur.* — le superlatif relatif se construit avec **de**, jamais avec *en*.\n\n**3.** *Es guapísimo.* ou *Es muy guapo.* — les deux formes de l'absolu ne se cumulent jamais."}$exo$::jsonb),
  ('2bd4b6df-bb1f-53fb-b7ff-cd33dad0cf60'::uuid, 2, 'traduction', $exo${"titre":"Les records de la classe","consigne":"Lis le document, puis rédige les phrases demandées en espagnol.","enonce":"**Document.** Résultats du cross du collège, classe de 3e B.\n\n| Élève | Temps | Âge |\n| Adrián | 12 min | 14 ans |\n| Sofía | 10 min | 15 ans |\n| Leo | 15 min | 14 ans |\n\n1. Écris **trois phrases** au superlatif relatif : l'élève le plus rapide de la classe, le plus lent, la plus âgée. (*rápido*, *lento*)\n2. Sofía dit que la course était *muy larga* et *muy difícil*. Réécris ces deux adjectifs avec *-ísimo*.\n3. Donne le superlatif savant de *bueno* et de *malo*, puis écris une phrase avec l'un d'eux.","bareme":[{"critere":"Trois superlatifs relatifs justes avec de la clase","points":9},{"critere":"Larguísima et dificilísima justes","points":6},{"critere":"Óptimo et pésimo avec une phrase correcte","points":5}],"dureeMin":10,"corrige":"**1.**\n- *Sofía es la alumna más rápida de la clase.*\n- *Leo es el alumno más lento de la clase.*\n- *Sofía es la (alumna) mayor de la clase.* ou *la más mayor* (courant). On attend **de la clase**, jamais *en la clase*.\n\n**2.** *larguísima* (g devient **gu**, accord au féminin) ; *dificilísima* (accord au féminin).\n\n**3.** *bueno* → **óptimo** ; *malo* → **pésimo**. Exemple : *El tiempo fue pésimo: llovió todo el día.* — registre soutenu."}$exo$::jsonb),
  ('2bd4b6df-bb1f-53fb-b7ff-cd33dad0cf60'::uuid, 3, 'traduction', $exo${"titre":"La critique gastronomique","consigne":"Corrige les erreurs en justifiant, puis rédige une courte critique en espagnol.","enonce":"**1. Chaque phrase contient une erreur.** Corrige-la et explique.\n\na) Es el restaurante más caro en la ciudad.\nb) La paella estaba muy riquísima.\nc) El postre era ricísimo.\nd) Es el plato más bueno del menú. (utilise le comparatif irrégulier)\n\n**2. Production (50 mots environ).** Tu as mangé dans un restaurant de Madrid. Rédige une critique en employant :\n- deux superlatifs relatifs avec **de** ;\n- trois superlatifs absolus en **-ísimo**, dont un avec changement orthographique ;\n- un superlatif savant (*óptimo*, *pésimo*, *máximo*, *mínimo*).","bareme":[{"critere":"Quatre corrections justes : de la ciudad, riquísima, riquísimo, el mejor plato","points":6},{"critere":"Quatre explications exactes","points":4},{"critere":"Deux superlatifs relatifs avec de","points":4},{"critere":"Trois -ísimo justes, dont un changement orthographique, et un superlatif savant","points":5},{"critere":"Critique compréhensible","points":1}],"dureeMin":15,"corrige":"**1.**\na) *Es el restaurante más caro **de** la ciudad.* — le complément du superlatif relatif se construit avec *de*, jamais *en*.\nb) *La paella estaba **riquísima**.* — *muy* et *-ísimo* ne se cumulent pas.\nc) *El postre era **riquísimo**.* — c devient *qu* pour garder le son [k].\nd) *Es **el mejor** plato del menú.* — *bueno* a un comparatif irrégulier : *mejor* ; « más bueno » est évité.\n\n**2.** Exemple :\n*Ayer cené en el restaurante más famoso del barrio. La tortilla estaba riquísima y el pan, blanquísimo, era buenísimo. Es el mejor restaurante de Madrid, pero el servicio fue lentísimo. Precio: el mínimo para un sitio así. Calidad: óptima.*\nOn vérifie : *más famoso del barrio*, *el mejor… de Madrid* (relatif + de) ; *riquísima*, *blanquísimo* (changements c → qu), *lentísimo* ; superlatif savant *mínimo* / *óptima*."}$exo$::jsonb),
  ('b4544d40-42f4-515e-ac23-81a8a85aa331'::uuid, 1, 'traduction', $exo${"titre":"Le mot qui perd sa fin","consigne":"Complète chaque groupe avec la forme qui convient du mot entre parenthèses. Attention : l'apocope n'est pas toujours possible.","enonce":"**Complète** avec la bonne forme :\n\na) (bueno) un … amigo\nb) (primero) el … día del mes\nc) (grande) una … ciudad\nd) (ciento) … euros\ne) (santo) … Pedro\nf) (ninguno) … problema\ng) (tercero) la … vez\nh) (cualquiera) … día\ni) (alguno) … día\nj) (malo) … tiempo","bareme":[{"critere":"Apocopes devant un nom masculin singulier justes : buen, primer, ningún, algún, mal","points":10},{"critere":"Apocopes particulières justes : gran (devant un féminin), cien, San, cualquier","points":7},{"critere":"Tercera gardée entière devant un féminin, accents de ningún et algún écrits","points":3}],"dureeMin":6,"corrige":"a) un **buen** amigo — *bueno* s'apocope devant un nom masculin singulier.\nb) el **primer** día del mes — même règle.\nc) una **gran** ciudad — *grande* devient *gran* devant un nom singulier, **masculin ou féminin**.\nd) **cien** euros — *ciento* devient *cien* devant un nom.\ne) **San** Pedro — *santo* devient *san* devant un prénom masculin.\nf) **ningún** problema — avec l'accent écrit.\ng) la **tercera** vez — devant un **féminin**, rien ne change : pas d'apocope.\nh) **cualquier** día — *cualquiera* devient *cualquier* devant tout nom.\ni) **algún** día — avec l'accent écrit.\nj) **mal** tiempo — *malo* s'apocope devant un nom masculin singulier."}$exo$::jsonb),
  ('b4544d40-42f4-515e-ac23-81a8a85aa331'::uuid, 2, 'traduction', $exo${"titre":"Le guide de voyage de Clara","consigne":"Traduis les phrases en espagnol en appliquant les règles de l'apocope, puis réponds à la question.","enonce":"**Situation.** Clara prépare un petit guide pour un voyage de classe en République dominicaine.\n\n**1. Traduis en espagnol :**\n\na) Le premier jour, nous visitons Saint-Domingue (*Santo Domingo*).\nb) Un bon guide coûte cent euros.\nc) Cent vingt élèves participent au voyage.\nd) Lucas est le premier de la classe.\ne) C'est une grande femme (= une femme importante).\nf) Il y a de grands musées (*museos*).\n\n**2.** Explique la différence de sens entre *un gran hombre* et *un hombre grande*.","bareme":[{"critere":"Apocopes justes : primer día, buen guía, cien euros, gran mujer","points":8},{"critere":"Exceptions respectées : Santo Domingo, ciento veinte, el primero sans nom, grandes au pluriel","points":8},{"critere":"Différence de sens gran devant / grande derrière expliquée","points":4}],"dureeMin":10,"corrige":"**1.**\na) *El **primer** día visitamos **Santo** Domingo.* — *primer* devant un masculin singulier ; *Santo* garde sa forme devant **Do-** (exception).\nb) *Un **buen** guía cuesta **cien** euros.* — *buen* devant un masculin ; *cien* devant un nom.\nc) ***Ciento** veinte alumnos participan en el viaje.* — *ciento* reste entier devant un autre nombre.\nd) *Lucas es **el primero** de la clase.* — pas de nom juste derrière : forme pleine.\ne) *Es una **gran** mujer.* — *gran* devant un nom singulier, même féminin.\nf) *Hay **grandes** museos.* — au **pluriel**, la forme entière revient.\n\n**2.** Le sens change avec la place : ***gran*** placé **devant** le nom signifie « important, remarquable » (*un gran hombre* = un grand homme) ; ***grande*** placé **derrière** signifie « de grande taille » (*un hombre grande* = un homme grand)."}$exo$::jsonb),
  ('b4544d40-42f4-515e-ac23-81a8a85aa331'::uuid, 3, 'traduction', $exo${"titre":"Le blog de voyage à corriger","consigne":"Corrige le texte en justifiant chaque correction, puis rédige un court paragraphe en espagnol.","enonce":"**Document.** Théo a écrit ce paragraphe en espagnol sur son blog de voyage. Il contient **sept erreurs** liées à l'apocope.\n\n> El primero día de mi viaje, visité la iglesia de San Tomás en Santo Domingo. Es una grande ciudad de más de ciento mil habitantes. Mis amigos dominicanos son grans personas. Cualquiera día es bueno para ir a la playa. Nuestro guía es un hombre buen y simpático.\n\n1. Recopie le texte corrigé.\n2. Pour **cinq** erreurs, explique la règle en une phrase.\n3. Rédige un paragraphe de 40 mots environ sur ta ville ou ton village. Tu dois employer : *buen* ou *mal*, *gran*, *primer* ou *tercer*, *cien* et un adjectif placé **après** le nom qui garde donc sa forme pleine.","bareme":[{"critere":"Les sept erreurs corrigées : primer, Santo Tomás, gran ciudad, cien mil, grandes, cualquier, hombre bueno","points":7},{"critere":"Cinq règles expliquées avec justesse","points":5},{"critere":"Production : buen ou mal, gran, primer ou tercer et cien employés correctement","points":6},{"critere":"Production : adjectif placé après le nom sans apocope, texte compréhensible","points":2}],"dureeMin":16,"corrige":"**1.** *El **primer** día de mi viaje, visité la iglesia de **Santo** Tomás en Santo Domingo. Es una **gran** ciudad de más de **cien** mil habitantes. Mis amigos dominicanos son **grandes** personas. **Cualquier** día es bueno para ir a la playa. Nuestro guía es un hombre **bueno** y simpático.*\n\n**2.** Règles attendues (cinq parmi) :\n- *primero* devient *primer* devant un nom masculin singulier : *el primer día*.\n- *santo* devient *san* devant un prénom masculin, **sauf** devant To- et Do- : *Santo Tomás*.\n- *grande* devient *gran* devant un nom singulier, masculin ou féminin : *una gran ciudad*.\n- *ciento* devient *cien* devant *mil* et *millones* : *cien mil*.\n- Au **pluriel**, la forme entière revient : *grandes personas* (« grans » n'existe pas).\n- *cualquiera* devient *cualquier* devant tout nom : *cualquier día*.\n- L'apocope ne joue que si l'adjectif est **immédiatement devant** le nom : *un hombre bueno*.\n\n**3.** Exemple de production :\n*Vivo en un pueblo pequeño. Hay un buen mercado los sábados y una gran plaza con una iglesia antigua. Mi casa está en el primer piso de un edificio de cien años. Hoy hace mal tiempo, pero es un pueblo bonito.*\nOn vérifie : *buen mercado*, *mal tiempo*, *gran plaza*, *primer piso*, *cien años*, et un adjectif après le nom (*una iglesia antigua*, *un pueblo bonito*)."}$exo$::jsonb),
  ('645ef08c-7822-5572-9c5b-8631ea834298'::uuid, 1, 'traduction', $exo${"titre":"Haber, hay ou está ?","consigne":"Conjugue les verbes au passé composé (pretérito perfecto), puis complète avec hay ou está.","enonce":"**1. Conjugue au pretérito perfecto** (haber au présent + participe passé) :\n\na) yo (comer)\nb) tú (hablar)\nc) ella (llegar)\nd) nosotros (vivir)\ne) ellos (terminar)\n\n**2. Complète avec *hay* ou *está* :**\n\na) En mi calle … una panadería.\nb) La panadería … al lado del cine.\nc) … muchos alumnos en el patio.\nd) ¿Dónde … el libro de Ana?\ne) … dos parques en el barrio.","bareme":[{"critere":"Cinq formes du pretérito perfecto justes (he comido, has hablado, ha llegado, hemos vivido, han terminado)","points":10},{"critere":"Hay pour l'existence, invariable même au pluriel ; está pour la localisation d'une chose connue","points":10}],"dureeMin":6,"corrige":"**1.**\na) **he comido**\nb) **has hablado**\nc) **ha llegado** — pas d'auxiliaire « être » en espagnol : *haber* partout.\nd) **hemos vivido**\ne) **han terminado**\nLe participe ne s'accorde jamais avec *haber*.\n\n**2.**\na) En mi calle **hay** una panadería. — existence d'une chose non encore identifiée.\nb) La panadería **está** al lado del cine. — localisation d'une chose déjà connue (*la* panadería).\nc) **Hay** muchos alumnos en el patio. — *hay* est **invariable**, même devant un pluriel.\nd) ¿Dónde **está** el libro de Ana? — on cherche où se trouve un objet précis.\ne) **Hay** dos parques en el barrio."}$exo$::jsonb),
  ('645ef08c-7822-5572-9c5b-8631ea834298'::uuid, 2, 'traduction', $exo${"titre":"Le journal de Sofía","consigne":"Transforme les phrases puis traduis en espagnol, en respectant les deux règles de l'auxiliaire unique.","enonce":"**Situation.** Sofía, 14 ans, raconte sa semaine dans son journal.\n\n**1. Mets au pretérito perfecto** (participes donnés quand ils sont irréguliers) :\n\na) Nunca visito Madrid.\nb) Mis amigas llegan tarde.\nc) No lo veo (*visto*).\nd) La carta que escribo (*escrito*) es larga.\n\n**2. Traduis en espagnol :**\n\na) Il y avait beaucoup d'élèves à la fête.\nb) Il y aura un concert samedi.\nc) Il faut étudier pour réussir.\nd) Quand je suis arrivée, il était déjà sorti (*salir*).","bareme":[{"critere":"Pretérito perfecto juste, sans accord du participe (han llegado, he escrito)","points":6},{"critere":"Bloc haber + participe soudé : négation, pronom et nunca placés devant","points":4},{"critere":"Formes de hay justes : había, habrá, et hay que + infinitif","points":6},{"critere":"Plus-que-parfait juste : había salido","points":4}],"dureeMin":11,"corrige":"**1.**\na) ***Nunca he visitado** Madrid* (ou *No he visitado nunca Madrid*) — jamais « he nunca visitado » : le bloc est soudé.\nb) *Mis amigas **han llegado** tarde.* — le participe ne s'accorde pas : jamais « llegadas ».\nc) ***No lo he visto.*** — la négation et le pronom se placent **devant** l'auxiliaire.\nd) *La carta que **he escrito** es larga.* — aucun accord, même avec un complément placé avant : jamais « escrita ».\n\n**2.**\na) ***Había** muchos alumnos en la fiesta.* — imparfait de *hay*, invariable.\nb) ***Habrá** un concierto el sábado.* — futur de *hay*.\nc) ***Hay que** estudiar para aprobar.* — obligation impersonnelle.\nd) *Cuando llegué, ya **había salido**.* — plus-que-parfait : *había* + participe."}$exo$::jsonb),
  ('645ef08c-7822-5572-9c5b-8631ea834298'::uuid, 3, 'traduction', $exo${"titre":"Le déménagement à Séville","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Inès raconte son déménagement à Séville. Son texte contient **six erreurs** liées à *haber*.\n\n> Este año, hemos nos mudado a Sevilla. Mi madre ha encontrada un trabajo en un hospital. En nuestro barrio hay dos parques y está un cine. Han habido muchos cambios en mi vida. Mis hermanas han llegadas en septiembre. He nunca visto una ciudad tan bonita.\n\n1. Recopie le texte corrigé.\n2. Pour **quatre** erreurs, explique la règle en une phrase.\n3. Rédige 5 phrases en espagnol (45 mots environ) sur un changement dans ta vie (nouvelle école, nouveau sport…). Tu dois employer : un pretérito perfecto à la forme négative, un plus-que-parfait (*había* + participe), *hay* ou *había* pour l'existence, *habrá* et *hay que* + infinitif.","bareme":[{"critere":"Six erreurs corrigées : nos hemos mudado, encontrado, hay un cine, ha habido, llegado, nunca he visto","points":6},{"critere":"Quatre règles expliquées avec justesse (auxiliaire unique, pas d'accord, bloc soudé, hay invariable, hay / está)","points":4},{"critere":"Production : pretérito perfecto négatif et plus-que-parfait justes","points":5},{"critere":"Production : hay ou había, habrá et hay que employés correctement","points":5}],"dureeMin":17,"corrige":"**1.** *Este año, **nos hemos mudado** a Sevilla. Mi madre ha **encontrado** un trabajo en un hospital. En nuestro barrio hay dos parques y **hay** un cine. **Ha habido** muchos cambios en mi vida. Mis hermanas han **llegado** en septiembre. **Nunca he visto** (ou *No he visto nunca*) una ciudad tan bonita.*\n\n**2.** Règles attendues (quatre parmi) :\n- Le bloc *haber* + participe est **soudé** : le pronom se place devant (*nos hemos mudado*), l'adverbe aussi (*nunca he visto*).\n- Le participe **ne s'accorde jamais** avec *haber* : *encontrado*, *llegado*.\n- *Hay* (et ses formes, *ha habido*) est **invariable** : jamais « han habido ».\n- *Hay* pose l'**existence** d'une chose non identifiée (*un cine*) ; *está* donne la localisation d'une chose connue.\n\n**3.** Exemple de production :\n*Este año he cambiado de instituto. Todavía no he hecho muchos amigos. Antes de llegar, nunca había visto un instituto tan grande: hay mil alumnos. El próximo mes habrá una excursión. Hay que estudiar mucho, pero me gusta.*\nOn vérifie : *no he hecho* (négatif), *había visto* (plus-que-parfait), *hay mil alumnos*, *habrá*, *hay que estudiar*, sans accord du participe."}$exo$::jsonb),
  ('0be4629e-2624-5a27-9f8d-8e6876100948'::uuid, 1, 'traduction', $exo${"titre":"Le pronom à sa place","consigne":"Complète avec le verbe pronominal à la forme demandée, en plaçant correctement le pronom, puis traduis.","enonce":"**1. Complète :**\n\na) (levantarse, yo, présent) … a las siete.\nb) (ducharse) Voy a … ahora.\nc) (levantarse, tú, impératif) ¡… ya!\nd) (peinarse) Mi hermana está … .\ne) (lavarse, nosotros, présent) … las manos antes de comer.\n\n**2. Traduis en espagnol :**\n\na) Je m'en vais.\nb) Tu te souviens de Marta ? (*acordarse de*)\nc) Ils s'écrivent tous les jours.","bareme":[{"critere":"Pronom devant le verbe conjugué : me levanto, nos lavamos","points":6},{"critere":"Pronom soudé derrière l'infinitif, le gérondif et l'impératif : ducharme, peinándose, levántate","points":8},{"critere":"Traductions justes : me voy, te acuerdas de, se escriben","points":6}],"dureeMin":7,"corrige":"**1.**\na) **Me levanto** a las siete. — verbe conjugué : pronom **devant**.\nb) Voy a **ducharme** ahora. — infinitif : pronom **soudé derrière** (on accepte aussi *Me voy a duchar*, avec un semi-auxiliaire).\nc) ¡**Levántate** ya! — impératif affirmatif : pronom soudé, accent écrit ajouté.\nd) Mi hermana está **peinándose**. — gérondif : pronom soudé (ou *se está peinando*).\ne) **Nos lavamos** las manos antes de comer.\n\n**2.**\na) ***Me voy.*** — *irse* = partir.\nb) *¿**Te acuerdas de** Marta?* — *acordarse de* = se souvenir de.\nc) ***Se escriben** todos los días.* — valeur **réciproque**."}$exo$::jsonb),
  ('0be4629e-2624-5a27-9f8d-8e6876100948'::uuid, 2, 'traduction', $exo${"titre":"Les cinq visages de se","consigne":"Identifie la valeur de se dans chaque phrase et traduis-la, puis écris les phrases demandées.","enonce":"**Situation.** En se promenant dans Salamanque, Yanis note des phrases entendues ou lues sur les murs.\n\n**1. Pour chaque phrase**, donne la valeur de *se* (réfléchie, réciproque, lexicale, passive, impersonnelle) et traduis :\n\na) Se venden pisos.\nb) Aquí se habla inglés.\nc) Pablo y Lucía se quieren mucho.\nd) El niño se lava la cara.\ne) Mi abuela se queja siempre.\n\n**2. Écris en espagnol**, avec une tournure en *se* :\n\na) On vend des vélos (*bicicletas*).\nb) Ici on mange bien.\nc) Il s'est enfilé toute la pizza (passé simple : *comió*).","bareme":[{"critere":"Cinq valeurs de se identifiées correctement","points":7},{"critere":"Cinq traductions justes","points":5},{"critere":"Passive accordée au pluriel (se venden) et impersonnelle au singulier (se come)","points":6},{"critere":"Pronominal d'intensité juste : se comió toda la pizza","points":2}],"dureeMin":11,"corrige":"**1.**\na) *Se venden pisos* — **passive** : le verbe s'accorde avec *pisos* → « Appartements à vendre ».\nb) *Aquí se habla inglés* — **impersonnelle** : verbe au singulier → « Ici, on parle anglais ».\nc) *Pablo y Lucía se quieren mucho* — **réciproque** → « Pablo et Lucía s'aiment beaucoup ».\nd) *El niño se lava la cara* — **réfléchie** : l'action revient sur le sujet → « L'enfant se lave le visage ».\ne) *Mi abuela se queja siempre* — **lexicale** : *quejarse* n'existe qu'à la forme pronominale → « Ma grand-mère se plaint toujours ».\n\n**2.**\na) ***Se venden** bicicletas.* — passive : accord au pluriel avec *bicicletas*.\nb) *Aquí **se come** bien.* — impersonnelle : singulier.\nc) ***Se comió** toda la pizza.* — pronominal d'intensité : nuance d'appropriation, sans valeur réfléchie."}$exo$::jsonb),
  ('0be4629e-2624-5a27-9f8d-8e6876100948'::uuid, 3, 'traduction', $exo${"titre":"Le matin de Léna","consigne":"Traduis le texte en espagnol, justifie trois choix, puis rédige un court texte.","enonce":"**Document.** Léna raconte ses matins.\n\n> « Tous les matins, je me réveille à sept heures, mais je reste au lit dix minutes. Ensuite, je me douche et je m'habille. Mon frère et moi, nous nous disputons souvent. Hier, il s'est enfilé tout le gâteau ! Dans mon quartier, on vend des maisons anciennes. Je m'en vais à huit heures. »\n\nAide : *despertarse* (e → ie), *quedarse*, *ducharse*, *vestirse* (me visto), *pelearse*, *venderse*, *irse* ; « il s'est enfilé » au passé simple : *comió*.\n\n1. Traduis le texte en espagnol.\n2. Justifie en une phrase chacun de ces choix : la traduction de « je reste », celle de « on vend des maisons », celle de « Je m'en vais ».\n3. Rédige 5 phrases en espagnol (45 mots environ) sur ta routine du week-end. Tu dois employer : un verbe pronominal conjugué, un pronom soudé à un infinitif, un emploi réciproque, un *se* impersonnel ou passif, et un verbe dont le sens change avec le pronom (*irse, dormirse, quedarse, ponerse*…).","bareme":[{"critere":"Traduction : pronoms réfléchis justes et bien placés (me despierto, me ducho, me visto, nos peleamos)","points":6},{"critere":"Traduction : me quedo, se comió, se venden accordé, me voy","points":4},{"critere":"Trois justifications exactes appuyées sur le cours","points":4},{"critere":"Production : les cinq emplois demandés, pronoms bien placés","points":6}],"dureeMin":18,"corrige":"**1.** *Todas las mañanas **me despierto** a las siete, pero **me quedo** en la cama diez minutos. Luego **me ducho** y **me visto**. Mi hermano y yo **nos peleamos** a menudo. Ayer ¡**se comió** toda la tarta! En mi barrio **se venden** casas antiguas. **Me voy** a las ocho.*\n\n**2.**\n- « je reste » → *me quedo* : *quedar* seul veut dire « convenir » ; **quedarse** signifie « rester sur place » — le pronom change le sens.\n- « on vend des maisons » → *se venden casas* : *se* **passif**, le verbe s'accorde avec *casas*, au pluriel.\n- « Je m'en vais » → *me voy* : *ir* = aller, **irse** = partir.\n\n**3.** Exemple de production :\n*El sábado me levanto tarde. Después voy a ducharme y a desayunar. Mis amigos y yo nos llamamos para quedar. En mi pueblo se come muy bien los domingos. Por la noche, me duermo delante de la tele.*\nOn vérifie : *me levanto* (conjugué), *ducharme* (soudé à l'infinitif), *nos llamamos* (réciproque), *se come* (impersonnel, singulier), *me duermo* (s'endormir). Toute production qui contient les cinq emplois correctement est acceptée."}$exo$::jsonb),
  ('bfaa5252-9135-53e4-a918-7cae4aa7d5dc'::uuid, 1, 'traduction', $exo${"titre":"La conjugaison en botte","consigne":"Conjugue les verbes au présent de l'indicatif.","enonce":"**1. Conjugue au présent, à toutes les personnes :**\n\na) *pensar*\nb) *poder*\n\n**2. Conjugue à la personne demandée :**\n\na) yo (jugar)\nb) nosotros (volver)\nc) ellos (querer)\nd) tú (dormir)\ne) vosotros (empezar)\nf) él (oler)","bareme":[{"critere":"Pensar et poder justes aux six personnes, sans diphtongue à nosotros et vosotros","points":10},{"critere":"Six formes isolées justes : juego, volvemos, quieren, duermes, empezáis, huele","points":10}],"dureeMin":7,"corrige":"**1.**\na) *pienso, piensas, piensa, **pensamos, pensáis**, piensan*\nb) *puedo, puedes, puede, **podemos, podéis**, pueden*\nLes quatre formes qui diphtonguent dessinent une **botte** : *nosotros* et *vosotros* restent réguliers, car l'accent tonique tombe sur la terminaison.\n\n**2.**\na) yo **juego** — *jugar* est le seul verbe en u → ue.\nb) nosotros **volvemos** — pas de diphtongue.\nc) ellos **quieren** — e → ie.\nd) tú **duermes** — o → ue.\ne) vosotros **empezáis** — pas de diphtongue.\nf) él **huele** — *oler* prend un **h** quand il diphtongue."}$exo$::jsonb),
  ('bfaa5252-9135-53e4-a918-7cae4aa7d5dc'::uuid, 2, 'traduction', $exo${"titre":"La lettre de Paula","consigne":"Complète la lettre avec les verbes au présent, puis réponds aux questions.","enonce":"**Situation.** Paula écrit à sa correspondante française.\n\n> Hola Camille: Por la mañana, (despertarse, yo) … a las siete, pero mi hermano (dormir) … hasta las nueve. Nosotros (empezar) … las clases a las ocho y media. Los sábados, mis amigos y yo (jugar) … al fútbol, pero mis primos (preferir) … el baloncesto. Mi madre (cerrar) … la tienda a las ocho. En la cocina, siempre (oler) … a café. ¿(Querer, tú) … venir en verano? Yo no (poder) … ir a Francia este año.\n\n1. Recopie les verbes conjugués.\n2. Explique pourquoi *empezar* et *jugar* ne diphtonguent pas dans cette lettre.\n3. Mets au passé simple : *yo pensé* ou *yo piensé* ? Justifie.","bareme":[{"critere":"Neuf verbes justes : me despierto, duerme, empezamos, jugamos, prefieren, cierra, huele, Quieres, puedo","points":12},{"critere":"Explication : à nosotros, l'accent tonique tombe sur la terminaison, donc pas de diphtongue","points":4},{"critere":"Passé simple pensé, sans diphtongue, justifié","points":4}],"dureeMin":11,"corrige":"**1.** *me despierto* — *duerme* — *empezamos* — *jugamos* — *prefieren* — *cierra* — *huele* — *¿Quieres* — *puedo*.\n\n**2.** *Empezar* et *jugar* sont conjugués à **nosotros** (*empezamos*, *jugamos*) : à cette personne, l'accent tonique tombe sur la **terminaison** et non sur la voyelle du radical, donc la voyelle reste simple. C'est l'une des deux personnes hors de la « botte ».\n\n**3.** ***Pensé*** : la diphtongue n'apparaît qu'au présent de l'indicatif, au présent du subjonctif et à l'impératif ; **jamais** au passé simple, à l'imparfait ni au futur (*pensé, pensaba, pensaré*). De plus, l'accent tonique de *pensé* est sur la terminaison."}$exo$::jsonb),
  ('bfaa5252-9135-53e4-a918-7cae4aa7d5dc'::uuid, 3, 'traduction', $exo${"titre":"Les fautes de Hugo","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Hugo a écrit ce texte sur sa famille. Il contient **sept erreurs** de conjugaison.\n\n> Normalmente, yo me desperto a las siete. Mis padres piensan que nosotros duermemos poco. Mi hermana y yo juegamos al tenis los domingos. Ayer, yo piensé en mis abuelos. Mi perro olé todo el jardín. Tú no podes venir hoy, pero mis amigos queren verte.\n\n1. Recopie le texte corrigé.\n2. Explique la règle de la **botte** et pourquoi elle existe (3 lignes au plus).\n3. Pour **trois** autres erreurs, explique la correction en une phrase.\n4. Rédige 5 phrases en espagnol (45 mots environ) sur tes loisirs. Tu dois employer **quatre** verbes à diphtongue différents, dont un à la personne *nosotros* et *jugar*.","bareme":[{"critere":"Sept erreurs corrigées : despierto, dormimos, jugamos, pensé, huele, puedes, quieren","points":7},{"critere":"Règle de la botte expliquée par la place de l'accent tonique","points":4},{"critere":"Trois autres corrections justifiées (h de huele, jugar u → ue, pas de diphtongue au passé simple…)","points":3},{"critere":"Production : quatre verbes à diphtongue justes, nosotros sans diphtongue, jugar juste","points":6}],"dureeMin":17,"corrige":"**1.** *Normalmente, yo me **despierto** a las siete. Mis padres piensan que nosotros **dormimos** poco. Mi hermana y yo **jugamos** al tenis los domingos. Ayer, yo **pensé** en mis abuelos. Mi perro **huele** todo el jardín. Tú no **puedes** venir hoy, pero mis amigos **quieren** verte.*\n\n**2.** Quand l'accent tonique tombe sur la voyelle du radical, elle **diphtongue** (e → ie, o → ue). À *nosotros* et *vosotros*, l'accent tombe sur la **terminaison** : la voyelle reste simple. Les quatre formes qui diphtonguent (yo, tú, él, ellos) dessinent une botte autour de ces deux personnes.\n\n**3.** Corrections attendues (trois parmi) :\n- *despierto* : *despertar* diphtongue e → ie à la personne *yo*.\n- *jugamos* : *jugar* (u → ue) ne diphtongue pas à *nosotros*.\n- *pensé* : pas de diphtongue au **passé simple**.\n- *huele* : *oler* prend un **h** à l'écrit quand il diphtongue.\n- *puedes*, *quieren* : diphtongue obligatoire à *tú* et *ellos*.\n\n**4.** Exemple de production :\n*Los miércoles juego al baloncesto. Mis amigos y yo volvemos a casa a las seis. Prefiero los deportes de equipo. A veces mi hermano no puede venir y yo cuento los puntos. Los domingos empiezo a leer un libro.*\nOn vérifie : *juego*, *volvemos* (nosotros sans diphtongue), *prefiero*, *puede*, *cuento*, *empiezo*."}$exo$::jsonb),
  ('03115cee-db14-52b3-a9e4-5d8370047754'::uuid, 1, 'traduction', $exo${"titre":"La famille de pedir","consigne":"Conjugue les verbes à la forme demandée.","enonce":"**1. Conjugue *pedir* au présent de l'indicatif**, à toutes les personnes.\n\n**2. Donne la forme demandée :**\n\na) yo (seguir), présent\nb) yo (elegir), présent\nc) él (pedir), passé simple\nd) yo (pedir), passé simple\ne) le gérondif de *servir*\nf) le gérondif de *decir*","bareme":[{"critere":"Pedir juste aux six personnes, sans affaiblissement à nosotros et vosotros","points":8},{"critere":"Pièges orthographiques justes : sigo, elijo","points":4},{"critere":"Passé simple pidió / pedí et gérondifs sirviendo, diciendo justes","points":8}],"dureeMin":7,"corrige":"**1.** *pido, pides, pide, **pedimos, pedís**, piden* — le e devient i sous l'accent tonique, avec la même botte que la diphtongue.\n\n**2.**\na) **sigo** — *seguir* perd son u devant o.\nb) **elijo** — le g devient j devant o.\nc) **pidió** — au passé simple, l'affaiblissement touche les **3es personnes** (terminaison en *ió*).\nd) **pedí** — pas d'affaiblissement à la 1re personne du passé simple.\ne) **sirviendo** — le gérondif s'affaiblit toujours (terminaison en *ie*).\nf) **diciendo**"}$exo$::jsonb),
  ('03115cee-db14-52b3-a9e4-5d8370047754'::uuid, 2, 'traduction', $exo${"titre":"Au restaurant de Toledo","consigne":"Complète le texte avec les verbes au temps demandé, puis réponds à la question.","enonce":"**Situation.** Nora raconte un repas avec sa famille à Tolède.\n\n> En este restaurante, yo siempre (pedir, présent) … paella. El camarero nos (servir, présent) … muy rápido. Nosotros (repetir, présent) … el postre porque está muy rico. Ayer, mi padre (pedir, passé simple) … pescado y mis primos (pedir, passé simple) … carne. Yo (pedir, passé simple) … una ensalada. Ahora el camarero está (servir, gérondif) … el café. Espero que tú (pedir, subjonctif présent) … el flan la próxima vez.\n\n1. Recopie les huit verbes conjugués.\n2. Donne le repère du cours qui permet de savoir si *pedir* s'affaiblit au passé simple, et applique-le à *pidió* et *pedí*.","bareme":[{"critere":"Présent juste : pido, sirve, repetimos","points":5},{"critere":"Passé simple juste : pidió, pidieron, pedí","points":6},{"critere":"Gérondif sirviendo et subjonctif pidas justes","points":4},{"critere":"Repère ie / ió énoncé et appliqué","points":5}],"dureeMin":11,"corrige":"**1.** *pido* — *sirve* — *repetimos* (nosotros : pas d'affaiblissement) — *pidió* — *pidieron* — *pedí* — *sirviendo* — *pidas* (au subjonctif présent, l'affaiblissement touche **toutes** les personnes).\n\n**2.** Repère : dès que la **terminaison** contient *ie* ou *ió*, l'affaiblissement s'applique. *Pidió* se termine en *ió* : le e du radical devient i (jamais « pedió »). *Pedí* n'a ni *ie* ni *ió* dans sa terminaison : le radical reste en e. Au passé simple, seules les 3es personnes s'affaiblissent (*pidió, pidieron*)."}$exo$::jsonb),
  ('03115cee-db14-52b3-a9e4-5d8370047754'::uuid, 3, 'traduction', $exo${"titre":"La nuit agitée","consigne":"Corrige le texte, explique tes corrections, puis rédige un court récit en espagnol.","enonce":"**Document.** Adam raconte une nuit difficile. Son texte contient **sept erreurs**.\n\n> Anoche, mi hermano dormió mal y se sentió enfermo. Mi madre pedió un médico. Mis padres preferieron llamar a urgencias. Ahora mi hermano está mejor y yo sego sus consejos: estamos pediendo menos comida rápida. Para la cena de mañana, yo eligo el menú.\n\n1. Recopie le texte corrigé.\n2. Qu'est-ce qu'un verbe **mixte** ? Cite les deux verbes mixtes du texte et donne leur forme au présent (yo).\n3. Explique deux autres corrections en une phrase chacune.\n4. Rédige 5 phrases en espagnol (45 mots environ) sur un repas au restaurant, au passé simple et au présent. Tu dois employer *pedir* à la 3e personne du passé simple, un gérondif d'un verbe en *-ir* affaibli et *seguir* ou *elegir* à la 1re personne du présent.","bareme":[{"critere":"Sept erreurs corrigées : durmió, sintió, pidió, prefirieron, sigo, pidiendo, elijo","points":7},{"critere":"Verbe mixte défini, dormir et sentir cités avec duermo et siento","points":4},{"critere":"Deux autres corrections justifiées avec justesse","points":3},{"critere":"Production : pidió ou pidieron, gérondif affaibli, sigo ou elijo corrects","points":6}],"dureeMin":17,"corrige":"**1.** *Anoche, mi hermano **durmió** mal y se **sintió** enfermo. Mi madre **pidió** un médico. Mis padres **prefirieron** llamar a urgencias. Ahora mi hermano está mejor y yo **sigo** sus consejos: estamos **pidiendo** menos comida rápida. Para la cena de mañana, yo **elijo** el menú.*\n\n**2.** Un verbe **mixte** est un verbe en *-ir* qui **diphtongue au présent** et **s'affaiblit ailleurs** (passé simple aux 3es personnes, gérondif). Dans le texte : *dormir* (**duermo** / *durmió*) et *sentir* (**siento** / *sintió*) ; *preferir* aussi (**prefiero** / *prefirieron*).\n\n**3.** Corrections attendues (deux parmi) :\n- *pidió*, *pidiendo* : terminaison en *ió* ou *ie* → affaiblissement.\n- *sigo* : *seguir* perd son u devant o.\n- *elijo* : le g d'*elegir* devient j devant o.\n\n**4.** Exemple de production :\n*El sábado fuimos a un restaurante. Mi hermana pidió una pizza y mis padres pidieron pescado. El camarero estaba sirviendo el postre cuando llegó mi tío. Hoy yo elijo el restaurante. Sigo pensando en esa pizza.*\nOn vérifie : *pidió / pidieron*, *sirviendo*, *elijo*, *sigo*."}$exo$::jsonb),
  ('266b7835-4048-5395-a11c-183456b80c41'::uuid, 1, 'traduction', $exo${"titre":"Ser ou estar ?","consigne":"Complète avec ser ou estar au présent, puis traduis.","enonce":"**1. Complète avec *ser* ou *estar* au présent :**\n\na) Madrid … en España.\nb) Mi madre … profesora.\nc) Hoy … lunes.\nd) Yo … cansado.\ne) La mesa … de madera.\nf) … las tres.\ng) Nosotros … estudiando.\nh) La fiesta … en mi casa.\n\n**2. Traduis :**\n\na) Je suis d'accord.\nb) Il est malade.","bareme":[{"critere":"Ser juste pour l'identité, la profession, la date, l'heure, la matière et l'événement (es, es, son, es, es)","points":10},{"critere":"Estar juste pour la localisation, l'état et la forme progressive (está, estoy, estamos)","points":6},{"critere":"Traductions justes : estoy de acuerdo, está enfermo (ou malo)","points":4}],"dureeMin":7,"corrige":"**1.**\na) Madrid **está** en España. — localisation d'un lieu.\nb) Mi madre **es** profesora. — profession.\nc) Hoy **es** lunes. — date.\nd) Yo **estoy** cansado. — état.\ne) La mesa **es** de madera. — matière.\nf) **Son** las tres. — l'heure, avec *ser* au pluriel.\ng) Nosotros **estamos** estudiando. — forme progressive.\nh) La fiesta **es** en mi casa. — un **événement** a lieu quelque part : *ser*.\n\n**2.**\na) ***Estoy de acuerdo.*** — expression figée avec *estar*.\nb) ***Está enfermo*** (ou *Está malo*). — état de santé."}$exo$::jsonb),
  ('266b7835-4048-5395-a11c-183456b80c41'::uuid, 2, 'traduction', $exo${"titre":"La carte postale de Valence","consigne":"Complète la carte postale avec ser ou estar, puis traduis les phrases en choisissant le bon verbe.","enonce":"**Situation.** Marco envoie une carte postale à son ami Pablo.\n\n> Hola Pablo: (yo) … en Valencia con mis padres. La ciudad … muy bonita y … cerca del mar. Hoy … sábado y … las diez de la mañana. El hotel … grande, pero hoy nuestra habitación … sucia. El concierto … esta noche en la plaza. ¡(yo) … muy contento!\n\n1. Recopie les neuf verbes.\n2. **Traduis** en espagnol :\na) Il est malin. / Il est prêt.\nb) Ce garçon est ennuyeux. / Ce garçon s'ennuie.\nc) Cette paella est délicieuse.","bareme":[{"critere":"Neuf verbes justes : Estoy, es, está, es, son, es, está, es, Estoy","points":11},{"critere":"Paires listo et aburrido traduites avec le bon verbe","points":6},{"critere":"Estar rico pour délicieux","points":3}],"dureeMin":11,"corrige":"**1.** *Estoy* (localisation) — *es* (caractéristique) — *está* (localisation) — *es* (date) — *son* (heure) — *es* (caractéristique du lieu) — *está* (état constaté aujourd'hui) — *es* (un événement a lieu : *ser*) — *Estoy* (humeur).\n\n**2.**\na) ***Es listo*** (il est malin) / ***Está listo*** (il est prêt).\nb) *Este chico **es aburrido*** (ennuyeux) / *Este chico **está aburrido*** (il s'ennuie).\nc) *Esta paella **está rica**.* — *estar rico* = délicieux ; *ser rico* signifierait « être riche ».\nLes adjectifs qui changent de sens avec *ser* et *estar* sont des mots différents, pas des nuances."}$exo$::jsonb),
  ('266b7835-4048-5395-a11c-183456b80c41'::uuid, 3, 'traduction', $exo${"titre":"Les vacances de Julien","consigne":"Corrige le texte en justifiant tes choix, puis rédige un court texte en espagnol.","enonce":"**Document.** Julien raconte ses vacances. Son texte contient **sept erreurs** entre *ser* et *estar*.\n\n> Soy en Sevilla de vacaciones. Mi hermano está alto y moreno, pero hoy es cansado. Hoy está martes. La paella de mi tía es muy rica hoy. El concierto de flamenco está en el estadio. La sopa es fría porque llegamos tarde. Estamos de acuerdo: ¡Sevilla es preciosa!\n\n1. Recopie le texte corrigé.\n2. Pour **quatre** erreurs, justifie la correction en une phrase.\n3. Explique le raccourci du cours qui permet de choisir entre *ser* et *estar*.\n4. Rédige 5 phrases en espagnol (45 mots environ) pour décrire ta ville et ce que tu ressens aujourd'hui. Tu dois employer *ser* trois fois (trois emplois différents) et *estar* trois fois (localisation, état, forme progressive).","bareme":[{"critere":"Sept erreurs corrigées : Estoy, es alto, está cansado, es martes, está rica, es en el estadio, está fría","points":7},{"critere":"Quatre justifications exactes","points":4},{"critere":"Raccourci expliqué : qu'est-ce que c'est ? / comment est-ce maintenant ?","points":3},{"critere":"Production : trois emplois de ser et trois de estar justes","points":6}],"dureeMin":17,"corrige":"**1.** ***Estoy** en Sevilla de vacaciones. Mi hermano **es** alto y moreno, pero hoy **está** cansado. Hoy **es** martes. La paella de mi tía **está** muy rica hoy. El concierto de flamenco **es** en el estadio. La sopa **está** fría porque llegamos tarde. Estamos de acuerdo: ¡Sevilla es preciosa!*\n\n**2.** Justifications (quatre parmi) :\n- *Estoy en Sevilla* : localisation d'une personne → *estar*.\n- *es alto* : caractéristique qui le définit → *ser*.\n- *está cansado* : état passager, constaté → *estar*.\n- *es martes* : la date → *ser*.\n- *está rica* : *estar rico* = délicieux (*ser rico* = riche).\n- *es en el estadio* : un **événement** a lieu quelque part → *ser*.\n- *está fría* : résultat d'un changement (elle a refroidi) → *estar*.\n\n**3.** *Ser* répond à « **qu'est-ce que c'est ?** » (ce qui définit) ; *estar* répond à « **comment est-ce, en ce moment ?** » (ce qui se constate).\n\n**4.** Exemple de production :\n*Mi ciudad es pequeña y es muy antigua. Está en el norte de Francia. Hoy es viernes. Estoy un poco nervioso porque estoy preparando un examen. Mi madre es enfermera y hoy está en el hospital.*\nOn vérifie : *ser* (caractéristique, date, profession) et *estar* (localisation, état, forme progressive)."}$exo$::jsonb),
  ('1cb6784d-d42f-5c13-a42f-2ac0ce3cc2a7'::uuid, 1, 'traduction', $exo${"titre":"En train de…","consigne":"Donne le gérondif de chaque verbe, puis réponds avec estar + gérondif.","enonce":"**1. Donne le gérondif :**\n\na) *hablar*\nb) *comer*\nc) *vivir*\nd) *leer*\ne) *decir*\nf) *dormir*\ng) *ir*\nh) *oír*\n\n**2. Réponds à la question *¿Qué estás haciendo?*** avec *estar* + gérondif :\n\na) (estudiar)\nb) (escribir un mensaje)\nc) (leer un libro)","bareme":[{"critere":"Gérondifs réguliers justes : hablando, comiendo, viviendo","points":5},{"critere":"Gérondifs irréguliers justes : leyendo, diciendo, durmiendo, yendo, oyendo","points":9},{"critere":"Trois réponses justes avec estoy + gérondif","points":6}],"dureeMin":7,"corrige":"**1.**\na) **hablando** (-ar → -ando)\nb) **comiendo** (-er → -iendo)\nc) **viviendo** (-ir → -iendo)\nd) **leyendo** — *-iendo* devient *-yendo* après une voyelle.\ne) **diciendo**\nf) **durmiendo**\ng) **yendo**\nh) **oyendo**\n\n**2.**\na) ***Estoy estudiando.***\nb) ***Estoy escribiendo** un mensaje.*\nc) ***Estoy leyendo** un libro.*\nLa forme progressive se forme avec *estar* conjugué + gérondif."}$exo$::jsonb),
  ('1cb6784d-d42f-5c13-a42f-2ac0ce3cc2a7'::uuid, 2, 'traduction', $exo${"titre":"Le message d'Élise","consigne":"Traduis les phrases en espagnol en utilisant les périphrases du cours.","enonce":"**Situation.** Élise écrit à sa correspondante de Grenade pour donner de ses nouvelles.\n\n**Traduis en espagnol :**\n\na) J'étudie l'espagnol depuis trois ans. (*llevar*)\nb) Il pleut toujours à Paris. (*seguir*)\nc) Mon grand-père va mieux petit à petit. (*ir*, *mejorar*)\nd) Hier, mon chien est sorti en courant.\ne) En entrant dans la classe, j'ai vu Juan. (*al*)\nf) Mon frère a fini par accepter. (*acabar*)\n\n**Question.** Pourquoi la périphrase avec *llevar* est-elle, selon le cours, « la plus rentable » ?","bareme":[{"critere":"Llevar + durée + gérondif et seguir + gérondif justes","points":6},{"critere":"Ir + gérondif et acabar + gérondif justes","points":4},{"critere":"Gérondif seul de manière (salió corriendo) et al + infinitif justes","points":6},{"critere":"Intérêt de llevar expliqué : rendre le « depuis » sans subordonnée","points":4}],"dureeMin":11,"corrige":"a) ***Llevo tres años estudiando** español.* — *llevar* + durée + gérondif : la durée écoulée.\nb) ***Sigue lloviendo** en París.* — continuation.\nc) *Mi abuelo **va mejorando**.* — progression lente.\nd) *Ayer mi perro **salió corriendo**.* — gérondif seul : la manière.\ne) ***Al entrar** en clase, vi a Juan.* — « en + participe présent » français se rend par *al* + infinitif ; jamais « en entrando » : après une préposition, l'infinitif.\nf) *Mi hermano **acabó aceptando**.* — le point d'aboutissement.\n\n**Question.** La périphrase avec *llevar* rend le « **depuis** » français en une seule proposition, **sans passer par une subordonnée** (*hace tres años que estudio…*)."}$exo$::jsonb),
  ('1cb6784d-d42f-5c13-a42f-2ac0ce3cc2a7'::uuid, 3, 'traduction', $exo${"titre":"Le gérondif mal employé","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Léo a traduit mot à mot un texte français. Il contient **six erreurs** liées au gérondif.\n\n> Ayer recibí una caja conteniendo libros. En saliendo del colegio, vi a Marta. Estaba leiendo en un banco. Luego llegó a su casa, encontrando a su hermano dormiendo. Hace dos años que estudio español y sigo estudiar cada día.\n\n1. Recopie le texte corrigé.\n2. Le cours dit ce que le gérondif **ne peut pas** faire. Explique les deux interdits et montre où ils apparaissent dans le texte.\n3. Réécris la phrase *Hace dos años que estudio español* avec la périphrase *llevar*.\n4. Rédige 5 phrases en espagnol (45 mots environ) sur ce que tu fais en ce moment et depuis quand. Tu dois employer *estar* + gérondif, *llevar* + durée + gérondif, *seguir* + gérondif, un gérondif en *-yendo* et un gérondif seul de manière.","bareme":[{"critere":"Six erreurs corrigées : que contenía, al salir, leyendo, y encontró (postériorité), durmiendo, sigo estudiando","points":6},{"critere":"Deux interdits expliqués (qualifier un nom, exprimer la postériorité) et repérés","points":4},{"critere":"Réécriture juste : Llevo dos años estudiando español","points":3},{"critere":"Production : les cinq emplois demandés corrects","points":7}],"dureeMin":18,"corrige":"**1.** *Ayer recibí una caja **que contenía** libros. **Al salir** del colegio, vi a Marta. Estaba **leyendo** en un banco. Luego llegó a su casa **y encontró** a su hermano **durmiendo**. Hace dos años que estudio español y **sigo estudiando** cada día.*\n\n**2.**\n- Le gérondif ne peut pas **qualifier un nom** (calque du français) : *una caja conteniendo libros* → *una caja **que contiene / que contenía** libros*.\n- Il ne peut pas exprimer la **postériorité** : il dit le **simultané**. *Llegó a su casa, encontrando…* (elle trouve son frère **après** être arrivée) → deux propositions reliées par *y* : *llegó a su casa y encontró…*\n(Les autres fautes : *al salir* — après une préposition, l'infinitif ; *leyendo* — -yendo après une voyelle ; *durmiendo* — affaiblissement ; *sigo estudiando* — seguir + gérondif.)\n\n**3.** ***Llevo dos años estudiando español.***\n\n**4.** Exemple de production :\n*Ahora estoy escribiendo este texto. Llevo cuatro años aprendiendo español. Sigo jugando al fútbol los miércoles. Por la noche, estoy leyendo una novela. Esta mañana llegué al colegio corriendo.*\nOn vérifie : *estoy escribiendo*, *llevo… aprendiendo*, *sigo jugando*, *leyendo*, *corriendo* (manière)."}$exo$::jsonb),
  ('980457df-9598-52de-a649-0b32777a4960'::uuid, 1, 'traduction', $exo${"titre":"Former et accorder le participe","consigne":"Donne le participe passé de chaque verbe, puis complète les phrases en accordant ou non.","enonce":"**1. Donne le participe passé :**\n\na) *hablar*\nb) *comer*\nc) *abrir*\nd) *decir*\ne) *escribir*\nf) *hacer*\ng) *romper*\nh) *volver*\n\n**2. Complète avec le participe du verbe entre parenthèses** (accordé ou non) :\n\na) La ventana está (abrir) … .\nb) Las chicas han (llegar) … .\nc) Las casas fueron (construir) … en 1920.\nd) Es una carta (escribir) … a mano.","bareme":[{"critere":"Participes réguliers et irréguliers justes : hablado, comido, abierto, dicho, escrito, hecho, roto, vuelto","points":10},{"critere":"Accord juste : abierta, construidas, escrita ; pas d'accord avec haber : llegado","points":10}],"dureeMin":7,"corrige":"**1.**\na) **hablado** b) **comido** c) **abierto** d) **dicho** e) **escrito** f) **hecho** g) **roto** h) **vuelto**\n\n**2.**\na) La ventana está **abierta**. — avec *estar*, accord avec le sujet (*la ventana*, féminin singulier).\nb) Las chicas han **llegado**. — avec *haber*, **jamais** d'accord.\nc) Las casas fueron **construidas** en 1920. — avec *ser*, accord avec le sujet (féminin pluriel).\nd) Es una carta **escrita** a mano. — employé comme adjectif, accord avec le nom."}$exo$::jsonb),
  ('980457df-9598-52de-a649-0b32777a4960'::uuid, 2, 'traduction', $exo${"titre":"Le retour de la fête","consigne":"Complète le récit avec les participes, accordés ou non, puis transforme les phrases.","enonce":"**Situation.** Carmen rentre chez elle après une fête.\n\n> Cuando volví a casa, la puerta estaba (abrir) … y dos ventanas estaban (romper) … . Mis hermanas habían (salir) … . Las cartas que había (escribir) … estaban (poner) … en la mesa. Mi padre me dijo: «¡Todo está (hacer) …!»\n\n1. Recopie les six participes.\n2. Explique la différence de sens entre *La casa fue construida en 1920* et *La casa está construida*.\n3. Le cours dit que l'espagnol préfère d'autres tournures à la passive avec *ser*. Réécris *La casa fue construida en 1920* de **deux** autres façons.","bareme":[{"critere":"Participes irréguliers justes et accordés avec estar : abierta, rotas, puestas, hecho","points":8},{"critere":"Pas d'accord avec haber : salido, escrito","points":4},{"critere":"Différence passive d'action / état résultant expliquée","points":4},{"critere":"Deux réécritures justes : se construyó, construyeron","points":4}],"dureeMin":11,"corrige":"**1.** *abierta* (accord avec *la puerta*) — *rotas* (avec *dos ventanas*) — *salido* (avec *haber* : jamais d'accord) — *escrito* (avec *haber*, même si *las cartas* est placé avant) — *puestas* (avec *estar*, accord avec *las cartas*) — *hecho* (*todo*, masculin singulier).\n\n**2.** *Fue construida* (*ser* + participe) est la **passive d'action** : on assiste au fait, la construction a eu lieu en 1920. *Está construida* (*estar* + participe) décrit l'**état résultant** : la maison est finie, le fait est accompli.\n\n**3.**\n- Tournure en *se* : ***Se construyó** la casa en 1920.*\n- Troisième personne du pluriel : ***Construyeron** la casa en 1920.*"}$exo$::jsonb),
  ('980457df-9598-52de-a649-0b32777a4960'::uuid, 3, 'traduction', $exo${"titre":"Le compte rendu de Samuel","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Samuel a écrit le compte rendu d'une journée de cuisine au collège. Il contient **sept erreurs** sur le participe passé.\n\n> Hoy hemos freído patatas y las patatas freídas estaban muy ricas. Las recetas que he escritas están en el cuaderno. La puerta de la cocina está abierto. Por desgracia, he rompido un plato. Las profesoras han volvidas a las tres. Nos han dado un texto imprimido. Los menús fueron escrito por los alumnos.\n\n1. Recopie le texte corrigé.\n2. Énonce en une ligne la règle d'accord du participe passé en espagnol.\n3. Qu'est-ce qu'un participe **double** ? Explique avec les deux exemples du texte.\n4. Rédige 5 phrases en espagnol (45 mots environ) sur une sortie scolaire. Tu dois employer : un temps composé avec *haber* et un participe irrégulier, *estar* + participe accordé au féminin, *ser* + participe au pluriel et un participe employé comme adjectif.","bareme":[{"critere":"Sept erreurs corrigées : fritas, escrito, abierta, roto, vuelto, impreso, escritos","points":7},{"critere":"Règle d'accord énoncée : figé avec haber, accordé partout ailleurs","points":3},{"critere":"Participe double expliqué avec freír et imprimir","points":4},{"critere":"Production : les quatre emplois demandés, accords justes","points":6}],"dureeMin":17,"corrige":"**1.** *Hoy hemos freído patatas y las patatas **fritas** estaban muy ricas. Las recetas que he **escrito** están en el cuaderno. La puerta de la cocina está **abierta**. Por desgracia, he **roto** un plato. Las profesoras han **vuelto** a las tres. Nos han dado un texto **impreso**. Los menús fueron **escritos** por los alumnos.*\n\n**2.** Ce qui suit *haber* est **figé** (jamais d'accord) ; avec *ser*, *estar* ou comme adjectif, le participe **s'accorde** (avec le sujet ou le nom).\n\n**3.** Un participe double existe sous deux formes : une **régulière** pour les temps composés, une **irrégulière** employée comme adjectif. *Freír* : *hemos freído* (temps composé, correct dans le texte) mais *patatas fritas* (adjectif). *Imprimir* : *he imprimido* mais *un texto impreso*.\n\n**4.** Exemple de production :\n*Hoy hemos visto un museo muy grande. La sala principal estaba cerrada. Los cuadros fueron pintados por Goya. He escrito un resumen para la clase. Hemos comprado unas postales pintadas a mano.*\nOn vérifie : *hemos visto / he escrito* (haber + irrégulier, sans accord), *estaba cerrada* (estar, féminin), *fueron pintados* (ser, pluriel), *postales pintadas* (adjectif)."}$exo$::jsonb),
  ('592f02fe-9d96-541f-9656-f0073890d321'::uuid, 1, 'traduction', $exo${"titre":"Ce qui me plaît","consigne":"Complète avec le verbe et le pronom qui conviennent, puis réponds pour dire « moi aussi » ou « moi non plus ».","enonce":"**1. Complète :**\n\na) A mí … (gustar) el chocolate.\nb) A ella … (gustar) los perros.\nc) A nosotros … (gustar) bailar y cantar.\nd) A ellos … (encantar) las películas de terror.\ne) … (doler, a mí) la cabeza.\nf) ¿A ti … (gustar) el fútbol?\n\n**2. Réponds :**\n\na) — Me gusta el cine. — (moi aussi) …\nb) — No me gustan los lunes. — (moi non plus) …","bareme":[{"critere":"Pronom complément juste à chaque phrase : me, le, nos, les, me, te","points":6},{"critere":"Accord du verbe avec ce qui plaît : gusta, gustan, gusta (deux infinitifs), encantan, duele","points":10},{"critere":"Réponses justes : A mí también, A mí tampoco","points":4}],"dureeMin":6,"corrige":"**1.**\na) A mí **me gusta** el chocolate.\nb) A ella **le gustan** los perros. — le sujet est *los perros*, pluriel.\nc) A nosotros **nos gusta** bailar y cantar. — deux infinitifs : **singulier quand même**.\nd) A ellos **les encantan** las películas de terror.\ne) **Me duele** la cabeza. — le sujet est *la cabeza*.\nf) ¿A ti **te gusta** el fútbol?\nLe verbe s'accorde avec **ce qui plaît**, jamais avec la personne.\n\n**2.**\na) ***A mí también.*** — accord après une affirmation.\nb) ***A mí tampoco.*** — accord après une négation."}$exo$::jsonb),
  ('592f02fe-9d96-541f-9656-f0073890d321'::uuid, 2, 'traduction', $exo${"titre":"Le sondage de la classe","consigne":"Rédige les phrases à partir du tableau, puis traduis.","enonce":"**Situation.** Rayan a fait un sondage dans sa classe d'espagnol.\n\n| Élève | Ce qu'il aime | Ce qu'il n'aime pas |\n|---|---|---|\n| Ana | le cinéma (beaucoup) | les maths |\n| Luis | les jeux vidéo (il adore) | lire |\n| Ana et Luis | la musique | se lever tôt |\n\n1. Écris **cinq phrases** en espagnol pour présenter les résultats (commence par *A Ana…*, *A Luis…*, *A Ana y a Luis…*). Emploie *mucho*, *encantar* et *no… nada*.\n2. **Traduis :**\na) Il nous faut deux chaises.\nb) Il me reste peu d'argent.\nc) Je préfère le cinéma au théâtre (*gustar más… que*).","bareme":[{"critere":"Renforcement a + nom avec pronom le ou les conservé","points":5},{"critere":"Accord du verbe avec ce qui plaît dans les cinq phrases","points":6},{"critere":"Degré juste : mucho, encantan, no… nada (jamais muy)","points":3},{"critere":"Traductions justes : nos hacen falta, me queda, me gusta más… que","points":6}],"dureeMin":11,"corrige":"**1.** Phrases attendues :\n- *A Ana **le gusta mucho** el cine.*\n- *A Ana **no le gustan** las matemáticas.* — pluriel.\n- *A Luis **le encantan** los videojuegos.*\n- *A Luis **no le gusta nada** leer.*\n- *A Ana y a Luis **les gusta** la música, pero **no les gusta** levantarse temprano.*\nLe pronom (*le, les*) reste **obligatoire** même quand le nom est exprimé ; le verbe s'accorde avec ce qui plaît.\n\n**2.**\na) ***Nos hacen falta** dos sillas.* — pluriel, accordé avec *dos sillas*.\nb) ***Me queda** poco dinero.*\nc) ***Me gusta más** el cine **que** el teatro.*"}$exo$::jsonb),
  ('592f02fe-9d96-541f-9656-f0073890d321'::uuid, 3, 'traduction', $exo${"titre":"Le profil d'Enzo","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court dialogue en espagnol.","enonce":"**Document.** Enzo se présente sur un site d'échanges linguistiques. Son texte contient **sept erreurs**.\n\n> Hola, me llamo Enzo. Yo gusto el fútbol y me gusta los videojuegos. Mi hermano Juan le gusta el tenis. A mí gusta mucho viajar. Me gusta muy la música. Me gustan leer y escribir. Hoy me duelen la cabeza.\n\n1. Recopie le texte corrigé.\n2. Explique en deux ou trois phrases pourquoi on dit *Me gustan las películas* et non « Me gusta las películas ».\n3. Pour **trois** autres erreurs, explique la correction.\n4. Rédige un dialogue de 6 répliques entre deux élèves qui comparent leurs goûts. Tu dois employer *a mí también*, *a mí tampoco*, *a mí sí*, *a mí no*, un verbe de la famille de *gustar* autre que *gustar* et le renforcement *a* + prénom.","bareme":[{"critere":"Sept erreurs corrigées : me gusta, me gustan, A mi hermano Juan, a mí me gusta, mucho, me gusta leer y escribir, me duele","points":7},{"critere":"Construction inversée expliquée : le sujet est la chose qui plaît","points":4},{"critere":"Trois autres corrections justifiées","points":3},{"critere":"Dialogue : les quatre réponses employées à bon escient, autre verbe et renforcement justes","points":6}],"dureeMin":18,"corrige":"**1.** *Hola, me llamo Enzo. **Me gusta** el fútbol y **me gustan** los videojuegos. **A** mi hermano Juan le gusta el tenis. A mí **me** gusta mucho viajar. Me gusta **mucho** la música. **Me gusta** leer y escribir. Hoy **me duele** la cabeza.*\n\n**2.** Dans la construction de *gustar*, le **sujet** n'est pas la personne mais **la chose qui plaît** ; la personne est un complément (*me, te, le…*). *Las películas* est le sujet, au pluriel : le verbe se met au pluriel, *gustan*.\n\n**3.** Corrections attendues (trois parmi) :\n- « Yo gusto » → *me gusta* : la personne n'est pas le sujet.\n- *A mi hermano Juan le gusta* : le renforcement se fait avec *a* + nom, et *le* reste obligatoire.\n- *A mí me gusta* : le pronom complément est obligatoire même avec *a mí*.\n- *mucho* : on ne dit jamais « me gusta muy ».\n- *Me gusta leer y escribir* : deux infinitifs, verbe au singulier.\n- *Me duele la cabeza* : *la cabeza* est singulier.\n\n**4.** Exemple de dialogue :\n— *Me encanta el baloncesto.* — *A mí también.*\n— *No me gusta nada el invierno.* — *A mí tampoco.*\n— *No me interesan los videojuegos.* — *¡A mí sí!*\n— *Me gusta mucho levantarme tarde.* — *A mí no.*\n— *¿Y a Lucas? — A Lucas le molesta el ruido.*\nOn vérifie : *también* après une affirmation, *tampoco* et *sí* après une négation, *no* après une affirmation, *encantar / interesar / molestar*, *A Lucas le…*"}$exo$::jsonb),
  ('75e01212-05cc-5d16-b5ff-0978f4237166'::uuid, 1, 'traduction', $exo${"titre":"Il faut, je dois","consigne":"Complète avec tener que, hay que ou deber, puis traduis.","enonce":"**1. Complète avec la structure qui convient** (conjuguée au présent si besoin) :\n\na) Para aprobar, … estudiar. (en général)\nb) Yo … ir al médico mañana. (obligation personnelle)\nc) Tú … respetar a tus padres. (devoir moral)\nd) Nosotros … terminar los deberes esta tarde. (obligation personnelle)\n\n**2. Traduis :**\n\na) Il fallait partir tôt.\nb) Il doit être malade. (je suppose)\nc) Ne sors pas ! (tú)","bareme":[{"critere":"Hay que pour l'obligation impersonnelle, tener que conjugué pour l'obligation personnelle","points":8},{"critere":"Deber pour le devoir moral : debes","points":3},{"critere":"Traductions justes : había que, debe de estar, no salgas","points":9}],"dureeMin":7,"corrige":"**1.**\na) Para aprobar, **hay que** estudiar. — obligation impersonnelle, valable pour tous, invariable.\nb) Yo **tengo que** ir al médico mañana. — obligation personnelle.\nc) Tú **debes** respetar a tus padres. — devoir moral.\nd) Nosotros **tenemos que** terminar los deberes esta tarde.\n\n**2.**\na) ***Había que** salir temprano.* — *hay que* à l'imparfait.\nb) ***Debe de estar** enfermo.* — *deber de* + infinitif = probabilité (et non obligation).\nc) *¡**No salgas**!* — ordre direct à l'impératif négatif, au subjonctif."}$exo$::jsonb),
  ('75e01212-05cc-5d16-b5ff-0978f4237166'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de la colonie","consigne":"Traduis les consignes du moniteur en espagnol en choisissant la bonne tournure, puis réponds à la question.","enonce":"**Situation.** Mateo, moniteur d'une colonie de vacances à Cadix, prépare les règles à afficher.\n\n**1. Traduis en espagnol :**\n\na) Il faut arriver à l'heure au repas. (règle générale)\nb) Tu dois ranger ta chambre. (obligation personnelle)\nc) Vous devez respecter les horaires. (*vosotros*, devoir moral)\nd) Il faut que tu viennes à la réunion. (*es necesario que*)\ne) Demain, il faudra partir tôt.\nf) Range ton sac ! (*ordenar*, tú)\n\n**2.** Explique la différence de sens entre :\n*Tenía que estudiar, pero fui al cine.* et *Tuve que estudiar toda la tarde.*","bareme":[{"critere":"Hay que et habrá que pour l'obligation impersonnelle, invariables","points":5},{"critere":"Tener que et deber conjugués justes (tienes que, debéis)","points":5},{"critere":"Es necesario que + subjonctif (vengas) et impératif (ordena) justes","points":5},{"critere":"Nuance imparfait / passé simple expliquée","points":5}],"dureeMin":11,"corrige":"**1.**\na) ***Hay que** llegar a la hora a la comida.*\nb) ***Tienes que** ordenar tu habitación.*\nc) ***Debéis** respetar los horarios.*\nd) ***Es necesario que vengas** a la reunión.* — subjonctif après *es necesario que* (on accepte *Hace falta que vengas*).\ne) *Mañana **habrá que** salir temprano.* — *hay que* au futur, invariable.\nf) *¡**Ordena** tu mochila!* — impératif, ordre direct.\n\n**2.** L'**imparfait** (*tenía que*) dit que l'obligation existait, sans dire si elle a été suivie : ici, elle ne l'a pas été (il est allé au cinéma). Le **passé simple** (*tuve que*) dit que l'obligation a été **exécutée** : il a vraiment étudié tout l'après-midi. L'imparfait laisse ouvert, le passé simple conclut."}$exo$::jsonb),
  ('75e01212-05cc-5d16-b5ff-0978f4237166'::uuid, 3, 'traduction', $exo${"titre":"Conseils à une petite sœur","consigne":"Corrige le texte en justifiant tes corrections, puis rédige une courte lettre en espagnol.","enonce":"**Document.** Lina écrit à sa petite sœur qui entre au collège. Son message contient **six erreurs** sur l'expression de l'obligation.\n\n> Querida Alba: En el colegio, hayan que respetar las normas. Tienes estudiar cada día. Debe de hacer tus deberes antes de cenar (c'est une obligation). Es necesario que vienes puntual. ¡No sales sin tu mochila! Mañana habrán que madrugar.\n\n1. Recopie le message corrigé.\n2. Explique la différence entre *Tengo que trabajar* et *Hay que trabajar*, puis entre *deber* et *deber de*.\n3. Rédige une lettre de 50 mots environ à un ami qui prépare le brevet. Tu dois employer : *tener que*, *hay que*, *deber* (obligation), *deber de* (probabilité), *hace falta que* + subjonctif et un impératif négatif.","bareme":[{"critere":"Six erreurs corrigées : hay que, tienes que, debes, vengas, no salgas, habrá que","points":6},{"critere":"Deux différences expliquées : personnelle / impersonnelle, obligation / probabilité","points":5},{"critere":"Production : tener que, hay que, deber et deber de employés avec le bon sens","points":6},{"critere":"Production : hace falta que + subjonctif et impératif négatif justes","points":3}],"dureeMin":18,"corrige":"**1.** *Querida Alba: En el colegio, **hay que** respetar las normas. **Tienes que** estudiar cada día. **Debes** hacer tus deberes antes de cenar. Es necesario que **vengas** puntual. ¡**No salgas** sin tu mochila! Mañana **habrá que** madrugar.*\nJustifications : *hay que* est invariable ; *tener* est toujours suivi de *que* ; *deber de* dit la probabilité, l'obligation est *deber* ; *es necesario que* + subjonctif ; l'impératif négatif passe au subjonctif ; *habrá que* reste au singulier.\n\n**2.** *Tengo que trabajar* : c'est **moi** qui dois travailler (obligation personnelle). *Hay que trabajar* : il faut travailler **en général**, pour tout le monde (impersonnelle). Le français dit « il faut » dans les deux cas. *Deber* + infinitif exprime l'**obligation** (*Debes estudiar*) ; *deber de* + infinitif exprime la **probabilité** (*Debe de estar enfermo* = je suppose qu'il est malade).\n\n**3.** Exemple de production :\n*Querido Tom: Tienes que repasar cada día. Hay que dormir bien antes de un examen. Debes organizarte. Tu hermano debe de estar orgulloso de ti. Hace falta que descanses el domingo. ¡No estudies toda la noche! Un abrazo.*\nOn vérifie le sens de chaque tournure et le subjonctif après *hace falta que* et à l'impératif négatif."}$exo$::jsonb),
  ('49b7e098-0ea0-5589-9a62-3dcee283772d'::uuid, 1, 'traduction', $exo${"titre":"Soler, le verbe de l'habitude","consigne":"Conjugue soler, puis traduis les phrases.","enonce":"**1. Conjugue *soler* au présent**, à toutes les personnes.\n\n**2. Traduis en espagnol :**\n\na) J'ai l'habitude de me lever tôt.\nb) Il pleut d'ordinaire en automne.\nc) Je l'ai rappelé. (*volver a*)\nd) Nous allons de temps en temps à la plage.","bareme":[{"critere":"Soler juste aux six personnes, diphtongue o → ue dans la botte","points":8},{"critere":"Soler + infinitif juste : suelo levantarme, suele llover","points":6},{"critere":"Volver a + infinitif et de vez en cuando justes","points":6}],"dureeMin":7,"corrige":"**1.** *suelo, sueles, suele, **solemos, soléis**, suelen* — *soler* est un verbe à diphtongue (o → ue).\n\n**2.**\na) ***Suelo levantarme** temprano.* — *soler* + infinitif, pronom soudé à l'infinitif.\nb) ***Suele llover** en otoño.*\nc) ***Volví a llamarlo.*** — *volver a* + infinitif remplace le préfixe « re- » français.\nd) *Vamos a la playa **de vez en cuando**.*"}$exo$::jsonb),
  ('49b7e098-0ea0-5589-9a62-3dcee283772d'::uuid, 2, 'traduction', $exo${"titre":"L'enfance de la grand-mère","consigne":"Traduis le récit en espagnol en exprimant l'habitude, puis réponds à la question.","enonce":"**Situation.** La grand-mère d'Iris, née à Grenade, raconte son enfance.\n\n**1. Traduis en espagnol :**\n\n> « Quand j'étais petite, j'avais l'habitude d'aller au marché avec ma mère (*soler*). Nous jouions dans la rue. De temps en temps, nous allions à la plage. Presque jamais nous ne mangions au restaurant. Aujourd'hui, je continue à nager tous les étés. »\n\n2. Pourquoi ne peut-on pas écrire « Ayer solí ir al mercado » ?\n3. Quelle est la différence entre *acostumbrar a* et *acostumbrarse a* ?","bareme":[{"critere":"Solía + infinitif et imparfaits d'habitude justes (era, jugábamos, íbamos, comíamos)","points":8},{"critere":"Marqueurs de fréquence justes : de vez en cuando, casi nunca, todos los veranos","points":4},{"critere":"Seguir + gérondif juste : sigo nadando","points":2},{"critere":"Soler impossible au passé simple expliqué ; acostumbrar a / acostumbrarse a distingués","points":6}],"dureeMin":12,"corrige":"**1.** *Cuando **era** pequeña, **solía ir** al mercado con mi madre. **Jugábamos** en la calle. **De vez en cuando**, **íbamos** a la playa. **Casi nunca comíamos** en un restaurante. Hoy **sigo nadando** todos los veranos.*\n- *soler* à l'imparfait (*solía*) + infinitif ; l'**imparfait** seul exprime aussi l'habitude passée.\n- *seguir* + gérondif : l'action qui continue.\n\n**2.** *Soler* ne s'emploie qu'au **présent** et à l'**imparfait**, **jamais** au passé simple ni au futur : une habitude n'est pas un événement ponctuel. On écrit *Ayer fui al mercado* (fait unique) ou *Solía ir al mercado* (habitude).\n\n**3.** *Acostumbrar a* + infinitif = **avoir l'habitude de** (registre soutenu). *Acostumbrarse a* = **s'habituer à** : le sens est différent."}$exo$::jsonb),
  ('49b7e098-0ea0-5589-9a62-3dcee283772d'::uuid, 3, 'traduction', $exo${"titre":"Avant et maintenant","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Nathan compare sa vie d'avant et celle d'aujourd'hui. Son texte contient **six erreurs**.\n\n> Cuando era pequeño, solí jugar al fútbol todos los días. Ahora yo solo levantarme tarde los domingos. Mi padre acostumbra de leer el periódico. Ayer rellamé a mi abuela. Sigo estudiar piano. El año que viene soleré ir al gimnasio.\n\n1. Recopie le texte corrigé (pour la dernière phrase, propose une tournure possible au futur).\n2. Pour **quatre** erreurs, explique la règle en une phrase.\n3. Explique la nuance entre *cada día* et *todos los días*.\n4. Rédige 5 phrases en espagnol (50 mots environ) qui comparent ton enfance et ta vie actuelle. Tu dois employer *soler* au présent et à l'imparfait, un imparfait d'habitude, deux marqueurs de fréquence, *volver a* + infinitif et *seguir* + gérondif.","bareme":[{"critere":"Six erreurs corrigées : solía, suelo, acostumbra a, volví a llamar, sigo estudiando, futur sans soler","points":6},{"critere":"Quatre règles expliquées avec justesse","points":4},{"critere":"Nuance cada día / todos los días expliquée","points":2},{"critere":"Production : soler aux deux temps, imparfait d'habitude, volver a et seguir + gérondif justes","points":6},{"critere":"Production : deux marqueurs de fréquence, texte compréhensible","points":2}],"dureeMin":18,"corrige":"**1.** *Cuando era pequeño, **solía** jugar al fútbol todos los días. Ahora **suelo** levantarme tarde los domingos. Mi padre acostumbra **a** leer el periódico. Ayer **volví a llamar** a mi abuela. Sigo **estudiando** piano. El año que viene **iré** (ou *voy a ir*) al gimnasio **a menudo**.*\n\n**2.** Règles attendues (quatre parmi) :\n- *Soler* s'emploie au présent et à l'imparfait (*solía*), jamais au passé simple ni au futur.\n- *Soler* diphtongue : *suelo* (« solo » veut dire « seul »).\n- *Acostumbrar* se construit avec **a** + infinitif.\n- L'espagnol n'a pas de préfixe « re- » productif : *volver a* + infinitif.\n- *Seguir* + **gérondif** exprime l'action qui continue.\n\n**3.** *Cada día* détaille **jour après jour** ; *todos los días* embrasse **l'ensemble** des jours.\n\n**4.** Exemple de production :\n*Cuando era niña, solía pasar las vacaciones en el pueblo. Jugaba siempre con mis primos. Ahora suelo quedarme en la ciudad y a veces vuelvo a visitar el pueblo. Sigo viendo a mis primos en Navidad. Casi nunca me aburro.*\nOn vérifie : *solía / suelo*, *jugaba*, *siempre, a veces, casi nunca*, *vuelvo a visitar*, *sigo viendo*."}$exo$::jsonb),
  ('6b515cda-c7e4-5179-b3a9-e9231a139c5e'::uuid, 1, 'traduction', $exo${"titre":"Supposer avec le futur","consigne":"Traduis les phrases en français sans faire de contresens, puis complète avec le mode qui convient.","enonce":"**1. Traduis en français :**\n\na) ¿Qué hora es? — Serán las tres.\nb) Estará enfermo.\nc) Habrá salido.\nd) Tendría veinte años cuando llegó a Madrid.\n\n**2. Conjugue le verbe au mode qui convient :**\n\na) A lo mejor (venir, él) … mañana.\nb) Puede que (llover) … esta tarde.","bareme":[{"critere":"Futur de probabilité traduit par une supposition sur le présent : il doit être trois heures, il doit être malade","points":8},{"critere":"Futur antérieur et conditionnel de probabilité justes : il a dû sortir, il devait avoir vingt ans","points":6},{"critere":"Modes justes : a lo mejor viene (indicatif), puede que llueva (subjonctif)","points":6}],"dureeMin":7,"corrige":"**1.**\na) « Quelle heure est-il ? — **Il doit être** trois heures. » — le futur suppose sur le **présent** (et non « il sera trois heures »).\nb) « **Il doit être** malade (en ce moment). » — contresens fréquent : ce n'est pas « il sera malade ».\nc) « **Il a dû sortir.** » — futur antérieur : supposition sur un fait accompli, vu du présent.\nd) « **Il devait avoir** vingt ans quand il est arrivé à Madrid. » — le conditionnel suppose sur le **passé**.\n\n**2.**\na) A lo mejor **viene** mañana. — *a lo mejor* : **toujours** l'indicatif.\nb) Puede que **llueva** esta tarde. — *puede que* : **toujours** le subjonctif."}$exo$::jsonb),
  ('6b515cda-c7e4-5179-b3a9-e9231a139c5e'::uuid, 2, 'traduction', $exo${"titre":"Où est passé Carlos ?","consigne":"Traduis les suppositions en espagnol en utilisant les outils du cours, puis réponds à la question.","enonce":"**Situation.** Carlos devait retrouver ses amis au cinéma à 20 h. Il n'est pas là. Ses amis font des suppositions.\n\n**1. Traduis en espagnol :**\n\na) Il doit être dans le bus. (futur de probabilité)\nb) Il a dû oublier. (futur antérieur : *olvidarse*)\nc) Il devait être huit heures quand il est parti. (conditionnel)\nd) Il doit être fatigué. (*deber de*)\ne) Peut-être qu'il est malade — j'en suis presque sûr. (*quizás*)\nf) Peut-être qu'il vient en taxi — je n'en sais rien. (*quizás*)\n\n**2.** Explique la différence entre *Carlos debe estudiar* et *Carlos debe de estudiar*.","bareme":[{"critere":"Futur et futur antérieur de probabilité justes : estará, se habrá olvidado","points":5},{"critere":"Conditionnel de probabilité sur le passé juste : serían las ocho","points":3},{"critere":"Deber de + infinitif juste : debe de estar cansado","points":3},{"critere":"Quizás + indicatif (forte probabilité) et + subjonctif (faible) justes","points":5},{"critere":"Différence obligation / probabilité expliquée","points":4}],"dureeMin":12,"corrige":"**1.**\na) ***Estará** en el autobús.* — futur pour une supposition sur le présent.\nb) ***Se habrá olvidado.*** — futur antérieur : fait accompli, vu du présent.\nc) ***Serían** las ocho cuando salió.* — conditionnel : supposition sur le passé.\nd) ***Debe de estar** cansado.* — la tournure explicite de probabilité.\ne) ***Quizás está** enfermo.* — indicatif : la probabilité est forte.\nf) ***Quizás venga** en taxi.* — subjonctif : la probabilité est faible.\n\n**2.** *Carlos debe estudiar* : *deber* + infinitif = **obligation** (Carlos doit étudier). *Carlos debe de estudiar* : *deber de* + infinitif = **probabilité** (Carlos doit être en train d'étudier, je suppose)."}$exo$::jsonb),
  ('6b515cda-c7e4-5179-b3a9-e9231a139c5e'::uuid, 3, 'traduction', $exo${"titre":"Lucía n'est pas rentrée","consigne":"Traduis le dialogue en français sans contresens, justifie tes choix, puis rédige un court dialogue en espagnol.","enonce":"**Document.** Il est neuf heures du soir. La famille de Lucía l'attend pour dîner.\n\n> — Son las nueve y Lucía no ha llegado.\n> — Estará en el metro, dice su madre.\n> — O habrá perdido el tren.\n> — Debe de estar cansada: ayer serían las doce cuando apagó la luz.\n> — A lo mejor viene en taxi.\n> — Puede que llegue tarde a la cena.\n\n1. Traduis le dialogue en français.\n2. Pour *Estará*, *habrá perdido* et *serían*, explique en une phrase le temps employé et sur quel moment porte la supposition.\n3. Pourquoi *A lo mejor viene* et *Puede que llegue* n'emploient-ils pas le même mode ?\n4. Rédige un dialogue de 6 répliques (50 mots environ) : ton professeur n'est pas arrivé en cours et la classe fait des suppositions. Tu dois employer le futur de probabilité, le futur antérieur, le conditionnel de probabilité, *deber de*, *quizás* (avec le mode de ton choix, justifié) et *puede que*.","bareme":[{"critere":"Traduction sans contresens : il doit être, il a dû perdre, elle doit être, il devait être minuit","points":6},{"critere":"Trois temps de probabilité expliqués avec le moment visé","points":4},{"critere":"Modes après a lo mejor et puede que expliqués","points":3},{"critere":"Production : les six outils employés correctement","points":7}],"dureeMin":18,"corrige":"**1.**\n— Il est neuf heures et Lucía n'est pas arrivée.\n— **Elle doit être** dans le métro, dit sa mère.\n— Ou **elle a dû rater** le train.\n— **Elle doit être** fatiguée : hier, **il devait être** minuit quand elle a éteint la lumière.\n— **Peut-être qu'elle** vient en taxi.\n— **Il se peut qu'elle arrive** en retard au dîner.\n\n**2.**\n- *Estará* : **futur** de probabilité → supposition sur le **présent** (maintenant, elle est sans doute dans le métro).\n- *Habrá perdido* : **futur antérieur** → supposition sur un **fait accompli**, vu du présent.\n- *Serían* : **conditionnel** → supposition sur le **passé** (hier soir).\n\n**3.** Ce sont les deux exceptions absolues : *a lo mejor* est **toujours** suivi de l'**indicatif** ; *puede que* est **toujours** suivi du **subjonctif**.\n\n**4.** Exemple de production :\n— *¿Dónde está el profesor? — Estará en un atasco.*\n— *O se habrá olvidado de la clase.*\n— *Debe de estar enfermo: ayer tosía mucho.*\n— *Serían las ocho cuando salió de casa.*\n— *Quizás venga más tarde* (subjonctif : je n'en sais rien).\n— *Puede que tengamos una hora libre.*\nOn vérifie chaque outil et la justification du mode après *quizás*."}$exo$::jsonb),
  ('448c72c2-5bed-509b-b386-793c310014fd'::uuid, 1, 'traduction', $exo${"titre":"Donner un ordre","consigne":"Mets les verbes à l'impératif, puis traduis.","enonce":"**1. Donne l'impératif affirmatif à la personne *tú* :**\n\na) *hablar*\nb) *comer*\nc) *vivir*\nd) *hacer*\ne) *decir*\nf) *ir*\ng) *tener*\nh) *salir*\n\n**2. Donne l'impératif négatif (tú) :**\n\na) *hablar*\nb) *comer*\n\n**3. Traduis :** Tu devrais te reposer.","bareme":[{"critere":"Impératifs réguliers justes : habla, come, vive","points":5},{"critere":"Impératifs irréguliers justes : haz, di, ve, ten, sal","points":8},{"critere":"Impératif négatif au subjonctif : no hables, no comas","points":4},{"critere":"Conseil ferme juste : deberías descansar","points":3}],"dureeMin":7,"corrige":"**1.**\na) **habla** b) **come** c) **vive** d) **haz** e) **di** f) **ve** g) **ten** h) **sal**\n\n**2.**\na) **no hables** b) **no comas** — l'impératif négatif passe **toujours** au subjonctif.\n\n**3.** ***Deberías descansar.*** — *deberías* + infinitif : le conseil ferme, plus poli que l'impératif."}$exo$::jsonb),
  ('448c72c2-5bed-509b-b386-793c310014fd'::uuid, 2, 'traduction', $exo${"titre":"Aider Lola en maths","consigne":"Rédige les conseils demandés en espagnol, du plus direct au plus poli, puis transforme les phrases.","enonce":"**Situation.** Lola a eu 6 sur 20 à son contrôle de maths. Ses amis lui donnent des conseils.\n\n**1. Écris un conseil pour Lola** avec chaque structure :\n\na) l'impératif (*estudiar*)\nb) *deberías* + infinitif (*hacer ejercicios*)\nc) *podrías* + infinitif (*pedir ayuda al profesor*)\nd) *¿Por qué no…?* (*ir a la biblioteca*)\ne) *¿Y si…?* (*estudiar juntas*)\nf) *Te aconsejo que* + subjonctif (*repasar cada día*)\n\n**2. Transforme** à l'impératif négatif, en déplaçant les pronoms :\n\na) ¡Dímelo!\nb) ¡Cómpralo!","bareme":[{"critere":"Impératif, deberías et podrías + infinitif justes","points":6},{"critere":"¿Por qué no…? et ¿Y si…? suivis de l'indicatif","points":4},{"critere":"Te aconsejo que + subjonctif juste : repases","points":4},{"critere":"Impératifs négatifs avec pronoms devant : no me lo digas, no lo compres","points":6}],"dureeMin":11,"corrige":"**1.**\na) *¡**Estudia** más!* — l'ordre.\nb) ***Deberías hacer** ejercicios.* — le conseil ferme.\nc) ***Podrías pedir** ayuda al profesor.* — la suggestion.\nd) *¿**Por qué no vas** a la biblioteca?* — la question, à l'indicatif.\ne) *¿**Y si estudiamos** juntas?* — l'invitation, **indicatif**.\nf) ***Te aconsejo que repases** cada día.* — après un verbe de conseil, subjonctif (le sujet change).\n\n**2.**\na) *¡**No me lo digas**!*\nb) *¡**No lo compres**!*\nL'affirmatif soude les pronoms au verbe ; le négatif passe au subjonctif et place les pronoms **devant**."}$exo$::jsonb),
  ('448c72c2-5bed-509b-b386-793c310014fd'::uuid, 3, 'traduction', $exo${"titre":"La lettre à un ami inquiet","consigne":"Corrige le texte en justifiant tes corrections, puis rédige une courte lettre en espagnol.","enonce":"**Document.** Malik répond à son correspondant Pedro, qui est stressé avant un examen. Sa lettre contient **sept erreurs**.\n\n> Querido Pedro: ¡No habla tanto de tus nervios! Te aconsejo que descansas este fin de semana. Hace tus deberes con calma. Si tienes un problema, ¡me lo di! Yo que tú, iré al cine. Ojalá puedo ayudarte, pero estoy lejos. ¿Y si salgamos juntos en verano?\n\n1. Recopie la lettre corrigée.\n2. Pour **quatre** erreurs, explique la règle en une phrase.\n3. Quelle nuance sépare *Ojalá apruebes* et *Ojalá pudiera ayudarte* ?\n4. Rédige une lettre de 50 mots environ à un ami qui veut arrêter le sport. Tu dois employer au moins quatre barreaux de l'échelle du conseil (dont l'impératif négatif), *te recomiendo que* + subjonctif et *yo que tú* + conditionnel.","bareme":[{"critere":"Sept erreurs corrigées : no hables, descanses, haz, dímelo, iría, pudiera, salimos","points":7},{"critere":"Quatre règles expliquées avec justesse","points":4},{"critere":"Nuance ojalá + subjonctif présent / imparfait expliquée","points":3},{"critere":"Production : quatre structures de l'échelle, te recomiendo que + subjonctif, yo que tú + conditionnel","points":6}],"dureeMin":18,"corrige":"**1.** *Querido Pedro: ¡**No hables** tanto de tus nervios! Te aconsejo que **descanses** este fin de semana. **Haz** tus deberes con calma. Si tienes un problema, ¡**dímelo**! Yo que tú, **iría** al cine. Ojalá **pudiera** ayudarte, pero estoy lejos. ¿Y si **salimos** juntos en verano?*\n\n**2.** Règles attendues (quatre parmi) :\n- L'impératif **négatif** passe au subjonctif : *no hables*.\n- Après *te aconsejo que*, le **subjonctif** : *descanses*.\n- *Hacer* a un impératif irrégulier : *haz* ; *decir* aussi : *di*.\n- L'impératif affirmatif **soude** les pronoms : *dímelo*.\n- *Yo que tú* se poursuit au **conditionnel** : *iría*.\n- *¿Y si…?* est suivi de l'**indicatif** : *salimos*.\n\n**3.** *Ojalá* + **subjonctif présent** (*apruebes*) : un souhait **possible**. *Ojalá* + **imparfait du subjonctif** (*pudiera*) : un souhait **improbable** — « si seulement je pouvais ».\n\n**4.** Exemple de production :\n*Querida Sara: ¡No dejes el baloncesto! Deberías hablar con tu entrenador. Podrías probar otro equipo. ¿Por qué no vienes a mi club? Te recomiendo que lo pienses bien. Yo que tú, seguiría un año más. ¡Ánimo!*\nOn vérifie : impératif négatif, *deberías*, *podrías*, *¿por qué no…?*, *te recomiendo que* + subjonctif, *yo que tú* + conditionnel."}$exo$::jsonb),
  ('747a0610-aa22-57df-a449-8da772399021'::uuid, 1, 'traduction', $exo${"titre":"Les trois conjugaisons","consigne":"Conjugue les verbes au présent de l'indicatif.","enonce":"**1. Conjugue au présent**, à toutes les personnes :\n\na) *hablar*\nb) *comer*\nc) *vivir*\n\n**2. Donne la première personne (yo) du présent :**\n\na) *hacer*\nb) *conocer*\nc) *salir*\nd) *saber*\ne) *dar*\nf) *poner*","bareme":[{"critere":"Hablar, comer et vivir justes aux six personnes, accents de habláis et coméis","points":12},{"critere":"Six premières personnes irrégulières justes : hago, conozco, salgo, sé, doy, pongo","points":8}],"dureeMin":7,"corrige":"**1.**\na) *hablo, hablas, habla, hablamos, habláis, hablan*\nb) *como, comes, come, comemos, coméis, comen*\nc) *vivo, vives, vive, vivimos, vivís, viven*\nLes verbes en *-er* et *-ir* ne diffèrent qu'à *nosotros* et *vosotros*.\n\n**2.**\na) **hago** b) **conozco** (comme tous les verbes en *-cer*, *-cir*) c) **salgo** d) **sé** (avec accent) e) **doy** f) **pongo**\nCe sont des verbes « à *yo* irrégulier » : le reste de la conjugaison est régulier."}$exo$::jsonb),
  ('747a0610-aa22-57df-a449-8da772399021'::uuid, 2, 'traduction', $exo${"titre":"La présentation de Mateo","consigne":"Complète le texte avec les verbes au présent, puis réponds aux questions.","enonce":"**Situation.** Mateo, élève à Tolède, se présente à sa classe d'échange.\n\n> Me llamo Mateo y (tener) … quince años. (Ser) … de Toledo. Todos los días (salir) … de casa a las ocho y (ir) … al instituto en autobús. (Conocer) … a muchos alumnos. Mi hermana y yo (hacer) … los deberes juntos. Mis padres (estar) … muy contentos. (Estudiar) … francés desde hace dos años. Mañana (venir) … mi primo de Madrid. ¿Tú (saber) … dónde (estar) … el museo?\n\n1. Recopie les onze verbes conjugués.\n2. Pourquoi *están* porte-t-il un accent écrit ?\n3. Quels sont les **deux** emplois du présent, autres que l'action en cours, qui apparaissent dans le texte ?","bareme":[{"critere":"Premières personnes irrégulières et cumulards justes : tengo, soy, salgo, voy, conozco, vengo ou viene","points":8},{"critere":"Autres formes justes : hacemos, están, estudio, sabes, está","points":5},{"critere":"Accent de estar expliqué : l'accent tonique tombe sur la terminaison","points":3},{"critere":"Deux emplois repérés : action commencée dans le passé (desde hace), futur proche (mañana)","points":4}],"dureeMin":12,"corrige":"**1.** *tengo* — *Soy* — *salgo* — *voy* — *Conozco* — *hacemos* — *están* — *Estudio* — *viene* — *sabes* — *está*.\n- *tengo* : *tener* cumule un *yo* irrégulier et une diphtongue.\n- *soy*, *voy* : verbes totalement irréguliers.\n- *salgo*, *conozco* : *yo* irrégulier.\n- *viene* : 3e personne de *venir* (diphtongue).\n\n**2.** *Estar* porte un accent écrit sur ses formes *estás, está, estáis, están* car l'accent tonique tombe sur la **terminaison**, contrairement aux autres verbes. L'oublier est une faute d'orthographe.\n\n**3.**\n- *Estudio francés desde hace dos años* : une action **commencée dans le passé** et qui dure.\n- *Mañana viene mi primo* : le présent pour un **futur proche**."}$exo$::jsonb),
  ('747a0610-aa22-57df-a449-8da772399021'::uuid, 3, 'traduction', $exo${"titre":"Le portrait de Jade","consigne":"Corrige le texte en justifiant tes corrections, puis rédige un court texte en espagnol.","enonce":"**Document.** Jade se présente à sa correspondante de Burgos. Son texte contient **sept erreurs** de conjugaison au présent.\n\n> Hola, me llamo Jade. Tieno catorce años y vivemos en Lyon. Los sábados yo hazo deporte y conoco a muchos chicos del club. Mi padre esta cansado porque trabaja mucho. Yo no sabo cocinar, pero mi madre y yo tienemos un blog de recetas.\n\n1. Recopie le texte corrigé.\n2. Classe les sept erreurs en trois familles : *yo* irrégulier, verbe du radical ou cumulard, autre (orthographe ou terminaison).\n3. Explique pourquoi connaître la première personne du présent « débloque » d'autres temps.\n4. Rédige 5 phrases en espagnol (50 mots environ) pour te présenter. Tu dois employer : trois verbes à *yo* irrégulier différents, un cumulard (*tener, venir, decir*), *estar* avec son accent, un présent de futur proche et *desde hace*.","bareme":[{"critere":"Sept erreurs corrigées : tengo, vivimos, hago, conozco, está, sé, tenemos","points":7},{"critere":"Erreurs classées avec justesse","points":3},{"critere":"Lien avec le subjonctif expliqué (les irrégularités de yo se propagent)","points":3},{"critere":"Production : les cinq éléments demandés corrects","points":7}],"dureeMin":18,"corrige":"**1.** *Hola, me llamo Jade. **Tengo** catorce años y **vivimos** en Lyon. Los sábados yo **hago** deporte y **conozco** a muchos chicos del club. Mi padre **está** cansado porque trabaja mucho. Yo no **sé** cocinar, pero mi madre y yo **tenemos** un blog de recetas.*\n\n**2.**\n- *Yo* irrégulier : **hago**, **conozco**, **sé**.\n- Verbe du radical / cumulard : **tengo** (cumulard : *yo* irrégulier), **tenemos** (pas de diphtongue à *nosotros* — ni « tienemos »).\n- Autre : **vivimos** (terminaison des verbes en *-ir* à *nosotros*) ; **está** (accent écrit obligatoire).\n\n**3.** Le **subjonctif présent** se construit à partir de la première personne du présent : les irrégularités de *yo* se propagent à tout le subjonctif (*hago* → *haga*, *tengo* → *tenga*, *conozco* → *conozca*).\n\n**4.** Exemple de production :\n*Me llamo Noé y vivo en Rennes. Estudio español desde hace tres años. Los lunes salgo del colegio a las cinco, hago los deberes y pongo la mesa. Tengo dos hermanos. Mañana voy a la piscina y mis amigos están muy contentos.*\nOn vérifie : *salgo, hago, pongo* (yo irrégulier), *tengo* (cumulard), *están* (accent), *mañana voy* (futur proche), *desde hace*."}$exo$::jsonb),
  ('193f6816-fc53-5451-bae3-f2597571a846'::uuid, 1, 'traduction', $exo${"titre":"La voyelle qui bascule","consigne":"Forme le subjonctif présent des verbes, puis traduis la phrase.","enonce":"**1. Conjugue au subjonctif présent**, à toutes les personnes :\n\na) *hablar*\nb) *comer*\n\n**2. Donne la forme demandée du subjonctif présent :**\n\na) yo (hacer)\nb) él (tener)\nc) yo (ser)\nd) nosotros (ir)\ne) tú (estar)\n\n**3. Traduis :** Quand tu arriveras, appelle-moi.","bareme":[{"critere":"Hablar et comer justes aux six personnes, voyelle inversée (e / a)","points":8},{"critere":"Cinq formes justes : haga, tenga, sea, vayamos, estés","points":7},{"critere":"Traduction avec cuando + subjonctif : Cuando llegues, llámame","points":5}],"dureeMin":8,"corrige":"**1.**\na) *hable, hables, hable, hablemos, habléis, hablen* — verbe en *-ar* : terminaisons en **e**.\nb) *coma, comas, coma, comamos, comáis, coman* — verbe en *-er* : terminaisons en **a**.\n\n**2.**\na) **haga** — on part de *hago*.\nb) **tenga** — on part de *tengo*.\nc) **sea**\nd) **vayamos**\ne) **estés**\n*Ser, ir, estar* font partie des six irréguliers (*sea, vaya, haya, sepa, dé, esté*).\n\n**3.** ***Cuando llegues, llámame.*** — futur dans une subordonnée de temps : **subjonctif présent**, jamais « cuando llegarás »."}$exo$::jsonb),
  ('193f6816-fc53-5451-bae3-f2597571a846'::uuid, 2, 'traduction', $exo${"titre":"Les consignes avant le voyage","consigne":"Complète le message avec les verbes au subjonctif présent, puis réponds aux questions.","enonce":"**Situation.** Avant le voyage de classe d'Ana à Madrid, sa mère lui laisse un message.\n\n> Ana: quiero que me (llamar, tú) … cada noche. Es necesario que (hacer, tú) … la maleta hoy. Cuando (llegar, tú) … al hotel, escríbeme. Te lo digo para que lo (saber, tú) … : no creo que (hacer) … frío allí. Me alegro de que (ir, tú) … a Madrid. Antes de que (salir, tú) … , cierra la puerta. Y espero que tus amigas y tú lo (pasar) … muy bien.\n\n1. Recopie les huit verbes au subjonctif.\n2. Pour **quatre** d'entre eux, nomme le déclencheur du subjonctif (volonté, sentiment, doute, jugement impersonnel, futur dans une subordonnée de temps, but, conjonction).\n3. Pourquoi *cuando* est-il suivi du subjonctif dans ce message ?","bareme":[{"critere":"Huit subjonctifs justes : llames, hagas, llegues, sepas, haga, vayas, salgas, paséis","points":10},{"critere":"Quatre déclencheurs identifiés avec justesse","points":6},{"critere":"Cuando + subjonctif expliqué par la valeur de futur","points":4}],"dureeMin":12,"corrige":"**1.** *llames* — *hagas* — *llegues* — *sepas* — *haga* — *vayas* — *salgas* — *paséis*.\n\n**2.** Déclencheurs :\n- *quiero que me llames* : **volonté**.\n- *es necesario que hagas* : **jugement impersonnel**.\n- *cuando llegues* : **futur dans une subordonnée de temps**.\n- *para que lo sepas* : **but**.\n- *no creo que haga* : **doute, négation d'opinion**.\n- *me alegro de que vayas* : **sentiment**.\n- *antes de que salgas* : **conjonction** qui l'exige toujours.\n- *espero que lo paséis* : **souhait**.\n\n**3.** *Cuando llegues* renvoie à un moment **futur** (l'arrivée n'a pas encore eu lieu) : en espagnol, une subordonnée de temps à valeur de futur se met au **subjonctif présent**, là où le français emploie le futur (« quand tu arriveras »)."}$exo$::jsonb),
  ('193f6816-fc53-5451-bae3-f2597571a846'::uuid, 3, 'traduction', $exo${"titre":"La lettre de Maxime","consigne":"Corrige le texte en justifiant tes corrections, puis rédige une courte lettre en espagnol.","enonce":"**Document.** Maxime écrit à sa correspondante de Valladolid, qui va venir en France. Sa lettre contient **sept erreurs**.\n\n> Querida Irene: Cuando llegarás a París, te enseñaré la ciudad. Quiero que vienes a mi colegio. Te escribo para que lo sabes todo. No creo que es difícil. Espero que tú pides tu pasaporte pronto. Es necesario que estamos en la estación a las diez. Ojalá hace buen tiempo.\n\n1. Recopie la lettre corrigée.\n2. Pour **quatre** erreurs, nomme le déclencheur du subjonctif.\n3. Explique la formation de *pidas* (verbe à affaiblissement) et celle de *vengas*.\n4. Rédige une lettre de 50 mots environ pour inviter un ami espagnol chez toi. Tu dois employer le subjonctif après cinq déclencheurs différents, dont *cuando* à valeur de futur et une conjonction qui l'exige toujours (*para que, antes de que, sin que…*).","bareme":[{"critere":"Sept erreurs corrigées : llegues, vengas, sepas, sea, pidas, estemos, haga","points":7},{"critere":"Quatre déclencheurs nommés avec justesse","points":4},{"critere":"Formation de pidas et vengas expliquée (première personne du présent, voyelle inversée)","points":3},{"critere":"Production : cinq déclencheurs différents suivis d'un subjonctif juste","points":6}],"dureeMin":18,"corrige":"**1.** *Querida Irene: Cuando **llegues** a París, te enseñaré la ciudad. Quiero que **vengas** a mi colegio. Te escribo para que lo **sepas** todo. No creo que **sea** difícil. Espero que tú **pidas** tu pasaporte pronto. Es necesario que **estemos** en la estación a las diez. Ojalá **haga** buen tiempo.*\n\n**2.** Déclencheurs (quatre parmi) :\n- *cuando llegues* : futur dans une subordonnée de temps (le piège majeur du francophone).\n- *quiero que vengas* : volonté.\n- *para que lo sepas* : but (conjonction qui exige toujours le subjonctif).\n- *no creo que sea* : doute, négation d'opinion.\n- *espero que pidas* : souhait.\n- *es necesario que estemos* : jugement impersonnel.\n- *ojalá haga* : souhait.\n\n**3.**\n- *pidas* : on part de la première personne *pido*, on retire le *-o* et on inverse la voyelle (*-ir* → **a**) ; l'affaiblissement touche **toutes** les personnes du subjonctif (*pidamos*, *pidáis*).\n- *vengas* : on part de *vengo* : l'irrégularité de *yo* se propage à tout le subjonctif.\n\n**4.** Exemple de production :\n*Querido Álex: Quiero que vengas a mi casa en julio. Cuando llegues, iremos a la playa. Te lo digo antes de que compres el billete. Me alegro de que puedas venir. Es importante que traigas un bañador. ¡Ojalá haga sol!*\nOn vérifie : volonté, *cuando* + futur, *antes de que*, sentiment, jugement impersonnel, *ojalá*, avec des subjonctifs justes."}$exo$::jsonb),
  ('8dc6f8da-9011-5d99-8aec-fa68662c30d0'::uuid, 1, 'traduction', $exo${"titre":"Retratos y lenguas: lo esencial","consigne":"Traduis la partie 1 en espagnol, puis réponds en français à la partie 2 (une phrase par question).","enonce":"**1. Traduis en espagnol.**\n\n1. l'autoportrait\n2. le regard\n3. les racines\n4. la langue maternelle\n5. le sentiment d'appartenance\n6. bilingue\n\n**2. Repères.**\n\n7. Dans *Las Meninas* (1656), où Velázquez s'est-il représenté, et pourquoi dit-on que c'est un autoportrait glissé dans un portrait de cour ?\n8. Que montre *Las dos Fridas* (1939) de Frida Kahlo ?\n9. Quelles langues la Constitution espagnole de 1978 reconnaît-elle à côté du castillan, et où ?","bareme":[{"critere":"Six traductions justes (el autorretrato, la mirada, las raíces, la lengua materna, el sentimiento de pertenencia, bilingüe)","points":12},{"critere":"Trois repères exacts (Velázquez pinceau à la main près de l'infante ; double identité de Frida ; catalan, basque, galicien dans leurs communautés)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *el autorretrato*\n2. *la mirada*\n3. *las raíces*\n4. *la lengua materna*\n5. *el sentimiento de pertenencia*\n6. *bilingüe* (avec le tréma)\n(2 points chacune ; l'article oublié retire un demi-point.)\n\n**2.**\n7. Velázquez s'est peint **lui-même, pinceau à la main, à côté de l'infante** : le tableau représente la cour, mais le peintre s'y montre au travail. (3 points)\n8. Le tableau montre **deux Frida** assises, l'une en **robe européenne**, l'autre en **costume mexicain (tehuana)** : il exprime une **identité double**. (3 points)\n9. Le **catalan**, le **basque (euskera)** et le **galicien**, reconnus dans **leurs communautés**, le castillan étant la langue officielle de l'État. (2 points)"}$exo$::jsonb),
  ('8dc6f8da-9011-5d99-8aec-fa68662c30d0'::uuid, 2, 'traduction', $exo${"titre":"Daniela, entre dos culturas","consigne":"Lis le témoignage (texte inventé pour le sujet), puis réponds en espagnol aux questions.","enonce":"**Documento — testimonio de Daniela, 16 años (texto inventado)**\n\n> Me llamo Daniela y vivo en Los Ángeles. Mis padres nacieron en México. En casa hablamos español, en el instituto hablo inglés y con mis amigos hablamos spanglish: decimos «voy a parquear» o «vamos a comer el lonche». Mis abuelos dicen que no hablo bien español. A veces no sé si soy mexicana o estadounidense. Pero creo que tengo raíces en los dos países, y eso es una riqueza.\n\n1. ¿Dónde vive Daniela y de dónde son sus padres? (una frase)\n2. Copia **dos palabras** de spanglish del texto y explica en francés lo que significan.\n3. ¿Daniela se siente de dos culturas? Contesta en 40 a 60 palabras. Usa **A mi parecer…** y **Sin embargo…** y cita una frase del texto.","bareme":[{"critere":"Question 1 : Los Ángeles, parents nés au Mexique","points":4},{"critere":"Question 2 : parquear (se garer) et lonche (déjeuner) relevés et expliqués","points":6},{"critere":"Question 3 : réponse argumentée avec une citation, A mi parecer et Sin embargo","points":7},{"critere":"Correction de l'espagnol","points":3}],"dureeMin":11,"corrige":"1. *Daniela vive en Los Ángeles y sus padres nacieron en México.*\n\n2. *parquear* = se garer ; *lonche* = le déjeuner. Ce sont des mots anglais (*to park*, *lunch*) adaptés à l'espagnol : c'est le **spanglish**, le mélange d'anglais et d'espagnol des Latinos des États-Unis.\n\n3. Réponse type : *A mi parecer, Daniela se siente de dos culturas: habla español en casa, inglés en el instituto y spanglish con sus amigos. Sin embargo, a veces duda: dice «no sé si soy mexicana o estadounidense». Al final, piensa que tener raíces en los dos países es una riqueza.*\n\nÉléments attendus : les trois langues de Daniela, son doute, et sa conclusion positive (deux racines = une richesse) ; une citation exacte ; les deux expressions demandées."}$exo$::jsonb),
  ('8dc6f8da-9011-5d99-8aec-fa68662c30d0'::uuid, 3, 'traduction', $exo${"titre":"¿Qué revela un autorretrato?","consigne":"Rédige en espagnol un paragraphe argumenté de 110 à 140 mots, appuyé sur au moins deux artistes du cours.","enonce":"**Tema.** *¿Qué revela un autorretrato de su autor y de su época?*\n\nTon paragraphe doit :\n\n1. présenter **au moins deux autoportraits** du cours (artiste, date si elle est connue, ce qu'on y voit) ;\n2. expliquer ce que chacun révèle de l'artiste (sa place, son identité, sa souffrance…) ;\n3. employer les expressions du cours : *En primer plano se ve… / Parece que el pintor (la pintora) quiere mostrar… / A mi parecer… / Sin embargo…* ;\n4. utiliser au moins trois mots du chapitre (*el autorretrato, el rostro, los rasgos, la mirada, reflejar, las raíces*).","bareme":[{"critere":"Deux autoportraits du cours décrits avec exactitude","points":6},{"critere":"Interprétation : ce que l'œuvre révèle de l'artiste et de son époque","points":6},{"critere":"Expressions d'argumentation et vocabulaire du chapitre","points":4},{"critere":"Correction de la langue et longueur respectée","points":4}],"dureeMin":18,"corrige":"**Párrafo modelo (unas 130 palabras)** :\n\n*Un autorretrato no muestra solamente un rostro. En Las Meninas, pintado en 1656, Velázquez se representa con el pincel en la mano, al lado de la infanta. Parece que el pintor quiere mostrar su importancia en la corte: no es un simple criado, es un artista. Goya, por su parte, se pinta viejo y enfermo, sin buscar la belleza: su autorretrato es casi una confesión. En Las dos Fridas, pintado en 1939, Frida Kahlo se representa dos veces: una Frida lleva un vestido europeo y la otra un traje mexicano. Creo que la pintora refleja su doble identidad. A mi parecer, un autorretrato revela el lugar que el artista quiere ocupar en su época. Sin embargo, también puede revelar un dolor íntimo.*\n\n**Ce que le correcteur vérifie** :\n- deux œuvres exactes (Velázquez, *Las Meninas*, 1656 ; les autoportraits de Goya, vieilli et malade ; Frida Kahlo, *Las dos Fridas*, 1939) ;\n- une interprétation pour chacune (place à la cour ; aveu sans flatterie ; identité double) ;\n- les expressions du cours et trois mots du chapitre."}$exo$::jsonb),
  ('c14d0179-a9bc-508f-adcb-8541781dec60'::uuid, 1, 'traduction', $exo${"titre":"Abuelos y nietos: lo esencial","consigne":"Traduis la partie 1 en espagnol, puis réponds en français à la partie 2 (une phrase par question).","enonce":"**1. Traduis en espagnol.**\n\n1. les petits-enfants\n2. le fossé des générations\n3. hériter\n4. transmettre\n5. le souvenir\n6. bien s'entendre avec\n7. vivre ensemble, cohabiter\n\n**2. Repères.**\n\n8. Que cherchent les *Abuelas de Plaza de Mayo*, et pendant quelle dictature ces enfants ont-ils disparu ?\n9. De quoi parle *Alcarràs* de Carla Simón (Ours d'or 2022) ?\n10. Quelle place tient la mémoire familiale dans *Coco* (Pixar, 2017) ?","bareme":[{"critere":"Sept traductions justes (los nietos, la brecha generacional, heredar, transmitir, el recuerdo, llevarse bien con, convivir)","points":12},{"critere":"Trois repères exacts (petits-enfants volés, 1976-1983 ; famille de cultivateurs de pêches en Catalogne ; mémoire des ancêtres vitale)","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *los nietos*\n2. *la brecha generacional*\n3. *heredar*\n4. *transmitir*\n5. *el recuerdo*\n6. *llevarse bien con*\n7. *convivir*\n(12 points au total, environ 1,5 à 2 points par traduction.)\n\n**2.**\n8. Ces grands-mères cherchent leurs **petits-enfants volés par la dictature argentine (1976-1983)** ; plus de 130 ont retrouvé leur identité. (3 points)\n9. *Alcarràs* montre une **famille de cultivateurs de pêches en Catalogne** — grands-parents, parents et enfants — face à la **fin d'un mode de vie**. (3 points)\n10. Dans *Coco*, un garçon découvre **ses ancêtres le jour des morts**, au Mexique : la mémoire familiale y est **vitale**. (2 points)"}$exo$::jsonb),
  ('c14d0179-a9bc-508f-adcb-8541781dec60'::uuid, 2, 'traduction', $exo${"titre":"Carmen y su nieta Lucía","consigne":"Lis le témoignage (texte inventé pour le sujet), puis réponds en espagnol.","enonce":"**Documento — testimonio de Carmen, 72 años, Sevilla (texto inventado)**\n\n> Cada mañana llevo a mis nietos al colegio porque mi hija trabaja. Mi padre nunca habló de la guerra civil: en casa, era un silencio. Ahora mi nieta Lucía, que tiene 15 años, me hace muchas preguntas sobre esa época. Ella pasa horas con su móvil, mientras que yo prefiero leer el periódico. Pero nos llevamos muy bien, y un día le voy a dar las cartas de mi madre.\n\n1. ¿Por qué Carmen lleva a sus nietos al colegio? ¿Qué muestra este detalle sobre los abuelos en España? (dos frases)\n2. Escribe **una frase con *Es verdad que…, pero…*** sobre la relación entre Carmen y Lucía.\n3. Explica en tres frases qué se transmite entre Carmen y Lucía (objetos, recuerdos, preguntas) y por qué es la nieta quien hace las preguntas.","bareme":[{"critere":"Question 1 : sa fille travaille ; les grands-parents, pilier discret de l'économie familiale","points":5},{"critere":"Question 2 : concession juste construite avec Es verdad que…, pero…","points":4},{"critere":"Question 3 : ce qui se transmet et le lien avec le silence après la guerre civile","points":8},{"critere":"Correction de l'espagnol","points":3}],"dureeMin":12,"corrige":"1. *Carmen lleva a sus nietos al colegio porque su hija trabaja. Este detalle muestra que en España los abuelos cuidan muy a menudo a los nietos: son un pilar discreto de la economía familiar.*\n\n2. Exemple : *Es verdad que Lucía pasa horas con su móvil y Carmen prefiere el periódico, pero se llevan muy bien.* Toute concession fidèle au texte est acceptée.\n\n3. Réponse type : *Entre Carmen y Lucía se transmiten recuerdos y objetos: un día Carmen le va a dar las cartas de su madre. Es la nieta quien hace las preguntas porque el padre de Carmen nunca habló de la guerra civil: en muchas familias hubo un silencio. Así, la memoria pasa de una generación a otra.*\n\nÉléments attendus : les **cartas** (objet, héritage matériel), les **souvenirs** de l'époque (immatériel), et le **silence** des familles après la guerre civile et la dictature, que les petits-enfants brisent par leurs questions."}$exo$::jsonb),
  ('c14d0179-a9bc-508f-adcb-8541781dec60'::uuid, 3, 'traduction', $exo${"titre":"¿Qué nos transmiten nuestros abuelos?","consigne":"Rédige en espagnol un paragraphe argumenté de 110 à 140 mots, appuyé sur au moins deux repères du cours, dont un d'Espagne et un d'Amérique latine.","enonce":"**Tema.** *¿Qué nos transmiten nuestros abuelos?*\n\nTon paragraphe doit :\n\n1. s'appuyer sur **deux repères** du cours au moins (un en Espagne, un en Amérique latine) ;\n2. distinguer ce qui se transmet (biens, souvenirs, silences, questions) ;\n3. employer au moins trois expressions du cours : *Mientras que… / Esto se debe a que… / Es verdad que…, pero… / En resumen…* ;\n4. utiliser au moins trois mots du chapitre (*heredar, la herencia, transmitir, el recuerdo, los nietos…*).","bareme":[{"critere":"Deux repères exacts, l'un d'Espagne, l'autre d'Amérique latine","points":6},{"critere":"Analyse de ce qui se transmet (matériel, mémoire, silence)","points":5},{"critere":"Trois expressions d'argumentation du cours","points":3},{"critere":"Vocabulaire du chapitre","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Párrafo modelo (unas 130 palabras)** :\n\n*Nuestros abuelos no nos transmiten solamente una herencia material. En Argentina, las Abuelas de Plaza de Mayo buscan desde 1977 a los nietos robados por la dictadura (1976-1983): más de 130 han recuperado su identidad. Esto se debe a que la memoria familiar es una lucha. En España, muchas familias guardaron silencio después de la guerra civil y de la dictadura de Franco, y hoy son los nietos quienes hacen las preguntas. Mientras que los mayores callaban, los jóvenes quieren saber. En la película Coco, un niño mexicano descubre a sus antepasados el Día de Muertos. Es verdad que heredamos casas o dinero, pero también heredamos recuerdos, silencios y preguntas. En resumen, los abuelos nos transmiten una historia que tenemos que conocer.*\n\n**Ce que le correcteur vérifie** :\n- un repère espagnol exact (guerre civile 1936-1939 et dictature 1939-1975 ; *Volver*, Almodóvar, 2006 ; *Alcarràs*, 2022 ; les *abuelos* qui gardent les petits-enfants) et un repère latino-américain exact (*Abuelas de Plaza de Mayo* ; *Coco* ; *Mafalda*) ;\n- l'idée qu'on hérite de biens **et** de souvenirs, de silences et de questions ;\n- trois expressions du cours et trois mots du chapitre."}$exo$::jsonb),
  ('05302e8f-a3f4-5a72-b6ae-d0806d1d1dc1'::uuid, 1, 'traduction', $exo${"titre":"Fiestas y patrimonio","consigne":"Associe chaque fête à son lieu et à sa date (réponds par exemple : Las Fallas → …), puis traduis la partie 2 en espagnol.","enonce":"**1. Associe chaque fête à son lieu et à sa date.**\n\nFêtes : Las Fallas · San Fermín · El Día de Muertos · El Inti Raymi\n\nLieux et dates (dans le désordre) : A. Cuzco (Pérou), 24 juin — B. Valence, 19 mars — C. Mexique, 1er et 2 novembre — D. Pampelune, 6-14 juillet\n\nPour chaque fête, ajoute ce qu'on y célèbre en quelques mots (en français).\n\n**2. Traduis en espagnol.**\n\n5. le patrimoine\n6. la trace\n7. commémorer\n8. l'ancêtre\n9. les peuples autochtones","bareme":[{"critere":"Quatre associations fête / lieu / date correctes","points":6},{"critere":"Ce que célèbre chaque fête, exact","points":6},{"critere":"Cinq traductions justes (el patrimonio, la huella, conmemorar, el antepasado, los pueblos originarios)","points":8}],"dureeMin":8,"corrige":"**1.**\n- *Las Fallas* → **B**, Valence, 19 mars : des figures géantes brûlées ; patrimoine de l'UNESCO depuis 2016.\n- *San Fermín* → **D**, Pampelune, 6-14 juillet : les *encierros*, course devant les taureaux dans les rues.\n- *El Día de Muertos* → **C**, Mexique, 1er et 2 novembre : on accueille les défunts avec des autels (*ofrendas*), des *calaveras* en sucre et des fleurs de *cempasúchil*.\n- *El Inti Raymi* → **A**, Cuzco, 24 juin : la fête inca du Soleil, rejouée à Sacsayhuamán.\n(1,5 point par association, 1,5 point par explication.)\n\n**2.**\n5. *el patrimonio*\n6. *la huella*\n7. *conmemorar*\n8. *el antepasado*\n9. *los pueblos originarios*\n(1,6 point chacune, arrondi à 8 au total.)"}$exo$::jsonb),
  ('05302e8f-a3f4-5a72-b6ae-d0806d1d1dc1'::uuid, 2, 'traduction', $exo${"titre":"El 12 de octubre: una fecha, tres relatos","consigne":"Lis le document, puis réponds en espagnol.","enonce":"**Documento — una misma fecha**\n\n> El 12 de octubre de 1492, Cristóbal Colón llega a América. Hoy, en España, este día es la *Fiesta Nacional*. En Venezuela, desde 2002, se llama *Día de la Resistencia Indígena*. En Argentina, desde 2010, se llama *Día del Respeto a la Diversidad Cultural*.\n\n1. ¿Qué pasó el 12 de octubre de 1492, y cómo se llama este día en España?\n2. Explica por qué Venezuela y Argentina cambiaron el nombre de esta fecha. Usa **Para unos…, para otros…**\n3. Da tu opinión en dos frases que empiecen por **Me parece importante que…** (+ subjuntivo).\n\n*Ayuda : que conozcamos (connaître), que respetemos (respecter), que recordemos (se souvenir de).*","bareme":[{"critere":"Question 1 : arrivée de Colomb en Amérique, Fiesta Nacional","points":4},{"critere":"Question 2 : deux points de vue opposés expliqués avec Para unos…, para otros…","points":7},{"critere":"Question 3 : deux phrases avec Me parece importante que + subjonctif correct","points":6},{"critere":"Correction de l'espagnol","points":3}],"dureeMin":12,"corrige":"1. *El 12 de octubre de 1492, Cristóbal Colón llegó a América. En España, este día es la Fiesta Nacional.*\n\n2. Réponse type : *Para unos, el 12 de octubre celebra el encuentro entre Europa y América y la historia de España. Para otros, esta fecha recuerda la conquista y el sufrimiento de los pueblos originarios. Por eso Venezuela lo llama Día de la Resistencia Indígena y Argentina Día del Respeto a la Diversidad Cultural: quieren contar la historia desde el punto de vista de los indígenas.*\n\n3. Exemples :\n- *Me parece importante que conozcamos las dos versiones de la historia.*\n- *Me parece importante que respetemos a los pueblos originarios.*\n- *Me parece importante que recordemos la conquista.*\nLe verbe doit être au **subjonctif** : *Me parece importante que conocemos* est compté faux."}$exo$::jsonb),
  ('05302e8f-a3f4-5a72-b6ae-d0806d1d1dc1'::uuid, 3, 'traduction', $exo${"titre":"¿Por qué seguimos celebrando fiestas tan antiguas?","consigne":"Rédige en espagnol un paragraphe argumenté de 110 à 140 mots, appuyé sur au moins deux fêtes et un lieu de patrimoine du cours.","enonce":"**Tema.** *¿Por qué seguimos celebrando fiestas tan antiguas?*\n\nTon paragraphe doit :\n\n1. présenter **deux fêtes** du cours (lieu, date, ce qu'on y fait) ;\n2. citer **un lieu de patrimoine** (Alhambra, Chichén Itzá ou Teotihuacan) pour montrer que le passé est aussi dans les pierres ;\n3. expliquer pourquoi ces traditions durent et pourquoi elles peuvent faire débat ;\n4. employer *Esta fiesta se celebra en… desde… / Hoy en día…, antes… / Para unos…, para otros… / Me parece importante que…* (+ subjonctif).","bareme":[{"critere":"Deux fêtes exactes (lieu, date, pratiques)","points":5},{"critere":"Un lieu de patrimoine exact et bien relié au sujet","points":3},{"critere":"Analyse : pourquoi la tradition dure, pourquoi elle change ou fait débat","points":6},{"critere":"Expressions du cours, dont le subjonctif après Me parece importante que","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Párrafo modelo (unas 130 palabras)** :\n\n*En el mundo hispánico, el pasado no se queda en los museos. El Día de Muertos se celebra en México el 1 y el 2 de noviembre: las familias preparan ofrendas con fotos, flores de cempasúchil y calaveras de azúcar para recibir a sus difuntos. En Cuzco, el 24 de junio, el Inti Raymi recuerda la fiesta inca del Sol. El pasado también está en las piedras: la Alhambra de Granada fue el palacio de los nazaríes, los últimos reyes musulmanes de al-Andalus. Seguimos celebrando estas fiestas porque unen a las familias y a los pueblos alrededor de sus antepasados. Para unos son tradiciones religiosas, para otros fiestas de la memoria. Hoy en día atraen a muchos turistas. Me parece importante que conservemos este patrimonio.*\n\n**Ce que le correcteur vérifie** :\n- deux fêtes exactes (Fallas, 19 mars, Valence ; San Fermín, 6-14 juillet, Pampelune, *encierros* ; Semana Santa, processions ; Día de Muertos ; Inti Raymi) ;\n- un lieu de patrimoine exact (Alhambra des Nasrides ; Chichén Itzá, cité maya et pyramide de Kukulcán ; Teotihuacan, pyramides du Soleil et de la Lune) ;\n- l'idée qu'une fête est un passé **rejoué** chaque année, qui peut changer et faire débat ;\n- les expressions imposées, dont un **subjonctif** correct."}$exo$::jsonb),
  ('ee113ceb-ff52-54c4-825b-793cc61f8198'::uuid, 1, 'traduction', $exo${"titre":"Ciudad, jóvenes y turismo","consigne":"Traduis la partie 1 en espagnol, puis réponds en français à la partie 2 (une phrase par repère).","enonce":"**1. Traduis en espagnol.**\n\n1. l'environnement\n2. la pollution\n3. le loyer\n4. s'engager\n5. le tourisme de masse\n6. durable\n7. piétonnier\n\n**2. Explique chaque repère en une phrase.**\n\n8. Les *superilles* de Barcelone (depuis 2016).\n9. Le Metrocable de Medellín (2004).\n10. Le 15-M (15 mai 2011).","bareme":[{"critere":"Sept traductions justes (el medio ambiente, la contaminación, el alquiler, comprometerse, el turismo masivo, sostenible, peatonal)","points":12},{"critere":"Trois repères correctement expliqués","points":8}],"dureeMin":7,"corrige":"**1.**\n1. *el medio ambiente*\n2. *la contaminación*\n3. *el alquiler*\n4. *comprometerse*\n5. *el turismo masivo*\n6. *sostenible*\n7. *peatonal*\n(12 points au total.)\n\n**2.**\n8. Les *superilles* sont des **îlots de rues rendus aux piétons, aux arbres et aux jeux**, depuis 2016 dans le quartier de Poblenou. (3 points)\n9. Le Metrocable est un **téléphérique qui relie les quartiers pauvres des collines au métro** : un transport devenu outil d'intégration. (3 points)\n10. Le 15-M est le mouvement des **Indignés**, qui occupent la **Puerta del Sol** à Madrid contre le **chômage et la crise**. (2 points)"}$exo$::jsonb),
  ('ee113ceb-ff52-54c4-825b-793cc61f8198'::uuid, 2, 'traduction', $exo${"titre":"Canarias tiene un límite","consigne":"Lis le témoignage (texte inventé pour le sujet ; les faits datés viennent du cours), puis réponds en espagnol.","enonce":"**Documento — testimonio de Airam, 19 años, Tenerife (texto inventado)**\n\n> El 20 de abril de 2024 salí a la calle con miles de canarios. En mi pancarta estaba escrito: «Canarias tiene un límite». Mi familia vive del turismo: mi padre trabaja en un hotel. Pero cada año el alquiler sube, porque muchos pisos son ahora pisos turísticos. Mi hermana mayor no puede alquilar un piso en su propia isla.\n\n1. ¿Qué hizo Airam el 20 de abril de 2024 y por qué? (dos frases)\n2. Presenta la ventaja y el inconveniente del turismo para la familia de Airam: **La ventaja es que… / El inconveniente es que…**\n3. Propón **dos soluciones** con **Habría que…** y termina con un deseo: **Ojalá…** (+ subjuntivo).\n\n*Ayuda : que baje (baisser), que sea (être), que haya (avoir, il y ait).*","bareme":[{"critere":"Question 1 : manifestation contre le tourisme de masse et la hausse des loyers","points":4},{"critere":"Question 2 : avantage et inconvénient tirés du texte, formules justes","points":5},{"critere":"Question 3 : deux solutions avec Habría que + infinitif, souhait avec Ojalá + subjonctif","points":8},{"critere":"Correction de l'espagnol","points":3}],"dureeMin":12,"corrige":"1. *El 20 de abril de 2024, Airam participó en una manifestación con miles de canarios. Protestaba contra el turismo masivo y la subida de los alquileres.*\n\n2. *La ventaja es que el turismo da trabajo a su familia: su padre trabaja en un hotel. El inconveniente es que el alquiler sube cada año y su hermana no puede vivir en su propia isla.*\n\n3. Exemples :\n- *Habría que limitar los pisos turísticos.*\n- *Habría que construir viviendas para los habitantes.* (ou *controlar los alquileres*, *limitar el número de turistas*, comme au Machu Picchu)\n- *Ojalá el turismo sea más sostenible.* / *Ojalá el alquiler baje.*\n\n*Habría que* se construit avec l'**infinitif** ; *Ojalá* exige le **subjonctif** (*Ojalá el alquiler baja* est compté faux)."}$exo$::jsonb),
  ('ee113ceb-ff52-54c4-825b-793cc61f8198'::uuid, 3, 'traduction', $exo${"titre":"¿Cómo será la ciudad del mañana?","consigne":"Rédige en espagnol un paragraphe argumenté de 110 à 140 mots, appuyé sur au moins deux exemples de villes du cours.","enonce":"**Tema.** *¿Cómo será la ciudad del mañana?*\n\nTon paragraphe doit :\n\n1. présenter **un problème** des villes d'aujourd'hui (*El problema es que…*) ;\n2. s'appuyer sur **au moins deux exemples** du cours (Barcelone, Madrid, Medellín) ;\n3. donner un avantage et un inconvénient de ces solutions (*La ventaja es que… / El inconveniente es que…*) ;\n4. proposer une idée pour ta propre ville (*Habría que… / Sería necesario…*) ;\n5. finir par un souhait avec *Ojalá* + subjonctif.","bareme":[{"critere":"Deux exemples de villes exacts et datés","points":6},{"critere":"Analyse : problème, avantage, inconvénient","points":5},{"critere":"Proposition personnelle et souhait au subjonctif","points":3},{"critere":"Vocabulaire du chapitre (medio ambiente, contaminación, peatonal, sostenible…)","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Párrafo modelo (unas 130 palabras)** :\n\n*El problema es que en las grandes ciudades hay demasiados coches y la contaminación es peligrosa para la salud. Algunas ciudades hispánicas ya buscan soluciones. En Barcelona, desde 2016, las superilles devuelven las calles a los peatones, a los árboles y a los juegos. En Madrid, la zona de Madrid Central, creada en 2018, limita la circulación para reducir la contaminación del aire. En Medellín, el Metrocable une desde 2004 los barrios pobres de las colinas con el metro. La ventaja es que el aire es más limpio y la ciudad más justa. El inconveniente es que algunos habitantes necesitan el coche para trabajar. En mi ciudad, habría que crear más calles peatonales. Ojalá la ciudad del mañana sea más sostenible.*\n\n**Ce que le correcteur vérifie** :\n- deux exemples exacts (*superilles*, 2016, Poblenou ; Madrid Central, 2018, zone à faibles émissions ; Metrocable, 2004, intégration des quartiers des collines) ;\n- un problème, un avantage, un inconvénient ;\n- *Habría que* + infinitif et *Ojalá* + subjonctif (*sea, haya, tenga* accepté si correct) ;\n- le vocabulaire du chapitre."}$exo$::jsonb),
  ('e5e6f348-2819-555b-9389-9f540382337a'::uuid, 1, 'traduction', $exo${"titre":"Obras, moda y leyendas","consigne":"Associe chaque nom à ce qu'il faut savoir (réponds par exemple : 1 → …), puis traduis la partie 2 en espagnol.","enonce":"**1. Associe.**\n\n1. Picasso\n2. Fernando Botero\n3. Salvador Dalí\n4. Cristóbal Balenciaga\n5. La Llorona\n\nA. Couturier basque, inspiré par les costumes espagnols et les habits religieux — B. Une femme en pleurs qui erre la nuit en cherchant ses enfants (Mexique) — C. 58 toiles d'après *Las Meninas* de Velázquez (1957) — D. Les montres molles de *La persistance de la mémoire* (1931) — E. *Mona Lisa a los doce años* (1959), avec ses figures rondes\n\n**2. Traduis en espagnol.**\n\n6. le chef-d'œuvre\n7. l'hommage\n8. s'inspirer de\n9. la mode rapide\n10. la légende","bareme":[{"critere":"Cinq associations correctes","points":10},{"critere":"Cinq traductions justes (la obra maestra, el homenaje, inspirarse en, la moda rápida, la leyenda)","points":10}],"dureeMin":7,"corrige":"**1.**\n1 → **C** : Picasso peint 58 toiles d'après *Las Meninas* en 1957 (Museu Picasso de Barcelone).\n2 → **E** : Botero reprend la Joconde avec ses figures rondes.\n3 → **D** : Dalí, surréaliste, détourne les objets familiers.\n4 → **A** : Balenciaga, né à Getaria en 1895.\n5 → **B** : la légende mexicaine de La Llorona.\n(2 points par association.)\n\n**2.**\n6. *la obra maestra*\n7. *el homenaje*\n8. *inspirarse en* — attention, pas *inspirarse de*.\n9. *la moda rápida*\n10. *la leyenda*\n(2 points par traduction.)"}$exo$::jsonb),
  ('e5e6f348-2819-555b-9389-9f540382337a'::uuid, 2, 'traduction', $exo${"titre":"Velázquez y Picasso: dos Meninas","consigne":"Lis la présentation des deux documents, puis réponds en espagnol.","enonce":"**Documento 1** — *Las Meninas*, Diego Velázquez, 1656 (Museo del Prado, Madrid). Un cuadro en colores: en el centro, la infanta; a su lado, el pintor se representa con el pincel en la mano.\n\n**Documento 2** — *Las Meninas*, Pablo Picasso, 1957 (Museu Picasso, Barcelona). Una de las 58 versiones que Picasso pintó a partir del cuadro de Velázquez: el cuadro es casi en blanco y negro y las figuras están deformadas.\n\n1. Presenta cada documento en una frase (autor, fecha, lugar).\n2. Compara las dos obras en dos frases con **A diferencia del original…, en esta versión…**\n3. ¿Picasso copia, rinde homenaje o hace una parodia? Contesta en 40 a 60 palabras con **El artista se inspira en…** y **Me llama la atención…**","bareme":[{"critere":"Question 1 : deux présentations exactes","points":4},{"critere":"Question 2 : comparaison juste (couleurs, formes) avec la formule demandée","points":6},{"critere":"Question 3 : jugement argumenté, avec inspirarse en et Me llama la atención","points":7},{"critere":"Correction de l'espagnol","points":3}],"dureeMin":12,"corrige":"1. *El documento 1 es Las Meninas, un cuadro de Diego Velázquez pintado en 1656 y conservado en el Museo del Prado de Madrid. El documento 2 es una versión de Las Meninas pintada por Pablo Picasso en 1957, que está en el Museu Picasso de Barcelona.*\n\n2. *A diferencia del original, que está pintado en colores, en esta versión el cuadro es casi en blanco y negro. A diferencia del original, en esta versión las figuras están deformadas.*\n\n3. Réponse type : *El artista se inspira en la obra maestra de Velázquez: no la copia, porque cambia los colores y deforma las figuras. Pinta 58 versiones: es un homenaje al maestro, pero también impone su propio estilo. Me llama la atención la libertad de las formas.*\n\nÉléments attendus : ce n'est pas une copie (changements visibles) ; c'est un **hommage** (reprendre 58 fois le même tableau) qui affirme aussi le style de Picasso ; *inspirarse **en*** (pas *de*). Un élève qui défend l'idée de parodie peut obtenir les points s'il justifie par la déformation des figures."}$exo$::jsonb),
  ('e5e6f348-2819-555b-9389-9f540382337a'::uuid, 3, 'traduction', $exo${"titre":"¿Copiar es crear?","consigne":"Rédige en espagnol un paragraphe argumenté de 110 à 140 mots, appuyé sur au moins trois repères du cours pris dans deux domaines différents (art, mode, légendes).","enonce":"**Tema.** *¿Copiar es crear?*\n\nTon paragraphe doit :\n\n1. s'appuyer sur **trois repères** du cours au moins, dans deux domaines différents ;\n2. montrer qu'une reprise peut être un **hommage**, une **parodie** ou un **détournement** ;\n3. présenter une limite : le débat sur l'**appropriation culturelle** (Carolina Herrera, 2019) ;\n4. employer *El artista se inspira en… / rinde homenaje a… / A diferencia del original… / Lo que más me gusta es…*.","bareme":[{"critere":"Trois repères exacts dans deux domaines différents","points":6},{"critere":"Distinction hommage / parodie / détournement appliquée aux exemples","points":4},{"critere":"Limite : l'appropriation culturelle expliquée avec l'exemple du cours","points":4},{"critere":"Expressions du cours et vocabulaire du chapitre","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Párrafo modelo (unas 135 palabras)** :\n\n*Crear no siempre es partir de nada. En 1957, Picasso pinta 58 versiones de Las Meninas: se inspira en Velázquez y le rinde homenaje, pero impone su propio estilo. Fernando Botero hace casi una parodia con Mona Lisa a los doce años, porque da a la Gioconda sus figuras redondas. Dalí, con sus relojes blandos, transforma objetos familiares. Las leyendas también se reinventan: la Llorona vuelve en el cine y en las canciones. Sin embargo, copiar puede ser un problema. En 2019, México acusó a la diseñadora Carolina Herrera de usar motivos indígenas sin citarlos: es el debate sobre la apropiación cultural. A mi parecer, copiar es crear cuando el artista dialoga con la obra y respeta su origen. Lo que más me gusta es la libertad de estas versiones.*\n\n**Ce que le correcteur vérifie** :\n- trois repères exacts dans deux domaines (Picasso / *Las Meninas* 1957 ; Botero 1959 ; Dalí 1931 ; Balenciaga ; Zara et la mode rapide ; Carolina Herrera 2019 ; La Llorona ; El Dorado ; Don Quichotte 1605 et 1615) ;\n- les notions d'hommage, de parodie ou de détournement bien appliquées ;\n- la limite de l'appropriation culturelle ;\n- les expressions du cours."}$exo$::jsonb),
  ('0f1e0d1e-c934-50c7-a7c7-fe95c62ab731'::uuid, 1, 'traduction', $exo${"titre":"Otra España: lo esencial","consigne":"Réponds en français aux questions de la partie 1 (une phrase chacune), puis traduis la partie 2 en espagnol.","enonce":"**1. Repères.**\n\n1. Combien l'Espagne compte-t-elle de communautés autonomes ?\n2. Depuis quand Madrid est-elle la capitale, et qui y a installé la cour ?\n3. Qu'est-ce que la Puerta del Sol, et que fait-on là-bas le 31 décembre à minuit ?\n4. Dans quel musée madrilène se trouve *Guernica* de Picasso (1937) ?\n5. De quelle région le flamenco est-il originaire ?\n\n**2. Traduis en espagnol.**\n\n6. le cliché\n7. le paysage\n8. la côte\n9. la marée noire\n10. la pêche","bareme":[{"critere":"Cinq repères exacts","points":10},{"critere":"Cinq traductions justes (el tópico, el paisaje, la costa, la marea negra, la pesca)","points":10}],"dureeMin":7,"corrige":"**1.**\n1. **17 communautés autonomes** (et 2 villes autonomes, Ceuta et Melilla).\n2. Depuis **1561** : **Philippe II** y installe la cour.\n3. C'est le **kilomètre zéro** des routes d'Espagne ; on y mange **les douze raisins** à minuit.\n4. Au musée **Reina Sofía**.\n5. D'**Andalousie** (il est andalou et gitan).\n(2 points chacun.)\n\n**2.**\n6. *el tópico* (ou *el estereotipo*)\n7. *el paisaje*\n8. *la costa* (ou *el litoral*)\n9. *la marea negra*\n10. *la pesca*\n(2 points chacune.)"}$exo$::jsonb),
  ('0f1e0d1e-c934-50c7-a7c7-fe95c62ab731'::uuid, 2, 'traduction', $exo${"titre":"Detrás de la postal","consigne":"Lis l'affiche (inventée pour le sujet) et la fiche d'informations, puis réponds en espagnol.","enonce":"**Documento 1 — un cartel turístico (inventado)**\n\n> ¡Venga a España! Siempre sol, playa, flamenco y paella.\n\n**Documento 2 — ficha de informaciones**\n\n- Galicia: región verde, donde llueve mucho. Vigo es uno de los primeros puertos de pesca de Europa.\n- El flamenco es andaluz y gitano.\n- La paella es valenciana.\n- España tiene 17 comunidades autónomas, montañas (los Pirineos) y un desierto (Tabernas, en Almería).\n\n1. ¿Qué imagen de España da el cartel? (una frase)\n2. Escribe **tres frases** con **Se suele pensar que…, pero en realidad…** para corregir los tópicos del cartel con la ficha.\n3. Escribe **una frase** con **No todos los españoles…** y **una frase** con **Por ejemplo…**","bareme":[{"critere":"Question 1 : une image réduite à quatre clichés","points":3},{"critere":"Question 2 : trois clichés corrigés avec la fiche, formule juste","points":9},{"critere":"Question 3 : généralisation prudente et exemple justes","points":5},{"critere":"Correction de l'espagnol","points":3}],"dureeMin":11,"corrige":"1. *El cartel da una imagen muy simple de España: solo sol, playa, flamenco y paella.* Toute phrase qui parle d'une image réduite à quelques clichés est acceptée.\n\n2. Exemples :\n- *Se suele pensar que en España siempre hace sol, pero en realidad en Galicia llueve mucho y el paisaje es muy verde.*\n- *Se suele pensar que el flamenco es de toda España, pero en realidad es andaluz y gitano.*\n- *Se suele pensar que la paella es un plato de todo el país, pero en realidad es valenciana.*\n- (accepté) *Se suele pensar que España es solo playa, pero en realidad tiene montañas como los Pirineos y un desierto en Almería.*\n\n3. Exemples :\n- *No todos los españoles bailan flamenco.*\n- *Por ejemplo, Vigo vive de la pesca y no del turismo de playa.*"}$exo$::jsonb),
  ('0f1e0d1e-c934-50c7-a7c7-fe95c62ab731'::uuid, 3, 'traduction', $exo${"titre":"¿El mar: riqueza en peligro?","consigne":"Rédige en espagnol un paragraphe argumenté de 110 à 140 mots, appuyé sur au moins trois repères du cours sur la mer.","enonce":"**Tema.** *¿El mar: riqueza en peligro?*\n\nTon paragraphe doit :\n\n1. montrer que la mer est une **richesse** pour l'Espagne (côtes, pêche, tourisme), avec des chiffres ou des lieux du cours ;\n2. montrer qu'elle est **en danger**, avec **deux catastrophes ou menaces** du cours ;\n3. présenter une **réaction** de la société ;\n4. employer *Se suele pensar que…, pero en realidad… / Por ejemplo… / Es el caso de…* et au moins trois mots du chapitre.","bareme":[{"critere":"La mer comme richesse : faits exacts (8 000 km de côtes, première flotte de l'UE, Vigo)","points":5},{"critere":"Deux menaces exactes et datées (Prestige 2002, Mar Menor)","points":5},{"critere":"Une réaction de la société (Nunca Máis, bénévoles, personnalité juridique 2022)","points":4},{"critere":"Expressions du cours et vocabulaire du chapitre","points":3},{"critere":"Correction de la langue et longueur respectée","points":3}],"dureeMin":18,"corrige":"**Párrafo modelo (unas 130 palabras)** :\n\n*Se suele pensar que el mar en España solo sirve para el turismo de playa, pero en realidad es una riqueza mucho más grande. España tiene casi 8 000 kilómetros de costas y la primera flota de pesca de la Unión Europea. Por ejemplo, Vigo, en Galicia, es uno de los primeros puertos de pesca de Europa. Sin embargo, esta riqueza está en peligro. En 2002, el petrolero Prestige provocó una marea negra en Galicia: miles de voluntarios limpiaron las playas y nació el movimiento Nunca Máis. Es el caso también de la Mar Menor, en Murcia, una laguna contaminada por la agricultura intensiva. En 2022, una ley le dio personalidad jurídica, una primicia en Europa. En mi opinión, proteger el mar es proteger a los pescadores.*\n\n**Ce que le correcteur vérifie** :\n- la richesse : près de 8 000 km de côtes (Méditerranée, Atlantique, Cantabrique), première flotte de pêche de l'UE, Vigo ;\n- deux menaces : le *Prestige* (2002, marée noire en Galice) et la Mar Menor (lagune polluée par l'agriculture intensive) ;\n- une réaction : bénévoles et *Nunca Máis* ; personnalité juridique de la Mar Menor (2022) ;\n- les expressions imposées et le vocabulaire (*la costa, la pesca, el pescador, la marea negra*)."}$exo$::jsonb),
  ('a2c23e67-374d-5cae-9fd8-f6d6d329779d'::uuid, 1, 'traduction', $exo${"titre":"Haz, di, ven: el imperativo","consigne":"Donne l'impératif affirmatif demandé.","enonce":"**1. Impératif affirmatif, personne *tú*.**\n\n1. hablar\n2. comer\n3. hacer\n4. decir\n5. salir\n6. poner\n7. venir\n8. volver\n\n**2. Impératif affirmatif, personne *vosotros*.**\n\n9. hablar\n10. comer\n11. vivir\n12. escuchar","bareme":[{"critere":"Formes régulières et à diphtongue à la personne tú (habla, come, vuelve)","points":5},{"critere":"Cinq irréguliers à la personne tú (haz, di, sal, pon, ven)","points":9},{"critere":"Quatre formes vosotros en -d (hablad, comed, vivid, escuchad)","points":6}],"dureeMin":6,"corrige":"**1.**\n1. *habla* — 3e personne du singulier du présent.\n2. *come*\n3. *haz* (irrégulier)\n4. *di* (irrégulier)\n5. *sal* (irrégulier)\n6. *pon* (irrégulier)\n7. *ven* (irrégulier)\n8. *vuelve* — le verbe garde sa diphtongue.\n\n**2.**\n9. *hablad*\n10. *comed*\n11. *vivid*\n12. *escuchad*\n— à la personne *vosotros*, le **-r** de l'infinitif devient **-d**.\n\nCritère 1 : environ 1,7 point par forme (habla, come, vuelve). Critère 2 : environ 1,8 point par irrégulier. Critère 3 : 1,5 point par forme."}$exo$::jsonb),
  ('a2c23e67-374d-5cae-9fd8-f6d6d329779d'::uuid, 2, 'traduction', $exo${"titre":"Del sí al no","consigne":"Partie 1 : mets chaque ordre à la forme négative. Partie 2 : mets chaque défense à la forme affirmative. Attention à la place des pronoms et aux accents.","enonce":"**1. Passe à la forme négative.**\n\n1. Habla.\n2. Dímelo.\n3. Levántate.\n4. Hazlo.\n5. Cómpralo. (tú)\n\n**2. Passe à la forme affirmative.**\n\n6. No lo toques. (tú)\n7. No te sientes. (tú)\n8. No os levantéis. (vosotros)\n9. No nos sentemos. (nosotros)\n10. No lo comáis. (vosotros)","bareme":[{"critere":"Partie 1 : no + subjonctif présent (hables, digas, te levantes, hagas, compres)","points":6},{"critere":"Partie 1 : pronoms placés devant le verbe au négatif","points":4},{"critere":"Partie 2 : impératifs affirmatifs justes avec pronoms soudés","points":6},{"critere":"Partie 2 : accents écrits et chute du -s / du -d (sentémonos, levantaos)","points":4}],"dureeMin":11,"corrige":"**1.**\n1. *No hables.*\n2. *No me lo digas.* — subjonctif *digas*, pronoms devant.\n3. *No te levantes.*\n4. *No lo hagas.* — subjonctif de *hacer* : *hagas*.\n5. *No lo compres.*\n\n**2.**\n6. *Tócalo.* — enclise et accent écrit pour garder l'accent tonique.\n7. *Siéntate.*\n8. *Levantaos.* — le **-d** de *levantad* tombe devant *os*.\n9. *Sentémonos.* — le **-s** de *sentemos* tombe devant *nos*.\n10. *Comedlo.*\n\nToute forme *no habla, no dímelo, levantados, sentémosnos* est comptée fausse. L'oubli d'un accent écrit (*sientate, tocalo*) retire 1 point au critère 4."}$exo$::jsonb),
  ('a2c23e67-374d-5cae-9fd8-f6d6d329779d'::uuid, 3, 'traduction', $exo${"titre":"Las instrucciones del profesor","consigne":"Traduis le texte en espagnol (thème). Choisis chaque fois la bonne personne (tú, vosotros, nosotros) et la bonne forme (affirmative ou négative).","enonce":"**Thème : traduis en espagnol.**\n\nLe professeur parle à sa classe la veille d'une sortie :\n\n> « Demain, levez-vous tôt et prenez votre sac. N'oubliez pas vos billets ! Lucas, écoute-moi et ne fais pas de bruit. Si tu as un problème, dis-le-moi. Dans le bus, ne vous levez pas. Et maintenant, asseyons-nous et parlons du programme. »\n\n*Ayuda : se lever = levantarse ; prendre = tomar ; oublier = olvidar ; le billet = el billete ; écouter = escuchar ; le bruit = el ruido ; s'asseoir = sentarse ; parler = hablar.*","bareme":[{"critere":"Impératifs vosotros affirmatifs justes (levantaos, tomad)","points":4},{"critere":"Défenses au subjonctif (no olvidéis, no hagas, no os levantéis)","points":5},{"critere":"Personne tú avec enclise et accents (escúchame, dímelo)","points":5},{"critere":"Personne nosotros (sentémonos, hablemos)","points":3},{"critere":"Correction générale de la traduction","points":3}],"dureeMin":18,"corrige":"**Traduction modèle** :\n\n*« Mañana, levantaos temprano y tomad vuestra mochila. ¡No olvidéis vuestros billetes! Lucas, escúchame y no hagas ruido. Si tienes un problema, dímelo. En el autobús, no os levantéis. Y ahora, sentémonos y hablemos del programa. »*\n\n**Points de contrôle** :\n- *levantaos* (le -d de *levantad* tombe devant *os*), *tomad* ;\n- *no olvidéis*, *no hagas*, *no os levantéis* : **no + subjonctif présent**, pronoms devant ;\n- *escúchame*, *dímelo* : impératif *tú*, pronoms soudés, accent écrit ;\n- *sentémonos* (le -s tombe devant *nos*), *hablemos* : personne *nosotros* au subjonctif.\n\nAccepté : *bolsa* ou *mochila* pour « sac », *bus* pour *autobús*, *pronto* pour *temprano*."}$exo$::jsonb),
  ('2aee1ab0-684b-522d-9089-53ec4ebdf184'::uuid, 1, 'traduction', $exo${"titre":"¿Por o para?","consigne":"Complète chaque phrase avec por ou para.","enonce":"Complète avec *por* ou *para*.\n\n1. Estudio ___ aprobar el examen.\n2. Hablamos ___ teléfono.\n3. Este regalo es ___ ti.\n4. Lo compré ___ diez euros.\n5. Salgo ___ Madrid mañana.\n6. Me levanto temprano ___ la mañana.\n7. *Don Quijote* fue escrito ___ Cervantes.\n8. Tengo que terminar este trabajo ___ el lunes.\n9. Gracias ___ tu ayuda.\n10. Lo hizo ___ amor.","bareme":[{"critere":"Para bien employé : but, destinataire, destination, date limite (1, 3, 5, 8)","points":8},{"critere":"Por bien employé : moyen, prix, moment, agent, cause (2, 4, 6, 7, 9, 10)","points":12}],"dureeMin":7,"corrige":"1. ***para** aprobar* — but + infinitif.\n2. ***por** teléfono* — moyen.\n3. ***para** ti* — destinataire.\n4. ***por** diez euros* — prix, échange.\n5. ***para** Madrid* — destination.\n6. ***por** la mañana* — moment de la journée.\n7. *escrito **por** Cervantes* — agent du passif.\n8. ***para** el lunes* — date limite.\n9. *Gracias **por** tu ayuda* — on remercie « à cause de » l'aide.\n10. ***por** amor* — cause.\n\n2 points par phrase."}$exo$::jsonb),
  ('2aee1ab0-684b-522d-9089-53ec4ebdf184'::uuid, 2, 'traduction', $exo${"titre":"Justifica tu elección","consigne":"Complète chaque phrase avec por ou para, puis écris en français l'emploi qui justifie ton choix (but, cause, moyen, etc.).","enonce":"1. Paseamos ___ el parque todos los domingos.\n2. ___ mí, el español es más fácil que el inglés.\n3. Es muy alto ___ su edad.\n4. Lucho ___ mis derechos.\n5. Te llamo ___ decirte que llego tarde.\n6. La casa está ___ limpiar.\n7. ___ fin, llegamos a Sevilla.\n8. Queremos ser amigos ___ siempre.\n\n**Puis traduis en espagnol :**\n\n9. J'ai traversé Tolède.\n10. Je vais vers Tolède.","bareme":[{"critere":"Huit prépositions justes","points":8},{"critere":"Huit emplois correctement nommés","points":8},{"critere":"Traductions 9 et 10 (pasé por / voy para)","points":4}],"dureeMin":11,"corrige":"1. ***por** el parque* — lieu traversé ou vague.\n2. ***Para** mí* — point de vue (selon moi).\n3. ***para** su edad* — comparaison.\n4. ***por** mis derechos* — en faveur de.\n5. ***para** decirte* — but + infinitif.\n6. *está **por** limpiar* — *estar por* + infinitif = rester à faire.\n7. ***Por** fin* — expression figée (enfin).\n8. ***para** siempre* — expression figée (pour toujours).\n(1 point par préposition, 1 point par emploi.)\n\n9. *Pasé por Toledo.* — lieu traversé.\n10. *Voy para Toledo.* — direction, destination (*Voy a Toledo* accepté pour le sens, mais l'exercice attend *para*).\n(2 points chacune.)"}$exo$::jsonb),
  ('2aee1ab0-684b-522d-9089-53ec4ebdf184'::uuid, 3, 'traduction', $exo${"titre":"Un viaje a Sevilla","consigne":"Partie 1 : explique la différence de sens entre les deux phrases. Partie 2 : traduis le texte en espagnol en justifiant chaque por et chaque para entre parenthèses.","enonce":"**1. Explique la différence de sens (en français).**\n\n1. *Trabajo por mi familia.* / *Trabajo para mi familia.*\n\n**2. Thème : traduis en espagnol.**\n\n> Merci pour ton message ! Je t'écris pour te dire que je pars pour Séville vendredi. J'ai acheté le billet pour trente euros, par internet. Je voyagerai le matin et je passerai par Cordoue. J'ai un cadeau pour ta mère. Selon moi, ce sera un voyage génial. Je dois rendre mon exposé pour lundi, c'est pourquoi j'emporte mon ordinateur.\n\n*Ayuda : el mensaje ; el billete ; internet ; viajar ; Córdoba ; el regalo ; genial ; entregar la exposición ; llevar el ordenador. Tu peux écrire les verbes au présent ou au futur.*","bareme":[{"critere":"Partie 1 : différence de sens expliquée (cause, en faveur / employeur, destinataire)","points":4},{"critere":"Por justes et justifiés (gracias por, por treinta euros, por internet, por la mañana, pasar por, por eso)","points":7},{"critere":"Para justes et justifiés (para decirte, para Sevilla, para tu madre, para mí, para el lunes)","points":6},{"critere":"Correction générale de la traduction","points":3}],"dureeMin":18,"corrige":"**1.**\n*Trabajo por mi familia* : je travaille **à cause d'elle, en sa faveur** (pour la faire vivre). *Trabajo para mi familia* : ma famille est **mon employeur**, ou la **destinataire** de mon travail.\n\n**2. Traduction modèle** :\n*¡Gracias por (cause) tu mensaje! Te escribo para (but + infinitif) decirte que salgo para (destination) Sevilla el viernes. Compré el billete por (prix) treinta euros, por (moyen) internet. Viajaré por (moment de la journée) la mañana y pasaré por (lieu traversé) Córdoba. Tengo un regalo para (destinataire) tu madre. Para (point de vue) mí, será un viaje genial. Tengo que entregar mi exposición para (date limite) el lunes, por eso (expression figée : c'est pourquoi) llevo mi ordenador.*\n\nPoints de contrôle : 6 *por* et 5 *para*, chacun avec son emploi. *Gracias para* ou *por el lunes* sont comptés faux. Le présent (*viajo, paso*) est accepté à la place du futur ; *Debo entregar* est accepté pour *Tengo que entregar*."}$exo$::jsonb),
  ('5c2c1c34-c99f-5efd-9de8-e36dee8a407a'::uuid, 1, 'traduction', $exo${"titre":"A, en o nada","consigne":"Complète chaque phrase avec a, al, en ou Ø (aucune préposition).","enonce":"Complète avec *a*, *al*, *en* ou *Ø*.\n\n1. Veo ___ María en el patio.\n2. Tengo ___ dos hermanos.\n3. Estoy ___ la playa.\n4. Voy ___ Madrid en tren.\n5. Vamos al colegio ___ pie.\n6. La clase empieza ___ las ocho.\n7. ___ verano, hace mucho calor.\n8. ___ lunes voy al gimnasio. (le lundi)\n9. Busco ___ médico de mi abuela.\n10. Empieza ___ llover.","bareme":[{"critere":"A devant un COD de personne précise, absent avec tener (1, 2, 9)","points":6},{"critere":"A / en pour le mouvement et le lieu (3, 4, 5, 10)","points":8},{"critere":"Prépositions du temps (6, 7, 8)","points":6}],"dureeMin":7,"corrige":"1. *Veo **a** María* — COD de personne précise.\n2. *Tengo **Ø** dos hermanos* — *tener* ne prend jamais *a*.\n3. *Estoy **en** la playa* — lieu où l'on est, sans mouvement.\n4. *Voy **a** Madrid* — mouvement, destination.\n5. ***a** pie* — expression.\n6. ***a** las ocho* — l'heure.\n7. ***En** verano* — la saison.\n8. ***Ø** El lunes voy al gimnasio* — le jour sans préposition.\n9. *Busco **al** médico de mi abuela* — un médecin précis : *a + el = al*.\n10. *Empieza **a** llover* — verbe de début + infinitif.\n\n2 points par phrase."}$exo$::jsonb),
  ('5c2c1c34-c99f-5efd-9de8-e36dee8a407a'::uuid, 2, 'traduction', $exo${"titre":"Querer algo, querer a alguien","consigne":"Partie 1 : explique la différence de sens. Partie 2 : traduis en espagnol.","enonce":"**1. Explique en français la différence.**\n\n1. *Busco un médico.* / *Busco al médico de mi abuela.*\n2. *Quiero un perro.* / *Quiero a mi perro.*\n\n**2. Traduis en espagnol.**\n\n3. J'aime mes parents.\n4. Je ne vois personne.\n5. Qui cherches-tu ?\n6. Je viens te voir.\n7. Je vais étudier. (futur proche)\n8. J'habite à Séville, mais je vais à Madrid dans deux jours.\n9. Nous allons à Tolède à cheval.","bareme":[{"critere":"Partie 1 : différences de sens expliquées (personne précise ou non ; vouloir / aimer)","points":6},{"critere":"A devant quien, nadie et un COD de personne (3, 4, 5)","points":6},{"critere":"A de mouvement, ir a + infinitif, en sans mouvement, dentro de, a caballo (6 à 9)","points":6},{"critere":"Correction des phrases","points":2}],"dureeMin":11,"corrige":"**1.**\n1. *Busco un médico* : je cherche **n'importe quel** médecin ; *Busco al médico de mi abuela* : je cherche **un médecin précis**, d'où le *a*.\n2. *Quiero un perro* : je **veux** un chien (une chose que je n'ai pas) ; *Quiero a mi perro* : j'**aime** mon chien — le *a* change le sens de *querer*.\n\n**2.**\n3. *Quiero a mis padres.*\n4. *No veo a nadie.*\n5. *¿A quién buscas?*\n6. *Vengo a verte.*\n7. *Voy a estudiar.*\n8. *Vivo en Sevilla, pero voy a Madrid dentro de dos días.* — *en* sans mouvement, *a* avec mouvement, *dentro de* pour un délai futur.\n9. *Vamos a Toledo a caballo.*"}$exo$::jsonb),
  ('5c2c1c34-c99f-5efd-9de8-e36dee8a407a'::uuid, 3, 'traduction', $exo${"titre":"Un fin de semana en Toledo","consigne":"Partie 1 : corrige les fautes et explique chaque correction. Partie 2 : traduis le texte en espagnol.","enonce":"**1. Chaque phrase contient une faute. Corrige-la et explique-la.**\n\n1. Veo mi abuela cada domingo.\n2. Tengo a tres primos.\n3. Estoy a Madrid.\n4. Vamos en pie al colegio.\n5. En el sábado voy al cine.\n\n**2. Thème : traduis en espagnol.**\n\n> Le samedi, je vais voir mes grands-parents à Tolède, en train. En été, nous nous promenons dans le parc et je promène leur chien. À huit heures, nous dînons. Je n'y connais personne d'autre, mais j'aime cette ville. Dans trois semaines, j'irai à Tolède à pied avec ma classe !\n\n*Ayuda : pasear (se promener / promener) ; cenar ; conocer ; la ciudad.*","bareme":[{"critere":"Partie 1 : cinq corrections justes","points":5},{"critere":"Partie 1 : règles correctement expliquées","points":4},{"critere":"Partie 2 : a devant les personnes et l'animal familier (a mis abuelos, a su perro, a nadie)","points":4},{"critere":"Partie 2 : mouvement, lieu, transport et temps (los sábados, a Toledo, en tren, en verano, a las ocho, dentro de, a pie)","points":5},{"critere":"Correction générale de la traduction","points":2}],"dureeMin":18,"corrige":"**1.**\n1. *Veo **a** mi abuela cada domingo.* — COD de personne précise.\n2. *Tengo **tres primos**.* — *tener* ne prend jamais *a*.\n3. *Estoy **en** Madrid.* — lieu sans mouvement : *en*.\n4. *Vamos **a pie** al colegio.* — on dit *a pie*.\n5. ***El** sábado voy al cine.* — le jour, sans préposition.\n\n**2. Traduction modèle** :\n*Los sábados voy a ver a mis abuelos a Toledo en tren. En verano, paseamos por el parque y paseo a su perro. A las ocho, cenamos. No conozco a nadie más, pero me gusta esta ciudad. Dentro de tres semanas, voy a ir a Toledo a pie con mi clase.*\n\nPoints de contrôle :\n- *Los sábados* (sans préposition), *voy a ver* (mouvement + infinitif), ***a** mis abuelos* (personnes précises), *a Toledo*, *en tren* ;\n- *En verano* ; *paseo **a** su perro* (animal familier) ; *A las ocho* ;\n- *No conozco **a** nadie* ;\n- *Dentro de tres semanas* ; *a pie*. *Iré* est accepté à la place de *voy a ir* ; *paseamos en el parque* est toléré."}$exo$::jsonb),
  ('06e09431-d14d-5b9e-8e35-c93c22cbb919'::uuid, 1, 'traduction', $exo${"titre":"Hay, hace, desde hace","consigne":"Complète chaque phrase avec hay, hace, desde, desde hace ou dentro de.","enonce":"Complète chaque phrase.\n\n1. ___ muchos alumnos en el patio. (il y a beaucoup d'élèves)\n2. Llegué a Madrid ___ dos años. (il y a deux ans)\n3. Vivo aquí ___ tres años. (depuis trois ans)\n4. Estudio español ___ 2023. (depuis 2023)\n5. ___ seis meses que aprendo a nadar. (cela fait six mois)\n6. Vuelvo ___ dos días. (dans deux jours)\n7. ¿___ cuándo vives en Sevilla? (depuis quand)\n8. ___ una farmacia cerca de mi casa. (il y a une pharmacie)","bareme":[{"critere":"Hay pour l'existence (1, 8)","points":5},{"critere":"Hace pour un moment passé ou une durée (2, 5)","points":5},{"critere":"Desde, desde hace, dentro de bien choisis (3, 4, 6, 7)","points":10}],"dureeMin":6,"corrige":"1. ***Hay** muchos alumnos* — existence.\n2. *Llegué a Madrid **hace** dos años* — moment dans le passé (passé simple : l'action est finie).\n3. *Vivo aquí **desde hace** tres años* — durée qui continue.\n4. *Estudio español **desde** 2023* — date de départ.\n5. ***Hace** seis meses que aprendo a nadar* — *hace* + durée + *que* + présent.\n6. *Vuelvo **dentro de** dos días* — délai futur.\n7. *¿**Desde** cuándo vives en Sevilla?*\n8. ***Hay** una farmacia* — existence.\n\n*Hay dos años que…* est toujours compté faux. 2,5 points par réponse."}$exo$::jsonb),
  ('06e09431-d14d-5b9e-8e35-c93c22cbb919'::uuid, 2, 'traduction', $exo${"titre":"Tres maneras de decirlo","consigne":"Partie 1 : exprime chaque idée de trois façons (desde hace, hace… que, llevar + gérondif). Partie 2 : traduis.","enonce":"**1. Écris chaque phrase de trois façons.**\n\n1. Cela fait deux ans que je joue de la guitare. (*tocar la guitarra*)\n2. Cela fait une heure que nous attendons le bus. (*esperar el autobús*)\n\n**2. Traduis en espagnol.**\n\n3. Ça fait une heure que je t'attends.\n4. Depuis combien de temps apprends-tu l'espagnol ?\n5. Il y a longtemps, j'ai vécu à Madrid.\n6. Au bout de deux jours, il est rentré.\n7. J'ai étudié pendant trois heures.","bareme":[{"critere":"Partie 1 : les trois tournures justes pour chaque phrase, verbe au présent","points":10},{"critere":"Partie 1 : gérondifs corrects avec llevar (tocando, esperando)","points":2},{"critere":"Partie 2 : repères de durée justes (llevo… esperándote, cuánto tiempo, hace mucho, al cabo de, durante)","points":8}],"dureeMin":12,"corrige":"**1.**\n1. *Toco la guitarra desde hace dos años.* / *Hace dos años que toco la guitarra.* / *Llevo dos años tocando la guitarra.*\n2. *Esperamos el autobús desde hace una hora.* / *Hace una hora que esperamos el autobús.* / *Llevamos una hora esperando el autobús.*\nDans les trois cas, le verbe est au **présent** : l'action continue. *Llevar* s'accorde avec le sujet (*llevo, llevamos*) et se construit avec le **gérondif**.\n\n**2.**\n3. *Llevo una hora esperándote.* (ou *Hace una hora que te espero*)\n4. *¿Cuánto tiempo hace que aprendes español?* / *¿Cuánto tiempo llevas aprendiendo español?*\n5. *Hace mucho (tiempo), viví en Madrid.* — action finie : passé simple.\n6. *Al cabo de dos días, volvió.*\n7. *Estudié durante tres horas.*"}$exo$::jsonb),
  ('06e09431-d14d-5b9e-8e35-c93c22cbb919'::uuid, 3, 'traduction', $exo${"titre":"Una nueva vida en Valencia","consigne":"Traduis le texte en espagnol (thème). Pour chaque expression de temps, choisis la bonne tournure et le bon temps du verbe.","enonce":"**Thème : traduis en espagnol.**\n\n> Je suis arrivée à Valence il y a trois ans. Au début, je ne connaissais personne. Aujourd'hui, cela fait deux ans que je joue au basket dans un club et j'y ai beaucoup d'amis. Hier, cela faisait une heure que j'attendais mon amie Lucía devant le stade quand elle m'a appelée. Il y a beaucoup de parcs dans cette ville. Dans six mois, je vais partir en France et je serai triste : depuis que je suis arrivée, je suis heureuse ici.\n\n*Ayuda : jugar al baloncesto ; el club ; el estadio ; llamar ; irse a Francia ; triste ; feliz ; conocer. « Quand elle m'a appelée » = cuando me llamó.*","bareme":[{"critere":"Hace + durée pour un moment passé, verbe au passé simple (llegué hace tres años)","points":4},{"critere":"Durée qui continue au présent (hace dos años que juego / llevo dos años jugando)","points":4},{"critere":"Durée au passé à l'imparfait (hacía una hora que esperaba / llevaba una hora esperando)","points":5},{"critere":"Hay (existence), dentro de, desde que","points":4},{"critere":"Correction générale de la traduction","points":3}],"dureeMin":20,"corrige":"**Traduction modèle** :\n\n*Llegué a Valencia hace tres años. Al principio, no conocía a nadie. Hoy, hace dos años que juego al baloncesto en un club y tengo muchos amigos. Ayer, llevaba una hora esperando a mi amiga Lucía delante del estadio cuando me llamó. Hay muchos parques en esta ciudad. Dentro de seis meses, voy a irme a Francia y estaré triste: desde que llegué, soy feliz aquí.*\n\n**Points de contrôle** :\n- *Llegué … hace tres años* : action finie → **passé simple** ;\n- *hace dos años que juego* (ou *juego … desde hace dos años*, *llevo dos años jugando*) : durée qui continue → **présent** ;\n- *llevaba una hora esperando* (ou *hacía una hora que esperaba*) : durée au passé → **imparfait** ;\n- *Hay muchos parques* : existence, jamais *hace* ;\n- *Dentro de seis meses* : délai futur ;\n- *desde que llegué* : *desde que* + verbe.\n\nAccepté : *me iré a Francia*, *estoy contenta* pour *soy feliz* ; *a mi amiga* est attendu (COD de personne), son oubli retire 1 point au critère 5."}$exo$::jsonb),
  ('0933b441-0b01-5b69-bb49-5d82429907ec'::uuid, 1, 'traduction', $exo${"titre":"Cien, ciento, quinientos","consigne":"Écris chaque nombre en toutes lettres en espagnol, avec le nom quand il est donné.","enonce":"Écris en lettres.\n\n1. 16\n2. 22\n3. 45\n4. 100 euros\n5. 105\n6. 200 chicas (filles)\n7. 500 personas\n8. 700 libros\n9. 2 000\n10. 1 000 000 de personas","bareme":[{"critere":"Nombres de 16 à 45 bien écrits (un mot jusqu'à 29, y ensuite)","points":6},{"critere":"Cien / ciento bien choisis (100 euros, 105)","points":4},{"critere":"Centaines accordées et irrégulières (doscientas, quinientas, setecientos)","points":6},{"critere":"Mil invariable et millón de","points":4}],"dureeMin":6,"corrige":"1. *dieciséis* (un seul mot, accent)\n2. *veintidós*\n3. *cuarenta y cinco* — trois mots avec *y* à partir de 31.\n4. *cien euros* — *cien* devant un nom.\n5. *ciento cinco* — pas de *y* entre les centaines et les unités.\n6. *doscientas chicas* — la centaine s'accorde au féminin.\n7. *quinientas personas* — forme irrégulière *quinient-*, accordée au féminin.\n8. *setecientos libros* — forme irrégulière.\n9. *dos mil* — *mil* est invariable.\n10. *un millón de personas* — *millón* est un nom, suivi de *de*.\n\n2 points par nombre."}$exo$::jsonb),
  ('0933b441-0b01-5b69-bb49-5d82429907ec'::uuid, 2, 'traduction', $exo${"titre":"¿Qué hora es? ¿Qué día es?","consigne":"Écris en toutes lettres en espagnol les heures et les dates.","enonce":"**1. Écris l'heure en espagnol (phrase complète).**\n\n1. 1 h\n2. 2 h\n3. 7 h 15\n4. 10 h 30\n5. 8 h 45\n6. À 8 heures du soir\n\n**2. Écris les dates et les repères en lettres.**\n\n7. Aujourd'hui, c'est lundi 12 octobre 2026.\n8. le premier jour\n9. le troisième étage\n10. le XXIe siècle\n11. les années quatre-vingt","bareme":[{"critere":"Heures justes (es la una / son las…, y cuarto, y media, menos cuarto)","points":9},{"critere":"Date complète en lettres, avec l'année lue comme un nombre","points":5},{"critere":"Ordinaux apocopés et siècle au cardinal","points":4},{"critere":"Décennie","points":2}],"dureeMin":11,"corrige":"**1.**\n1. *Es la una.* — singulier pour une heure.\n2. *Son las dos.*\n3. *Son las siete y cuarto.*\n4. *Son las diez y media.*\n5. *Son las nueve menos cuarto.* — on part de l'heure suivante.\n6. *A las ocho de la tarde* (ou *de la noche*).\n(1,5 point chacune.)\n\n**2.**\n7. *Hoy es lunes, doce de octubre de dos mil veintiséis.* (ou *Estamos a doce de octubre de dos mil veintiséis*)\n8. *el primer día* — *primero* perd son -o devant un nom masculin.\n9. *el tercer piso* — idem pour *tercero*.\n10. *el siglo veintiuno* — au-delà de dix, on emploie le cardinal.\n11. *los años ochenta*."}$exo$::jsonb),
  ('0933b441-0b01-5b69-bb49-5d82429907ec'::uuid, 3, 'traduction', $exo${"titre":"Leer una noticia en voz alta","consigne":"Recopie le texte en écrivant en toutes lettres tous les nombres, dates et heures en chiffres. Puis explique trois pièges que tu as évités.","enonce":"**Texte (les nombres sont en chiffres) :**\n\n> El 23 de abril de 1616 murió Cervantes. Hoy, en su homenaje, 500 personas leen el *Quijote* en Madrid. La lectura empieza a la 1 de la tarde y termina a las 9 y 45 de la noche. Los organizadores esperan 1 000 000 de visitantes en la semana. Una entrada cuesta 100 euros para las empresas, pero es gratuita para los 21 primeros lectores. Es la 3.ª edición de este acto en el siglo XXI.\n\n**1.** Recopie le texte en lettres (lis *3.ª edición* comme *tercera*).\n\n**2.** Explique en français trois pièges évités (cien / ciento, accord des centaines, uno / un, mil / millón, heure…).","bareme":[{"critere":"Date en lettres juste (veintitrés de abril de mil seiscientos dieciséis)","points":4},{"critere":"Quinientas, cien, un millón de, veintiún justes","points":6},{"critere":"Heures justes (a la una, a las diez menos cuarto)","points":4},{"critere":"Siècle au cardinal (siglo veintiuno)","points":2},{"critere":"Trois pièges correctement expliqués","points":4}],"dureeMin":18,"corrige":"**1. Texte en lettres** :\n*El veintitrés de abril de mil seiscientos dieciséis murió Cervantes. Hoy, en su homenaje, quinientas personas leen el Quijote en Madrid. La lectura empieza a la una de la tarde y termina a las diez menos cuarto de la noche. Los organizadores esperan un millón de visitantes en la semana. Una entrada cuesta cien euros para las empresas, pero es gratuita para los veintiún primeros lectores. Es la tercera edición de este acto en el siglo veintiuno.*\n\nPoints de contrôle :\n- *veintitrés* (un mot, accent) ; *mil seiscientos dieciséis* (l'année se lit comme un nombre) ;\n- *quinientas personas* : forme irrégulière **et** accord au féminin ;\n- *a la una* (singulier) ; 9 h 45 → *las diez menos cuarto* ;\n- *un millón de visitantes* ; *cien euros* ; *veintiún primeros lectores* (*uno* devient *un* devant un nom masculin) ;\n- *el siglo veintiuno* (cardinal au-delà de dix).\n\n**2. Pièges attendus (au choix, trois)** : *cien* devant un nom et non *ciento* ; la centaine s'accorde (*quinientas*) et *quinientos* est irrégulier ; *veintiún* devant un nom masculin ; *millón* est un nom suivi de *de*, alors que *mil* est invariable et sans article ; *es la una* / *a la una* au singulier ; 9 h 45 se dit à partir de l'heure suivante."}$exo$::jsonb),
  ('d0606240-8745-5ee6-9cb9-7cc403416785'::uuid, 1, 'traduction', $exo${"titre":"Casita, cafecito, poquito","consigne":"Forme le diminutif demandé de chaque mot.","enonce":"Forme le diminutif de chaque mot.\n\n1. casa (-ita)\n2. perro (-ito)\n3. café\n4. flor\n5. poco\n6. amigo\n7. taza\n8. mesa\n9. canción\n10. ahora (à la mexicaine)","bareme":[{"critere":"Diminutifs simples en -ito / -ita (casita, perrito, mesita)","points":6},{"critere":"Suffixes -cito / -ecito bien choisis (cafecito, florecita, cancioncita)","points":6},{"critere":"Orthographe adaptée pour garder le son (poquito, amiguito, tacita) et ahorita","points":8}],"dureeMin":6,"corrige":"1. *casita* — on supprime la voyelle finale.\n2. *perrito*\n3. *cafecito* — *-cito* après *-é*.\n4. *florecita* — mot d'une syllabe : *-ecita*.\n5. *poquito* — *c* devient *qu* pour garder le son [k].\n6. *amiguito* — *g* devient *gu*.\n7. *tacita* — *z* devient *c* devant *i*.\n8. *mesita*\n9. *cancioncita* — *-cita* après *-n*.\n10. *ahorita* — le diminutif s'accroche même aux adverbes en Amérique latine.\n\n2 points par mot."}$exo$::jsonb),
  ('d0606240-8745-5ee6-9cb9-7cc403416785'::uuid, 2, 'traduction', $exo${"titre":"Grande, pequeño, feo o querido","consigne":"Explique en français le sens de chaque mot souligné (taille, affection, coup, mépris, ou mot devenu autonome).","enonce":"Explique le sens du mot en gras.\n\n1. Voy a visitar a **mi abuelita**.\n2. Salió de la habitación con **un portazo**.\n3. Vive en **una casucha** al lado del río.\n4. ¡No digas **palabrotas**!\n5. Tiene **un perrazo** negro.\n6. Me comí **un bocadillo** de jamón.\n7. Busco mis **zapatillas**.\n8. El **ratón** del ordenador no funciona.\n9. Mis tíos viven en **una casona** en el campo.\n10. Me dio **un codazo**.","bareme":[{"critere":"Valeur affective du diminutif (abuelita)","points":2},{"critere":"Augmentatifs, coups et péjoratifs bien compris (portazo, casucha, palabrotas, perrazo, casona, codazo)","points":12},{"critere":"Mots devenus autonomes reconnus (bocadillo, zapatillas, ratón)","points":6}],"dureeMin":11,"corrige":"1. *mi abuelita* : ma grand-mère **chérie** — le diminutif dit l'**affection**, pas la taille.\n2. *un portazo* : un **claquement de porte** — *-azo* = un coup donné avec.\n3. *una casucha* : une **masure**, une maison misérable — *-ucha* est péjoratif.\n4. *palabrotas* : des **gros mots** — *-ota*, grossier.\n5. *un perrazo* : un **énorme chien** — *-azo*, très grand.\n6. *un bocadillo* : un **sandwich** — mot devenu autonome.\n7. *zapatillas* : des **chaussons / baskets** — mot autonome.\n8. *el ratón* : la **souris** (de l'ordinateur) — mot autonome, plus un augmentatif de *rata*.\n9. *una casona* : une **grande maison** — *-ona*, augmentatif.\n10. *un codazo* : un **coup de coude** — *-azo* = coup.\n\n2 points par mot."}$exo$::jsonb),
  ('d0606240-8745-5ee6-9cb9-7cc403416785'::uuid, 3, 'traduction', $exo${"titre":"Un momentito, por favor","consigne":"Partie 1 : analyse chaque mot en gras (suffixe, formation, sens). Partie 2 : réécris la phrase neutre en la rendant plus chaleureuse avec des diminutifs, puis plus méprisante avec des péjoratifs.","enonce":"**1. Analyse les mots en gras.**\n\n> —¡Hola, Pablito! Dame **un momentito**, que tomo **un cafecito** y te llamo **ahorita**. Mi **casita** está **cerquita**, ven cuando quieras.\n\nPour chaque mot : le mot de base, le suffixe, la modification d'orthographe s'il y en a une, et ce que le diminutif ajoute au sens.\n\n**2. Réécris la phrase deux fois.**\n\n> Vivo en una casa pequeña con un perro y tengo un cuarto.\n\na) version **affectueuse** (diminutifs sur *casa*, *perro*) ;\nb) version **méprisante** (péjoratifs sur *casa* et *cuarto*).\n\nExplique enfin en deux phrases pourquoi le cours dit que le diminutif rend la phrase « plus chaleureuse » plutôt que « plus petite ».","bareme":[{"critere":"Partie 1 : cinq mots correctement analysés (base, suffixe)","points":6},{"critere":"Partie 1 : modifications d'orthographe (cerquita) et sens (ahorita, affection) expliqués","points":4},{"critere":"Partie 2 : version affectueuse juste (casita, perrito)","points":3},{"critere":"Partie 2 : version méprisante juste (casucha, cuartucho)","points":3},{"critere":"Explication : affection et adoucissement plutôt que taille","points":4}],"dureeMin":16,"corrige":"**1.**\n- *momentito* : *momento* + *-ito* ; un tout petit moment — le diminutif **adoucit la demande**.\n- *cafecito* : *café* + *-cito* (après *-é*) ; un petit café offert avec chaleur.\n- *ahorita* : *ahora* + *-ita* ; « tout de suite » (ou « un peu plus tard ») à la mexicaine — le diminutif s'accroche à un **adverbe**.\n- *casita* : *casa* + *-ita*, voyelle finale supprimée ; ma petite maison, dite avec **affection**.\n- *cerquita* : *cerca* + *-ita*, **c → qu** pour garder le son [k] ; tout près.\n\n**2.**\na) *Vivo en una casita con un perrito y tengo un cuarto.* (on accepte aussi *cuartito*)\nb) *Vivo en una casucha con un perro y tengo un cuartucho.* — *-ucha / -ucho* = misérable.\n(L'adjectif *pequeña* peut être gardé ou supprimé, puisque le diminutif le dit déjà.)\n\n**Explication attendue** : le diminutif exprime souvent l'**affection** plus que la taille (*mi abuelita* n'est pas petite, elle est aimée). Dans la phrase de Pablo, il **adoucit** la demande et rend le ton amical : la phrase n'est pas « plus petite », elle est plus chaleureuse."}$exo$::jsonb),
  ('84370f35-aba7-51fd-91e9-cf10e3556e73'::uuid, 1, 'redaction', $exo${"titre":"Six siècles de poésie en quatre cases","consigne":"Réponds à chaque question en phrases complètes ou en complétant le tableau.","enonce":"**1.** Recopie et complète le tableau suivant (une ligne par période) :\n\n| La période | Ce que la poésie y fait | Un nom (poète ou groupe) |\n| Moyen Âge | … | … |\n| Renaissance | … | … |\n| XVIIe siècle | … | … |\n| XVIIIe siècle | … | … |\n\n**2.** Quels sont les **trois grands chantiers** du poète, quel que soit le siècle ? Donne pour chacun un moyen précis.","bareme":[{"critere":"Tableau : ce que fait la poésie à chaque période, juste (chantée, en français savant, soumise à la règle, arme des idées)","points":8},{"critere":"Tableau : un nom exact par période (troubadours/trouvères ou Villon, Pléiade/Ronsard/Du Bellay, La Fontaine, Lumières)","points":6},{"critere":"Les trois chantiers (rythme, son, image) avec un moyen juste pour chacun","points":6}],"dureeMin":7,"corrige":"**1.**\n- **Moyen Âge** : la poésie se **chante** ; elle dit l'amour courtois (un chevalier au service d'une dame inaccessible). Noms : troubadours au sud, trouvères au nord ; François **Villon** en rupture (la faim, la prison, la mort).\n- **Renaissance** : elle passe au **français** et devient savante ; le sonnet, venu d'Italie, triomphe. Noms : la **Pléiade**, **Ronsard**, **Du Bellay** (*Défense et illustration de la langue française*, 1549).\n- **XVIIe siècle** : elle obéit à la **règle** : mètres fixes, rimes riches, respect des genres. Nom : **La Fontaine** et la fable.\n- **XVIIIe siècle** : elle devient une **arme** contre l'intolérance et l'injustice ; le siècle préfère l'essai, le conte et la fable au lyrisme. Nom : les **Lumières**.\n\n**2.** Les trois chantiers : le **rythme** (le vers, la strophe, la césure), le **son** (la rime, les allitérations, les assonances), l'**image** (comparaison, métaphore, personnification). Un moyen juste par chantier suffit."}$exo$::jsonb),
  ('84370f35-aba7-51fd-91e9-cf10e3556e73'::uuid, 2, 'redaction', $exo${"titre":"L'exposé d'Inès : situer quatre textes","consigne":"Situe chaque texte dans le temps en t'appuyant sur un indice précis, puis réponds à la dernière question en quelques phrases.","enonce":"**Situation.** Inès prépare un exposé sur l'histoire de la poésie. Sa professeure lui confie quatre fiches, sans date :\n\n- **Fiche A** : un poème fait pour être chanté ; un chevalier y promet de servir une dame qu'il ne peut approcher.\n- **Fiche B** : un manifeste qui veut faire du français une langue de poésie, au lieu du latin.\n- **Fiche C** : un poème en vers de mètre fixe, aux rimes soignées, où des animaux parlent et dont la fin tire une leçon.\n- **Fiche D** : un texte bref qui cache sa cible derrière des animaux pour attaquer l'intolérance et l'injustice.\n\n1. Pour chaque fiche, indique la période (siècle) et, si possible, un nom d'auteur ou de groupe.\n2. Pour chaque fiche, cite l'indice qui t'a permis de décider.\n3. Inès veut conclure son exposé par ce qui ne change pas d'un bout à l'autre des six siècles. Rédige sa conclusion (3 à 4 phrases).","bareme":[{"critere":"Les quatre fiches correctement situées (Moyen Âge, Renaissance, XVIIe, XVIIIe) avec un nom plausible","points":8},{"critere":"Un indice pertinent tiré de chaque fiche pour justifier","points":6},{"critere":"Conclusion : la poésie rend la langue plus dense que la prose, par le rythme, le son et l'image","points":6}],"dureeMin":11,"corrige":"**1 et 2.**\n- **A** : **Moyen Âge** (troubadours, trouvères). Indices : poème **chanté**, **amour courtois** (chevalier au service d'une dame inaccessible).\n- **B** : **Renaissance, XVIe siècle** ; la **Pléiade**, Du Bellay (*Défense et illustration de la langue française*, 1549). Indice : la volonté d'écrire une poésie savante **en français** plutôt qu'en latin.\n- **C** : **XVIIe siècle** ; **La Fontaine**. Indices : **mètres fixes**, rimes soignées (la règle classique), genre de la **fable** (animaux, leçon).\n- **D** : **XVIIIe siècle**, les **Lumières**. Indices : la poésie mise au service des **idées**, contre l'**intolérance** et l'**injustice** ; la fable qui cache sa cible derrière des animaux.\n\n**3.** Conclusion attendue, par exemple : « Pendant six siècles, la poésie a changé de forme, de sujet et de public : chantée au Moyen Âge, savante à la Renaissance, réglée au XVIIe siècle, combative au XVIIIe. Mais elle garde une constante : elle travaille la langue pour la rendre plus dense que la prose. Elle le fait toujours par trois chantiers : le rythme (vers, strophe, césure), le son (rime, allitération, assonance) et l'image (comparaison, métaphore, personnification). »"}$exo$::jsonb),
  ('84370f35-aba7-51fd-91e9-cf10e3556e73'::uuid, 3, 'redaction', $exo${"titre":"Ce qui change, ce qui demeure","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, organisé par des connecteurs logiques, en t'appuyant sur des exemples précis du cours.","enonce":"**Sujet.** « Pendant six siècles, la poésie française change de forme, de sujet et de public — mais elle garde une constante. »\n\nMontre, dans un paragraphe argumenté, que cette affirmation est juste :\n- d'abord en expliquant ce qui **change** (au moins **trois** périodes, du Moyen Âge au XVIIIe siècle, avec un nom ou une œuvre pour chacune) ;\n- ensuite en montrant ce qui **demeure**, en nommant les trois chantiers du poète et leurs moyens.\n\nTu peux évoquer un changement de **public** (chanté / lu), de **langue** (latin / français) ou de **fonction** (aimer / combattre).","bareme":[{"critere":"Thèse posée clairement en ouverture et reprise en conclusion","points":3},{"critere":"Au moins trois périodes exactement caractérisées, chacune avec un nom ou une œuvre juste","points":8},{"critere":"La constante expliquée : rythme, son, image, avec leurs moyens","points":5},{"critere":"Paragraphe organisé par des connecteurs, expression correcte","points":4}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n**Thèse** : la poésie française se transforme sans cesse, mais elle reste un travail de la langue qui la rend plus dense que la prose.\n\n**Ce qui change** (trois périodes au moins, exactes) :\n- **Moyen Âge** : poésie **chantée**, amour courtois ; troubadours et trouvères ; Villon rompt avec la courtoisie et écrit la faim, la prison, la mort. Public : on l'écoute.\n- **Renaissance** : la **Pléiade** (Ronsard, Du Bellay) veut une poésie savante **en français** ; *Défense et illustration de la langue française* (1549) ; le **sonnet** venu d'Italie ; thèmes de la fuite du temps, de la beauté qui passe, de l'exil. Changement de langue.\n- **XVIIe siècle** : la **règle** (mètres fixes, rimes riches, genres respectés) ; La Fontaine et la **fable**.\n- **XVIIIe siècle** : la poésie devient une **arme** des Lumières contre l'intolérance et l'injustice ; le siècle préfère l'essai, le conte et la fable ; la fable cache sa cible derrière des animaux. Changement de fonction : d'aimer à combattre.\n\n**Ce qui demeure** : trois chantiers — le **rythme** (vers, strophe, césure), le **son** (rime, allitération, assonance), l'**image** (comparaison, métaphore, personnification).\n\n**Connecteurs attendus** : d'abord, ensuite, en revanche, pourtant, ainsi.\n\nÀ sanctionner : dates ou attributions fausses (par exemple La Fontaine à la Renaissance), simple liste sans lien logique."}$exo$::jsonb),
  ('a8d8b644-7546-571f-b461-ca81ad148e9e'::uuid, 1, 'redaction', $exo${"titre":"Compter, ranger, nommer","consigne":"Réponds à chaque question en montrant ta démarche.","enonce":"**1.** Découpe ce vers de Du Bellay en syllabes, donne son nombre de syllabes, le nom du mètre et place la césure :\n\n> Heureux qui, comme Ulysse, a fait un beau voyage\n\n**2.** Donne le nom de la disposition des rimes dans chaque cas (les mots sont les fins de vers d'un quatrain) :\n- a) maison / fleur / cœur / saison\n- b) ciel / mer / miel / hiver\n- c) nuit / bruit / jour / amour\n\n**3.** Comment s'appelle une strophe de 3 vers ? de 4 vers ? Combien de vers compte un sonnet ?","bareme":[{"critere":"Découpage juste avec élision du e muet de « comme » et d'« Ulysse », 12 syllabes, alexandrin, césure après « Ulysse »","points":9},{"critere":"Trois dispositions de rimes justes (embrassées, croisées, suivies ou plates)","points":6},{"critere":"Tercet, quatrain, 14 vers","points":5}],"dureeMin":7,"corrige":"**1.** Heu / reux / qui / com / m(e)U / lys // s(e)a / fait / un / beau / vo / ya(ge).\n- Le **e** de « comme » ne compte pas : il est devant la voyelle de « Ulysse » (**élision**) ; de même le **e** final d'« Ulysse » devant « a ».\n- Le **e** final de « voyage », en **fin de vers**, ne compte pas.\n- Total : **12 syllabes** : c'est un **alexandrin**. La **césure** tombe après la 6e syllabe, après « Ulysse » : deux **hémistiches** de 6 (« Heureux qui, comme Ulysse » / « a fait un beau voyage »).\n\n**2.**\n- a) maison / saison encadrent fleur / cœur : **ABBA**, rimes **embrassées**.\n- b) ciel / miel et mer / hiver alternent : **ABAB**, rimes **croisées**.\n- c) nuit / bruit puis jour / amour : **AABB**, rimes **suivies** (ou plates).\n\n**3.** 3 vers : un **tercet** ; 4 vers : un **quatrain** ; un sonnet compte **14 vers** (deux quatrains et deux tercets)."}$exo$::jsonb),
  ('a8d8b644-7546-571f-b461-ca81ad148e9e'::uuid, 2, 'redaction', $exo${"titre":"Analyser un quatrain de Du Bellay","consigne":"Lis le quatrain, puis réponds aux questions en employant le vocabulaire exact de l'analyse poétique.","enonce":"> Heureux qui, comme Ulysse, a fait un beau voyage,\n> Ou comme cestuy-là qui conquit la toison,\n> Et puis est retourné, plein d'usage et raison,\n> Vivre entre ses parents le reste de son âge !\n>\n> — Joachim Du Bellay, *Les Regrets*, 1558 (« cestuy-là » : celui-là, Jason ; « usage » : expérience)\n\n1. Quel est le mètre de ces vers ? Justifie en découpant le vers 4 en syllabes.\n2. Donne le schéma des rimes et son nom. Indique pour chaque rime si elle est féminine ou masculine.\n3. La rime « toison / raison » est-elle pauvre, suffisante ou riche ? Justifie.\n4. Relève et nomme la figure de style des vers 1 et 2. Que permet-elle de dire ?","bareme":[{"critere":"Alexandrin justifié par un découpage juste du vers 4 (élision de « Vivre entre », e de fin de vers non compté)","points":6},{"critere":"Schéma ABBA, rimes embrassées ; voyage/âge féminines, toison/raison masculines","points":5},{"critere":"Richesse de la rime justifiée par les sons communs","points":3},{"critere":"Comparaison identifiée (outil « comme ») et interprétée : le voyage antique dit le retour chez soi","points":6}],"dureeMin":11,"corrige":"**1.** Ce sont des **alexandrins** (12 syllabes). Vers 4 : Vi / vr(e)en / tre / ses / pa / rents // le / res / te / de / son / â(ge). Le **e** de « Vivre » s'élide devant « entre » ; celui d'« entre » compte (devant la consonne de « ses ») ; celui de « reste » compte (devant « de ») ; celui d'« âge », en fin de vers, ne compte pas. Total : 12, césure après « parents ».\n\n**2.** voyage (A) / toison (B) / raison (B) / âge (A) : **ABBA**, rimes **embrassées**. « voyage » et « âge » finissent par un e muet : rimes **féminines** ; « toison » et « raison » : rimes **masculines**.\n\n**3.** « toison / raison » partagent les sons [z] et [ɔ̃] (voyelle nasale « on ») : **deux** sons communs, rime **suffisante**. « toi- » et « rai- » ne partagent pas leur voyelle : la rime n'est pas riche.\n\n**4.** Figure : la **comparaison** (outil « comme » : « comme Ulysse », « comme cestuy-là »). Le poète rapproche le bonheur de celui qui rentre chez lui des héros antiques Ulysse et Jason, revenus après un long voyage. Le voyage antique sert à dire le désir de retour d'un homme réel, exilé à Rome : c'est l'éloge du retour au pays."}$exo$::jsonb),
  ('a8d8b644-7546-571f-b461-ca81ad148e9e'::uuid, 3, 'redaction', $exo${"titre":"Nommer ce que le texte fait","consigne":"Relève et nomme les procédés demandés, puis rédige un paragraphe d'analyse qui explique leurs effets.","enonce":"Poème écrit pour ce contrôle :\n\n> Le vent siffle, soupire et s'assoit sur les seuils ;\n> Le vent porte en ses bras la lumière obscure\n> Des soirs d'hiver ; et moi, seul, je garde mon deuil,\n> Ce silence pareil à une pierre dure.\n\n1. Relève et nomme **cinq** procédés parmi : allitération, anaphore, personnification, oxymore, comparaison, enjambement, rejet. Cite chaque fois le passage.\n2. Explique précisément l'**enjambement** entre les vers 2 et 3 : quel groupe déborde, et quel mot est mis en valeur ?\n3. Rédige un paragraphe (10 à 12 lignes) qui montre que ces procédés ne « décorent » pas mais **imitent, insistent ou martèlent** : quelle atmosphère construisent-ils ?","bareme":[{"critere":"Cinq procédés justement nommés et cités","points":8},{"critere":"Enjambement et rejet correctement décrits (« Des soirs d'hiver » rejeté au vers 3)","points":4},{"critere":"Effets interprétés : les procédés imitent le vent, insistent sur la tristesse, construisent le deuil","points":5},{"critere":"Paragraphe organisé, vocabulaire d'analyse exact","points":3}],"dureeMin":17,"corrige":"**1.** Procédés attendus (cinq au choix) :\n- **Allitération** en [s] au vers 1 : « siffle, soupire, s'assoit, seuils » — elle imite le sifflement du vent.\n- **Anaphore** : « Le vent » en tête des vers 1 et 2.\n- **Personnification** du vent : il « soupire », « s'assoit », « porte en ses bras » — conduites humaines.\n- **Oxymore** : « la lumière obscure » (deux mots contraires accolés).\n- **Comparaison** : « Ce silence pareil à une pierre dure » (outil « pareil à »).\n- **Enjambement** / **rejet** entre les vers 2 et 3.\n\n**2.** La phrase « Le vent porte en ses bras la lumière obscure / Des soirs d'hiver » déborde du vers 2 sur le vers 3 : c'est un **enjambement**. Le débordement est court et placé **au début** du vers suivant : c'est un **rejet**, qui met en valeur « Des soirs d'hiver » — le froid et la fin du jour.\n\n**3.** Paragraphe attendu : l'allitération fait **entendre** le vent (imitation) ; l'anaphore « Le vent » **insiste** sur cette présence qui envahit tout ; la personnification en fait presque un compagnon qui « s'assoit » sur les seuils, face à un « je » « seul » ; l'oxymore « lumière obscure » dit une clarté sans chaleur, entre jour et nuit ; le rejet détache « Des soirs d'hiver » ; la comparaison finale donne au silence le poids d'une « pierre dure », image concrète du deuil. Ensemble, ils construisent une atmosphère de solitude et de tristesse : la forme **martèle** ce que dit le sens."}$exo$::jsonb),
  ('b200bdee-fd6d-5a3f-9206-ec78ec85c43b'::uuid, 1, 'redaction', $exo${"titre":"Qui est qui dans le Roman de Renart ?","consigne":"Réponds en phrases complètes.","enonce":"1. Le *Roman de Renart* est-il un roman écrit par un seul auteur ? Explique ce que sont les « branches » et donne la période de leur composition.\n2. Associe chaque animal à son rôle dans la société transposée :\n   - Noble le lion · Ysengrin le loup · Tibert le chat · Chantecler le coq · Renart le goupil\n   - rôles : le vassal · le roi · le petit qui n'a que sa ruse · le grand baron brutal · le naïf plein de vanité\n3. Quelle trace le personnage de Renart a-t-il laissée dans la langue française ?","bareme":[{"critere":"Ensemble de récits en vers (branches), plusieurs auteurs, vers 1170-1250","points":6},{"critere":"Cinq associations justes animal / rôle","points":10},{"critere":"Le nom propre Renart a remplacé le mot « goupil »","points":4}],"dureeMin":7,"corrige":"**1.** Non : ce n'est ni un roman au sens moderne ni l'œuvre d'un seul auteur. C'est un **ensemble de récits en vers**, les **branches**, chacune formant un récit indépendant, composées entre **1170 et 1250 environ**.\n\n**2.**\n- **Noble** le lion : **le roi** ;\n- **Ysengrin** le loup : **le grand baron brutal** ;\n- **Tibert** le chat : **un vassal** (comme Brun l'ours) ;\n- **Chantecler** le coq : **le naïf plein de vanité** ;\n- **Renart** le goupil : **le petit, qui n'a que sa ruse**.\n\n**3.** Le succès du personnage est tel que son **nom propre a remplacé le mot « goupil »** : le renard s'appelle aujourd'hui « renard » à cause de lui."}$exo$::jsonb),
  ('b200bdee-fd6d-5a3f-9206-ec78ec85c43b'::uuid, 2, 'redaction', $exo${"titre":"Le procès de Renart","consigne":"Lis le résumé, puis réponds aux questions en t'appuyant sur des éléments précis.","enonce":"**Épisode imaginé pour ce contrôle, à la manière des branches.**\n\n> Ysengrin porte plainte devant le roi Noble : Renart a encore dévoré ses provisions. Noble réunit sa cour pour juger le goupil « dans les formes ». Brun l'ours, envoyé chercher Renart, revient la tête prise dans un tronc où le rusé l'a attiré avec du miel. Au procès, Renart jure sur des reliques « qu'il n'a jamais touché un morceau » — les reliques sont une dent de chien. Il glisse une bourse au chapelain de la cour, promet de partir en pèlerinage, et Noble le relâche. À peine sorti, Renart jette son bâton de pèlerin et se moque du roi.\n\n1. Quel **modèle sérieux** cet épisode parodie-t-il ? Définis la parodie.\n2. Relève un exemple de **comique de situation** et un exemple de **comique de mots**.\n3. Montre que l'épisode vise la **justice**, la **force** et la **religion** : un élément pour chaque cible.","bareme":[{"critere":"Le procès féodal parodié ; parodie définie comme imitation comique d'un modèle sérieux","points":6},{"critere":"Un comique de situation et un comique de mots justement relevés","points":6},{"critere":"Les trois cibles de la satire illustrées par un élément précis chacune","points":8}],"dureeMin":12,"corrige":"**1.** L'épisode parodie le **procès féodal** : un roi réunit sa cour pour juger un vassal « dans les formes », avec plainte, convocation et serment. Ici le tribunal est **grotesque**, puisqu'on juge un renard. La **parodie** est l'**imitation comique d'un modèle sérieux**.\n\n**2.**\n- **Comique de situation** (ruses, coups, déguisements, proche de la farce) : Brun revient la tête coincée dans un tronc, piégé par le miel ; ou Renart qui jette son bâton de pèlerin.\n- **Comique de mots** (jeux de mots, serments détournés) : le **serment** de Renart « qu'il n'a jamais touché un morceau », prêté sur une dent de chien — un serment détourné.\n\n**3.**\n- La **justice** s'**achète** : la bourse glissée au chapelain obtient la libération.\n- La **force** tient lieu de droit : Ysengrin, le baron brutal, porte plainte alors qu'il est lui-même un prédateur ; Renart, le petit, n'a que la ruse pour résister.\n- La **religion** sert de **couverture** : faux serment sur de fausses reliques, faux pèlerinage promis pour échapper à la peine.\n\nAccepter toute autre illustration juste tirée du résumé."}$exo$::jsonb),
  ('b200bdee-fd6d-5a3f-9206-ec78ec85c43b'::uuid, 3, 'redaction', $exo${"titre":"Rire avec un menteur","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur le cours.","enonce":"**Sujet.** Renart est menteur, voleur et cruel. Pourtant, depuis le Moyen Âge, le lecteur rit avec lui plutôt que contre lui.\n\nExplique ce paradoxe dans un paragraphe argumenté. Tu mobiliseras au moins **trois** des idées suivantes, avec des exemples précis :\n- la parodie des genres sérieux ;\n- le comique de situation et de mots ;\n- le masque animal ;\n- la satire des puissants ;\n- la nature des victimes de Renart.","bareme":[{"critere":"Paradoxe posé clairement (Renart n'est pas un héros positif, pourtant on rit avec lui)","points":3},{"critere":"Parodie et comique expliqués avec exemples (chanson de geste, roman courtois, procès ; farce, serments détournés)","points":5},{"critere":"Le masque animal : critiquer sans nommer","points":4},{"critere":"La satire : les victimes détiennent le pouvoir et ne valent pas mieux (justice achetée, force, religion)","points":5},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **Le paradoxe** : Renart n'est pas un héros positif — il est menteur, voleur et cruel — et pourtant le lecteur prend son parti.\n- **La parodie** : le texte imite comiquement des modèles sérieux — des ruses de goupil à la place des combats héroïques de la **chanson de geste**, des animaux à la place des chevaliers du **roman courtois**, un **tribunal grotesque** à la place du procès féodal. Le rire naît de ce décalage.\n- **Le comique** : de **situation** (ruses, déguisements, coups reçus, proche de la farce) et de **mots** (jeux de mots, serments détournés).\n- **Le masque animal** : faire parler des animaux permet de dire des choses qu'un texte sur des humains ne pourrait pas dire **impunément** : on critique le roi et les barons sans les nommer.\n- **La satire** : elle vise la **justice** qu'on achète, la **force** qui tient lieu de droit, la **religion** qui sert de couverture.\n- **Les victimes** : elles sont aussi mauvaises que lui, et ce sont **elles qui détiennent le pouvoir** (Noble, roi faible ; Ysengrin, baron brutal ; Chantecler, naïf vaniteux). Renart est « le petit, qui n'a que sa ruse » : on rit avec lui parce que ses tours dégonflent les puissants.\n\n**Conclusion attendue** : le rire est complice parce qu'il est **satirique** ; il ne fait pas de Renart un modèle, il révèle les vices d'une société."}$exo$::jsonb),
  ('49965686-6d82-542f-9855-8b1bc14db7a5'::uuid, 1, 'redaction', $exo${"titre":"Le sonnet et ses maîtres","consigne":"Réponds en phrases complètes.","enonce":"1. D'où vient le sonnet et à quel siècle s'impose-t-il en France ? Avec quel groupe de poètes ?\n2. Décris sa structure : nombre de vers, strophes, rimes les plus fréquentes en France. Comment s'appelle son dernier vers et quel est son rôle ?\n3. Complète : Du Bellay écrit *Les Regrets* en … pendant son séjour à … . Ronsard reprend à Horace le thème du … , qui signifie … .","bareme":[{"critere":"Origine italienne, XVIe siècle, la Pléiade","points":5},{"critere":"14 vers, deux quatrains et deux tercets, ABBA ABBA puis CCD EED, la chute qui condense le poème","points":9},{"critere":"1558, Rome, carpe diem, « cueille le jour » (la beauté passe, il faut en jouir)","points":6}],"dureeMin":7,"corrige":"**1.** Le sonnet vient d'**Italie** ; il arrive au **XVIe siècle** et devient la forme reine de la poésie française avec la **Pléiade**.\n\n**2.** Il compte **14 vers** : **deux quatrains** (la situation, l'image posée), le plus souvent rimés **ABBA ABBA**, puis **deux tercets** (la rupture : on change de ton, on répond), souvent en **CCD EED** en France. Le dernier vers est la **chute** : il condense tout le poème. Un sonnet est un raisonnement en quatorze vers, avec une bascule au milieu et une pointe à la fin.\n\n**3.** Du Bellay écrit *Les Regrets* en **1558**, pendant son séjour à **Rome**. Ronsard reprend à Horace le thème du **carpe diem**, qui signifie « **cueille le jour** » : la beauté passe, il faut en jouir."}$exo$::jsonb),
  ('49965686-6d82-542f-9855-8b1bc14db7a5'::uuid, 2, 'redaction', $exo${"titre":"« Heureux qui, comme Ulysse » : un raisonnement en quatorze vers","consigne":"Lis le sonnet, puis réponds aux questions en citant le texte.","enonce":"> Heureux qui, comme Ulysse, a fait un beau voyage,\n> Ou comme cestuy-là qui conquit la toison,\n> Et puis est retourné, plein d'usage et raison,\n> Vivre entre ses parents le reste de son âge !\n>\n> Quand reverrai-je, hélas, de mon petit village\n> Fumer la cheminée, et en quelle saison\n> Reverrai-je le clos de ma pauvre maison,\n> Qui m'est une province, et beaucoup davantage ?\n>\n> Plus me plaît le séjour qu'ont bâti mes aïeux,\n> Que des palais romains le front audacieux,\n> Plus que le marbre dur me plaît l'ardoise fine,\n>\n> Plus mon Loire gaulois, que le Tibre latin,\n> Plus mon petit Liré, que le mont Palatin,\n> Et plus que l'air marin la douceur angevine.\n>\n> — Du Bellay, *Les Regrets*, 1558 (Liré : village natal du poète, en Anjou)\n\n1. Donne le schéma des rimes du sonnet et montre qu'il suit la structure habituelle en France.\n2. Où se trouve la **bascule** du poème ? Que fait le poète dans les quatrains, puis dans les tercets ?\n3. Relève **trois** oppositions entre Rome et le pays natal. Quel est le procédé d'ensemble ?\n4. Que condense la **chute** ?","bareme":[{"critere":"Schéma ABBA ABBA CCD EED identifié et relié à la structure du sonnet","points":5},{"critere":"Bascule entre quatrains et tercets expliquée (situation / désir de retour, puis comparaison qui tranche)","points":5},{"critere":"Trois oppositions Rome / village exactes et procédé nommé","points":6},{"critere":"Chute interprétée : la douceur angevine l'emporte, le mal du pays","points":4}],"dureeMin":12,"corrige":"**1.** Quatrains : voyage / toison / raison / âge (ABBA), village / saison / maison / davantage (ABBA) ; tercets : aïeux / audacieux / fine (CCD), latin / Palatin / angevine (EED). Schéma **ABBA ABBA CCD EED** : la structure la plus fréquente du sonnet français, deux quatrains en rimes embrassées puis deux tercets.\n\n**2.** Les **quatrains** posent la situation : l'éloge de celui qui rentre chez lui (Ulysse, Jason), puis la plainte du poète loin de chez lui (« Quand reverrai-je, hélas »). Les **tercets** changent de ton : le poète ne se plaint plus, il **compare et tranche** (« Plus me plaît… que… »). La bascule se fait au passage des quatrains aux tercets.\n\n**3.** Oppositions (trois au choix) : « le séjour qu'ont bâti mes aïeux » / « des palais romains le front audacieux » ; « le marbre dur » / « l'ardoise fine » ; « mon Loire gaulois » / « le Tibre latin » ; « mon petit Liré » / « le mont Palatin » ; « l'air marin » / « la douceur angevine ». Le procédé d'ensemble : **opposer la grandeur romaine à la douceur du village natal**, avec la reprise de « Plus ».\n\n**4.** La **chute** « Et plus que l'air marin la douceur angevine » condense tout le poème : la simplicité du pays natal l'emporte sur tout le prestige de Rome. Le voyage antique sert à dire le **mal du pays** d'un homme réel."}$exo$::jsonb),
  ('49965686-6d82-542f-9855-8b1bc14db7a5'::uuid, 3, 'redaction', $exo${"titre":"Le cerf, la biche et l'abeille","consigne":"Réponds aux deux premières questions, puis rédige le paragraphe demandé.","enonce":"Quatrains écrits pour ce contrôle, à la manière des poètes de la Pléiade :\n\n> Je suis le cerf blessé qui fuit par la forêt\n> Et porte dans son flanc la flèche de vos yeux ;\n> Vous, biche insaisissable, allez de lieux en lieux,\n> Et je suis l'oiseau pris qu'une cage retient.\n>\n> Mon désir, comme abeille, erre de fleur en fleur,\n> Sans trouver le repos qu'il cherche en votre cœur.\n\n1. Relève les **quatre** images animales du poème et dis ce que chacune exprime.\n2. Quelles images sont des **métaphores**, laquelle est une **comparaison** ? Justifie.\n3. Un camarade affirme : « Dans ces sonnets, le poète aime les animaux et décrit la nature. » Réfute cette lecture dans un paragraphe argumenté (10 à 15 lignes) : d'où viennent ces images, quel est le rôle de l'animal, et pourquoi la forme du sonnet convient-elle à ce « raisonnement » amoureux ?","bareme":[{"critere":"Quatre images relevées et interprétées (cerf blessé : douleur ; biche : l'inaccessible ; oiseau en cage : dépendance ; abeille : désir qui va de fleur en fleur)","points":8},{"critere":"Métaphores (sans outil) et comparaison (« comme abeille ») distinguées et justifiées","points":4},{"critere":"Origine pétrarquiste et animal véhicule de la métaphore, non bête réelle","points":5},{"critere":"Paragraphe organisé qui réfute clairement la lecture proposée","points":3}],"dureeMin":17,"corrige":"**1.**\n- Le poète en **cerf blessé** (« la flèche de vos yeux ») : la **douleur du désir**.\n- La dame en **biche insaisissable** : l'**inaccessible**.\n- Le poète en **oiseau** pris dans une **cage** : la **dépendance**.\n- Le désir en **abeille** qui erre « de fleur en fleur » : le **désir qui va de fleur en fleur**, sans repos.\n\n**2.** « Je suis le cerf blessé », « Vous, biche insaisissable », « je suis l'oiseau pris » : **métaphores**, car le rapprochement se fait **sans outil** de comparaison. « Mon désir, **comme** abeille » : **comparaison**, avec l'outil « comme ».\n\n**3.** Paragraphe attendu : la lecture proposée est un contresens. Ces figures animales **viennent de Pétrarque**, poète italien que la Pléiade imite ; ce sont des images conventionnelles du discours amoureux. L'animal n'y est **pas une bête réelle** : c'est un **véhicule de la métaphore**, qui permet de dire ce que le poète ne peut pas dire en propre (la blessure d'amour, la fuite de l'aimée, la captivité). Le sonnet s'y prête parce qu'il est un **raisonnement en quatorze vers** : les quatrains posent l'image, les tercets opèrent la **rupture**, et la **chute** condense le propos en une pointe finale. Le poème ne décrit donc pas la nature : il construit une pensée du désir."}$exo$::jsonb),
  ('c12fd49c-b21f-5ec5-86b4-f1f9095c0b01'::uuid, 1, 'redaction', $exo${"titre":"Le lion, d'hier à aujourd'hui","consigne":"Réponds en phrases complètes.","enonce":"1. Que représente le lion dans la **Bible** ? Donne ses deux valeurs opposées.\n2. D'où vient l'expression « la part du lion » et que signifie-t-elle ?\n3. Que devient le lion dans ces trois textes du Moyen Âge : le **bestiaire**, le *Chevalier au lion* de Chrétien de Troyes, le *Roman de Renart* ?\n4. Que veut dire : le motif du lion est à la fois **universel** et **pluriel** ?","bareme":[{"critere":"Bible : menace (fosse aux lions) et force au service du juste (Samson, Daniel) ; la part du lion chez Ésope","points":7},{"critere":"Les trois lions médiévaux justes (symbole du Christ, compagnon fidèle d'Yvain, Noble roi faible et partial)","points":8},{"critere":"Universel (partout) et pluriel (change de valeur selon l'époque, le genre, l'intention)","points":5}],"dureeMin":8,"corrige":"**1.** Dans la Bible, le lion est à la fois **la menace** (la fosse aux lions) et **la force au service du juste** (Samson, Daniel).\n\n**2.** L'expression vient des **fables d'Ésope** : le lion, puissant, prend sa part d'avance. « La part du lion » désigne **la plus grosse part, prise par le plus fort**.\n\n**3.**\n- Le **bestiaire** en fait un symbole du **Christ** : il efface ses traces, dort les yeux ouverts, ranime ses petits au troisième jour.\n- Chez Chrétien de Troyes, il est le **compagnon fidèle** d'Yvain.\n- Dans le *Roman de Renart*, **Noble** est un **roi faible et partial**.\n\n**4.** **Universel** : on retrouve le lion partout, dans tous les temps. **Pluriel** : il **change de valeur** selon l'époque, le genre et l'intention de l'auteur. Le lion n'est ni bon ni mauvais : c'est un **signe**, qui se lit dans son contexte."}$exo$::jsonb),
  ('c12fd49c-b21f-5ec5-86b4-f1f9095c0b01'::uuid, 2, 'redaction', $exo${"titre":"L'exposition de Maël","consigne":"Analyse les quatre cartels, puis réponds aux questions en justifiant.","enonce":"**Situation.** Maël prépare pour le CDI une petite exposition, « Le lion dans les livres ». Il a rédigé quatre cartels :\n\n- **Cartel 1** : un bestiaire médiéval raconte que le lion dort les yeux ouverts et ranime ses petits au troisième jour.\n- **Cartel 2** : dans le *Roman de Renart*, le roi Noble se laisse berner et juge selon ses intérêts.\n- **Cartel 3** : La Fontaine, « La Génisse, la Chèvre et la Brebis en société avec le Lion » : le lion s'associe aux trois autres, puis garde tout le butin.\n- **Cartel 4** : La Fontaine, « Le Lion et le Rat » : un rat délivre le lion pris dans un filet. Morale : « On a souvent besoin d'un plus petit que soi. »\n\n1. Pour chaque cartel, dis en une phrase ce que le lion y représente.\n2. Montre, avec deux cartels bien choisis, que la même bête peut porter des sens **contraires**.\n3. Maël hésite pour le titre du panneau final. Propose une phrase qui résume la leçon de l'exposition et justifie-la.","bareme":[{"critere":"Sens juste du lion dans chacun des quatre cartels","points":8},{"critere":"Deux cartels opposés de façon pertinente et expliquée","points":6},{"critere":"Phrase de synthèse juste (un signe se lit dans son contexte) et justifiée","points":6}],"dureeMin":12,"corrige":"**1.**\n- **Cartel 1** : le lion est une figure du **Christ** (vertus chrétiennes : il veille, il ressuscite ses petits au troisième jour).\n- **Cartel 2** : **Noble**, un **roi faible et partial** — la satire du pouvoir.\n- **Cartel 3** : la **loi du plus fort déguisée en contrat** : le puissant prend « la part du lion ».\n- **Cartel 4** : le **rapport de force se retourne** : le puissant a besoin d'un plus petit que lui.\n\n**2.** Par exemple, cartel 1 et cartel 2 : le même animal est une figure sacrée du Christ dans le bestiaire et un roi ridicule et injuste dans le *Roman de Renart*. Ou cartels 3 et 4 : chez le même auteur, le lion est tantôt le fort qui écrase, tantôt le fort qui dépend du faible. La valeur change avec le **genre** (bestiaire religieux / récit satirique) et l'**intention** de l'auteur.\n\n**3.** Exemple : « Le lion n'est ni bon ni mauvais : c'est un signe, et un signe se lit dans son contexte. » Justification : le motif est **universel** (on le retrouve partout) mais **pluriel** (il change de valeur selon l'époque, le genre et l'intention). Toute formulation équivalente est acceptée."}$exo$::jsonb),
  ('c12fd49c-b21f-5ec5-86b4-f1f9095c0b01'::uuid, 3, 'redaction', $exo${"titre":"Une image a-t-elle un sens fixe ?","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des exemples précis.","enonce":"**Sujet.** « Le lion traverse toute la littérature — et il n'y veut jamais dire tout à fait la même chose. »\n\nEn t'appuyant sur au moins **quatre** moments de l'histoire du motif (les origines, le Moyen Âge, l'âge classique, l'époque moderne), montre qu'une image littéraire n'a pas de sens fixe. Tu expliqueras **ce qui fait varier** le sens (époque, genre, intention de l'auteur) et tu termineras par ce que ce constat apprend au lecteur.","bareme":[{"critere":"Thèse claire : une image n'a pas de sens fixe, elle se lit dans son contexte","points":3},{"critere":"Quatre moments exacts avec un exemple précis chacun (Bible ou Ésope, bestiaire/Yvain/Renart, La Fontaine, emblème ou Kessel)","points":8},{"critere":"Explication de ce qui fait varier le sens : époque, genre, intention","points":5},{"critere":"Organisation, connecteurs, expression","points":4}],"dureeMin":19,"corrige":"**Éléments attendus.**\n\n- **Thèse** : le lion est un motif **universel** mais **pluriel** ; comme tout signe, il se lit dans son contexte.\n- **Les origines** : dans la **Bible**, menace (la fosse aux lions) et force au service du juste (Samson, Daniel) ; chez **Ésope**, le puissant qui prend « la part du lion ».\n- **Le Moyen Âge** : le **bestiaire** en fait un symbole du Christ (il efface ses traces, dort les yeux ouverts, ranime ses petits au troisième jour) ; Chrétien de Troyes en fait le **compagnon fidèle** d'Yvain ; le *Roman de Renart* en fait **Noble**, roi faible et partial.\n- **L'âge classique** : **La Fontaine** — « La Génisse, la Chèvre et la Brebis en société avec le Lion » (la loi du plus fort déguisée en contrat) ; « Le Lion et le Rat » (le rapport de force se retourne).\n- **L'époque moderne** : **emblème** politique (drapeaux, blasons) ou commercial (logos) ; sujet **romanesque** dans *Le Lion* de Joseph Kessel, où l'animal sauvage interroge la place de l'homme dans la nature.\n- **Ce qui fait varier le sens** : l'**époque** (foi médiévale, critique classique), le **genre** (bestiaire religieux, récit satirique, fable, roman) et l'**intention** (édifier, faire rire, dénoncer, interroger).\n- **Leçon pour le lecteur** : ne pas plaquer un sens tout fait sur une image ; la lire dans son contexte.\n\nÀ sanctionner : attributions fausses, exemples sans explication, absence de conclusion."}$exo$::jsonb),
  ('0c8cd730-90f7-5fc4-be33-6cf606139a47'::uuid, 1, 'redaction', $exo${"titre":"La mécanique de la fable","consigne":"Réponds en phrases complètes.","enonce":"1. Définis la **fable** et l'**apologue**.\n2. De quels **deux temps** une fable est-elle faite ? Où la morale peut-elle se placer ?\n3. L'animalisation des personnages produit trois effets. Nomme-les et explique chacun en une phrase.\n4. En quelles années paraissent les *Fables* de La Fontaine ? Les Lumières ont-elles inventé la fable ?","bareme":[{"critere":"Fable et apologue définis (récit court, animaux, morale ; récit qui sert une démonstration)","points":5},{"critere":"Récit et morale ; morale explicite en tête ou en fin, parfois implicite","points":4},{"critere":"Plaisir, protection, brièveté expliqués","points":7},{"critere":"1668-1694 ; non, les Lumières la rechargent","points":4}],"dureeMin":8,"corrige":"**1.** La **fable** est un récit court, souvent en vers, qui met en scène des animaux et débouche sur une morale. C'est un **apologue** : un **récit qui sert une démonstration**.\n\n**2.** Le **récit** (la situation, la rencontre, l'issue) et la **morale**. La morale peut être **explicite**, en tête ou en fin, ou parfois **implicite**.\n\n**3.**\n- Le **plaisir** : la scène est plaisante, donc elle est lue.\n- La **protection** : l'auteur parle d'un loup, non d'un ministre ; il critique sans se mettre en danger.\n- La **brièveté** : une fable se retient, donc elle circule.\n\n**4.** Les *Fables* paraissent de **1668 à 1694**, un siècle avant les Lumières. Les Lumières **n'inventent pas** la fable : elles la trouvent déjà chargée de critique (la cour, l'arbitraire, la justice inégale) et la **rechargent**."}$exo$::jsonb),
  ('0c8cd730-90f7-5fc4-be33-6cf606139a47'::uuid, 2, 'redaction', $exo${"titre":"Le Loup juge","consigne":"Lis la fable, puis réponds aux questions en citant le texte.","enonce":"Fable écrite pour ce contrôle, à la manière de La Fontaine :\n\n> Un Loup, nommé juge au tribunal des prés,\n> Vit un jour comparaître un Mouton et un Ours.\n> Le Mouton avait bu à la source d'en haut ;\n> L'Ours avait ravagé trois ruches et un clos.\n> « Toi, dit le Loup au Mouton, tu salis l'eau de tous :\n> Tu seras tondu ras et chassé du troupeau. »\n> Quant à l'Ours, on lui fit servir le miel et le repos.\n> Ainsi va la justice : elle pèse les griffes,\n> Et non pas les fautes.\n\n1. Distingue le **récit** et la **morale**. La morale est-elle explicite ou implicite ?\n2. Quelle **injustice** la fable dénonce-t-elle ? Rapproche-la d'un vers célèbre de La Fontaine que tu connais.\n3. Pourquoi l'auteur a-t-il choisi des **animaux** plutôt que des juges et des nobles ? Donne deux raisons.\n4. Relève un passage **ironique** et explique ce qu'il fait comprendre.","bareme":[{"critere":"Récit (v. 1-7) et morale explicite en fin (v. 8-9) distingués","points":4},{"critere":"Justice inégale selon la puissance, rapprochée de « Selon que vous serez puissant ou misérable… »","points":6},{"critere":"Deux effets de l'animalisation justifiés (plaisir, protection, brièveté)","points":5},{"critere":"Ironie relevée et expliquée","points":5}],"dureeMin":12,"corrige":"**1.** Le **récit** occupe les vers 1 à 7 (la situation : le procès ; la rencontre ; l'issue : le Mouton puni, l'Ours choyé). La **morale** est **explicite**, placée **en fin** : « Ainsi va la justice : elle pèse les griffes, / Et non pas les fautes. »\n\n**2.** La fable dénonce une **justice inégale** : la faute minuscule du faible (boire à la source) est lourdement punie, le ravage du puissant est récompensé. C'est la leçon de La Fontaine : « Selon que vous serez puissant ou misérable, / Les jugements de cour vous rendront blanc ou noir. »\n\n**3.** Deux raisons parmi : le **plaisir** (la scène animale est plaisante, donc lue) ; la **protection** (l'auteur parle d'un loup, non d'un juge ou d'un ministre : il ne peut pas être poursuivi) ; la **brièveté** (la fable se retient et circule).\n\n**4.** Par exemple : « tu salis l'eau de tous » — le juge fait passer pour un crime contre tous un geste innocent ; ou « on lui fit servir le miel et le repos » — le coupable reçoit en récompense ce qu'il a volé. L'**ironie** dit le contraire de ce qui serait juste pour rendre l'injustice **insoutenable** ; le lecteur qui la décode devient complice, donc convaincu par lui-même."}$exo$::jsonb),
  ('0c8cd730-90f7-5fc4-be33-6cf606139a47'::uuid, 3, 'redaction', $exo${"titre":"Détourner le regard pour faire voir","consigne":"Lis le document, puis rédige un paragraphe argumenté d'une vingtaine de lignes.","enonce":"**Document.** Dans *Candide* (1759), conte philosophique de Voltaire, le héros, jeune homme naïf, rencontre près de Surinam un esclave noir à qui l'on a coupé une main et une jambe. L'esclave explique son sort et conclut :\n\n> « C'est à ce prix que vous mangez du sucre en Europe. »\n\n**Sujet.** « Les Lumières n'inventent pas la fable : elles la trouvent déjà chargée, et elles la rechargent. » En t'appuyant sur le document et sur le cours, explique :\n- ce que la fable « chargeait » déjà chez La Fontaine ;\n- quelle **stratégie** commune partagent la fable et les formes voisines des Lumières (conte philosophique, lettre fictive…) ;\n- quel **combat** des Lumières le document illustre, et comment il touche le lecteur ;\n- le rôle de l'**ironie** dans cette stratégie.","bareme":[{"critere":"La Fontaine : critique de la cour, de l'arbitraire, de la justice inégale (1668-1694)","points":4},{"critere":"Stratégie du détour expliquée : un animal, un naïf, un étranger pour montrer le scandale de chez soi, avec exemples (Candide, Lettres persanes)","points":5},{"critere":"Combat contre l'esclavage identifié ; la phrase implique le lecteur européen (« vous »)","points":4},{"critere":"Ironie définie et son effet (complicité, conviction) expliqué","points":4},{"critere":"Paragraphe organisé et correct","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **La fable déjà chargée** : publiées de 1668 à 1694, les *Fables* de La Fontaine critiquent déjà la **cour**, l'**arbitraire du pouvoir** et la **justice inégale** (« Selon que vous serez puissant ou misérable… »).\n- **La stratégie commune** : **détourner le regard vers un ailleurs** — un **animal** (la fable), un **naïf** (Candide), un **étranger** (les *Lettres persanes* de Montesquieu) — pour faire voir le **scandale de chez soi**. Le conte philosophique (*Candide*, *Micromégas*) reprend ce principe.\n- **Le combat du document** : l'**esclavage**. Le regard naïf de Candide découvre le corps mutilé ; la phrase de l'esclave relie ce supplice à un plaisir ordinaire du lecteur, le **sucre**. Le « **vous** » met le lecteur européen en cause : il est complice. D'autres combats des Lumières : l'intolérance religieuse, la torture et l'affaire Calas, la censure ; ce qu'elles défendent : raison, tolérance, égalité devant la loi, liberté d'expression.\n- **L'ironie** : dire le contraire de ce qu'on pense pour le rendre **insoutenable**. Le lecteur qui la décode devient **complice**, donc **convaincu par lui-même**. (Dans *Candide*, le personnage naïf rend l'horreur plus visible parce qu'il ne la justifie pas.)\n\n**Conclusion** : les Lumières gardent la mécanique de l'apologue et la mettent au service de leurs combats."}$exo$::jsonb),
  ('1f740378-bc6a-576a-b8e3-f86e71be993f'::uuid, 1, 'redaction', $exo${"titre":"Convaincre, persuader, délibérer","consigne":"Réponds en phrases complètes.","enonce":"1. Distingue **convaincre**, **persuader** et **délibérer** : à quoi chacun s'adresse-t-il et avec quels moyens ?\n2. Donne trois facteurs qui font du XIXe siècle « le siècle de la presse ».\n3. Complète : *J'accuse… !* est publié par … dans le journal … le … , pendant l'affaire … .\n4. Qui publie *Le Deuxième Sexe*, en quelle année, et pour quelle cause ?","bareme":[{"critere":"Trois visées justes : raison et arguments ; émotions et images ; jugement qui pèse plusieurs thèses","points":8},{"critere":"Trois facteurs : imprimerie industrielle, alphabétisation, loi du 29 juillet 1881","points":6},{"critere":"Zola, L'Aurore, 13 janvier 1898, Dreyfus ; Beauvoir, 1949, féminisme","points":6}],"dureeMin":7,"corrige":"**1.**\n- **Convaincre** s'adresse à la **raison**, par des **arguments** et des **preuves**.\n- **Persuader** s'adresse aux **émotions**, par des **images**, des exemples frappants, le **rythme**.\n- **Délibérer** s'adresse au **jugement** : on **pèse plusieurs thèses** avant de trancher.\nUn texte efficace combine souvent les trois.\n\n**2.** L'**imprimerie industrielle** (tirages de masse), l'**alphabétisation** (lectorat élargi), la **loi du 29 juillet 1881** (liberté de la presse).\n\n**3.** *J'accuse… !* est publié par **Émile Zola** dans **L'Aurore** le **13 janvier 1898**, pendant l'**affaire Dreyfus**.\n\n**4.** **Simone de Beauvoir** publie *Le Deuxième Sexe* en **1949** : un texte fondateur du **féminisme**."}$exo$::jsonb),
  ('1f740378-bc6a-576a-b8e3-f86e71be993f'::uuid, 2, 'redaction', $exo${"titre":"Sauver la bibliothèque des Tilleuls","consigne":"Lis la tribune, puis réponds aux questions en citant le texte.","enonce":"Tribune écrite pour ce contrôle :\n\n> **Ne fermez pas la bibliothèque des Tilleuls !**\n>\n> La mairie veut fermer notre bibliothèque de quartier pour économiser 40 000 euros par an. C'est une erreur. D'abord, elle est le seul lieu gratuit et chauffé où deux cents collégiens font leurs devoirs chaque semaine. Ensuite, elle prête chaque année plus de 15 000 livres : fermer ses portes, c'est fermer 15 000 fenêtres sur le monde. Faut-il vraiment économiser sur l'avenir de nos enfants ? Monsieur le Maire, venez un mercredi à 17 heures : vous verrez des tables pleines et des lecteurs qui attendent leur tour. Certes, le budget est contraint. Mais une ville qui ferme ses bibliothèques ne fait pas des économies : elle fabrique de l'ignorance.\n>\n> — Le collectif des parents des Tilleuls\n\n1. Formule la **thèse** de la tribune.\n2. Relève **deux arguments** et **un exemple** qui les illustre.\n3. Relève **deux connecteurs logiques** et dis ce qu'ils organisent.\n4. Nomme **trois procédés de style** (question rhétorique, hyperbole, apostrophe…) en citant le texte.\n5. Le texte cherche-t-il plutôt à convaincre ou à persuader ? Justifie.","bareme":[{"critere":"Thèse juste : il ne faut pas fermer la bibliothèque","points":3},{"critere":"Deux arguments et un exemple correctement distingués","points":6},{"critere":"Connecteurs relevés et fonction expliquée ; trois procédés nommés et cités","points":7},{"critere":"Visée justifiée : il combine convaincre et persuader","points":4}],"dureeMin":12,"corrige":"**1.** Thèse : **la mairie ne doit pas fermer la bibliothèque des Tilleuls**, car ce serait une erreur qui « fabrique de l'ignorance ».\n\n**2.** Arguments : elle est le **seul lieu gratuit et chauffé** où les collégiens font leurs devoirs ; elle **prête beaucoup de livres** (plus de 15 000 par an). Exemple : « deux cents collégiens » chaque semaine, ou la scène d'un mercredi à 17 heures, « des tables pleines ».\n\n**3.** « **D'abord** », « **Ensuite** » : ils ordonnent les arguments. « **Certes** … **Mais** » : concession puis réfutation (on reconnaît la contrainte budgétaire pour mieux la dépasser).\n\n**4.** Trois procédés parmi :\n- **Question rhétorique** : « Faut-il vraiment économiser sur l'avenir de nos enfants ? » (la réponse va de soi : non).\n- **Apostrophe** : « Monsieur le Maire, venez un mercredi… ».\n- **Hyperbole** / image : « fermer 15 000 fenêtres sur le monde », « elle fabrique de l'ignorance ».\n\n**5.** Le texte **combine** : il **convainc** par des arguments chiffrés (40 000 euros, 200 collégiens, 15 000 livres) et il **persuade** par des images, la question rhétorique et l'apostrophe qui touchent l'émotion. Réponse attendue : les deux, avec une justification de chaque côté."}$exo$::jsonb),
  ('1f740378-bc6a-576a-b8e3-f86e71be993f'::uuid, 3, 'redaction', $exo${"titre":"La tribune, une forme littéraire","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des exemples précis du cours.","enonce":"**Sujet.** « Un journal, ce n'est pas seulement de l'information : c'est une tribune, et la tribune est une forme littéraire. »\n\nDans un paragraphe argumenté :\n1. explique pourquoi, au XIXe siècle, la frontière entre écrivain et journaliste est presque inexistante (conditions de l'essor, auteurs, un texte-sommet) ;\n2. montre qu'au XXe siècle la littérature d'idées sert de grandes causes (deux exemples) mais doute aussi de ses armes ;\n3. termine par les **trois questions** que pose le XXIe siècle à qui lit une tribune aujourd'hui.","bareme":[{"critere":"XIXe : imprimerie, alphabétisation, loi de 1881 ; Hugo, Zola, Sand dans les journaux","points":5},{"critere":"J'accuse… ! exactement situé (Zola, L'Aurore, 13 janvier 1898, affaire Dreyfus)","points":3},{"critere":"XXe : deux causes avec exemple juste et doute après les propagandes","points":5},{"critere":"XXIe : vérifier, qui finance, que valent les images ; migration des genres","points":4},{"critere":"Paragraphe organisé et correct","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n1. **XIXe siècle** : l'imprimerie industrielle permet des tirages de masse, l'**alphabétisation** élargit le lectorat, la **loi du 29 juillet 1881** garantit la liberté de la presse. **Écrivains et journalistes sont les mêmes hommes** : Hugo, Zola, Sand publient dans les journaux. Le sommet du genre : **J'accuse… !** de **Zola**, en une de **L'Aurore**, le **13 janvier 1898**, pendant l'**affaire Dreyfus** — un texte à la fois article et œuvre, où la tribune devient une forme littéraire.\n\n2. **XXe siècle** : la littérature d'idées sert l'**antifascisme** et la **Résistance** (écrits de combat), la **décolonisation** (essais, discours), le **féminisme** (*Le Deuxième Sexe*, Simone de Beauvoir, 1949), l'**antiracisme** (tribunes, récits). Mais, **après les propagandes de masse**, elle **doute de ses propres armes** : l'art de persuader peut aussi servir le mensonge.\n\n3. **XXIe siècle** : chaque lecteur devient **diffuseur** — comment **vérifier** ? De nouveaux financements — **qui finance** ? L'abondance d'**images** — que valent-elles comme **preuve** ? Les genres migrent : tribunes en ligne, podcasts, documentaires, vidéos.\n\n**Conclusion** : la tribune reste une forme littéraire (thèse, arguments, exemples, procédés), mais le lecteur doit apprendre à l'interroger."}$exo$::jsonb),
  ('a629bed4-b40c-553e-bf7d-4c9a84099664'::uuid, 1, 'redaction', $exo${"titre":"Une brève et ses questions","consigne":"Lis la brève, puis réponds aux questions.","enonce":"Brève écrite pour ce contrôle :\n\n> **Un camion se renverse sur la rocade**\n> Mardi 14 mars, vers 7 heures, un camion de livraison s'est renversé sur la rocade de Rennes, près de la porte de Cleunay, après avoir glissé sur une chaussée verglacée. Le chauffeur, légèrement blessé, a été conduit au CHU. La circulation a été coupée pendant deux heures.\n\n1. Retrouve dans la brève les réponses aux questions **qui, quoi, quand, où, pourquoi, comment**.\n2. À quelle **famille** et à quel **genre** journalistique appartient ce texte ? Justifie.\n3. Classe ces trois phrases en **fait** ou **opinion** : a) « La circulation a été coupée deux heures. » b) « Cette rocade est la plus mal entretenue de France. » c) « Le chauffeur a été conduit au CHU. »","bareme":[{"critere":"Les six questions retrouvées dans le texte","points":9},{"critere":"Famille information, genre brève, justifié (le fait en quelques lignes)","points":5},{"critere":"Classement juste des trois phrases (fait, opinion, fait)","points":6}],"dureeMin":7,"corrige":"**1.**\n- **Qui** : un camion de livraison et son chauffeur.\n- **Quoi** : le camion s'est renversé ; le chauffeur est légèrement blessé.\n- **Quand** : mardi 14 mars, vers 7 heures.\n- **Où** : sur la rocade de Rennes, près de la porte de Cleunay.\n- **Pourquoi** : il a glissé sur une chaussée verglacée.\n- **Comment** : le camion a glissé et s'est renversé ; conséquences : conduite au CHU, circulation coupée deux heures.\n\n**2.** Famille : **information**. Genre : la **brève** — elle donne **le fait, en quelques lignes**, sans point de vue, l'essentiel d'abord.\n\n**3.** a) **fait** (vérifiable) ; b) **opinion** (un jugement, qui se discute) ; c) **fait**. Un fait se **vérifie**, une opinion se **discute**."}$exo$::jsonb),
  ('a629bed4-b40c-553e-bf7d-4c9a84099664'::uuid, 2, 'redaction', $exo${"titre":"La rédaction du journal du lycée","consigne":"Réponds à chaque question en justifiant tes choix avec le vocabulaire du cours.","enonce":"**Situation.** Yanis dirige le journal du lycée Jean-Moulin. Pour le prochain numéro :\n\n- Un message partagé des centaines de fois affirme, photo à l'appui, que « la cantine va fermer pendant un mois ». La photo montre une cantine fermée, sans date.\n- Quatre textes sont prévus : A) le compte rendu de la visite de Yanis à la ferme qui fournit la cantine ; B) la position de la rédaction sur l'uniforme scolaire ; C) une recherche de trois semaines sur le coût réel des repas ; D) un entretien avec la cheffe cuisinière.\n\n1. Avant de publier quoi que ce soit sur la fermeture, quelles vérifications Yanis doit-il faire ? Donne trois réflexes précis.\n2. Donne le **genre** de chacun des textes A, B, C, D et sa **famille** (information ou opinion).\n3. Pourquoi le journal doit-il signaler clairement la famille du texte B ?\n4. Rédige le **chapô** (deux phrases) du texte D.","bareme":[{"critere":"Trois vérifications justes : source primaire, recoupement par deux sources indépendantes, recherche d'image inversée, méfiance envers l'émotion","points":6},{"critere":"Genres et familles justes : reportage, éditorial, enquête, interview","points":6},{"critere":"Distinction fait / opinion expliquée pour le texte B","points":3},{"critere":"Chapô qui résume l'article D","points":5}],"dureeMin":12,"corrige":"**1.** Réflexes attendus (trois) :\n- **Remonter à la source primaire** : qui a lancé le message ? Existe-t-il un document de l'administration ?\n- **Recouper** : obtenir l'information d'**au moins deux sources indépendantes** (direction, gestionnaire de la cantine).\n- **Dater et localiser la photo** par une **recherche d'image inversée** : elle peut venir d'un autre lieu ou d'une autre année.\n- Se **méfier du message à forte émotion** : c'est souvent sa seule fonction.\nC'est le premier devoir de la **Charte de Munich** (1971) : respecter la vérité et vérifier avant de publier.\n\n**2.**\n- A : **reportage** (il raconte ce qu'il a vu) — information.\n- B : **éditorial** (la position du journal) — opinion.\n- C : **enquête** (recherche longue) — information.\n- D : **interview** (il donne la parole) — information.\n\n**3.** Confondre information et opinion est la première source de malentendus : un fait se vérifie, une opinion se discute. Un journal honnête signale laquelle des deux il publie, pour que le lecteur ne prenne pas un avis pour un fait.\n\n**4.** Exemple de chapô : « Chaque jour, elle prépare 600 repas pour les élèves de Jean-Moulin. La cheffe cuisinière nous raconte son métier, ses contraintes et ses projets pour la cantine. » Critères : court, sous le titre, il **résume** l'article."}$exo$::jsonb),
  ('a629bed4-b40c-553e-bf7d-4c9a84099664'::uuid, 3, 'redaction', $exo${"titre":"Un article à reprendre","consigne":"Analyse l'article, puis réécris-le selon les règles du métier.","enonce":"Article écrit pour ce contrôle, publié sur un site d'information locale :\n\n> **SCANDALE : LA PISCINE, UN DANGER MORTEL ?**\n>\n> Notre ville mérite mieux que ses élus incompétents. On raconte sur les réseaux qu'un enfant aurait glissé samedi à la piscine Léo-Lagrange. Selon un internaute anonyme, le carrelage serait « une vraie patinoire ». Il y a quinze ans, la piscine avait été rénovée. Un maître-nageur a indiqué que l'enfant, légèrement contusionné, était reparti avec ses parents. Profitez-en : les maillots Aquastar sont à −30 % jusqu'à dimanche !\n\n1. Repère les éléments de l'**habillage** présents (titre, attaque, chute…) et dis si le titre remplit correctement son rôle.\n2. Relève **trois manquements** à la **Charte de Munich** ou aux règles du journalisme, en citant le texte.\n3. Le texte respecte-t-il la **pyramide inversée** ? Justifie.\n4. Réécris le **titre** et les **deux premières phrases** de l'article en séparant les faits de l'opinion et en suivant la pyramide inversée.","bareme":[{"critere":"Habillage repéré et titre critiqué (émotion, question alarmiste sans fait)","points":4},{"critere":"Trois manquements justes et cités : non vérifié / source anonyme, opinion mêlée à l'information, publicité mêlée au métier","points":6},{"critere":"Pyramide inversée : l'essentiel est enfoui, justification","points":3},{"critere":"Réécriture : titre factuel, faits essentiels d'abord, sans opinion","points":5},{"critere":"Expression correcte et précise","points":2}],"dureeMin":20,"corrige":"**1.** Habillage : un **titre** (en capitales), une **attaque** (« Notre ville mérite mieux… »), une **chute** (la publicité). Pas de chapô ni d'intertitre. Le titre **accroche**, mais par la peur : une question alarmiste (« danger mortel ») que les faits ne justifient pas. Il faut se méfier des titres à forte émotion : c'est souvent leur seule fonction.\n\n**2.** Manquements (trois au choix) :\n- **Ne pas vérifier** : « On raconte sur les réseaux », « aurait glissé », « un internaute anonyme » — rien n'est recoupé par deux sources indépendantes.\n- **Confondre information et opinion** : « élus incompétents » est une opinion glissée dans un article d'information.\n- **Dénaturer l'information** : le titre parle de danger mortel alors que l'enfant est « légèrement contusionné ».\n- **Confondre le métier avec la publicité** : « les maillots Aquastar sont à −30 % ».\n\n**3.** Non : l'information la plus sûre et la plus importante (un enfant légèrement blessé samedi, reparti avec ses parents, selon un maître-nageur) arrive à la fin, après des rumeurs et un détail sans rapport (la rénovation). La pyramide inversée exige l'essentiel **d'abord**.\n\n**4.** Exemple :\n- Titre : « Piscine Léo-Lagrange : un enfant légèrement blessé après une chute »\n- « Samedi, un enfant a glissé sur le carrelage de la piscine Léo-Lagrange. Selon un maître-nageur, il a été légèrement contusionné et est reparti avec ses parents. »\nAccepter toute version factuelle, sans opinion ni rumeur, qui répond d'abord à qui, quoi, quand, où."}$exo$::jsonb),
  ('6ce74e29-30fe-5eda-8520-97b1bde07a25'::uuid, 1, 'redaction', $exo${"titre":"Le journal devient une machine","consigne":"Réponds en phrases complètes.","enonce":"1. Donne les **trois** grandes causes de l'essor de la presse au XIXe siècle, avec un détail précis pour chacune.\n2. Qu'est-ce qu'un **roman-feuilleton** ? Cite deux auteurs et un titre pour chacun.\n3. Que fait Émile de Girardin en 1836 avec *La Presse* ?","bareme":[{"critere":"Progrès techniques, alphabétisation (lois Ferry 1881-1882), invention économique de Girardin, avec détail","points":8},{"critere":"Roman publié en épisodes au bas de la une ; Sue et Dumas avec titres justes","points":7},{"critere":"Prix divisé par deux, financé par la publicité","points":5}],"dureeMin":7,"corrige":"**1.**\n- Les **progrès techniques** : presse rotative, papier bon marché, télégraphe, chemin de fer pour la diffusion.\n- L'**alphabétisation**, accélérée par les **lois Ferry** de 1881-1882 (école gratuite, laïque, obligatoire).\n- L'**invention économique** de Girardin : la **publicité** finance le journal.\n\n**2.** Un **roman-feuilleton** est un roman **publié en épisodes au bas de la une** d'un journal, pour fidéliser le lecteur. **Eugène Sue** : *Les Mystères de Paris*. **Alexandre Dumas** : *Les Trois Mousquetaires* ou *Le Comte de Monte-Cristo*.\n\n**3.** En **1836**, Girardin **divise par deux le prix** de *La Presse* en la finançant par la **publicité**."}$exo$::jsonb),
  ('6ce74e29-30fe-5eda-8520-97b1bde07a25'::uuid, 2, 'redaction', $exo${"titre":"La suite au prochain numéro","consigne":"Lis l'extrait, puis réponds aux questions en t'appuyant sur le texte et le cours.","enonce":"Fin d'épisode écrite pour ce contrôle, à la manière d'un feuilleton de 1840 :\n\n> Le comte de Varennes, l'homme le plus cruel de Paris, tira le poignard de sa ceinture. Louise, la pauvre ouvrière au cœur pur, recula jusqu'au parapet ; derrière elle, la Seine grondait. « Vous ne sortirez pas vivante de ce pont », murmura-t-il. Elle ferma les yeux. Un pas résonna dans la nuit…\n>\n> *(La suite au prochain numéro.)*\n\n1. Relève **trois** traits d'écriture du feuilleton et relie chacun à la **contrainte** qui l'explique.\n2. Explique le lien entre l'invention de Girardin et le succès du roman-feuilleton.\n3. Pourquoi peut-on dire qu'au XIXe siècle, entre littérature et journalisme, « la frontière est un mince filet de colle » ?","bareme":[{"critere":"Trois traits relevés et reliés aux contraintes (suspense de fin d'épisode, rebondissements, personnages typés)","points":9},{"critere":"Lien expliqué : journal moins cher grâce à la publicité, il faut fidéliser un large public","points":6},{"critere":"Même papier, mêmes auteurs, même public, justifié","points":5}],"dureeMin":12,"corrige":"**1.**\n- **Suspense en fin d'épisode** : la scène s'arrête au moment critique (« Un pas résonna dans la nuit… ») et renvoie au prochain numéro — contrainte : **fidéliser** le lecteur, qui doit acheter le numéro suivant.\n- **Rebondissement** : l'arrivée inattendue d'un inconnu — contrainte : la **parution régulière**, qui appelle des rebondissements fréquents.\n- **Personnages typés** : « l'homme le plus cruel de Paris », « la pauvre ouvrière au cœur pur » — contrainte : un **public large**, qui doit reconnaître tout de suite les personnages.\n- Accepter aussi : épisode court, action concentrée (des chapitres courts).\n\n**2.** En 1836, Girardin **divise par deux le prix** de *La Presse* en la finançant par la **publicité**. Pour attirer les annonceurs, il faut beaucoup de lecteurs, et des lecteurs **fidèles** : le roman-feuilleton, publié en épisodes au bas de la une, les fait revenir chaque jour.\n\n**3.** Littérature et journalisme partagent **le même papier** (le roman est imprimé dans le journal), **les mêmes auteurs** (Sue, Dumas, mais aussi Hugo ou Zola écrivent dans la presse) et **le même public**. La « colle » est ce qui sépare à peine le bas de page romanesque des colonnes d'information."}$exo$::jsonb),
  ('6ce74e29-30fe-5eda-8520-97b1bde07a25'::uuid, 3, 'redaction', $exo${"titre":"Une conquête et un danger","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des exemples précis.","enonce":"**Sujet.** « Au XIXe siècle, la presse est à la fois une conquête et un danger. »\n\nDiscute cette affirmation dans un paragraphe argumenté :\n- montre d'abord en quoi la presse est une **conquête** (liberté, combats d'écrivains, loi) ;\n- montre ensuite son **revers** (au moins deux aspects) ;\n- conclus sur ce que le XIXe siècle nous a laissé.","bareme":[{"critere":"Conquête : Hugo contre le coup d'État et la peine de mort ; Zola, J'accuse… ! (1898), procès et exil","points":5},{"critere":"Loi de 1881 : protège la liberté et punit la diffamation","points":4},{"critere":"Revers : fait divers et sensationnel, campagnes qui détruisent une réputation, caricature (Daumier, Le Charivari) entre censure et procès","points":5},{"critere":"Conclusion sur l'héritage : une, titre accrocheur, série, tribune, débat public","points":3},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **Une conquête** : en cent ans, le journal passe d'une feuille coûteuse pour quelques milliers de lecteurs au **premier objet culturel de masse**. Il devient l'arme des écrivains : **Hugo** combat le **coup d'État de Louis-Napoléon Bonaparte** et la **peine de mort** ; **Zola** publie **J'accuse… !** (1898), qui lui vaut un **procès** et l'**exil**. La **loi de 1881** protège cette liberté **tout en punissant la diffamation** : la liberté a une limite, la réputation d'autrui.\n- **Un danger** : l'invention du **fait divers** et de la chronique judiciaire entraîne la **course au sensationnel** ; les **campagnes de presse** peuvent **détruire une réputation** ; la **caricature** (Daumier, *Le Charivari*) subit **censure et procès**, ce qui montre aussi que le pouvoir se méfie de la presse.\n- **Nuance possible** : le même outil sert la vérité (J'accuse) ou l'emballement (campagnes).\n- **L'héritage** : la **une**, le **titre accrocheur**, la **série à épisodes**, la **tribune signée**, le **débat public par journaux interposés**.\n\nÀ sanctionner : confusion entre loi de 1881 (liberté de la presse) et lois Ferry (école)."}$exo$::jsonb),
  ('e16927b4-a7b2-5d99-81c8-3cee14bec333'::uuid, 1, 'redaction', $exo${"titre":"Dix-neuf ans d'exil","consigne":"Réponds en phrases complètes.","enonce":"1. Quel événement pousse Victor Hugo à l'exil, et à quelle date ?\n2. Donne les étapes de son exil avec leurs dates, et l'année de son retour.\n3. Pourquoi refuse-t-il l'amnistie de 1859 ? Que devient alors son exil ?\n4. Présente les deux recueils de l'exil : titre, date, registre, sujet.","bareme":[{"critere":"Coup d'État du 2 décembre 1851 ; étapes Bruxelles, Jersey (1852-1855), Guernesey (1855-1870), retour en 1870","points":7},{"critere":"Refus de l'amnistie : rentrer quand la liberté rentrera ; l'exil devient une position morale","points":5},{"critere":"Les Châtiments (1853, colère, Napoléon le Petit) et Les Contemplations (1856, deuil, Léopoldine)","points":8}],"dureeMin":8,"corrige":"**1.** Le **coup d'État du 2 décembre 1851** de Louis-Napoléon Bonaparte. Hugo, député opposé au coup de force, fuit.\n\n**2.** **Bruxelles**, puis **Jersey** (1852-1855), puis **Guernesey** (1855-1870). Il rentre en **1870**, après **dix-neuf ans**.\n\n**3.** Il refuse l'amnistie de 1859 parce qu'il ne veut rentrer **que lorsque la liberté sera rétablie** (« quand la liberté rentrera, il rentrera »). L'exil cesse d'être une punition subie pour devenir une **position morale**, qui lui donne une autorité que le pouvoir ne peut pas lui retirer.\n\n**4.**\n- *Les Châtiments* (**1853**) : registre de la **colère** (satire, invective, pamphlet en vers) contre « **Napoléon le Petit** ».\n- *Les Contemplations* (**1856**) : registre du **deuil**, la mort de sa fille **Léopoldine**, noyée en 1843 ; le recueil s'organise en « Autrefois » et « Aujourd'hui »."}$exo$::jsonb),
  ('e16927b4-a7b2-5d99-81c8-3cee14bec333'::uuid, 2, 'redaction', $exo${"titre":"« Et s'il n'en reste qu'un »","consigne":"Lis la strophe, puis réponds aux questions en citant le texte.","enonce":"> Si l'on n'est plus que mille, eh bien, j'en suis ! Si même\n> Ils ne sont plus que cent, je brave encor Sylla ;\n> S'il en demeure dix, je serai le dixième ;\n> Et s'il n'en reste qu'un, je serai celui-là !\n>\n> — Victor Hugo, « Ultima verba », *Les Châtiments*, 1853 (Sylla : dictateur romain ; il désigne ici Napoléon III)\n\n1. Relève et nomme le procédé de **répétition** qui structure la strophe.\n2. Comment évoluent les nombres d'un vers à l'autre ? Quel effet produit cette évolution ?\n3. Pourquoi Hugo désigne-t-il l'empereur sous le nom de **Sylla** ? À quel registre du recueil cela correspond-il ?\n4. Montre que cette strophe exprime l'**exil choisi** dont parle le cours.","bareme":[{"critere":"Répétition de « Si » en début de proposition (anaphore) relevée et nommée","points":5},{"critere":"Nombres décroissants (mille, cent, dix, un) et effet : solitude assumée, fermeté croissante","points":5},{"critere":"Sylla : critique déguisée d'un dictateur ; registre de la colère, satire","points":4},{"critere":"Lien avec le refus de l'amnistie et l'exil comme position morale","points":6}],"dureeMin":12,"corrige":"**1.** La répétition de « **Si** » (« Si l'on n'est plus que mille », « Si même / Ils ne sont plus que cent », « S'il en demeure dix », « s'il n'en reste qu'un ») : c'est une **anaphore**, qui **martèle** une même hypothèse. (Accepter aussi la reprise « je serai… je serai ».)\n\n**2.** Les nombres **diminuent** : mille, cent, dix, un. Plus les résistants sont peu nombreux, plus le poète affirme sa présence ; la phrase finale, « je serai celui-là », place le « je » seul face au pouvoir. L'effet : une **solitude assumée** et une détermination qui grandit à mesure que les autres renoncent.\n\n**3.** Sylla est un **dictateur romain** : le nommer, c'est désigner Napoléon III comme un tyran sans le nommer, par un rapprochement qui le rabaisse. Cela relève du registre de la **colère** des *Châtiments* : **satire**, **invective**, pamphlet en vers contre « Napoléon le Petit ».\n\n**4.** Le poète accepte d'être le dernier opposant : c'est l'esprit de son **refus de l'amnistie de 1859**. L'exil n'est plus une punition subie, c'est une **position morale** ; le vers « Et s'il n'en reste qu'un, je serai celui-là » en est la devise, et donne au poète une autorité que le pouvoir ne peut pas lui retirer."}$exo$::jsonb),
  ('e16927b4-a7b2-5d99-81c8-3cee14bec333'::uuid, 3, 'redaction', $exo${"titre":"L'île, prison et poste d'observation","consigne":"Lis le poème, puis rédige un commentaire en un paragraphe d'une vingtaine de lignes.","enonce":"Poème écrit pour ce contrôle, à la manière de Hugo en exil :\n\n> Ô France, je te vois de mon rocher sauvage,\n> Toi, là-bas, sous le joug ; moi, seul, sur cette plage.\n> L'Océan gronde et dit : « Proscrit, que fais-tu là ? »\n> — Je veille. Je veille, et je n'oublie pas.\n> Les vagues, les récifs, l'écume et la marée\n> Me tiennent enfermé, loin de toi, ma bien-aimée ;\n> Mais de ce bout du monde où l'on m'a rejeté,\n> Je vois mieux ton visage et ta captivité.\n\n**Sujet.** Comment ce poème fait-il de l'absence une force ? Dans ton paragraphe, tu analyseras au moins **quatre** procédés du cours (antithèse, champ lexical, apostrophe, anaphore ou répétition, personnification) et tu relieras le poème à l'expérience de Hugo à Guernesey.","bareme":[{"critere":"Problématique posée : l'absence devient une force","points":3},{"critere":"Quatre procédés justement nommés et cités (antithèse, champ lexical de la mer, apostrophe, répétition, personnification)","points":8},{"critere":"Interprétation : l'île est à la fois prison et poste d'observation","points":4},{"critere":"Lien avec l'exil de Hugo (Guernesey, position morale, il continue d'écrire)","points":3},{"critere":"Commentaire organisé et correct","points":2}],"dureeMin":20,"corrige":"**Éléments attendus.**\n\n- **Antithèse** entre ici et là-bas : « Toi, là-bas, sous le joug ; moi, seul, sur cette plage » — le monde est partagé en deux : la France captive, le poète libre mais seul.\n- **Apostrophe** au pays perdu : « Ô France », « ma bien-aimée » — la France devient un **interlocuteur**, presque une personne aimée.\n- **Personnification** de l'Océan, qui « gronde et dit » et interroge le « Proscrit » : une force qui répond.\n- **Champ lexical** de la mer et de l'île : « rocher », « plage », « Océan », « vagues », « récifs », « écume », « marée » — il dit l'**enfermement** (« Me tiennent enfermé ») et l'horizon.\n- **Répétition** : « Je veille. Je veille » — elle **martèle** la vigilance ; la réponse brève contraste avec la question de l'Océan.\n- **Retournement final** (« Mais … Je vois mieux ») : l'éloignement donne un regard plus clair. L'île est **à la fois prison et poste d'observation**.\n- **Lien avec Hugo** : exilé à **Guernesey** (1855-1870) après le coup d'État, il refuse l'amnistie ; l'exil devient une **position morale**. Il continue de publier, se fait photographier sur son rocher, écrit *Les Misérables* : « absent du territoire, il devient omniprésent dans les esprits ».\n\n**Conclusion attendue** : le poème transforme le manque en autorité ; l'exil, chez Hugo, est une manière de rester."}$exo$::jsonb),
  ('398e045d-42fe-5580-b782-247af6a3ed79'::uuid, 1, 'redaction', $exo${"titre":"Les voix de l'exil","consigne":"Réponds en phrases complètes.","enonce":"1. Distingue l'**exil subi** et l'**exil intérieur**.\n2. Associe chaque poète à son exil ou à son œuvre :\n   - Aimé Césaire · Paul Celan · Mahmoud Darwich · Nâzim Hikmet · Léopold Sédar Senghor\n   - a) il écrit depuis la prison puis l'exil ; b) il écrit l'Afrique depuis Paris ; c) il fait de la Palestine perdue un territoire de langue ; d) survivant de la Shoah, il écrit en allemand ; e) il forge le mot « négritude »\n3. Pourquoi le choix de Celan d'écrire en allemand est-il un choix lourd de sens ?","bareme":[{"critere":"Exil subi (on fuit une menace) et exil intérieur (on reste sans se reconnaître) distingués","points":5},{"critere":"Cinq associations justes","points":10},{"critere":"L'allemand est la langue des bourreaux","points":5}],"dureeMin":7,"corrige":"**1.** L'**exil subi** : on **fuit une menace**, on quitte son pays. L'**exil intérieur** : on **reste au pays**, mais on **ne s'y reconnaît plus**. Beaucoup de poèmes du XXe siècle jouent des deux.\n\n**2.**\n- **Aimé Césaire** : e) il forge le mot **négritude** (*Cahier d'un retour au pays natal*, 1939), transformant une insulte en fierté.\n- **Paul Celan** : d) survivant de la Shoah, il écrit en **allemand** une poésie trouée.\n- **Mahmoud Darwich** : c) il fait de la **Palestine perdue un territoire de langue**.\n- **Nâzim Hikmet** : a) poète turc, il écrit depuis la **prison** puis l'**exil**.\n- **Léopold Sédar Senghor** : b) il écrit l'**Afrique depuis Paris**.\n\n**3.** Parce que l'allemand est **la langue des bourreaux** : Celan, rescapé de la Shoah, écrit dans la langue de ceux qui ont voulu l'anéantir, et sa poésie « trouée » porte la trace de ce manque."}$exo$::jsonb),
  ('398e045d-42fe-5580-b782-247af6a3ed79'::uuid, 2, 'redaction', $exo${"titre":"La clé de ma mère","consigne":"Lis le poème, puis réponds aux questions en appliquant la méthode de lecture d'un poème d'exil.","enonce":"Poème écrit pour ce contrôle :\n\n> Ma mère a gardé la clé\n>                     d'une porte\n> qui n'ouvre plus sur rien.\n>\n> Chaque soir elle dit *saudade*\n> et personne ici ne sait\n> Lisbonne — le train — la frontière —\n> et puis\n>\n>\n> (*saudade* : mot portugais, la nostalgie d'un bonheur perdu)\n\n1. Que **nomme** le poème ? Relève les lieux, les objets, les mots précis.\n2. Que **tait**-il ? Appuie-toi sur les blancs et la fin.\n3. Comment la **forme** imite-t-elle la rupture ? Nomme trois procédés.\n4. Quelle **image récurrente** des poèmes d'exil retrouves-tu, et que porte-t-elle ?","bareme":[{"critere":"Ce que le poème nomme : Lisbonne, le train, la frontière, la clé, le mot saudade","points":4},{"critere":"Ce qu'il tait : le départ lui-même, ce qui est arrivé après, suggéré par les blancs et la phrase inachevée","points":5},{"critere":"Trois procédés formels justement nommés : vers libre, blancs typographiques, phrase inachevée, plurilinguisme","points":6},{"critere":"La clé d'une maison qui n'existe plus : la perte irréversible (et le train / la frontière : départ, passage)","points":5}],"dureeMin":12,"corrige":"**1.** Le poème **nomme** un lieu (**Lisbonne**), un moyen de départ (**le train**), un passage (**la frontière**), un objet (**la clé**), et un mot de la langue perdue (**saudade**).\n\n**2.** Il **tait** le récit du départ : pourquoi on est parti, ce qui s'est passé à la frontière, ce qu'est devenue la maison. Les **blancs** (le décalage de « d'une porte », les lignes vides à la fin) et la phrase **inachevée** « et puis » disent **ce qui manque** : l'indicible.\n\n**3.** Procédés (trois au choix) :\n- le **vers libre** (vers de longueur inégale, sans rime) : rupture avec l'ordre ancien ;\n- les **blancs typographiques** : ce qui manque ;\n- la **phrase inachevée** (« et puis ») et les tirets qui hachent l'énumération « Lisbonne — le train — la frontière — » : une énumération qui s'essouffle ;\n- le **plurilinguisme** : le mot portugais *saudade* au milieu du poème français, trace de la langue perdue.\n\n**4.** La **clé d'une maison qui n'existe plus** (« une porte / qui n'ouvre plus sur rien ») : elle porte la **perte irréversible**. Le **train** dit le départ, la **frontière** le passage. Quand la terre manque, il reste la langue : le mot *saudade* est le seul pays qui reste à la mère."}$exo$::jsonb),
  ('398e045d-42fe-5580-b782-247af6a3ed79'::uuid, 3, 'redaction', $exo${"titre":"Quand la terre manque, il reste la langue","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des exemples précis du cours.","enonce":"**Sujet.** « Quand la terre manque, il reste la langue : beaucoup de poètes exilés en font leur seul pays. »\n\nExplique et illustre cette affirmation. Tu t'appuieras :\n- sur le contexte du XXe siècle, siècle des exils de masse ;\n- sur au moins **trois** poètes du cours ;\n- sur ce que l'exil fait à la **forme** du poème ;\n- sur le rôle de la **chanson**.","bareme":[{"critere":"Contexte : guerres mondiales, totalitarismes, guerres coloniales, dictatures ; exil subi et intérieur","points":4},{"critere":"Trois poètes exactement présentés et reliés à l'idée de la langue comme pays (Césaire, Celan, Darwich, Senghor, Hikmet)","points":6},{"critere":"Effets de l'exil sur la forme : vers libre, blancs, plurilinguisme","points":4},{"critere":"La chanson circule là où le livre n'entre pas (Barbara, Ferré, Moustaki, rap)","points":3},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **Contexte** : le XXe siècle est celui des **exils de masse** — guerres mondiales, régimes totalitaires, guerres coloniales, dictatures. La poésie enregistre ces départs et en fait une forme. Exil **subi** (fuir une menace) ou **intérieur** (rester sans se reconnaître).\n- **Poètes** (trois au moins) :\n  - **Mahmoud Darwich** fait de la **Palestine perdue un territoire de langue** : exemple le plus direct de la langue comme pays.\n  - **Paul Celan**, survivant de la Shoah, écrit en **allemand**, la langue des bourreaux, une poésie trouée : il reconquiert la langue elle-même.\n  - **Aimé Césaire** forge le mot **négritude** dans le *Cahier d'un retour au pays natal* (1939) : il transforme une insulte en fierté, la langue devient une arme.\n  - **Senghor** écrit l'Afrique depuis Paris ; **Hikmet** écrit depuis la prison puis l'exil.\n- **La forme** : le **vers libre** imite la rupture avec l'ordre ancien ; les **blancs** et les phrases inachevées disent ce qui manque ; le **plurilinguisme** fait entrer des mots de la langue perdue dans le poème. Images récurrentes : valise, train, frontière, mer, clé d'une maison qui n'existe plus.\n- **La chanson** (Barbara, Ferré, Moustaki, plus tard le rap) prolonge ces poèmes parce qu'elle **circule là où le livre n'entre pas**.\n\n**Conclusion** : privé de sol, le poète habite sa langue ; le poème devient une patrie portative."}$exo$::jsonb),
  ('c5504697-78c6-54dc-8c2a-8e196a470503'::uuid, 1, 'redaction', $exo${"titre":"Le théâtre du réel","consigne":"Réponds en phrases complètes.","enonce":"1. Qui est Sonia Ristić ? Quel lien personnel a-t-elle avec le sujet de *Migrants* ?\n2. Définis le **théâtre documentaire** : quelle est sa matière première ?\n3. Qu'est-ce qu'une écriture **chorale** ? Quel effet produit-elle ?\n4. Définis l'**adresse directe** au public.","bareme":[{"critere":"Née à Belgrade en 1972, elle a connu l'exil pendant les guerres de Yougoslavie","points":5},{"critere":"Théâtre documentaire : témoignages, rapports, articles mis en forme dramatique","points":5},{"critere":"Écriture chorale : plusieurs voix sans héros unique, situation collective ; adresse directe définie","points":10}],"dureeMin":7,"corrige":"**1.** Sonia Ristić est née à **Belgrade en 1972** ; elle a elle-même **connu l'exil** au moment des **guerres de Yougoslavie**. Sa pièce *Migrants* porte à la scène des trajectoires contemporaines.\n\n**2.** Le **théâtre documentaire**, ou théâtre du réel, prend pour matière première des **témoignages**, des **rapports**, des **articles**, qu'il **met en forme dramatique**. Le spectateur n'est pas invité à s'évader mais à regarder ce qu'il croit déjà connaître par les journaux.\n\n**3.** Une écriture **chorale** fait entendre **plusieurs voix** (personnes déplacées, passeurs, fonctionnaires, témoins, parfois sans nom) **sans héros unique**. Effet : le destin individuel cède la place à une **situation collective**.\n\n**4.** L'**adresse directe** : un personnage **s'adresse aux spectateurs** sans passer par la fiction ; le spectateur est **pris à partie**."}$exo$::jsonb),
  ('c5504697-78c6-54dc-8c2a-8e196a470503'::uuid, 2, 'redaction', $exo${"titre":"Guichet numéro 4","consigne":"Lis l'extrait, puis réponds aux questions en citant le texte.","enonce":"Scène écrite pour ce contrôle, à la manière du théâtre documentaire :\n\n> *Plateau nu. Une chaise. Une lumière blanche.*\n>\n> UNE FEMME. — Onze mois. Onze mois que j'attends ce papier.\n> LE FONCTIONNAIRE. — Dossier incomplet. Revenez mardi.\n> UN HOMME, *face au public*. — Vous aussi, vous avez déjà attendu un mardi. Mais pas onze mois. Pas avec vos enfants dehors.\n> UNE FEMME. — Trois mille euros, la traversée. Alep, Izmir, Lesbos.\n> *Silence.*\n> LE FONCTIONNAIRE. — Suivant.\n\n1. Montre que l'écriture est **chorale**. Comment les personnages sont-ils désignés ?\n2. Relève un exemple d'**adresse directe** et explique son effet.\n3. Relève l'alternance entre le **concret** et le **silence** : que produit-elle ?\n4. Pourquoi l'**absence de décor** réaliste ?\n5. De quoi la scène parle-t-elle vraiment, selon le cours ?","bareme":[{"critere":"Écriture chorale : plusieurs voix, personnages désignés par leur fonction ou sans nom","points":4},{"critere":"Adresse directe relevée (« face au public ») et effet expliqué","points":4},{"critere":"Concret (durée, somme, villes) puis silence, et son effet","points":5},{"critere":"Plateau vide qui oblige à imaginer ; sujet : ce que l'attente et l'administration font aux personnes","points":7}],"dureeMin":12,"corrige":"**1.** Plusieurs voix s'enchaînent sans héros unique : **une femme, un homme, le fonctionnaire**. Ils ne sont **pas nommés** : ils sont désignés par leur fonction ou de façon générale. Le destin individuel cède la place à une **situation collective** : c'est une écriture **chorale**.\n\n**2.** « UN HOMME, *face au public*. — Vous aussi, vous avez déjà attendu un mardi. » Il **s'adresse directement aux spectateurs**, sans passer par la fiction : le spectateur est **pris à partie**, obligé de comparer sa propre attente à celle des personnages.\n\n**3.** Éléments concrets : « Onze mois », « Trois mille euros », « Alep, Izmir, Lesbos » — une durée d'attente, une somme, des noms de villes ; puis « *Silence.* » et le « Suivant » sec. L'alternance fait sentir le poids de chaque détail et laisse le spectateur seul face à ce qui n'est pas dit. Le **récit réveille là où le chiffre anesthésie**.\n\n**4.** Le **plateau vide** (« Plateau nu. Une chaise ») **oblige le spectateur à imaginer** ; rien ne le distrait des voix.\n\n**5.** Moins de la migration comme problème politique que de ce que **l'attente, la frontière et l'administration font à des personnes** : la dignité, la peur, l'espoir, la mémoire du pays quitté. Le texte ne conclut pas : il installe une question."}$exo$::jsonb),
  ('c5504697-78c6-54dc-8c2a-8e196a470503'::uuid, 3, 'redaction', $exo${"titre":"Représenter la souffrance sans en faire un spectacle","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur le cours.","enonce":"**Sujet.** « Le chiffre anesthésie, le récit réveille. » Mais représenter la souffrance d'autrui, n'est-ce pas risquer d'en faire un spectacle ?\n\nDans un paragraphe argumenté, tu montreras :\n- en quoi le théâtre documentaire de *Migrants* prétend « réveiller » le spectateur ;\n- quels **choix scéniques** lui permettent d'éviter le spectacle de la souffrance (au moins trois) ;\n- pourquoi le texte **ne conclut pas** à la place du public.\n\nTu peux évoquer d'autres formes qui posent la même question (romans, documentaires, photographies, chansons).","bareme":[{"critere":"Le pari expliqué : les chiffres de l'actualité laissent indifférent, le récit donne un visage","points":4},{"critere":"Trois choix scéniques analysés (écriture chorale, fragments et monologues, adresse directe, plateau vide, alternance concret / silence)","points":6},{"critere":"Le refus de conclure : une question installée, le public juge","points":4},{"critere":"La question éthique posée et discutée avec nuance","points":3},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **Le pari** : les chiffres de l'actualité (tant de morts, tant de demandeurs) **anesthésient** ; le **récit** redonne une voix et un visage. *Migrants* s'appuie sur des témoignages, rapports et articles mis en forme dramatique : le spectateur doit regarder ce qu'il croit déjà connaître par les journaux.\n- **Les choix scéniques** qui évitent le spectacle :\n  - l'**écriture chorale** : pas de héros sur qui pleurer, une **situation collective** ;\n  - les **récits fragmentés**, les **monologues** : aucune intrigue à suspense à consommer ;\n  - l'**adresse directe** : le spectateur est pris à partie, il ne peut pas rester voyeur ;\n  - l'**absence de décor** réaliste : pas d'images spectaculaires de naufrage, le plateau vide **oblige à imaginer** ;\n  - l'**alternance concret / silence** : un nom de ville, une somme, une durée d'attente — puis rien ; la retenue plutôt que l'effet.\n- **Le refus de conclure** : la pièce ne propose pas de solution politique ; elle **installe une question** et laisse au public la responsabilité du jugement. Elle parle de ce que l'attente, la frontière et l'administration font aux personnes : dignité, peur, espoir, mémoire.\n- **Nuance** : la question traverse toutes les formes (romans, documentaires, photographies, chansons) ; aucune n'y échappe tout à fait, mais la retenue formelle est une réponse.\n\n**Conclusion** : montrer sans exhiber, faire entendre plutôt que faire pleurer."}$exo$::jsonb),
  ('67baaeb0-9df3-58be-85b7-89fe88eae630'::uuid, 1, 'redaction', $exo${"titre":"Les outils du récit","consigne":"Réponds en phrases complètes.","enonce":"1. Le narrateur d'un roman est-il l'auteur ? Distingue narrateur **externe** et narrateur **interne**.\n2. Définis les trois **points de vue** : zéro, interne, externe.\n3. Associe chaque technique à ce qu'elle fait : **sommaire**, **scène**, **ellipse**, **pause** — a) on décrit ; b) on saute un moment ; c) on raconte au rythme réel ; d) on résume.","bareme":[{"critere":"Narrateur distinct de l'auteur ; externe (3e personne, de l'extérieur) et interne (un personnage raconte)","points":6},{"critere":"Trois points de vue justement définis","points":7},{"critere":"Quatre associations justes (sommaire d, scène c, ellipse b, pause a)","points":7}],"dureeMin":8,"corrige":"**1.** Non : **le narrateur n'est pas l'auteur** ; c'est une voix construite par le texte. Le narrateur **externe** raconte à la troisième personne, de l'extérieur de l'histoire ; le narrateur **interne** est un **personnage** qui raconte.\n\n**2.**\n- Point de vue **zéro** : le narrateur **sait tout** (pensées, passé, avenir des personnages).\n- Point de vue **interne** : on ne sait **que ce qu'un personnage sait**, voit, ressent.\n- Point de vue **externe** : on ne voit **que les comportements**, de l'extérieur.\n\n**3.** **Sommaire** : d) on résume. **Scène** : c) on raconte au rythme réel. **Ellipse** : b) on saute. **Pause** : a) on décrit."}$exo$::jsonb),
  ('67baaeb0-9df3-58be-85b7-89fe88eae630'::uuid, 2, 'redaction', $exo${"titre":"L'atelier de Julien","consigne":"Lis l'extrait, puis réponds aux questions en citant le texte.","enonce":"Extrait écrit pour ce contrôle :\n\n> Julien poussa la porte de l'atelier. La lumière grise tombait sur les établis ; une odeur de colle et de sciure lui piqua la gorge, et il sentit son cœur battre trop vite. Au fond, son père rabotait une planche sans lever la tête.\n> « Tu es en retard.\n> — Le bus, papa.\n> — Toujours le bus. »\n> Trois années passèrent. Pendant tout ce temps, Julien apprit le métier, se leva chaque jour à six heures, se tut chaque soir à table.\n> L'atelier, désormais, était vaste et clair : de hautes fenêtres, des outils rangés par taille, un poêle de fonte dans un coin.\n\n1. Le narrateur est-il externe ou interne ? Justifie.\n2. Quel est le **point de vue** du premier paragraphe ? Relève deux indices.\n3. Identifie dans l'extrait une **scène**, une **ellipse**, un **sommaire** et une **pause** en citant chaque fois le passage.\n4. Quel effet produit l'enchaînement de la scène et du sommaire sur la relation entre le père et le fils ?","bareme":[{"critere":"Narrateur externe justifié (3e personne, pas de « je » narrateur)","points":3},{"critere":"Point de vue interne justifié par deux indices (perceptions et sensations de Julien)","points":5},{"critere":"Scène, ellipse, sommaire et pause correctement identifiées et citées","points":8},{"critere":"Effet interprété : dialogue sec puis années résumées en silence","points":4}],"dureeMin":12,"corrige":"**1.** Narrateur **externe** : le récit est à la **troisième personne** (« Julien poussa », « il sentit ») ; celui qui raconte n'est pas un personnage.\n\n**2.** Point de vue **interne**, celui de Julien : on perçoit ce qu'il perçoit — « La lumière grise tombait sur les établis », « une odeur de colle et de sciure lui piqua la gorge » — et ce qu'il ressent — « il sentit son cœur battre trop vite ». On ne connaît pas les pensées du père, qui « rabotait une planche sans lever la tête » (vu de l'extérieur).\n\n**3.**\n- **Scène** : le dialogue « Tu es en retard. — Le bus, papa. — Toujours le bus. » (rythme réel).\n- **Ellipse** : « Trois années passèrent. » (on saute).\n- **Sommaire** : « Pendant tout ce temps, Julien apprit le métier, se leva chaque jour à six heures, se tut chaque soir à table. » (on résume).\n- **Pause** : « L'atelier, désormais, était vaste et clair : de hautes fenêtres, des outils rangés par taille, un poêle de fonte… » (on décrit, le temps de l'histoire s'arrête).\n\n**4.** La scène montre en trois répliques une relation tendue (reproche, excuse, reproche). Le sommaire qui suit résume trois ans par des gestes répétés et un silence (« se tut chaque soir ») : la relation ne change pas, elle se fige. Le rythme du récit dit ce que les personnages ne disent pas."}$exo$::jsonb),
  ('67baaeb0-9df3-58be-85b7-89fe88eae630'::uuid, 3, 'redaction', $exo${"titre":"Trois siècles de romans","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des auteurs et des œuvres précis.","enonce":"**Sujet.** « Le roman est le genre qui change le plus vite, parce qu'il n'a jamais eu de règles fixes. C'est aussi celui qui prétend le plus souvent dire la vérité sur la société. »\n\nMontre, du XVIIIe au XXIe siècle, comment le roman se transforme tout en cherchant à dire le vrai. Pour chaque siècle, donne **ce que le roman devient** et **au moins un auteur ou une œuvre**. Tu termineras en expliquant ce que le XXIe siècle garde des libertés du XXe.","bareme":[{"critere":"XVIIIe : légitimité par le déguisement (lettres, mémoires, conte), apprentissage d'un individu, auteur juste","points":4},{"critere":"XIXe : réalisme et naturalisme, personnage déterminé par son milieu ; Balzac, Flaubert, Zola","points":4},{"critere":"XXe : le récit doute de lui-même ; procédés et auteurs justes (Proust, Céline, Camus, Nouveau Roman)","points":5},{"critere":"XXIe : retour du récit du réel (autofiction, filiation, enquête) sans renoncer aux libertés","points":4},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **XVIIIe siècle** : le roman conquiert sa légitimité en se **déguisant** — roman **par lettres** (Laclos, *Les Liaisons dangereuses*), **mémoires fictifs** (Prévost, *Manon Lescaut*), **conte philosophique** (Voltaire, *Candide*). Il raconte l'**apprentissage d'un individu** confronté au monde.\n- **XIXe siècle** : **réalisme** et **naturalisme** : le personnage est **déterminé par son milieu**. Balzac veut « faire concurrence à l'état civil », Flaubert travaille la banalité, Zola applique une méthode qu'il dit **expérimentale**. Le roman raconte des **places sociales** : monter, tomber, tenir.\n- **XXe siècle** : le récit **doute de lui-même** — monologue intérieur, chronologie éclatée, personnage sans nom ni psychologie stable. **Proust** explore la mémoire, **Céline** casse la langue écrite, **Camus** écrit une voix blanche, le **Nouveau Roman** supprime l'intrigue.\n- **XXIe siècle** : **retour du récit du réel** — **autofiction**, **récits de filiation**, **romans d'enquête** : le roman reprend le rôle de **témoin**, **sans renoncer aux libertés** gagnées au XXe siècle (formes éclatées, voix singulières).\n\n**Fil conduit** : sans règles fixes, le roman change de forme à chaque époque, mais toujours pour rendre compte d'une vérité de la société ou de l'individu."}$exo$::jsonb),
  ('30417519-e1db-5a1c-a8ec-25d7f3771ef0'::uuid, 1, 'redaction', $exo${"titre":"Réalisme, naturalisme, Maupassant","consigne":"Réponds en phrases complètes.","enonce":"1. Que décrit le roman réaliste, et qu'abandonne-t-il ?\n2. Distingue **réalisme** et **naturalisme**. Duquel des deux Maupassant est-il le plus proche ?\n3. Définis le **discours indirect libre**.\n4. Présente Maupassant : dates, maître, nombre de nouvelles, forme typique de ses récits.","bareme":[{"critere":"Métiers, argent, intérieurs, corps, province ; abandon de l'idéalisation","points":4},{"critere":"Réalisme (personnage dans son milieu) / naturalisme (produit de l'hérédité et du milieu) ; Maupassant proche du réalisme","points":6},{"critere":"Discours indirect libre juste : pensées dans le récit sans guillemets ni verbe introducteur","points":4},{"critere":"1850-1893, Flaubert, environ trois cents nouvelles, situation resserrée et chute","points":6}],"dureeMin":7,"corrige":"**1.** Le réalisme écrit **les métiers, l'argent, les intérieurs, les corps**, la **province** autant que Paris ; il **abandonne l'idéalisation** et le seul monde des salons. Il ne se contente pas de décrire : il **choisit** ce qu'il décrit, et ce choix est déjà un jugement.\n\n**2.** Le **réalisme** décrit le personnage **dans** son milieu ; le **naturalisme** (Zola) en fait le **produit** de son **hérédité** et de son **milieu**. **Maupassant** reste plus proche du **réalisme** : il accuse la société sans se réclamer d'une science.\n\n**3.** Le **discours indirect libre** fait passer les **pensées d'un personnage dans le récit**, **sans guillemets ni verbe introducteur**.\n\n**4.** Maupassant (**1850-1893**), élève de **Flaubert**, a écrit environ **trois cents nouvelles** : peu de pages, une **situation resserrée**, souvent une **chute** qui retourne le sens."}$exo$::jsonb),
  ('30417519-e1db-5a1c-a8ec-25d7f3771ef0'::uuid, 2, 'redaction', $exo${"titre":"La Parure : une chute qui accuse","consigne":"Lis le résumé et les phrases proposées, puis réponds aux questions.","enonce":"**Résumé de « La Parure » (Maupassant, 1884).** Mathilde Loisel, femme d'un petit employé de ministère, souffre de ne pas être riche. Invitée à un bal, elle emprunte à son amie Mme Forestier une rivière de diamants. Elle brille toute la soirée, puis perd le bijou. Le couple s'endette pour en acheter un semblable, à trente-six mille francs, et le rend sans rien dire. Pendant dix ans, Mathilde fait le ménage, lave le linge, marchande chaque sou. Les dettes payées, elle rencontre Mme Forestier et lui avoue tout. Celle-ci répond que sa parure était fausse : elle valait au plus cinq cents francs.\n\n**Phrases écrites pour ce contrôle :**\n- a) Mathilde pensa : « Je n'ai rien à me mettre. »\n- b) Mathilde se regardait dans la glace. Comment irait-elle à ce bal avec cette robe de théâtre ? Elle serait la plus pauvre de toutes !\n- c) Mathilde se dit qu'elle n'avait rien à se mettre.\n\n1. Quelle phrase est au **discours indirect libre** ? Justifie en la comparant aux deux autres.\n2. En quoi la fin est-elle une **chute** ? Montre qu'elle ne fait pas que surprendre : que met-elle en accusation ?\n3. Dans le résumé, relève deux **détails matériels** qui disent la place sociale de Mathilde.\n4. Comment Maupassant laisse-t-il le lecteur juger lui-même ?","bareme":[{"critere":"Phrase b identifiée et justifiée (pas de guillemets ni de verbe introducteur, contre a direct et c indirect)","points":6},{"critere":"Chute expliquée : retournement final qui accuse la vanité et l'apparence","points":6},{"critere":"Deux détails matériels pertinents relevés et interprétés","points":4},{"critere":"Narrateur qui montre sans expliquer, ironie froide","points":4}],"dureeMin":12,"corrige":"**1.** La phrase **b** : les questions et l'exclamation (« Comment irait-elle à ce bal… ? Elle serait la plus pauvre de toutes ! ») sont les **pensées de Mathilde** fondues dans le récit, à la troisième personne, **sans guillemets ni verbe introducteur**. La phrase a est au discours **direct** (verbe « pensa » et guillemets) ; la phrase c au discours **indirect** (verbe introducteur « se dit » et subordonnée « qu'elle n'avait rien… »).\n\n**2.** La fin est une **chute** : un **retournement final** qui éclaire tout le récit — dix ans de misère ont été payés pour un bijou **faux**. Elle ne surprend pas seulement, elle **accuse** : la **vanité** et le culte de l'**apparence** (Mathilde a tout sacrifié pour paraître ; Mme Forestier, elle, portait un faux sans que personne le voie).\n\n**3.** Détails possibles : « petit employé de ministère » ; la parure **empruntée** ; « trente-six mille francs » de dettes ; « lave le linge, marchande chaque sou » ; « cinq cents francs ». Chez Maupassant, une robe, une pièce de monnaie disent la **place sociale**.\n\n**4.** Le narrateur **montre sans expliquer** : il ne commente pas, il livre les faits et la réplique finale ; l'**ironie froide** laisse les personnages se condamner eux-mêmes, et **le lecteur juge**."}$exo$::jsonb),
  ('30417519-e1db-5a1c-a8ec-25d7f3771ef0'::uuid, 3, 'redaction', $exo${"titre":"Choisir, c'est déjà juger","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des exemples précis.","enonce":"**Sujet.** « Le réalisme ne se contente pas de décrire : il choisit ce qu'il décrit, et ce choix est déjà un jugement. »\n\nMontre la justesse de cette affirmation à partir des nouvelles de Maupassant. Tu t'appuieras :\n- sur les **outils** du réalisme (documentation, détail vrai, discours indirect libre) ;\n- sur au moins **deux nouvelles** et leur cible ;\n- sur les **procédés** par lesquels Maupassant accuse sans commenter ;\n- et tu situeras Maupassant par rapport au **naturalisme**.","bareme":[{"critere":"Outils du réalisme expliqués (documentation, détail vrai qui fait croire au reste, discours indirect libre)","points":4},{"critere":"Deux nouvelles exactement reliées à leur cible (Boule de suif, La Parure, Aux champs, Mon oncle Jules)","points":5},{"critere":"Procédés : narrateur qui montre, ironie froide, descriptions brèves mais orientées, chute","points":5},{"critere":"Réalisme / naturalisme situés justement","points":3},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **Les outils** : la **documentation** (Zola visite des mines, Flaubert lit des traités), le **détail vrai** qui fait croire au reste, le **discours indirect libre** qui fait entendre les pensées d'un personnage de l'intérieur. Choisir les métiers, l'argent, les corps plutôt que l'idéal, c'est déjà prendre parti.\n- **Les nouvelles et leurs cibles** (deux au moins) :\n  - « **Boule de suif** » : la **hiérarchie sociale** et le mépris — des notables sacrifient une prostituée, puis la méprisent ; leur hypocrisie et leur lâcheté sont exposées.\n  - « **La Parure** » : la **vanité** et l'apparence — dix ans de misère pour rembourser un bijou faux.\n  - « **Aux champs** », « **Mon oncle Jules** » : l'**hypocrisie** familiale et l'**argent**.\n  - Plusieurs récits sur la **guerre de 1870** et ses lâchetés.\n- **Les procédés** : un narrateur qui **montre sans expliquer** (le lecteur juge), une **ironie froide** (les personnages se condamnent par leurs paroles), des **descriptions brèves mais orientées** (une robe, une pièce de monnaie, une soupe disent la place sociale), la **chute** qui ne surprend pas seulement mais **accuse**.\n- **Réalisme / naturalisme** : le naturalisme fait du personnage le **produit** de son hérédité et de son milieu ; Maupassant reste **plus proche du réalisme** : il accuse la société **sans se réclamer d'une science**.\n\n**Conclusion** : le choix du détail est un jugement silencieux."}$exo$::jsonb),
  ('f6d6fbe4-1685-5f4f-903b-d158ed5f55ea'::uuid, 1, 'redaction', $exo${"titre":"L'Étranger en quelques repères","consigne":"Réponds en phrases complètes.","enonce":"1. Quand paraît *L'Étranger* ? Qui est le narrateur, et où vit-il ?\n2. Résume l'histoire en quatre étapes.\n3. Quel temps domine le récit, et quel effet produit-il ?\n4. Dans quel « cycle » Camus range-t-il ce roman ? Cite les deux autres œuvres du cycle et leur genre.","bareme":[{"critere":"1942, Meursault, employé à Alger, récit à la première personne","points":4},{"critere":"Quatre étapes : mort et enterrement de la mère, liaison avec Marie, meurtre sur la plage, procès et condamnation à mort","points":6},{"critere":"Passé composé : les faits arrivent comme des constats","points":4},{"critere":"Cycle de l'absurde : Le Mythe de Sisyphe (essai), Caligula (théâtre)","points":6}],"dureeMin":7,"corrige":"**1.** *L'Étranger* paraît en **1942**. Le narrateur est **Meursault**, **employé à Alger**, qui raconte à la **première personne**.\n\n**2.** 1) La **mort de sa mère** et l'enterrement ; 2) une **liaison avec Marie**, une vie ordinaire ; 3) un **meurtre** sur une plage, sous un soleil écrasant ; 4) le **procès** et la **condamnation à mort**.\n\n**3.** Le **passé composé** domine : les faits arrivent **comme des constats**, sans lien ni interprétation.\n\n**4.** Le **cycle de l'absurde** : *L'Étranger* (roman), *Le Mythe de Sisyphe* (**essai**), *Caligula* (**théâtre**)."}$exo$::jsonb),
  ('f6d6fbe4-1685-5f4f-903b-d158ed5f55ea'::uuid, 2, 'redaction', $exo${"titre":"« Aujourd'hui, maman est morte »","consigne":"Lis l'incipit, puis réponds aux questions en citant le texte.","enonce":"> Aujourd'hui, maman est morte. Ou peut-être hier, je ne sais pas. J'ai reçu un télégramme de l'asile : « Mère décédée. Enterrement demain. Sentiments distingués. » Cela ne veut rien dire. C'était peut-être hier.\n>\n> — Albert Camus, *L'Étranger*, 1942\n\n1. Relève les marques de la **première personne** et le temps dominant. Quel effet produit ce temps ?\n2. Caractérise les **phrases** (longueur, construction, images). Pourquoi parle-t-on de **voix blanche** ?\n3. Qu'est-ce qui peut **choquer** le lecteur dans ce début ? Relève deux passages.\n4. Montre que ce début annonce ce qu'on reprochera à Meursault lors de son procès.","bareme":[{"critere":"Première personne et passé composé relevés ; effet : des constats","points":4},{"critere":"Phrases courtes, juxtaposées, sans subordination complexe ni image : voix blanche expliquée","points":6},{"critere":"Deux passages choquants relevés et commentés (incertitude sur la date, « Cela ne veut rien dire »)","points":5},{"critere":"Lien avec le procès : l'écart avec les rituels sociaux est jugé","points":5}],"dureeMin":12,"corrige":"**1.** « je ne sais pas », « J'ai reçu » : récit à la **première personne**. Temps dominant : le **passé composé** (« est morte », « J'ai reçu »). Les faits sont posés **comme des constats**, sans lien logique.\n\n**2.** Phrases **courtes**, **juxtaposées**, **aucune subordination complexe**, **aucune image** ; le télégramme lui-même est fait de mots secs. C'est la **voix blanche** : une écriture neutre, sans effets ni explications ; le narrateur dit tout et n'explique rien, ce qui produit un **malaise**.\n\n**3.** Le lecteur peut être choqué par : l'**incertitude sur la date** de la mort (« Ou peut-être hier, je ne sais pas », répétée : « C'était peut-être hier ») ; la **neutralité** face au deuil (aucune émotion exprimée) ; « **Cela ne veut rien dire** » (le télégramme, et même la mort, semblent vides de sens). Le mot tendre « maman » contraste avec l'absence de chagrin exprimé.\n\n**4.** Au procès, on reprochera à Meursault de **n'avoir pas pleuré** à l'enterrement, d'avoir « enterré sa mère avec un cœur de criminel ». Ce début montre déjà un homme qui **ne joue pas le jeu** des rituels sociaux du deuil. Ce n'est pas l'acte qui sera jugé, c'est l'**écart**."}$exo$::jsonb),
  ('f6d6fbe4-1685-5f4f-903b-d158ed5f55ea'::uuid, 3, 'redaction', $exo${"titre":"La fabrication d'une culpabilité","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur le roman et le cours.","enonce":"**Sujet.** « Ce n'est pas l'acte qui est jugé, c'est l'écart. La société ne pardonne pas qu'on refuse ses rituels. »\n\nExplique cette affirmation à propos de *L'Étranger*. Tu montreras :\n- ce que Meursault **ne fait pas** et ce qu'on lui reproche ;\n- comment la **structure en deux parties** démonte la fabrication d'une culpabilité ;\n- le lien avec la pensée de l'**absurde** et de la **révolte** chez Camus ;\n- en quoi l'œuvre est « à part » (sa langue, son héros, sa place, les débats qu'elle suscite).","bareme":[{"critere":"Ce que Meursault refuse (pleurer, mentir, se justifier) et les reproches correspondants","points":5},{"critere":"Deux parties : vie ordinaire puis procès qui relit et déforme les mêmes faits","points":5},{"critere":"Absurde (besoin de sens / silence du monde) et révolte (vivre lucidement) expliqués","points":4},{"critere":"Œuvre à part : langue, héros, rayonnement, débat sur l'Arabe sans nom","points":3},{"critere":"Organisation et expression","points":3}],"dureeMin":20,"corrige":"**Éléments attendus.**\n\n- **Ce que Meursault ne fait pas** : il ne **pleure pas** à l'enterrement de sa mère ; il refuse de **mentir**, de dire qu'il aime ; il refuse de **se justifier**. On lui reproche d'avoir « enterré sa mère avec un cœur de criminel », de ne pas se conformer, de refuser le rituel du procès. Le meurtre compte moins que cet **écart** : la société ne pardonne pas qu'on refuse ses rituels.\n- **Deux parties, deux temps** : la **première** suit une vie ordinaire jusqu'au meurtre ; la **seconde** — prison et procès — **relit ces mêmes faits** et les **déforme**. Racontés par d'autres, ils deviennent des **preuves de monstruosité**. Le roman démonte ainsi la **fabrication d'une culpabilité**.\n- **L'absurde** : il naît de la rencontre entre le **besoin humain de sens** et le **silence du monde**. Meursault ne donne pas de sens à ce qui n'en a pas ; la société, elle, a besoin d'un récit cohérent (un monstre) et le fabrique. La **révolte**, chez Camus, consiste à **vivre lucidement sans se raconter d'histoires**.\n- **Une œuvre à part** : par sa **langue** (voix blanche, passé composé), par son **héros** qui ne joue pas le jeu, par sa **place** (traduit dans le monde entier, l'un des romans français les plus lus) — et l'un des plus **discutés**, notamment pour la figure **sans nom de l'Arabe** tué sur la plage.\n\n**Conclusion** : le roman juge ceux qui jugent."}$exo$::jsonb),
  ('eabe54e2-2c91-5cfe-92c4-0244319af538'::uuid, 1, 'redaction', $exo${"titre":"Le pacte et ses voisins","consigne":"Réponds en phrases complètes.","enonce":"1. Définis l'**autobiographie** et le **pacte autobiographique**. Qui l'a formulé ?\n2. Nomme le genre correspondant à chaque description :\n   - a) il s'écrit au jour le jour, sans recul ;\n   - b) il raconte une époque à travers un témoin ;\n   - c) il part des parents ou grands-parents pour se comprendre soi ;\n   - d) il assume de mêler autobiographie et fiction ;\n   - e) la fiction y sert de paravent.\n3. Donne deux motifs pour lesquels on s'écrit, avec un auteur pour chacun.","bareme":[{"critere":"Récit rétrospectif d'une personne réelle ; pacte : auteur = narrateur = personnage ; Philippe Lejeune","points":6},{"critere":"Cinq genres justes (journal intime, Mémoires, récit de filiation, autofiction, roman autobiographique)","points":8},{"critere":"Deux motifs avec auteur juste (se justifier : Rousseau ; témoigner : Primo Levi ; parcours social : Ernaux)","points":6}],"dureeMin":7,"corrige":"**1.** L'**autobiographie** est le **récit rétrospectif** qu'une **personne réelle** fait de sa propre existence, en mettant l'accent sur sa vie individuelle. Le **pacte autobiographique**, formulé par **Philippe Lejeune** : l'**auteur**, le **narrateur** et le **personnage** sont **la même personne**.\n\n**2.** a) le **journal intime** ; b) les **Mémoires** ; c) le **récit de filiation** ; d) l'**autofiction** ; e) le **roman autobiographique**.\n\n**3.** Deux au choix : **se justifier** — **Rousseau**, *Les Confessions* (1782) ; **témoigner** — **Primo Levi** (récits de déportation) ; comprendre son **parcours social** — **Annie Ernaux** ; garder une **mémoire menacée** — récits de familles, de langues, de métiers disparus."}$exo$::jsonb),
  ('eabe54e2-2c91-5cfe-92c4-0244319af538'::uuid, 2, 'redaction', $exo${"titre":"Deux « je » dans une cuisine","consigne":"Lis l'extrait, puis réponds aux questions en citant le texte.","enonce":"Extrait écrit pour ce contrôle, à la manière d'un récit autobiographique :\n\n> Le dimanche, ma grand-mère faisait des crêpes dans la petite cuisine de la rue des Tanneurs. Je m'asseyais sur le tabouret rouge et j'attendais la première, toujours ratée, qu'elle me donnait en riant. J'ai compris bien plus tard qu'elle n'avait jamais appris à lire, et que ces dimanches étaient sa manière à elle de me transmettre quelque chose. Aujourd'hui encore, quand je sens l'odeur du beurre chaud, je revois ses mains farinées.\n\n1. Montre que deux **« je »** cohabitent dans cet extrait. Cite une phrase pour chacun.\n2. Relève les trois **temps verbaux** dominants et donne la valeur de chacun, selon le cours.\n3. Quel **cadre** l'auteur choisit-il pour raconter son enfance ? Quelle **distance** adopte-t-il (ironie, tendresse, froideur) ?\n4. De quel genre voisin ce texte se rapproche-t-il aussi ? Justifie.","bareme":[{"critere":"Le je qui a vécu et le je qui écrit distingués et cités (« J'ai compris bien plus tard »)","points":6},{"critere":"Imparfait de l'habitude, passé composé du bilan, présent qui rapproche","points":6},{"critere":"Cadre (la cuisine, le tabouret) et distance tendre justifiés","points":4},{"critere":"Récit de filiation reconnu et justifié","points":4}],"dureeMin":12,"corrige":"**1.** Le **« je » qui a vécu**, l'enfant : « Je m'asseyais sur le tabouret rouge et j'attendais la première ». Le **« je » qui écrit**, l'adulte : « J'ai compris bien plus tard qu'elle n'avait jamais appris à lire » — **le second sait ce que le premier ignorait**.\n\n**2.**\n- **Imparfait** (« faisait », « m'asseyais », « attendais », « donnait ») : **l'habitude**, les dimanches répétés.\n- **Passé composé** (« J'ai compris ») : le **bilan**, la découverte de l'adulte.\n- **Présent** (« Aujourd'hui encore, quand je sens… je revois ») : il **rapproche** le passé du moment de l'écriture.\n\n**3.** Le **cadre** : une **maison**, la petite cuisine de la rue des Tanneurs, avec un **objet** (le tabouret rouge). La **distance** est **tendre** : le rire de la grand-mère, la crêpe ratée offerte, les « mains farinées ».\n\n**4.** Il se rapproche du **récit de filiation** : il part d'une **grand-mère** pour se comprendre soi (ce qu'elle lui a transmis). On peut aussi évoquer la **mémoire menacée** d'une personne qui ne savait pas lire."}$exo$::jsonb),
  ('eabe54e2-2c91-5cfe-92c4-0244319af538'::uuid, 3, 'redaction', $exo${"titre":"La sincérité n'est pas la vérité","consigne":"Lis la citation, puis rédige un paragraphe argumenté d'une vingtaine de lignes.","enonce":"> « Je forme une entreprise qui n'eut jamais d'exemple, et dont l'exécution n'aura point d'imitateur. »\n>\n> — Jean-Jacques Rousseau, *Les Confessions* (1782)\n\n**Sujet.** Rousseau promet de tout dire. Pourtant, « la sincérité n'est pas la vérité ». Explique pourquoi un récit autobiographique ne peut jamais être une vérité parfaite, en t'appuyant sur les **trois problèmes** de l'écriture de soi. Tu termineras en expliquant **comment lire** une autobiographie, et tu illustreras par un exemple (Rousseau, Primo Levi ou Annie Ernaux).","bareme":[{"critere":"Ambition de Rousseau expliquée : tout dire, se justifier","points":3},{"critere":"Trois problèmes expliqués : le temps (deux je), la mémoire (trie, déforme), la sincérité (on se raconte devant quelqu'un)","points":7},{"critere":"Méthode de lecture : ce qu'elle choisit, ce qu'elle tait, pour qui elle est écrite ; ni tout croire ni la réduire à un document","points":4},{"critere":"Un exemple juste et exploité (Ernaux : écriture plate, choix politique ; Levi : témoigner)","points":3},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **L'ambition** : Rousseau ouvre *Les Confessions* en promettant de **tout dire** ; il présente son entreprise comme unique. Son motif : **se justifier**.\n- **Trois problèmes** :\n  - le **temps** : deux « je » cohabitent, celui qui vécut et celui qui écrit ; le second **sait ce que le premier ignorait** et relit sa vie à la lumière de la suite ;\n  - la **mémoire** : elle **trie, déforme, invente sans le vouloir** ;\n  - la **sincérité** : elle **n'est pas la vérité** — **on ne se raconte jamais devant personne** : on écrit pour un lecteur, qu'on veut convaincre, émouvoir ou dont on veut être absous.\n- **Comment lire** : **ne pas croire tout** ce que dit le texte, **ne pas le réduire à un document** ; chercher ce qu'il **choisit** de raconter, ce qu'il **tait**, et **pour qui** il est écrit.\n- **Exemple** : Annie Ernaux écrit dans une langue **volontairement plate**, sans effets, pour ne pas trahir le milieu dont elle vient : un choix **politique autant qu'esthétique**, qui montre que la forme même du récit de soi est une décision. Ou Primo Levi : **témoigner** de la déportation, où l'enjeu est la vérité collective.\n\n**Conclusion** : l'autobiographie dit vrai sur un regard, pas sur les faits seuls."}$exo$::jsonb),
  ('be439e77-0226-5502-80f3-2138e6b1cc4c'::uuid, 1, 'redaction', $exo${"titre":"Du Neuhof à la scène","consigne":"Réponds en phrases complètes.","enonce":"1. Qui est Abd Al Malik ? Quand paraît *Qu'Allah bénisse la France* et de quel genre de récit s'agit-il ?\n2. Dans quelle ville et quel quartier a-t-il grandi ?\n3. Donne, dans l'ordre du cours, les **étapes** de sa trajectoire.\n4. Qu'est-ce qu'un **récit de transfuge** ?","bareme":[{"critere":"Rappeur né Régis Fayette-Mikano en 1975 ; 2004 ; récit autobiographique","points":5},{"critere":"Strasbourg, quartier du Neuhof","points":3},{"critere":"Étapes : famille congolaise et précarité, école, délinquance, rap, conversion et islam soufi","points":7},{"critere":"Transfuge : on change de monde social sans jamais en changer tout à fait","points":5}],"dureeMin":7,"corrige":"**1.** Abd Al Malik, né **Régis Fayette-Mikano** en **1975**, est un **rappeur**. Il publie en **2004** *Qu'Allah bénisse la France*, **récit autobiographique** de son enfance.\n\n**2.** À **Strasbourg**, dans le quartier du **Neuhof**.\n\n**3.** Une **famille congolaise** et la **précarité** (le point de départ) ; l'**école**, où il réussit (une porte) ; la **délinquance**, en parallèle (l'autre chemin) ; la découverte du **rap** (une langue à soi) ; la **conversion**, puis le choix d'un **islam soufi** de paix (une discipline intérieure). Le héros n'est pas exemplaire d'avance : il **devient** ce qu'il raconte.\n\n**4.** Un **récit de transfuge** est le récit de quelqu'un qui **change de monde social** et découvre **qu'on n'en change jamais tout à fait** : il en garde la trace et la dette (envers sa mère, un frère, un professeur, un quartier)."}$exo$::jsonb),
  ('be439e77-0226-5502-80f3-2138e6b1cc4c'::uuid, 2, 'redaction', $exo${"titre":"Un titre et une langue mêlée","consigne":"Réponds aux questions en t'appuyant sur le cours et sur les phrases proposées.","enonce":"**Phrases écrites pour ce contrôle, à la manière d'un récit de quartier :**\n\n- a) Ce soir-là, ma mère est rentrée tard de l'usine, et elle a posé son sac sans rien dire.\n- b) En bas de la tour, les grands tenaient les murs, et ça tchatchait sec.\n- c) Chaque prière me lavait un peu de la colère accumulée.\n- d) J'avais lu Camus en cachette, comme on lit une lettre qui ne vous est pas adressée.\n\n1. Identifie le **registre** de chaque phrase (français courant, argot du quartier, référence religieuse, référence littéraire) et ce qu'il apporte au récit, selon le cours.\n2. Pourquoi le titre *Qu'Allah bénisse la France* est-il une **provocation calculée** ? Que cherche à montrer le livre ?\n3. Expliquer la phrase du cours : « Cette langue composite est le sujet même du livre. »","bareme":[{"critere":"Quatre registres justement identifiés","points":6},{"critere":"Apport de chaque registre (narration, voix réelle, quête intérieure, appropriation d'un héritage)","points":4},{"critere":"Titre : deux mots tenus pour incompatibles, le livre montre qu'ils ne le sont pas","points":5},{"critere":"Langue composite : une identité peut être plusieurs choses à la fois","points":5}],"dureeMin":12,"corrige":"**1.**\n- a) **Français courant** : la **narration**.\n- b) **Argot du quartier** (« tenaient les murs », « ça tchatchait ») : la **voix réelle** du quartier.\n- c) **Référence religieuse** (la prière) : la **quête intérieure**.\n- d) **Référence littéraire** (Camus) : l'**appropriation d'un héritage** — la lettre « qui ne vous est pas adressée » dit bien une culture qu'on fait sienne.\n\n**2.** Le titre **accole deux mots que le débat public tient pour incompatibles** (« Allah » et « la France »). C'est une provocation **calculée** : le livre entier **travaille à montrer qu'ils ne le sont pas**, qu'on peut être musulman et français, venu du Neuhof et héritier de la culture française.\n\n**3.** Le récit mêle français courant, argot et verlan, références religieuses et littéraires. Cette langue composite **prouve**, par sa forme même, ce que le livre affirme : **une identité peut être plusieurs choses à la fois**. La forme est l'argument."}$exo$::jsonb),
  ('be439e77-0226-5502-80f3-2138e6b1cc4c'::uuid, 3, 'redaction', $exo${"titre":"Fait divers, statistique ou récit ?","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur le cours.","enonce":"**Sujet.** « Un même parcours peut être raconté comme fait divers, comme statistique ou comme récit à la première personne — et le récit est le seul des trois à rendre au sujet le droit de se définir lui-même. »\n\nÀ partir de *Qu'Allah bénisse la France*, explique cette affirmation. Tu montreras :\n- ce que le fait divers et la statistique feraient du parcours de l'auteur ;\n- les **deux discours** sur le quartier que le livre refuse, et pourquoi ;\n- ce que le livre **défend** ;\n- en quoi la **trajectoire** racontée échappe aux deux caricatures.","bareme":[{"critere":"Fait divers et statistique réduisent la personne (un délinquant, un chiffre) ; le récit rend la parole","points":5},{"critere":"Deux discours refusés : décor de misère (nie les personnes) et quartier idéalisé (nie les difficultés)","points":4},{"critere":"Ce que le livre défend : éducation, spiritualité, parole","points":4},{"critere":"La trajectoire (école et délinquance simultanées, rap, conversion, dette) échappe aux caricatures","points":4},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **Fait divers et statistique** : le fait divers ne retiendrait que la **délinquance** ; la statistique ferait de l'auteur un chiffre (précarité, quartier). Les deux parlent **à la place** de la personne. Le **récit à la première personne** lui rend le **droit de se définir lui-même**.\n- **Deux discours refusés** : le quartier comme **décor de misère**, qui **nie les personnes** ; le quartier **idéalisé**, qui **nie les difficultés**. Le livre ne fait ni l'un ni l'autre.\n- **Ce qu'il défend** : l'**éducation** (une issue réelle), la **spiritualité** (un travail sur soi), la **parole** (un moyen d'exister).\n- **La trajectoire** : une famille congolaise dans la précarité, l'**école** où il réussit **et**, en même temps, la **délinquance** ; puis le **rap**, une langue à soi ; la **conversion** puis un islam soufi de paix. Le héros n'est pas exemplaire d'avance : il **devient** ce qu'il raconte. C'est un **récit de transfuge** : la réussite n'efface pas le point de départ, le narrateur revient sur ce qu'il **doit** (à sa mère, à un frère, à un professeur, à un quartier). Aucune case ne le contient.\n- Prolongements : un album, puis un **film** réalisé en **2014**.\n\n**Conclusion** : raconter, c'est reprendre la définition de soi aux autres."}$exo$::jsonb),
  ('ddd36c06-79ee-5afe-9c04-f57c9b28c204'::uuid, 1, 'redaction', $exo${"titre":"La ville qui classe","consigne":"Réponds en phrases complètes.","enonce":"1. Pourquoi peut-on dire que, dans un récit, la ville « n'est pas un décor » ?\n2. Associe chaque auteur du XIXe siècle à ce qu'il met en scène : Balzac · Hugo · Zola — a) les égouts et les barricades ; b) la pension Vauquer contre le faubourg Saint-Germain ; c) les Halles, le grand magasin, le quartier ouvrier.\n3. Qu'est-ce qu'une **métonymie** ? Donne l'exemple du cours.\n4. Quels nouveaux espaces le récit explore-t-il au XXe siècle ?","bareme":[{"critere":"La ville classe les personnages ; la description est un outil d'analyse sociale","points":5},{"critere":"Trois associations justes (Balzac b, Hugo a, Zola c)","points":6},{"critere":"Métonymie définie avec « la cité » pour ses habitants","points":4},{"critere":"Banlieues, grands ensembles, périphéries, marges (cité, zone, usine, gare)","points":5}],"dureeMin":7,"corrige":"**1.** Dans le récit, la ville **classe les personnages** : dire où quelqu'un habite, c'est déjà dire **ce qu'il peut espérer**. La **description** est un **outil d'analyse sociale** : le mobilier, l'odeur, la lumière disent un revenu et une trajectoire.\n\n**2.** **Balzac** : b) la pension Vauquer contre le faubourg Saint-Germain. **Hugo** : a) les égouts, les barricades des *Misérables*. **Zola** : c) les Halles, le grand magasin, le quartier ouvrier.\n\n**3.** La **métonymie** désigne un ensemble par l'un de ses éléments ou par ce qui lui est lié : « **la cité** » pour **ses habitants**.\n\n**4.** Au XXe siècle, la ville se dilate : **banlieues**, **grands ensembles**, **périphéries** ; le récit cherche les **marges** — la cité, la zone, l'usine, la gare — et ceux qui les habitent. La littérature ouvrière puis les écritures issues de l'immigration entrent dans le roman."}$exo$::jsonb),
  ('ddd36c06-79ee-5afe-9c04-f57c9b28c204'::uuid, 2, 'redaction', $exo${"titre":"Une cité, deux regards","consigne":"Compare les deux textes en répondant aux questions, avec des citations.","enonce":"Textes écrits pour ce contrôle :\n\n> **Texte A.** Depuis l'autoroute, on aperçoit les tours grises des Peupliers, alignées comme des dominos. Derrière les vitres de la voiture, tout paraît immobile, lointain, un peu inquiétant : des balcons encombrés, des silhouettes au pied des immeubles. On accélère.\n\n> **Texte B.** Moi, les Peupliers, je connais chaque cage d'escalier. Au quatrième, y a Mme Diallo qui fait sécher ses piments sur la rambarde. En bas, Karim répare les scooters, et quand il pleut, on se serre sous l'auvent du tabac en attendant le bus pour le centre-ville.\n\n1. Quelle est la **focalisation** de chaque texte ? D'où voit-on la cité ?\n2. Relève le **champ lexical** de l'espace dans chaque texte. Que révèle-t-il ?\n3. Relève une marque d'**oralité** dans le texte B et explique son effet.\n4. Relève l'**opposition centre / périphérie** et dis quelle hiérarchie elle suggère.\n5. Quel sentiment chaque texte produit-il chez le lecteur ? Pourquoi dit-on que la question **« qui parle ? »** est décisive ?","bareme":[{"critere":"Focalisations comparées : de l'extérieur, depuis une voiture qui passe / de l'intérieur","points":5},{"critere":"Champs lexicaux relevés et interprétés ; oralité relevée (« y a », « Moi ») et effet","points":6},{"critere":"Opposition centre / périphérie identifiée (autoroute, bus pour le centre-ville)","points":3},{"critere":"Effets comparés (distance et peur / proximité et sympathie) et enjeu de « qui parle »","points":6}],"dureeMin":12,"corrige":"**1.** **Texte A** : la cité est vue **de l'extérieur**, **depuis une voiture qui passe** (« Depuis l'autoroute », « Derrière les vitres de la voiture »). **Texte B** : elle est vue **de l'intérieur**, par un habitant qui dit « je » et « on ».\n\n**2.** A : « tours grises », « alignées comme des dominos », « balcons encombrés », « pied des immeubles » — un espace **anonyme**, uniforme. B : « cage d'escalier », « quatrième », « rambarde », « auvent du tabac » — un espace **habité**, précis, peuplé de noms (Mme Diallo, Karim).\n\n**3.** « **y a** » (au lieu de « il y a »), « **Moi**, les Peupliers » : le **discours oral** fait **entendre une langue réelle** et rend la parole à l'habitant.\n\n**4.** A : la cité est au bord de l'**autoroute**, en périphérie, qu'on traverse sans s'arrêter. B : on attend « le bus pour le **centre-ville** ». L'opposition suggère une **hiérarchie spatiale** : le centre est ailleurs, la cité à la marge.\n\n**5.** A produit de la **distance** et une légère **peur** (« un peu inquiétant », « On accélère ») : décrire la cité comme un paysage exotique, c'est la **mettre à distance**. B produit de la **sympathie**, de la familiarité. La question **« qui parle ? »** est décisive parce qu'une représentation n'est **jamais neutre** : le point de vue fabrique la sympathie, la peur ou l'indifférence."}$exo$::jsonb),
  ('ddd36c06-79ee-5afe-9c04-f57c9b28c204'::uuid, 3, 'redaction', $exo${"titre":"Une représentation n'est jamais neutre","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des exemples précis.","enonce":"**Sujet.** « Une représentation n'est jamais neutre : elle produit de la sympathie, de la peur ou de l'indifférence. Étudier les écritures urbaines, c'est apprendre à lire les images sociales qu'on nous propose — et à se demander qui les fabrique. »\n\nExplique et illustre cette affirmation en parcourant les trois siècles du cours (XIXe, XXe, XXIe) et en t'appuyant sur au moins **trois procédés** à repérer dans un texte.","bareme":[{"critere":"XIXe : description comme analyse sociale ; Balzac, Hugo ou Zola avec exemple juste","points":4},{"critere":"XXe : dilatation de la ville, marges, littérature ouvrière et de l'immigration ; risque de l'exotisme","points":4},{"critere":"XXIe : récits de l'intérieur, enquêtes, rap, slam, séries, documentaires","points":3},{"critere":"Trois procédés expliqués (champ lexical, métonymie, opposition centre/périphérie, focalisation, oralité)","points":6},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **XIXe siècle** : la ville **classe les personnages**. Balzac oppose la **pension Vauquer** au **faubourg Saint-Germain** ; Hugo peint les **égouts** et les **barricades** des *Misérables* ; Zola les **Halles**, le **grand magasin**, le **quartier ouvrier**. La **description** est un outil d'analyse sociale : le mobilier, l'odeur, la lumière disent un revenu et une trajectoire.\n- **XXe siècle** : la ville se dilate — **banlieues**, **grands ensembles**, **périphéries** ; le récit cherche les **marges** (cité, zone, usine, gare). La **littérature ouvrière**, puis les écritures issues de l'**immigration**, entrent dans le roman. Mais décrire une cité comme un **paysage exotique**, c'est déjà la **mettre à distance**.\n- **XXIe siècle** : récits écrits **de l'intérieur** par des auteurs venus des quartiers populaires, récits d'**enquête** nourris de terrain, formes venues d'ailleurs (**rap**, **slam**, **séries**, **documentaires**).\n- **Procédés** (trois au moins) : le **champ lexical** de l'espace (béton, cage d'escalier, périph) ; la **métonymie** (« la cité » pour ses habitants) qui peut effacer les individus ; l'**opposition centre / périphérie**, qui construit une hiérarchie ; la **focalisation** (de l'intérieur ou depuis une voiture qui passe) ; l'**oralité** (discours direct, argot) qui fait entendre une langue réelle.\n\n**Conclusion** : toute image de la ville est fabriquée par quelqu'un ; la lire, c'est se demander **qui parle**."}$exo$::jsonb),
  ('e2ab6e85-5aef-581c-8bc2-33a954612de7'::uuid, 1, 'redaction', $exo${"titre":"Vérone, deux familles","consigne":"Réponds en phrases complètes.","enonce":"1. Quand *Roméo et Juliette* est-elle écrite ? Où se passe l'action ? Quelles sont les deux familles ennemies ?\n2. Que révèle le **prologue** ? Qui le dit ?\n3. Qu'est-ce que l'**ironie tragique** dans cette pièce ?\n4. Cite les **trois obstacles** qui rendent l'amour impossible.","bareme":[{"critere":"Vers 1595, Vérone, Montaigu et Capulet","points":5},{"critere":"Prologue dit par un chœur, il révèle que les amants mourront","points":4},{"critere":"Ironie tragique : le spectateur sait la fin, chaque scène en rapproche","points":5},{"critere":"Haine héritée, ordre patriarcal, hasard","points":6}],"dureeMin":7,"corrige":"**1.** Écrite **vers 1595**, la pièce se passe à **Vérone**. Les familles ennemies sont les **Montaigu** et les **Capulet**.\n\n**2.** Le **prologue**, dit par un **chœur**, révèle dès l'ouverture que **les amants mourront**.\n\n**3.** Le spectateur **sait déjà** ce qui va se passer ; il regarde **comment** cela devient inévitable. Chaque scène rapproche d'une fin déjà connue : c'est l'**ironie tragique**.\n\n**4.** La **haine héritée** entre Montaigu et Capulet (personne n'en connaît plus l'origine) ; l'**ordre patriarcal** (Juliette est destinée à Pâris sans qu'on lui demande son avis) ; le **hasard** (un message qui n'arrive pas, un réveil trop tardif)."}$exo$::jsonb),
  ('e2ab6e85-5aef-581c-8bc2-33a954612de7'::uuid, 2, 'redaction', $exo${"titre":"Un théâtre libre","consigne":"Réponds aux questions en justifiant avec le vocabulaire du cours.","enonce":"**Situation.** Le club théâtre du lycée prépare *Roméo et Juliette*. Nora, la metteuse en scène, reçoit trois remarques :\n\n- **Élise** : « La pièce dure plusieurs jours et change sans cesse de lieu : un professeur de 1660 aurait crié au scandale. »\n- **Hugo** : « La nourrice et Mercutio font rire le public, alors que la pièce finit par deux morts. Ce n'est pas cohérent. »\n- **Sami** : « Tout se joue sur un message qui n'arrive pas. C'est un accident, pas une tragédie. »\n\n1. Élise a raison sur les faits : quelles **règles** classiques françaises Shakespeare ignore-t-il ? Donne-les avec ce qu'il fait à la place.\n2. Réponds à Hugo : pourquoi ce **mélange** n'est-il pas une incohérence ? Qui reprendra ce modèle ?\n3. Réponds à Sami en expliquant comment la **fatalité** passe, chez Shakespeare, par des détails ordinaires.","bareme":[{"critere":"Règles ignorées : unités de temps et de lieu, séparation des genres, unité de style, avec ce que fait Shakespeare","points":8},{"critere":"Mélange comique / tragique justifié ; modèle repris par les romantiques","points":6},{"critere":"Fatalité par le hasard et les détails ordinaires, dans une fin annoncée par le prologue","points":6}],"dureeMin":12,"corrige":"**1.**\n- **Unité de temps** : l'action dure **plusieurs jours**.\n- **Unité de lieu** : elle **change de lieu**.\n- **Séparation des genres** : il mêle **comique** (la nourrice, Mercutio) et **tragique**.\n- **Unité de style** : il mêle **la prose et le vers**, **les nobles et les valets**.\n\n**2.** Le mélange est un **choix** : il donne une image plus complète de la vie, où le rire côtoie la mort, et rend la chute plus brutale. Cette liberté, **condamnée par les classiques**, deviendra **le modèle des romantiques**.\n\n**3.** Chez Shakespeare, **la fatalité passe par des détails ordinaires** : un message qui n'arrive pas à temps, un réveil trop tardif. Le hasard n'est pas un simple accident : il s'ajoute à la **haine héritée** et à l'**ordre patriarcal**, et le **prologue** a annoncé la mort des amants. Le spectateur voit comment tout **devient inévitable** : c'est l'**ironie tragique**."}$exo$::jsonb),
  ('e2ab6e85-5aef-581c-8bc2-33a954612de7'::uuid, 3, 'redaction', $exo${"titre":"Deux camps et une frontière","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur la pièce et le cours.","enonce":"**Sujet.** « La pièce fonctionne partout où existent deux camps et une frontière. »\n\nExplique pourquoi *Roméo et Juliette* est sans cesse rejouée et adaptée. Tu montreras :\n- en quoi **aimer devient un acte politique** dans la pièce ;\n- comment la **langue d'images** des amants s'oppose au monde qui les entoure (au moins deux réseaux d'images) ;\n- ce que font les **adaptations** (au moins deux exemples) ;\n- et tu discuteras : est-ce l'amour ou la haine qui fait l'universalité de la pièce ?","bareme":[{"critere":"Aimer = choisir l'autre camp, trahir le sien ; haine héritée et ordre patriarcal","points":5},{"critere":"Deux réseaux d'images analysés (lumière et nuit, poison et remède, faucon et oiseau) et sonnet partagé","points":5},{"critere":"Adaptations exactes (West Side Story, ballets, opéras, films, cité, camp de réfugiés, réseau social)","points":3},{"critere":"Discussion nuancée sur la source de l'universalité","points":4},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **Aimer, un acte politique** : la **haine héritée** entre Montaigu et Capulet fait de l'amour une transgression ; **choisir l'autre camp, c'est trahir le sien**. L'**ordre patriarcal** ajoute un obstacle : Juliette est destinée à Pâris sans qu'on lui demande son avis.\n- **Une langue d'images** : **la lumière et la nuit** (Juliette est le soleil, à la scène du balcon ; l'amour vit la nuit, hors du regard des familles) ; **le poison et le remède** (la même substance sauve ou tue — comme l'amour lui-même) ; **le faucon et l'oiseau** (l'appel et la captivité). Les amants inventent **une langue à eux**, jusqu'au **sonnet partagé** de leur première rencontre : une langue commune au-dessus des camps.\n- **Les adaptations** : ballets, opéras, comédies musicales — ***West Side Story*** transpose l'intrigue dans les **gangs new-yorkais** —, films, adaptations **en cité**, **en camp de réfugiés**, **en réseau social**.\n- **Discussion** : l'universalité vient autant de la **haine** (la structure de deux camps séparés par une frontière existe partout) que de l'**amour** (le désir de la franchir) ; c'est leur **rencontre** qui fait la tragédie.\n\n**Conclusion** : la pièce se transpose parce que sa structure — deux camps, une frontière, deux êtres qui la franchissent — se retrouve dans toute société."}$exo$::jsonb),
  ('dd0a2966-6d85-5160-88a4-3f696b3b51a6'::uuid, 1, 'redaction', $exo${"titre":"Qui aime qui ?","consigne":"Réponds en phrases complètes.","enonce":"1. Quand Musset publie-t-il *Les Caprices de Marianne* ? Pourquoi la pièce est-elle d'abord écrite pour être **lue** ?\n2. Résume l'intrigue en quatre étapes, en nommant Cœlio, Octave, Marianne et Claudio.\n3. Caractérise en une phrase chacun des trois personnages du triangle.","bareme":[{"critere":"1833 ; après l'échec de sa première pièce, recueil Un spectacle dans un fauteuil","points":5},{"critere":"Quatre étapes justes : désir, délégation à Octave, déplacement vers Octave, mort de Cœlio par les hommes de Claudio","points":8},{"critere":"Cœlio idéaliste, Octave libertin cynique, Marianne enfermée dans un mariage","points":7}],"dureeMin":7,"corrige":"**1.** Musset publie la pièce en **1833**. Après l'**échec de sa première pièce**, il publie un recueil intitulé ***Un spectacle dans un fauteuil*** : la pièce est d'abord faite pour être lue.\n\n**2.**\n- **Le désir** : **Cœlio** aime **Marianne**, mariée au vieux juge **Claudio**.\n- **La délégation** : timide, il demande à son ami **Octave** de plaider sa cause.\n- **Le déplacement** : Marianne se refuse à Cœlio, puis se rapproche d'Octave.\n- **Le drame** : un malentendu envoie Cœlio à un rendez-vous piégé, où il est **tué par les hommes de Claudio**.\n\n**3.** **Cœlio** : l'**idéaliste**, qui préfère le rêve à la rencontre. **Octave** : le **libertin cynique**, qui se découvre incapable d'aimer. **Marianne** : enfermée dans un mariage, ses « caprices » sont **les seules libertés qu'on lui laisse**."}$exo$::jsonb),
  ('dd0a2966-6d85-5160-88a4-3f696b3b51a6'::uuid, 2, 'redaction', $exo${"titre":"Un drame romantique contre la règle","consigne":"Réponds aux questions en justifiant avec le cours.","enonce":"**Situation.** Pour un exposé, Lou doit montrer que *Les Caprices de Marianne* est un **drame romantique** et non une tragédie classique. Voici ses notes sur la pièce :\n\n- des scènes de fantaisie et de bouffonnerie côtoient une mort violente ;\n- l'action se déplace dans plusieurs lieux de la ville ;\n- les personnages parlent en prose ;\n- la mort de Cœlio vient d'un malentendu, et l'ironie ne quitte jamais la pièce.\n\n1. Pour chaque note, nomme le **trait du drame romantique** qu'elle illustre et la **règle classique** à laquelle il s'oppose.\n2. Donne les deux dates-repères du drame romantique et ce qu'elles désignent.\n3. Explique pourquoi Cœlio et Octave sont dits « **deux moitiés d'un même homme** ».","bareme":[{"critere":"Quatre traits romantiques justes, chacun opposé à la bonne règle classique","points":10},{"critere":"Préface de Cromwell (1827), bataille d'Hernani (1830)","points":4},{"critere":"Deux moitiés : le rêve de l'idéaliste et le cynisme du libertin, qui ensemble font un homme","points":6}],"dureeMin":12,"corrige":"**1.**\n- Fantaisie et mort violente : le **mélange des registres**, fantaisie et tragédie, contre la **séparation classique des genres**.\n- Plusieurs lieux : le **refus des unités**, contre les **trois unités**.\n- La **prose**, contre l'**alexandrin**.\n- Le malentendu et l'ironie : le **hasard** et l'**ironie constante**, contre la **nécessité tragique**.\n\n**2.** La **préface de Cromwell**, manifeste de Victor Hugo (**1827**) ; la **bataille d'Hernani** (**1830**), symbole du conflit entre classiques et romantiques.\n\n**3.** Cœlio est l'**idéaliste**, qui préfère le rêve à la rencontre ; Octave le **libertin cynique**, incapable d'aimer. Chacun possède ce qui manque à l'autre : l'un aime sans oser agir, l'autre agit sans aimer. Ensemble, ils forment un homme complet ; séparés, ils échouent tous les deux. Ils incarnent les deux pentes du **mal du siècle** : le rêve et le cynisme."}$exo$::jsonb),
  ('dd0a2966-6d85-5160-88a4-3f696b3b51a6'::uuid, 3, 'redaction', $exo${"titre":"Une mort sans coupable simple","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur la pièce et le cours.","enonce":"**Sujet.** À la fin des *Caprices de Marianne*, Cœlio est mort, et personne n'est un coupable simple.\n\nDans un paragraphe argumenté, montre comment chacun des trois personnages du triangle (et Claudio) porte une part de la responsabilité, puis explique ce que la pièce interroge à travers ce drame. Tu mobiliseras :\n- le **mal du siècle** ;\n- la condition faite aux **femmes mariées** ;\n- l'**amitié masculine** et la **parole déléguée**.","bareme":[{"critere":"Responsabilités partagées : Cœlio qui délègue, Octave qui prend la place, Marianne sans liberté, Claudio qui tue","points":5},{"critere":"Mal du siècle défini (génération d'après Napoléon, sans guerre ni foi, entre rêve et cynisme) et relié aux personnages","points":4},{"critere":"Condition des femmes mariées : les caprices comme seules libertés","points":4},{"critere":"Parole déléguée : parler pour un autre, c'est parler à sa place ; aveuglements de l'amitié","points":4},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **Des responsabilités partagées** : **Cœlio**, l'idéaliste, préfère le rêve à la rencontre et **délègue** sa parole ; **Octave**, en plaidant pour lui, attire sur lui l'intérêt de Marianne ; **Marianne**, enfermée dans un mariage subi, n'a pour liberté que ses « caprices » ; **Claudio**, le vieux juge jaloux, fait tuer Cœlio par ses hommes. Un **malentendu** envoie Cœlio au rendez-vous piégé : la mort est irréparable et **sans coupable désignable**.\n- **Le mal du siècle** : Cœlio et Octave appartiennent à une génération née **après l'épopée napoléonienne**, **sans guerre à faire, sans foi solide**, qui oscille entre **le rêve et le cynisme** — les deux « moitiés d'un même homme ». Musset l'analyse dans *La Confession d'un enfant du siècle*.\n- **Les femmes mariées** : la pièce montre un **mariage subi, sans issue** ; les « caprices » de Marianne sont les **seules libertés qu'on lui laisse**, non des lubies.\n- **L'amitié masculine et la parole déléguée** : l'amitié a ses **aveuglements** ; et **parler pour un autre, c'est déjà parler à sa place** — la délégation détourne le désir.\n- **Drame romantique** : le hasard et l'ironie remplacent la nécessité tragique ; la mort naît d'un enchaînement, non d'un destin.\n\n**Conclusion** : la pièce accuse moins une personne qu'une époque et ses contraintes."}$exo$::jsonb),
  ('f38a5f57-b6f1-5392-8a2e-8cfc29d582d8'::uuid, 1, 'redaction', $exo${"titre":"Roberto Zucco en repères","consigne":"Réponds en phrases complètes.","enonce":"1. Qui a écrit *Roberto Zucco* ? Donne ses dates, et l'année de création de la pièce. De quoi s'inspire-t-elle ?\n2. Comment la pièce est-elle découpée ? Quel effet produit ce découpage ?\n3. Comment les autres personnages sont-ils désignés ? Donne deux exemples et l'effet produit.\n4. Où se déroule le dernier tableau ?","bareme":[{"critere":"Bernard-Marie Koltès (1948-1989), créée en 1990, inspirée librement d'un fait divers","points":5},{"critere":"Quinze tableaux titrés, progression par stations, un chemin plutôt qu'une intrigue","points":6},{"critere":"Désignation par fonction (la Gamine, la Mère…) qui les rapproche des figures mythiques","points":6},{"critere":"Sur un toit, en plein soleil","points":3}],"dureeMin":7,"corrige":"**1.** **Bernard-Marie Koltès** (**1948-1989**) écrit la pièce peu avant sa mort ; elle est **créée en 1990**. Elle s'inspire **librement d'un fait divers**.\n\n**2.** En **quinze tableaux titrés**, plutôt qu'en actes : une progression par **stations**, à travers des lieux traversés (prison, chambre, métro, parc, commissariat, toit) — **un chemin, non une intrigue**. Elle rappelle autant la tragédie antique que le chemin de croix.\n\n**3.** Par leur **fonction**, pas par un nom : **la Gamine**, **la Mère**, **la Sœur**, **la Dame**, **le Costaud**. Cette désignation les **rapproche des figures mythiques**.\n\n**4.** **Sur un toit, en plein soleil** : la capture y devient une **apothéose ambiguë**."}$exo$::jsonb),
  ('f38a5f57-b6f1-5392-8a2e-8cfc29d582d8'::uuid, 2, 'redaction', $exo${"titre":"Une tragédie sans dieux","consigne":"Réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation.** Au sortir d'une représentation de *Roberto Zucco*, Théo dit : « Ce n'est pas une tragédie : il n'y a ni dieux, ni rois, et on ne sait même pas pourquoi il tue. »\n\n1. Montre que la **structure** de la pièce rappelle pourtant la tragédie.\n2. Qu'est-ce que Koltès **refuse** de donner au spectateur sur son héros, et que donne-t-il à la place ?\n3. Décris les deux **registres de langue** de la pièce et où ils apparaissent.\n4. Réponds à Théo : dans la tragédie moderne, par quoi la **fatalité** remplace-t-elle les dieux ?","bareme":[{"critere":"Structure : quinze tableaux, stations, chemin vers une fin, personnages-figures mythiques","points":5},{"critere":"Refus du mobile, de l'enfance analysée, de la leçon ; à la place une énergie, un regard","points":5},{"critere":"Deux registres : français écrit presque classique (monologues) / parole brute (scènes de rue)","points":4},{"critere":"Fatalité : déterminisme social, famille, ville ; héros sans grandeur avec une trajectoire subie","points":6}],"dureeMin":12,"corrige":"**1.** La pièce avance en **quinze tableaux** titrés, par **stations**, le long d'un chemin qui mène à une fin : une progression qui rappelle **la tragédie antique** (et le chemin de croix). Les personnages désignés par leur **fonction** (la Gamine, la Mère) ressemblent à des **figures mythiques**, et le dernier tableau, sur un toit en plein soleil, transforme la capture en **apothéose ambiguë**.\n\n**2.** Koltès refuse le **mobile**, l'**enfance analysée**, la **leçon** : aucune explication psychologique. À la place, il donne une **énergie** qui passe et détruit, et un **regard** : il demande qu'on regarde, sans compréhension ni pardon.\n\n**3.** Un français très **écrit**, presque **classique** dans son rythme, dans les **monologues** (qui touchent au mythe : le soleil, le rhinocéros, la disparition) ; une parole **brute** dans les **scènes de rue**.\n\n**4.** Théo a raison sur les dieux et les rois, mais la tragédie moderne **s'en passe** : la **fatalité** y prend la forme d'un **déterminisme social**, d'une **famille**, d'une **ville**. Le héros n'a plus de grandeur, seulement **une trajectoire qu'il ne maîtrise pas**. C'est donc bien une tragédie."}$exo$::jsonb),
  ('f38a5f57-b6f1-5392-8a2e-8cfc29d582d8'::uuid, 3, 'redaction', $exo${"titre":"Représenter un criminel, est-ce le glorifier ?","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, en pesant l'objection avant d'y répondre.","enonce":"**Sujet.** À sa création, *Roberto Zucco* a suscité un débat : représenter un criminel réel sur une scène, n'est-ce pas le glorifier ?\n\nDans un paragraphe argumenté :\n1. expose l'**objection** et ce qui, dans la pièce, peut lui donner prise (héros sans explication, dernier tableau) ;\n2. présente la **réponse de Koltès** : portrait ou figure ? que vise la pièce ?\n3. donne ton avis argumenté en t'appuyant sur ce que le cours dit de la **tragédie moderne**.","bareme":[{"critere":"Objection exposée honnêtement, avec des éléments de la pièce (énergie, monologues, apothéose ambiguë sur le toit)","points":4},{"critere":"Réponse de Koltès : une figure et non un portrait, comme Œdipe ou Médée","points":5},{"critere":"La pièce vise la violence d'une société entière plutôt que la folie d'un homme","points":4},{"critere":"Avis argumenté relié à la tragédie moderne (fatalité sociale, héros sans grandeur)","points":4},{"critere":"Organisation et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n1. **L'objection** : la pièce s'inspire librement d'un **fait divers** ; Koltès refuse d'expliquer son héros et ne donne aucune leçon ; ses **monologues** touchent au mythe (le soleil, le rhinocéros, la disparition) ; le **dernier tableau**, sur un toit en plein soleil, transforme la capture en **apothéose ambiguë**. On peut donc craindre qu'elle fasse d'un tueur un héros.\n\n2. **La réponse de Koltès** : Zucco n'est **pas un portrait**, c'est une **figure** — comme **Œdipe** ou **Médée**, qui tuent eux aussi sans qu'on glorifie le meurtre. La pièce vise **la violence d'une société entière**, plutôt que **la folie d'un homme**. Koltès ne demande ni compréhension ni pardon : il **demande qu'on regarde**.\n\n3. **Avis argumenté** (au choix, s'il est justifié) : par exemple, la pièce ne glorifie pas, car le héros **n'a plus de grandeur** ; il a seulement **une trajectoire qu'il ne maîtrise pas** ; la fatalité prend la forme d'un **déterminisme social**, d'une famille, d'une ville. Les autres personnages, désignés par leur fonction (la Gamine, la Mère), montrent un monde où la violence circule partout. On accepte un avis nuancé (le risque existe, mais la forme tragique le tient à distance).\n\nÀ sanctionner : un avis sans argument, ou l'absence de la réponse de Koltès."}$exo$::jsonb),
  ('0e59af0a-263a-5ec1-afa2-3aeafdd00f7f'::uuid, 1, 'redaction', $exo${"titre":"Raconter, montrer, suspendre, documenter","consigne":"Réponds en phrases complètes.","enonce":"1. Recopie et complète le tableau :\n\n| L'époque | Le traitement de la mort | Son moyen |\n| Antiquité et classicisme | … | … |\n| Théâtre élisabéthain et romantisme | … | … |\n| XXe siècle | … | … |\n| Aujourd'hui | … | … |\n\n2. Qui, dans la tragédie grecque, raconte ce qui s'est passé hors scène ? Sous quel nom le théâtre classique reprend-il cette règle ?\n3. Quelle pièce d'Ionesco fait de la mort une cérémonie lente ?","bareme":[{"critere":"Quatre traitements justes (raconter, montrer, suspendre, documenter)","points":8},{"critere":"Quatre moyens justes (récit du messager et hors-scène, mort sur scène, attente, témoignage/chœur/liste de noms)","points":6},{"critere":"Le messager ; la bienséance ; Le roi se meurt","points":6}],"dureeMin":7,"corrige":"**1.**\n- **Antiquité et classicisme** : **raconter** — le **récit du messager**, le **hors-scène**.\n- **Théâtre élisabéthain et romantisme** : **montrer** — la **mort sur scène**.\n- **XXe siècle** : **suspendre** — l'**attente** remplace l'événement.\n- **Aujourd'hui** : **documenter** — **témoignage**, **chœur**, **liste de noms**.\n\n**2.** Le **messager** vient raconter ce qui s'est passé hors scène. Le théâtre classique reprend la règle sous le nom de **bienséance** (rien de choquant sur scène).\n\n**3.** ***Le roi se meurt*** d'Ionesco."}$exo$::jsonb),
  ('0e59af0a-263a-5ec1-afa2-3aeafdd00f7f'::uuid, 2, 'redaction', $exo${"titre":"Trois façons de faire mourir Léandre","consigne":"Analyse les trois propositions, puis réponds aux questions.","enonce":"**Situation.** Une troupe de lycéens monte une pièce écrite par la classe, où le jeune Léandre meurt noyé en voulant sauver un enfant. Trois mises en scène sont proposées :\n\n- **Proposition A** : Léandre ne paraît plus ; un pêcheur arrive, essoufflé, et raconte longuement la tempête, la barque, le cri, le corps.\n- **Proposition B** : on voit Léandre se débattre dans des vagues de tissu bleu, puis on apporte son corps au centre du plateau.\n- **Proposition C** : la mère de Léandre attend sur le quai, seule ; la lumière baisse lentement ; elle répète « il va rentrer » ; silence ; noir.\n\n1. Pour chaque proposition, nomme le **traitement** de la mort et l'**époque** du théâtre à laquelle il se rattache.\n2. Relève dans chaque proposition au moins **un procédé** du cours (hors-scène et récit, chœur, objet qui reste, lumière qui baisse et silence, ellipse).\n3. Explique la phrase du cours : dans un cas la mort est un **fait**, dans l'autre un **événement de langage**. Applique-la aux propositions A et B.","bareme":[{"critere":"Trois traitements et époques justes (raconter : Antiquité/classicisme ; montrer : élisabéthain/romantisme ; suspendre : XXe)","points":7},{"critere":"Un procédé juste relevé dans chaque proposition","points":6},{"critere":"Fait / événement de langage expliqué et appliqué à A et B","points":7}],"dureeMin":12,"corrige":"**1.**\n- **A** : **raconter** — comme dans la tragédie grecque (le **messager**) et le **classicisme** (chez Racine, la mort d'Hippolyte rapportée par un récit).\n- **B** : **montrer** — comme le **théâtre élisabéthain** (le plateau jonché de corps d'*Hamlet*) et le **drame romantique**.\n- **C** : **suspendre** — comme le **XXe siècle** et le théâtre de l'**absurde** (Beckett, Ionesco) : l'**attente** remplace l'événement, la mort devient **durée**.\n\n**2.**\n- A : le **hors-scène** et le **récit** (la parole doit faire voir) ; le pêcheur joue le rôle du messager.\n- B : la mort **sur scène** et le **corps** apporté ; accepter l'**objet qui reste** si l'élève évoque le tissu ou le corps.\n- C : la **lumière qui baisse**, le **silence**, le **noir** ; l'**ellipse** (on ne voit ni n'entend la mort : elle laisse un vide).\n\n**3.** Faire entrer un cadavre sur scène (**B**) : la mort est un **fait**, visible, immédiat, qui frappe les yeux. La faire raconter (**A**) : elle devient un **événement de langage**, construit par les mots du récit, et le spectateur l'imagine ; le **hors-scène** peut rendre la mort **plus grande** que ne le ferait sa représentation. Les deux ne racontent pas la même histoire."}$exo$::jsonb),
  ('0e59af0a-263a-5ec1-afa2-3aeafdd00f7f'::uuid, 3, 'redaction', $exo${"titre":"Montrer ou cacher la mort","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des exemples précis.","enonce":"**Sujet.** « Que gagne-t-on à montrer, que gagne-t-on à cacher ? »\n\nÀ propos de la mort au théâtre, réponds à cette question dans un paragraphe argumenté qui :\n- examine ce que gagne le **hors-scène** (avec un exemple) ;\n- examine ce que gagne la **mort montrée** (avec un exemple) ;\n- présente la voie du **XXe siècle** (suspendre) ;\n- termine par le problème que pose aujourd'hui la **mort réelle** au théâtre.","bareme":[{"critere":"Hors-scène : la parole fait voir, la mort grandie ; messager grec ou récit de Racine (Hippolyte), bienséance","points":4},{"critere":"Mort montrée : Hamlet, drame romantique, liberté au nom de la vérité ; la mort comme fait","points":4},{"critere":"Suspendre : Beckett, Ionesco (Le roi se meurt), la mort comme durée","points":4},{"critere":"Aujourd'hui : documenter la mort réelle sans en faire un spectacle","points":4},{"critere":"Organisation, nuance et expression","points":4}],"dureeMin":20,"corrige":"**Éléments attendus.**\n\n- **Cacher (le hors-scène)** : la tragédie grecque évite de tuer devant le public, le **messager** raconte ; le théâtre classique en fait une règle, la **bienséance**. Chez **Racine**, la mort d'Hippolyte est rapportée par un **récit**, morceau de bravoure où **la parole doit faire voir**. On y gagne l'imagination du spectateur : le hors-scène **rend la mort plus grande** que ne le ferait sa représentation ; la mort devient un **événement de langage**.\n- **Montrer** : dans *Hamlet*, le dernier acte laisse un **plateau jonché de corps** ; le **drame romantique** revendique cette liberté **au nom de la vérité, contre les règles**. On y gagne la force du **fait** : la mort frappe les yeux, sans médiation.\n- **Suspendre** (XXe siècle) : chez **Beckett**, on n'en finit pas de mourir, l'attente est le sujet ; **Ionesco**, dans *Le roi se meurt*, en fait une **cérémonie lente et absurde**. La mort devient **durée** plutôt que coup de théâtre.\n- **Aujourd'hui** : le théâtre reprend la **mort réelle** (guerres, attentats, migrations, épidémies) et cherche des formes — **témoignage**, **chœur**, **liste de noms** — qui ne la **transforment pas en spectacle**.\n- Procédés mobilisables : hors-scène, chœur, objet qui reste, lumière qui baisse, silence, ellipse.\n\n**Conclusion** : montrer donne le fait, cacher donne le sens ; chaque époque choisit selon ce qu'elle veut faire éprouver."}$exo$::jsonb),
  ('b8d2a030-4cbd-5f79-8f1a-3e8d024c62da'::uuid, 1, 'redaction', $exo${"titre":"Quatre siècles de scène","consigne":"Réponds en phrases complètes.","enonce":"1. Donne le **principe** du théâtre à chaque époque (XVIIe, XVIIIe, XIXe, XXe-XXIe) et un auteur pour chacune.\n2. Quelles sont les **contraintes** de la règle classique au XVIIe siècle ? Explique chacune en quelques mots.\n3. Qu'est-ce que la **distanciation** de Brecht ?","bareme":[{"critere":"Quatre principes justes (règle, glissement, rupture, mise en question) avec un auteur exact chacun","points":8},{"critere":"Trois unités, vraisemblance, bienséance, séparation des genres expliquées","points":8},{"critere":"Distanciation : empêcher l'identification pour faire penser","points":4}],"dureeMin":7,"corrige":"**1.**\n- **XVIIe** : la **règle** classique — Corneille, Racine, Molière.\n- **XVIIIe** : le **glissement** vers le sentiment et la critique — Marivaux, Beaumarchais.\n- **XIXe** : la **rupture** romantique — Hugo, Musset, Vigny.\n- **XXe-XXIe** : la **mise en question** — Brecht, Beckett, Ionesco, Koltès.\n\n**2.**\n- Les **trois unités** : un jour, un lieu, une action.\n- La **vraisemblance** : rien d'incroyable.\n- La **bienséance** : rien de choquant sur scène.\n- La **séparation des genres** : tragédie et comédie ne se mêlent pas.\n\n**3.** La **distanciation** de Brecht est un ensemble de procédés qui **empêchent l'identification** du spectateur aux personnages, pour le **faire penser**."}$exo$::jsonb),
  ('b8d2a030-4cbd-5f79-8f1a-3e8d024c62da'::uuid, 2, 'redaction', $exo${"titre":"Dater quatre pièces","consigne":"Situe chaque pièce dans le temps et justifie avec un indice précis.","enonce":"**Situation.** Au CDI, Adam trouve quatre résumés de pièces sans date ni auteur :\n\n- **Pièce A** : en un seul jour et un seul lieu, un roi doit choisir entre son amour et son devoir envers l'État ; aucune violence n'est montrée sur scène.\n- **Pièce B** : deux vagabonds attendent au bord d'une route quelqu'un qui ne vient pas ; leurs répliques tournent en rond et le langage se défait.\n- **Pièce C** : un valet plein d'esprit se moque des privilèges de son maître, un comte.\n- **Pièce D** : sur plusieurs années et dans plusieurs pays, un héros proscrit passe du rire au sang ; un public divisé se bat dans la salle à la première.\n\n1. Rattache chaque pièce à un siècle et à un courant ou principe (règle, glissement, rupture, mise en question).\n2. Pour chacune, cite l'indice décisif et, si tu peux, un auteur du cours qui pratique ce théâtre.\n3. Laquelle de ces pièces aurait été la plus difficile à jouer au XVIIe siècle ? Pourquoi ?","bareme":[{"critere":"Quatre pièces correctement situées (A : XVIIe règle ; B : XXe absurde ; C : XVIIIe ; D : XIXe romantique)","points":8},{"critere":"Indice décisif et auteur pertinent pour chacune","points":8},{"critere":"Justification pour le XVIIe : règle, censure et goût du roi","points":4}],"dureeMin":12,"corrige":"**1 et 2.**\n- **A** : **XVIIe siècle**, la **règle** classique. Indices : unité de temps et de lieu, conflit du **devoir et de la passion**, bienséance (aucune violence montrée). Auteur : **Corneille** (conflit du devoir et de la passion) ; Racine accepté.\n- **B** : **XXe siècle**, la **mise en question** ; théâtre de l'**absurde**. Indices : intrigue et **langage défaits**, attente. Auteurs : **Beckett**, **Ionesco**.\n- **C** : **XVIIIe siècle**, le **glissement** vers la critique. Indice : une **critique politique dans la bouche d'un valet**. Auteur : **Beaumarchais** (*Le Mariage de Figaro*).\n- **D** : **XIXe siècle**, la **rupture romantique**. Indices : refus des unités, **mélange des genres** (du rire au sang), public qui se bat — comme la **bataille d'Hernani** (1830). Auteur : **Hugo**.\n\n**3.** La pièce **D** (ou B, si c'est justifié) : au XVIIe siècle, elle viole les **trois unités**, la **séparation des genres** et la **bienséance**. Le théâtre est alors un **art de cour**, soumis à la **censure** et au **goût du roi**. La pièce C aurait aussi posé problème par sa critique des privilèges ; accepter toute réponse justifiée par les règles."}$exo$::jsonb),
  ('b8d2a030-4cbd-5f79-8f1a-3e8d024c62da'::uuid, 3, 'redaction', $exo${"titre":"Que montre-t-on, à qui, depuis quel point de vue ?","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, appuyé sur des exemples précis.","enonce":"**Sujet.** « Le théâtre change quand changent son public, sa salle et ce qu'on lui autorise à montrer. » Et pourtant, depuis quatre siècles, une pièce répond toujours aux mêmes trois questions : **que montre-t-on, à qui, et depuis quel point de vue ?**\n\nMontre, en parcourant les quatre époques du cours, comment chacune répond différemment à ces trois questions. Tu t'appuieras sur au moins **quatre** auteurs ou œuvres.","bareme":[{"critere":"XVIIe : art de cour, censure, règles (unités, bienséance) ; Corneille, Racine ou Molière","points":4},{"critere":"XVIIIe : sentiment, brouillage des rangs, critique par un valet, drame bourgeois ; Marivaux ou Beaumarchais","points":4},{"critere":"XIXe : droit de tout montrer et obligation d'un point de vue ; Hernani, mélodrame, vaudeville","points":4},{"critere":"XXe-XXIe : metteur en scène auteur, distanciation, absurde, réel ; Brecht, Beckett, Ionesco, Koltès","points":5},{"critere":"Organisation autour des trois questions et expression","points":3}],"dureeMin":18,"corrige":"**Éléments attendus.**\n\n- **XVIIe siècle** — *à qui* : la **cour** ; le théâtre est soumis à la **censure** et au **goût du roi**. *Que montre-t-on* : ce que permettent les **trois unités**, la **vraisemblance**, la **bienséance** (rien de choquant) ; tragédie et comédie séparées. *Point de vue* : Corneille (conflit du devoir et de la passion), Racine (fatalité amoureuse), Molière (comédie de caractère et de mœurs : *Tartuffe*, *Dom Juan*, *L'Avare*, *Le Misanthrope*).\n- **XVIIIe siècle** — on glisse vers le **sentiment** et la **critique** : **Marivaux** brouille les rangs sociaux ; **Beaumarchais**, dans *Le Mariage de Figaro*, met une critique politique **dans la bouche d'un valet** (le point de vue descend) ; le **drame bourgeois** montre des héros ordinaires et des sujets sérieux.\n- **XIXe siècle** — la **rupture romantique** : mélange des genres, couleur locale, liberté de la scène ; la **bataille d'Hernani** (1830). Le public s'élargit (mélodrame, vaudeville au théâtre populaire). La scène gagne **le droit de tout montrer, et l'obligation d'avoir un point de vue**.\n- **XXe-XXIe siècles** — la **mise en question** : le **metteur en scène** devient un auteur ; **Brecht** et la **distanciation** changent le rapport au public (penser plutôt que s'identifier) ; **Beckett** et **Ionesco** défont l'intrigue et le langage ; **Koltès**, Vinaver, Lagarce réinventent le dialogue ; le théâtre part du **réel** (témoignages, documents, faits divers).\n\n**Conclusion** : les réponses changent avec le public, la salle et la liberté accordée, mais les trois questions demeurent."}$exo$::jsonb),
  ('15f19fce-8caf-52b0-a5f5-3e84c4e3f175'::uuid, 1, 'redaction', $exo${"titre":"Les mots du théâtre","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"Définis les termes suivants :\n\n1. une **didascalie** ;\n2. un **aparté** ;\n3. une **tirade** ;\n4. une **stichomythie** ;\n5. la **double énonciation**.","bareme":[{"critere":"Didascalie et aparté correctement définis","points":8},{"critere":"Tirade et stichomythie correctement définies et opposées","points":6},{"critere":"Double énonciation définie (personnage et public)","points":6}],"dureeMin":6,"corrige":"1. **Didascalie** : une **indication scénique** écrite par l'auteur (geste, ton, décor), qui **n'est pas prononcée**.\n2. **Aparté** : une réplique dite « à part » : **entendue du public**, mais **pas des autres personnages**.\n3. **Tirade** : une **longue réplique** ininterrompue.\n4. **Stichomythie** : un échange de **répliques très brèves**, qui s'enchaînent vite.\n5. **Double énonciation** : un personnage parle à un autre personnage **et au public** en même temps. Elle explique qu'un personnage rappelle ce que son interlocuteur sait déjà : c'est le spectateur qui l'ignore."}$exo$::jsonb),
  ('15f19fce-8caf-52b0-a5f5-3e84c4e3f175'::uuid, 2, 'redaction', $exo${"titre":"Le vase brisé","consigne":"Lis l'extrait, puis réponds aux questions en citant le texte.","enonce":"**Extrait (inventé pour l'exercice)**\n\n> *Un salon. Madame Loriot entre, un vase brisé à la main.*\n> MADAME LORIOT. — Qui a cassé mon vase ?\n> FIRMIN, *à part*. — Aïe, aïe, aïe…\n> LE CHAT, *passant tranquillement*. — Miaou.\n> FIRMIN. — Le chat !\n> MADAME LORIOT. — Le chat ?\n> FIRMIN. — Le chat.\n> MADAME LORIOT. — Mais nous n'avons pas de chat, Firmin !\n\n1. Relève une **didascalie** et un **aparté**. À quoi servent-ils ?\n2. Comment s'appelle l'échange rapide « Le chat ! / Le chat ? / Le chat. » ? Quel effet produit-il ?\n3. Quels **ressorts du comique** reconnais-tu dans cet extrait ? Nomme-en **trois**.","bareme":[{"critere":"Didascalie et aparté relevés et leur fonction expliquée","points":6},{"critere":"Stichomythie nommée ; effet de rythme et de comique","points":5},{"critere":"Trois ressorts du comique nommés et justifiés","points":9}],"dureeMin":11,"corrige":"1. **Didascalies** : « Un salon. Madame Loriot entre, un vase brisé à la main », « passant tranquillement ». Elles indiquent le **décor** et les **gestes**, sans être prononcées. **Aparté** : « FIRMIN, *à part*. — Aïe, aïe, aïe… » : entendu du **public** seulement, il révèle que Firmin est **coupable**. Le public en sait plus que Madame Loriot.\n2. C'est une **stichomythie** : répliques très brèves. Le **rythme** rapide crée un effet de ping-pong et fait monter le rire.\n3. Ressorts du comique :\n- comique de **mots** / de **répétition** : « Le chat » répété trois fois, « Aïe » ;\n- comique de **situation** : Firmin accuse un chat qui n'existe pas ; le public sait qu'il est coupable ; retournement final « nous n'avons pas de chat » ;\n- comique de **caractère** : le mensonge maladroit de Firmin ;\n- on accepte l'**absurde** du chat qui passe alors qu'il n'existe pas."}$exo$::jsonb),
  ('15f19fce-8caf-52b0-a5f5-3e84c4e3f175'::uuid, 3, 'redaction', $exo${"titre":"Le secret de la reine","consigne":"Lis l'extrait, puis réponds aux questions. La dernière question demande un paragraphe rédigé.","enonce":"**Extrait (inventé pour l'exercice)** — Acte I, scène 1.\n\n> *Le palais d'Argos, au lever du jour.*\n> LA NOURRICE. — Vous le savez, Madame : voilà dix ans que le roi votre époux est parti pour la guerre, et dix ans que vous l'attendez.\n> LA REINE. — Dix ans… Et ce matin, un messager annonce son retour.\n> LA NOURRICE. — Vous devriez vous réjouir.\n> LA REINE, *à part*. — S'il savait ce que j'ai fait en son absence…\n> *Entre un soldat.*\n> LE SOLDAT. — Le roi approche, Madame. Il a juré de punir celui qui l'a trahi.\n> LA REINE. — Qu'il vienne. Je l'attends.\n\n1. Pourquoi la nourrice rappelle-t-elle à la reine ce qu'elle sait déjà ? Nomme le procédé.\n2. Quel est le rôle de cette scène dans la **structure** de la pièce ? Que pose-t-elle ?\n3. Relève un **aparté** et explique comment il crée une **ironie tragique** avec la dernière réplique.\n4. À quel **genre** cette pièce semble-t-elle appartenir ? Justifie par trois indices.\n5. Quel changement indique la didascalie « *Entre un soldat* » dans le découpage de la pièce ?","bareme":[{"critere":"Double énonciation : information destinée au spectateur","points":4},{"critere":"Scène d'exposition : lieu, personnages, intrigue","points":4},{"critere":"Aparté et ironie tragique expliqués","points":5},{"critere":"Genre tragique justifié par trois indices","points":4},{"critere":"Entrée d'un personnage : nouvelle scène","points":3}],"dureeMin":18,"corrige":"1. La reine sait déjà que le roi est parti depuis dix ans : c'est le **spectateur** qui l'ignore. C'est la **double énonciation** : la nourrice parle à la reine **et au public**.\n2. C'est une **scène d'exposition** (acte I, scène 1) : elle pose le **lieu** (le palais d'Argos), le **temps** (au lever du jour), les **personnages** (la reine, le roi absent, la nourrice) et l'**intrigue** (le retour du roi, un secret, une trahison) ; le **nœud** s'annonce.\n3. **Aparté** : « S'il savait ce que j'ai fait en son absence… » : le public apprend que la reine cache une faute, que la nourrice ignore. Quand le soldat annonce que le roi veut « punir celui qui l'a trahi », le spectateur comprend que la reine est peut-être visée, alors que les autres personnages l'ignorent : c'est l'**ironie tragique**, née quand le spectateur sait ce que le personnage ignore. « Je l'attends » prend un double sens inquiétant.\n4. Une **tragédie** : personnages **nobles** (reine, roi), menace de **punition**, atmosphère de **destin** et de fin malheureuse probable, ton grave ; unité de **lieu** (le palais) et de **temps** (une journée qui commence).\n5. Au théâtre, la **scène change dès qu'un personnage entre ou sort** : l'entrée du soldat ouvre une nouvelle scène (scène 2)."}$exo$::jsonb),
  ('0b344c8a-3461-5331-bcbc-51fae81a3ed4'::uuid, 1, 'traduction', $exo${"titre":"Cinq cas et un article","consigne":"Réponds à chaque question avec précision, en employant le vocabulaire du cours.","enonce":"1. Combien de cas compte la déclinaison grecque ? Donne la fonction principale de chacun.\n2. Pourquoi l'ordre des mots est-il très libre en grec ?\n3. À quelle déclinaison et à quel genre appartient chacun de ces noms ? ἡ τιμή ; ὁ λόγος ; τὸ δῶρον ; ὁ πολίτης.\n4. Énonce la **règle du neutre** et explique pourquoi le cours appelle l'**article** « votre meilleur allié ».","bareme":[{"critere":"Cinq cas et leurs fonctions exactes","points":6},{"critere":"La terminaison, et non la place, indique la fonction","points":3},{"critere":"Quatre noms rangés avec déclinaison et genre justes","points":6},{"critere":"Règle du neutre énoncée et rôle de l'article expliqué","points":5}],"dureeMin":8,"corrige":"1. **Cinq cas** : **nominatif** (sujet, attribut), **vocatif** (interpellation), **accusatif** (COD, direction), **génitif** (complément du nom, origine), **datif** (COI, moyen, lieu).\n2. Parce que la fonction d'un mot est marquée par sa **terminaison** : ce n'est pas la place qui indique la fonction, c'est la finale.\n3. ἡ τιμή (l'honneur) : **1re** déclinaison, **féminin** en -η. ὁ λόγος (la parole) : **2e** déclinaison, **masculin** en -ος. τὸ δῶρον (le don) : **2e** déclinaison, **neutre** en -ον. ὁ πολίτης (le citoyen) : **1re** déclinaison, **masculin** en -ης.\n4. Au neutre, **le nominatif et l'accusatif sont toujours identiques**, dans toute la langue ; une forme neutre ambiguë se tranche par le **sens**. L'**article** (ὁ / ἡ / τό) se décline aussi et accompagne presque toujours le nom : devant un mot inconnu, **sa terminaison à lui donne le cas**. Lire l'article avant le nom fait gagner la moitié du travail de version."}$exo$::jsonb),
  ('0b344c8a-3461-5331-bcbc-51fae81a3ed4'::uuid, 2, 'traduction', $exo${"titre":"Le don du citoyen","consigne":"Analyse chaque groupe nominal (cas, fonction) en t'aidant de l'article, puis traduis.","enonce":"**Phrases**\n\n> 1. Τὸ δῶρον φέρει ὁ πολίτης.\n> 2. Ὁ πολίτης τῷ λόγῳ πείθει τὸν δῆμον.\n\n**Lexique**\n- τὸ δῶρον : le don (neutre, 2e décl.) — ὁ πολίτης : le citoyen (masc., 1re décl.)\n- φέρει : il apporte — πείθει : il persuade\n- ὁ λόγος : la parole ; τῷ λόγῳ est le **datif** singulier (τῷ = article au datif)\n- ὁ δῆμος : le peuple ; τὸν δῆμον est l'**accusatif** singulier (τόν = article à l'accusatif)\n\n1. Phrase 1 : τὸ δῶρον peut-il être sujet ? Quel mot est sûrement au nominatif, et grâce à quoi le sais-tu ? Donne la fonction de chaque groupe et traduis.\n2. Phrase 2 : donne le cas et la fonction de ὁ πολίτης, τῷ λόγῳ et τὸν δῆμον, puis traduis.\n3. Dans la phrase 1, le sujet est placé à la fin. Pourquoi cela ne gêne-t-il pas la compréhension ?","bareme":[{"critere":"Phrase 1 : ὁ πολίτης nominatif sujet grâce à l'article ὁ, τὸ δῶρον neutre donc COD","points":6},{"critere":"Phrase 2 : nominatif sujet, datif de moyen, accusatif COD identifiés","points":6},{"critere":"Deux traductions justes en bon français","points":5},{"critere":"La terminaison, non la place, donne la fonction","points":3}],"dureeMin":11,"corrige":"1. τὸ δῶρον est un **neutre** : au neutre, nominatif et accusatif sont identiques, il pourrait donc être sujet ou COD. Mais ὁ πολίτης est **sûrement au nominatif** : l'article **ὁ** est la forme du nominatif masculin singulier. Le sujet de φέρει est donc ὁ πολίτης, et τὸ δῶρον est à l'**accusatif**, **COD**. Traduction : « **Le citoyen apporte le don.** »\n2. ὁ πολίτης : **nominatif**, **sujet**. τῷ λόγῳ : **datif**, complément de **moyen** (« par la parole »). τὸν δῆμον : **accusatif**, **COD**. Traduction : « **Le citoyen persuade le peuple par la parole.** »\n3. En grec, c'est la **terminaison** (et celle de l'article) qui indique la fonction, pas la place : l'ordre des mots est très libre. Le sujet peut donc être à la fin sans ambiguïté."}$exo$::jsonb),
  ('0b344c8a-3461-5331-bcbc-51fae81a3ed4'::uuid, 3, 'traduction', $exo${"titre":"Deux neutres à trancher","consigne":"Analyse chaque mot (cas, fonction) en justifiant par l'article et par la règle du neutre, puis traduis.","enonce":"**Phrases**\n\n> 1. Τῷ πολίτῃ τὸ δῶρον δίδωσιν ὁ ἄρχων.\n> 2. Τὸ δῶρον τιμὴν φέρει.\n\n**Lexique**\n- ὁ πολίτης : le citoyen ; τῷ πολίτῃ est le **datif** singulier\n- τὸ δῶρον : le don (neutre)\n- δίδωσιν : il donne — φέρει : il apporte\n- ὁ ἄρχων : le magistrat (nominatif singulier)\n- ἡ τιμή : l'honneur ; τιμήν est l'**accusatif** singulier\n\n1. Phrase 1 : analyse τῷ πολίτῃ, τὸ δῶρον et ὁ ἄρχων. Comment sais-tu que τὸ δῶρον n'est pas le sujet ?\n2. Phrase 2 : τὸ δῶρον est cette fois le sujet. Qu'est-ce qui permet de l'affirmer, alors que sa forme est la même qu'en phrase 1 ?\n3. Traduis les deux phrases.\n4. Explique, à partir de ces deux phrases, la phrase du cours : « une forme neutre ambiguë se tranche par le sens, jamais par la terminaison ».","bareme":[{"critere":"Phrase 1 : datif COI, nominatif sujet repéré par l'article ὁ, τὸ δῶρον accusatif COD","points":5},{"critere":"Phrase 2 : τιμήν accusatif COD, donc τὸ δῶρον nominatif sujet","points":5},{"critere":"Deux traductions justes","points":5},{"critere":"Règle du neutre expliquée à partir des deux exemples","points":5}],"dureeMin":15,"corrige":"1. τῷ πολίτῃ : **datif** singulier → **COI** (« au citoyen »). ὁ ἄρχων : **nominatif** (article ὁ) → **sujet** de δίδωσιν. τὸ δῶρον : neutre, nominatif ou accusatif ; le sujet étant déjà ὁ ἄρχων, c'est l'**accusatif**, **COD**.\n2. Dans la phrase 2, le seul autre nom, τιμήν, est à l'**accusatif** (COD) ; aucun autre mot ne peut être sujet de φέρει. τὸ δῶρον, dont la forme vaut aussi pour le nominatif, est donc le **sujet**.\n3. Phrase 1 : « **Le magistrat donne le don au citoyen.** » Phrase 2 : « **Le don apporte l'honneur.** »\n4. Au neutre, **nominatif et accusatif sont toujours identiques** : τὸ δῶρον a exactement la même forme dans les deux phrases. La terminaison ne permet pas de trancher ; ce sont les **autres mots de la phrase** (un nominatif déjà présent en phrase 1, un accusatif déjà présent en phrase 2) et le **sens** qui décident de la fonction."}$exo$::jsonb),
  ('c89a68d4-6481-5042-a689-c8c3b6f23282'::uuid, 1, 'traduction', $exo${"titre":"Les institutions d'Athènes","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu'est-ce qu'une **polis** ? Pourquoi le morcellement du monde grec a-t-il favorisé l'expérimentation politique ?\n2. Associe chaque réformateur à sa date et à son apport : **Solon**, **Clisthène**, **Périclès**.\n3. Pour l'**Ecclésia**, la **Boulè**, l'**Héliée** et les **stratèges**, dis qui y siège et ce qu'ils font.","bareme":[{"critere":"Polis définie (ville, territoire, communauté de citoyens, indépendance) et rôle du morcellement","points":5},{"critere":"Solon, Clisthène, Périclès avec dates et apports exacts","points":7},{"critere":"Quatre institutions avec composition et rôle justes","points":8}],"dureeMin":8,"corrige":"1. La **polis** associe une **ville**, un **territoire** et une **communauté de citoyens** ; elle est **indépendante**. Le monde grec est un monde de cités rivales, jamais un État unifié : ce **morcellement** rend possible l'expérimentation politique.\n2. **Solon** (594 av. J.-C.) : abolit l'esclavage pour dettes et classe les citoyens par la richesse. **Clisthène** (508-507 av. J.-C.) : réorganise le corps civique par **dèmes** et fonde l'**isonomie**. **Périclès** (Ve siècle) : instaure le **misthos**, qui permet aux pauvres de siéger.\n3. **Ecclésia** : tous les citoyens ; vote les lois et la guerre. **Boulè** : 500 membres tirés au sort ; prépare les décisions. **Héliée** : jurés tirés au sort ; c'est le tribunal populaire. **Stratèges** : dix, élus et rééligibles ; commandent l'armée — ce sont les seuls élus."}$exo$::jsonb),
  ('c89a68d4-6481-5042-a689-c8c3b6f23282'::uuid, 2, 'traduction', $exo${"titre":"Qui vote à Athènes ?","consigne":"Lis le document, fais les calculs demandés, puis réponds en t'appuyant sur le cours.","enonce":"**Situation.** Léna prépare un exposé et affirme : « À Athènes, tout le monde votait : c'était la démocratie parfaite. »\n\n**Document – La population d'Athènes (ordre de grandeur, Ve siècle av. J.-C.)**\n\n| Groupe | Effectif | Droits politiques |\n| Citoyens | environ 40 000 | Tous |\n| Femmes, métèques, esclaves | le reste | Aucun |\n| **Total** | environ 250 000 | |\n\n1. Calcule la part des citoyens dans la population (en pourcentage arrondi à l'unité). Retrouve la formule du cours « un habitant sur six ».\n2. Qui est citoyen ? Qui sont les métèques ?\n3. Pourquoi la démocratie athénienne est-elle dite **directe** ?\n4. Corrige l'affirmation de Léna en une phrase qui emploie les deux mots du cours.","bareme":[{"critere":"Calcul juste : 40 000 / 250 000 = 16 %, soit environ un sur six","points":5},{"critere":"Citoyen : homme né de deux parents athéniens ; métèque : étranger libre","points":5},{"critere":"Démocratie directe : le citoyen vote lui-même à l'Ecclésia","points":4},{"critere":"Correction avec « directe » et « restreinte » justifiée","points":6}],"dureeMin":10,"corrige":"1. 40 000 ÷ 250 000 = 0,16, soit **16 %**. Or 1 ÷ 6 ≈ 0,167, soit environ 17 % : **un habitant sur six** environ est citoyen.\n2. Est **citoyen** un **homme** né de **deux parents athéniens**. Les **métèques** sont des **étrangers libres** installés dans la cité, souvent commerçants ; ils n'ont aucun droit politique.\n3. Elle est **directe** parce que le citoyen **vote lui-même** les lois et la guerre à l'**Ecclésia**, sans passer par des représentants ; la Boulè et l'Héliée sont tirées au sort parmi les citoyens.\n4. « Athènes est une démocratie **directe** mais **restreinte** : les citoyens votent eux-mêmes, mais les **femmes**, les **métèques** et les **esclaves**, soit environ cinq habitants sur six, n'ont **aucun droit politique**. »"}$exo$::jsonb),
  ('c89a68d4-6481-5042-a689-c8c3b6f23282'::uuid, 3, 'traduction', $exo${"titre":"Directe et restreinte","consigne":"Rédige un développement organisé d'une vingtaine de lignes, appuyé sur des exemples précis du cours.","enonce":"**Document**\n\n> « Une démocratie **directe** et **restreinte** : les deux mots comptent autant l'un que l'autre. »\n\n**Sujet.** Explique cette phrase du cours. Tu montreras :\n1. comment les réformes de Solon, de Clisthène et de Périclès ont construit la démocratie ;\n2. en quoi les institutions font participer directement les citoyens (et pourquoi les stratèges sont une exception) ;\n3. qui est exclu de la vie politique, chiffres à l'appui ;\n4. pourquoi il faut énoncer les limites « aussi précisément que les institutions ».","bareme":[{"critere":"Trois réformes datées avec leurs apports (esclavage pour dettes, dèmes et isonomie, misthos)","points":5},{"critere":"Participation directe : Ecclésia, tirage au sort de la Boulè et de l'Héliée, stratèges seuls élus","points":5},{"critere":"Exclus nommés (femmes, métèques, esclaves) avec les chiffres (40 000 sur 250 000)","points":5},{"critere":"Réflexion sur l'équilibre entre invention politique et limites","points":3},{"critere":"Développement organisé et rédigé","points":2}],"dureeMin":20,"corrige":"1. **La construction** : en **594 av. J.-C.**, **Solon** abolit l'esclavage pour dettes et classe les citoyens par la richesse. En **508-507 av. J.-C.**, **Clisthène** réorganise le corps civique par **dèmes** et fonde l'**isonomie** (l'égalité devant la loi). Au **Ve siècle**, **Périclès** instaure le **misthos**, une indemnité qui permet aux pauvres de siéger.\n2. **Directe** : tous les citoyens siègent à l'**Ecclésia**, qui vote les lois et la guerre ; la **Boulè** (500 membres) prépare les décisions et l'**Héliée** juge, leurs membres étant **tirés au sort**. Les **stratèges**, dix, sont **élus et rééligibles** : ce sont les seuls élus, car commander l'armée demande une compétence.\n3. **Restreinte** : sur environ **250 000 habitants**, seuls **40 000 environ** sont citoyens (hommes nés de deux parents athéniens), soit un sur six. Les **femmes**, les **métèques** (étrangers libres) et les **esclaves** n'ont **aucun droit politique**.\n4. **Pourquoi les deux mots** : Athènes a inventé une **pratique** et non seulement un mot ; mais présenter ses institutions sans ses limites serait idéaliser, et ne retenir que ses limites ferait oublier l'invention. Le cours demande donc d'énoncer les deux avec la même précision.\n\n**Conclusion attendue** : une invention politique majeure, fondée sur la participation directe, réservée à une minorité de la population."}$exo$::jsonb),
  ('9ed4e986-0250-5e48-9f4c-e3b1db8a1226'::uuid, 1, 'traduction', $exo${"titre":"Scène et école","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. De quelles fêtes naît le théâtre grec ? Pourquoi est-ce une **institution civique** et non un loisir ?\n2. Distingue **tragédie** et **comédie** et cite leurs auteurs.\n3. Définis : **hybris**, **némésis**, **catharsis**, **chœur**.\n4. Qu'a laissé chacun de ces philosophes : **Socrate**, **Platon**, **Aristote** ?","bareme":[{"critere":"Fêtes de Dionysos, théâtre joué devant des milliers de citoyens","points":3},{"critere":"Tragédie et comédie distinguées avec leurs auteurs","points":5},{"critere":"Quatre notions définies exactement","points":7},{"critere":"Socrate, Platon, Aristote : apport de chacun","points":5}],"dureeMin":8,"corrige":"1. Le théâtre naît des **fêtes de Dionysos**. Il se joue en plein jour, à ciel ouvert, **devant des milliers de citoyens** : c'est une institution de la cité.\n2. La **tragédie** met en scène la chute d'un héros pris dans un destin qui le dépasse (**Eschyle, Sophocle, Euripide**). La **comédie** met en scène la vie politique de la cité, raillée sans ménagement (**Aristophane**).\n3. **Hybris** : la démesure, le héros franchit la limite humaine. **Némésis** : le châtiment que l'hybris appelle. **Catharsis** : la purgation des passions éprouvée par le spectateur. **Chœur** : il commente l'action et fait le lien avec le public.\n4. **Socrate** (470-399 av. J.-C.) n'écrit rien : il interroge (maïeutique) et meurt condamné par la cité. **Platon**, son disciple, fonde l'**Académie** et écrit les *Dialogues*. **Aristote**, disciple de Platon, fonde le **Lycée** et classe l'ensemble des savoirs."}$exo$::jsonb),
  ('9ed4e986-0250-5e48-9f4c-e3b1db8a1226'::uuid, 2, 'traduction', $exo${"titre":"La chute de Créon","consigne":"Lis le résumé, puis réponds aux questions en employant les notions du cours.","enonce":"**Document – Résumé d'une tragédie de Sophocle, *Antigone***\n\n> Créon, roi de Thèbes, interdit d'enterrer Polynice, qui a combattu contre la cité. Antigone, sa sœur, l'enterre malgré tout, au nom des lois des dieux. Créon la condamne et refuse d'écouter son fils, le devin Tirésias et les vieillards de Thèbes, qui chantent entre les scènes et l'avertissent. Quand il cède enfin, il est trop tard : Antigone s'est donné la mort, son fils puis sa femme se tuent à leur tour. Créon reste seul, brisé.\n\n1. À quel genre appartient cette pièce ? Justifie avec la définition du cours.\n2. En quoi consiste l'**hybris** de Créon ? Quelle est sa **némésis** ?\n3. Quel rôle jouent les vieillards de Thèbes ? Nomme ce personnage collectif.\n4. Que peut éprouver le spectateur athénien devant ce spectacle ? Nomme la notion.","bareme":[{"critere":"Tragédie justifiée : chute d'un héros pris dans un destin qui le dépasse","points":4},{"critere":"Hybris (démesure, refus de toute limite) et némésis (perte des siens) identifiées","points":7},{"critere":"Chœur nommé, rôle de commentaire et de lien avec le public","points":4},{"critere":"Catharsis définie et appliquée au spectateur","points":5}],"dureeMin":12,"corrige":"1. C'est une **tragédie** : elle met en scène la **chute d'un héros** (Créon, roi de Thèbes) pris dans un destin qui le dépasse. Son auteur, **Sophocle**, est l'un des trois grands tragiques avec Eschyle et Euripide.\n2. L'**hybris** de Créon est sa **démesure** : il place sa décision au-dessus des lois des dieux et refuse d'écouter tous les avertissements, franchissant la limite humaine. Sa **némésis**, le châtiment que l'hybris appelle, est la mort d'Antigone, de son fils et de sa femme : il reste seul, brisé. Il n'est pas puni parce qu'il est méchant, mais parce qu'il a dépassé sa mesure.\n3. Les vieillards de Thèbes forment le **chœur** : ils **commentent l'action** et font le **lien avec le public**, ici en avertissant Créon.\n4. Le spectateur éprouve la **catharsis** : la **purgation des passions** (la pitié et la crainte que suscite la chute du héros)."}$exo$::jsonb),
  ('9ed4e986-0250-5e48-9f4c-e3b1db8a1226'::uuid, 3, 'traduction', $exo${"titre":"Deux inventions, une question","consigne":"Rédige un développement organisé d'une vingtaine de lignes, appuyé sur des exemples précis du cours.","enonce":"**Document**\n\n> « Le théâtre et la philosophie naissent dans la même cité, à la même époque, et posent la même question : comment vivre juste dans une cité imparfaite ? L'un la met en scène, l'autre l'argumente. »\n\n**Sujet.** Explique et illustre cette affirmation. Tu montreras :\n1. que le théâtre est une affaire de la cité, et comment la tragédie et la comédie interrogent la conduite humaine ;\n2. comment la philosophie, de Socrate à Aristote, cherche la règle qui préserve de la démesure ;\n3. ce que la condamnation de Socrate révèle des rapports entre la cité et ceux qui la questionnent ;\n4. ce que les deux inventions supposent de la cité.","bareme":[{"critere":"Théâtre civique (Dionysos, milliers de citoyens), tragédie et comédie avec auteurs","points":4},{"critere":"Mécanique hybris → némésis expliquée, catharsis et chœur mobilisés","points":5},{"critere":"Socrate, Platon, Aristote : apports justes (maïeutique, Académie, Lycée)","points":4},{"critere":"Condamnation de Socrate et condition commune (mettre publiquement en question) analysées","points":5},{"critere":"Développement organisé et rédigé","points":2}],"dureeMin":20,"corrige":"1. **Le théâtre** : né des **fêtes de Dionysos**, joué en plein jour devant des **milliers de citoyens**, c'est une **institution civique**. La **tragédie** (Eschyle, Sophocle, Euripide) montre la chute d'un héros : l'enchaînement **hybris → némésis** n'est pas une morale plaquée mais la mécanique même du genre ; le héros est puni pour avoir **dépassé sa mesure**. Le **chœur** commente l'action ; le spectateur éprouve la **catharsis**. La **comédie** (Aristophane) raille sans ménagement la vie politique : la cité rit d'elle-même.\n2. **La philosophie** : **Socrate** (470-399 av. J.-C.) n'écrit rien, il **interroge** (maïeutique) ; **Platon**, son disciple, fonde l'**Académie** et écrit les *Dialogues* ; **Aristote** fonde le **Lycée** et classe les savoirs. Là où le théâtre **montre** l'homme aux prises avec la démesure, la philosophie **cherche la règle** qui l'en préserve.\n3. **Socrate condamné par la cité** : la cité qui invente le questionnement public peut aussi punir celui qui questionne ; la cité juste n'est pas donnée, elle reste imparfaite — c'est exactement la question posée.\n4. **Une même condition** : les deux supposent une cité où l'on peut, **publiquement**, **mettre en question ce qui va de soi** (sur scène comme dans le dialogue).\n\n**Conclusion attendue** : deux formes, la mise en scène et l'argumentation, pour une même exigence."}$exo$::jsonb),
  ('26155276-3b14-553d-97de-85e5d4e5a28a'::uuid, 1, 'redaction', $exo${"titre":"Les cinq grandes périodes","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite dans l'ordre les **cinq grandes périodes** de l'histoire et, pour chacune, l'événement ou la date qui l'ouvre.\n2. À quelles années correspond le **XVIIIe siècle** ?\n3. Donne la définition d'une **source** en histoire et cite deux types de sources différents.","bareme":[{"critere":"Les cinq périodes dans l'ordre avec leurs bornes (écriture, 476, 1492, 1789)","points":10},{"critere":"Bornes exactes du XVIIIe siècle (1701-1800)","points":4},{"critere":"Définition d'une source et deux types cités","points":6}],"dureeMin":7,"corrige":"1. **Préhistoire** (des premiers hommes à l'invention de l'écriture, vers 3300 av. J.-C.) → **Antiquité** (de l'écriture à la chute de l'Empire romain d'Occident en **476**) → **Moyen Âge** (de 476 à **1492**, arrivée de Colomb en Amérique) → **Époque moderne** (de 1492 à **1789**, la Révolution française) → **Époque contemporaine** (depuis 1789, elle n'est pas close).\n2. Le XVIIIe siècle va de **1701 à 1800** (un siècle = cent ans, le premier siècle commence en l'an 1).\n3. Une **source** est une **trace du passé** sur laquelle l'historien travaille. Types : **écrite** (lois, lettres, journaux), **matérielle** (fouilles, monuments), **orale** (témoignages), **iconographique** (images, peintures). Deux suffisent."}$exo$::jsonb),
  ('26155276-3b14-553d-97de-85e5d4e5a28a'::uuid, 2, 'redaction', $exo${"titre":"Critiquer une source avant de la croire","consigne":"Lis le document puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Document – Une lettre retrouvée dans des archives**\n\n> En 1789, Camille, avocat parisien, écrit à son frère resté en province : « Tout Paris est dans la rue, le peuple a pris la Bastille, jamais on n'a vu pareille joie. »\n\n1. De quel **type de source** s'agit-il ? À quelle **période** de l'histoire appartient-elle ? Justifie.\n2. Applique à ce document les quatre questions de la **critique des sources** (qui parle, quand, pour qui, pourquoi).\n3. Pourquoi l'historien ne peut-il pas considérer que « tout Paris » était dans la rue ?","bareme":[{"critere":"Source écrite, époque contemporaine justifiée par la date 1789","points":5},{"critere":"Les quatre questions de la critique appliquées au document","points":10},{"critere":"Limite du témoignage expliquée (point de vue, exagération)","points":5}],"dureeMin":10,"corrige":"1. C'est une **source écrite** (une lettre). Elle date de 1789 : c'est la borne qui ouvre l'**époque contemporaine** (on peut aussi accepter qu'elle se situe à la charnière entre époque moderne et contemporaine).\n2. **Qui parle ?** Camille, un avocat parisien, donc un bourgeois instruit, témoin direct. **Quand ?** En 1789, au moment des faits. **Pour qui ?** Son frère : une lettre privée, pas un texte officiel. **Pourquoi ?** Pour raconter et partager son enthousiasme.\n3. Le témoin donne **son point de vue** et son émotion : « tout Paris » et « jamais on n'a vu » sont des **exagérations**. Il n'a pas pu tout voir. L'historien doit **croiser** cette lettre avec d'autres sources (rapports de police, journaux, registres) avant de conclure."}$exo$::jsonb),
  ('26155276-3b14-553d-97de-85e5d4e5a28a'::uuid, 3, 'redaction', $exo${"titre":"Une période, un outil discutable","consigne":"Rédige une réponse organisée en deux paragraphes, en t'appuyant sur des exemples précis du cours.","enonce":"**Document – Un historien s'interroge**\n\n> « Nos périodes ne sont pas écrites dans le passé : ce sont nos découpages. Pourquoi faire finir l'Antiquité en 476 plutôt qu'en 410 ou en 622 ? Et que dit 1492 à un paysan chinois ? »\n\n**Sujet :** En t'appuyant sur ce document et sur le cours, montre que le découpage de l'histoire en cinq périodes est un **outil utile**, mais aussi une **construction discutable**.","bareme":[{"critere":"Présentation des cinq périodes et de leur utilité pour penser le temps","points":5},{"critere":"Choix d'un événement-borne discuté (476 contre 410 ou 622)","points":4},{"critere":"Découpage né en Europe au XIXe siècle, mal adapté à la Chine, l'Afrique, les Amériques","points":5},{"critere":"Idée qu'une période se juge à ce qu'elle fait comprendre, pas à sa vérité","points":3},{"critere":"Réponse organisée en deux paragraphes, vocabulaire juste","points":3}],"dureeMin":18,"corrige":"**Un outil utile.** Les historiens découpent le temps en cinq périodes : Préhistoire (jusqu'à l'écriture, vers 3300 av. J.-C.), Antiquité (jusqu'en 476), Moyen Âge (jusqu'en 1492), époque moderne (jusqu'en 1789), époque contemporaine. Ce découpage permet de **se repérer**, de comparer, de nommer des ensembles cohérents. Les mots du temps (siècle, millénaire, av./apr. J.-C.) complètent cet outillage.\n\n**Une construction discutable.** Les bornes sont **choisies** : 476 (chute de l'Empire romain d'Occident) aurait pu être 410 (sac de Rome) ou 622 : choisir un événement, c'est décider où est la rupture. Surtout, ce découpage est **né en Europe au XIXe siècle** : 476 ou 1492 éclairent l'histoire européenne, mais **mal celle de la Chine, de l'Afrique ou des Amériques**, qui ont leurs évolutions propres. Même le repère av./apr. J.-C. est un choix chrétien devenu conventionnel.\n\n**Conclusion attendue :** une période **n'est pas un fait mais un outil** ; on la juge à ce qu'elle permet de comprendre, pas à sa vérité."}$exo$::jsonb),
  ('bd311e14-3447-5384-996b-66de05d4315b'::uuid, 1, 'redaction', $exo${"titre":"Les réformateurs d'Athènes","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu'est-ce qu'une **cité** grecque ? Cite ses trois éléments (acropole, agora, chôra) en définissant chacun.\n2. Complète : en **621** av. J.-C., Dracon… ; en **594**, Solon… ; en **508-507**, Clisthène…\n3. Qui sont les **citoyens** athéniens après la loi de Périclès de 451 ?","bareme":[{"critere":"Définition de la cité et de ses trois éléments","points":6},{"critere":"L'apport exact de Dracon, Solon et Clisthène","points":9},{"critere":"Définition du citoyen (homme, adulte, né de parents athéniens)","points":5}],"dureeMin":7,"corrige":"1. Une **cité** est un État indépendant formé d'un centre urbain, d'un territoire et d'institutions propres. L'**acropole** est la ville haute, celle des dieux ; l'**agora** la place publique ; la **chôra** la campagne alentour.\n2. **Dracon** (621) fait **écrire les lois**, qui cessent d'être le secret des nobles. **Solon** (594) **abolit l'esclavage pour dettes** et classe les citoyens selon leur **richesse** et non leur naissance. **Clisthène** (508-507) redécoupe la cité en **dèmes** groupés en **dix tribus** mêlant côte, ville et intérieur, crée la **Boulè des 500** tirée au sort et l'**ostracisme**.\n3. Un citoyen est un **homme**, **adulte**, **né de père et de mère athéniens** (loi de Périclès, 451)."}$exo$::jsonb),
  ('bd311e14-3447-5384-996b-66de05d4315b'::uuid, 2, 'redaction', $exo${"titre":"Clisthène brise les fidélités","consigne":"Lis le document puis réponds aux questions en justifiant avec le cours.","enonce":"**Document – La réforme de Clisthène (508-507 av. J.-C.)**\n\n> Clisthène répartit les Athéniens en dix tribus. Chaque tribu réunit des dèmes de la côte, de la ville et de l'intérieur. Chaque tribu tire au sort cinquante citoyens pour siéger à la Boulè.\n\n1. Combien de membres compte la **Boulè** ? Montre le calcul à partir du document.\n2. Pourquoi mêler dans une même tribu des dèmes de la côte, de la ville et de l'intérieur ?\n3. En quoi le **tirage au sort** et l'**ostracisme** affaiblissent-ils les grandes familles aristocratiques ?","bareme":[{"critere":"Calcul juste : 10 tribus × 50 = 500 bouleutes","points":4},{"critere":"Explication : briser les fidélités locales et familiales","points":8},{"critere":"Rôle du tirage au sort et de l'ostracisme contre l'aristocratie","points":8}],"dureeMin":10,"corrige":"1. 10 tribus × 50 citoyens = **500** membres : c'est la **Boulè des 500**.\n2. Avant Clisthène, les Athéniens se regroupaient par régions et autour des grandes familles nobles qui y dominaient. En mêlant dans chaque tribu des dèmes de la côte, de la ville et de l'intérieur, Clisthène **brise les fidélités locales et familiales** : une tribu n'est plus le fief d'un clan, les citoyens apprennent à agir ensemble à l'échelle de toute la cité.\n3. Le **tirage au sort** fait que le conseil n'est plus réservé aux riches ou aux nobles : il **échappe aux grandes familles**. L'**ostracisme** permet d'**exiler dix ans** un citoyen jugé menaçant, par exemple un aristocrate trop puissant qui voudrait devenir tyran. Chaque mesure retire du pouvoir à la naissance pour le donner à la loi."}$exo$::jsonb),
  ('bd311e14-3447-5384-996b-66de05d4315b'::uuid, 3, 'redaction', $exo${"titre":"Un siècle et demi pour inventer la démocratie","consigne":"Rédige un développement organisé (introduction courte, deux parties, conclusion) en citant dates et acteurs précis.","enonce":"**Sujet :** « La démocratie athénienne n'est pas tombée du ciel. » Montre comment, de **621 à 508-507 av. J.-C.**, une série de réformes met en place un contexte favorable à la démocratie, puis explique **les limites** de cette démocratie.\n\n**Aide :** pense au passage du pouvoir de la naissance à la loi, et à la composition réelle de la population d'Athènes.","bareme":[{"critere":"Réformes de Dracon, Solon et Pisistrate datées et expliquées","points":6},{"critere":"Réforme de Clisthène : dèmes, dix tribus, Boulè, ostracisme","points":5},{"critere":"Idée directrice : le pouvoir passe de la naissance à la loi","points":3},{"critere":"Limites : femmes, métèques, esclaves exclus, majorité de la population","points":4},{"critere":"Organisation du développement et rédaction","points":2}],"dureeMin":20,"corrige":"**Introduction.** Au VIIe siècle av. J.-C., Athènes est dominée par une aristocratie foncière. En un siècle et demi, des réformes transforment la cité.\n\n**I. Des réformes qui retirent le pouvoir à la naissance.**\n- **Dracon (621)** fait **écrire les lois** : elles cessent d'être le secret des nobles.\n- **Solon (594)** abolit l'**esclavage pour dettes**, ce qui sauve la petite paysannerie, et classe les citoyens selon leur **richesse**, non leur naissance.\n- **Pisistrate** (tyran, 561-527) affaiblit l'**aristocratie foncière** et développe les fêtes civiques qui soudent la cité.\n- **Clisthène (508-507)** redécoupe la cité en **dèmes** et **dix tribus** artificielles mêlant côte, ville et intérieur (fin des fidélités locales), crée la **Boulè des 500** tirée au sort et l'**ostracisme**.\n→ Chaque réforme retire du pouvoir à la naissance pour le donner à la **loi**.\n\n**II. Une démocratie limitée.** Est citoyen un homme adulte né de parents athéniens (loi de **Périclès, 451**). Sont exclus : les **femmes**, les **métèques** (étrangers libres), les **esclaves**. Ces exclus forment **la grande majorité** de la population.\n\n**Conclusion.** Athènes invente le gouvernement des citoyens par la loi, mais d'une minorité d'hommes libres."}$exo$::jsonb),
  ('ac5c939a-baae-5da3-b2d1-8866a527c42a'::uuid, 1, 'redaction', $exo${"titre":"Les institutions d'Athènes","consigne":"Réponds en complétant ou en rédigeant une phrase pour chaque institution.","enonce":"Pour chacune des quatre institutions athéniennes du Ve siècle av. J.-C., indique **sa composition** (et comment ses membres sont désignés) et **son rôle** :\n\n1. L'**Ecclésia**\n2. La **Boulè**\n3. L'**Héliée**\n4. Les **stratèges**\n\n5. Qu'est-ce que le **misthos** et qui l'instaure ?","bareme":[{"critere":"Composition, désignation et rôle justes des quatre institutions","points":14},{"critere":"Définition du misthos et rôle de Périclès","points":6}],"dureeMin":8,"corrige":"1. **Ecclésia** : tous les citoyens, réunis sur la **Pnyx** une quarantaine de fois par an ; elle **vote les lois, la guerre, la paix**.\n2. **Boulè** : 500 citoyens **tirés au sort** ; elle **prépare les séances** de l'Ecclésia.\n3. **Héliée** : des jurés **tirés au sort** ; elle **juge**.\n4. Les dix **stratèges** : **élus** (et non tirés au sort) ; ils **commandent** l'armée et la flotte. Périclès l'est quinze fois de suite.\n5. Le **misthos** est une **indemnité** versée aux citoyens qui exercent une charge (magistrats, juges). Il est instauré par **Périclès** : un artisan peut siéger sans perdre sa journée de travail."}$exo$::jsonb),
  ('ac5c939a-baae-5da3-b2d1-8866a527c42a'::uuid, 2, 'redaction', $exo${"titre":"Salamine et les rameurs","consigne":"Réponds aux questions en justifiant avec le cours.","enonce":"**Document – Les guerres médiques**\n\n| Bataille | Date |\n|---|---|\n| Marathon | 490 av. J.-C. |\n| Salamine | 480 av. J.-C. |\n| Platées | 479 av. J.-C. |\n\n1. Contre qui les Grecs combattent-ils ? Quelle bataille est la victoire **navale** décisive ?\n2. Qui rame sur les trières athéniennes ? Pourquoi la victoire de Salamine renforce-t-elle leur place dans la cité ?\n3. Explique en quoi le **misthos** rend l'égalité politique réelle pour ces citoyens pauvres.","bareme":[{"critere":"Les Perses ; Salamine (480) comme victoire navale décisive","points":5},{"critere":"Les thètes, rameurs devenus indispensables, donc écoutés à l'assemblée","points":8},{"critere":"Misthos : indemnité qui permet aux pauvres de siéger","points":7}],"dureeMin":10,"corrige":"1. Les Grecs combattent les **Perses**. **Salamine (480)** est la victoire **navale** décisive ; Marathon (490) est la première victoire terrestre et Platées (479) met fin à l'invasion.\n2. Les rameurs sont les **thètes**, les **citoyens les plus pauvres**. Salamine doit tout à la flotte, donc à eux : ils deviennent **indispensables** à la défense de la cité, et on les **écoute** davantage à l'Ecclésia. La puissance navale renforce la démocratie.\n3. Participer à l'Héliée ou à une magistrature prend du temps. Sans indemnité, seuls les riches pourraient siéger. Le **misthos**, créé par Périclès, dédommage le citoyen : un artisan peut siéger **sans perdre sa journée**. L'égalité politique (isonomie, isègoria) cesse d'être seulement théorique."}$exo$::jsonb),
  ('ac5c939a-baae-5da3-b2d1-8866a527c42a'::uuid, 3, 'redaction', $exo${"titre":"Démocratie dedans, empire dehors","consigne":"Rédige un développement argumenté en deux parties, avec dates et exemples précis.","enonce":"**Document – Plutarque, Vie de Périclès (IIe siècle apr. J.-C.)**\n\n> « Ce qui procura le plus de plaisir aux Athéniens, ce furent les monuments. […] Mais les ennemis de Périclès criaient que le peuple se déshonorait en transportant à Athènes le trésor commun des Grecs, déposé à Délos. »\n\n**Sujet :** Au Ve siècle av. J.-C., montre qu'Athènes est à la fois **une démocratie** et **un empire maritime**, et que les deux sont liés.","bareme":[{"critere":"Fonctionnement démocratique : institutions, tirage au sort, isonomie, misthos","points":6},{"critere":"Ligue de Délos (478), transfert du trésor (454), phoros","points":5},{"critere":"Lien : tribut qui finance Parthénon et flotte ; thètes rameurs","points":4},{"critere":"Répression des révoltes et guerre du Péloponnèse (431-404)","points":3},{"critere":"Utilisation du document et organisation","points":2}],"dureeMin":20,"corrige":"**I. Une démocratie.** Tous les citoyens votent les lois, la guerre et la paix à l'**Ecclésia** sur la Pnyx ; la **Boulè** des 500 et l'**Héliée** sont tirées au sort ; seuls les dix **stratèges** sont élus (Périclès quinze fois). **Isonomie** et **isègoria** : égalité devant la loi et droit égal à la parole. Le **misthos** permet aux pauvres de siéger.\n\n**II. Un empire maritime.** La **ligue de Délos** (478) est fondée pour défendre les Grecs contre les Perses. En **454**, le trésor est **transféré à Athènes** (c'est ce que dénoncent les ennemis de Périclès dans le document) : la ligue devient un instrument de domination. Les alliés paient un tribut, le **phoros** ; les cités qui se révoltent sont **écrasées**.\n\n**III. Le lien.** Le phoros finance le **Parthénon** et les monuments dont parle Plutarque, et la flotte ; la flotte fait vivre les **thètes**, rameurs et citoyens actifs de la démocratie. La démocratie profite de l'empire. Mais cette domination suscite la rivalité avec **Sparte** : la **guerre du Péloponnèse (431-404)** emporte la puissance athénienne.\n\n(Remarque critique attendue : Plutarque écrit plusieurs siècles après.)"}$exo$::jsonb),
  ('5bd4b4bd-27c8-5212-a4bc-8026b11f95d1'::uuid, 1, 'redaction', $exo${"titre":"Rome, de la République à l'Empire","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelles sont les dates de la **République** romaine ? Cite deux de ses institutions.\n2. Que se passe-t-il en **27 av. J.-C.** ? Comment appelle-t-on le régime qui commence ?\n3. Sous quel empereur l'Empire atteint-il son **extension maximale** ? Donne ses limites géographiques.\n4. Que décide l'**édit de Caracalla** en 212 ?","bareme":[{"critere":"République 509-27 av. J.-C. et deux institutions","points":5},{"critere":"Octave devient Auguste, le Principat","points":5},{"critere":"Trajan, de la Bretagne à l'Euphrate","points":5},{"critere":"Citoyenneté à presque tous les hommes libres","points":5}],"dureeMin":7,"corrige":"1. La République dure de **509 à 27 av. J.-C.** Institutions : le **Sénat**, les **magistratures**, les **comices** (deux suffisent).\n2. En **27 av. J.-C.**, **Octave** reçoit le nom d'**Auguste** et concentre les pouvoirs : c'est le début du **Principat** (l'Empire).\n3. Sous **Trajan** (98-117), l'Empire s'étend **de la Bretagne à l'Euphrate** (environ 60 millions d'habitants).\n4. L'**édit de Caracalla (212)** accorde la **citoyenneté romaine à presque tous les hommes libres** de l'Empire."}$exo$::jsonb),
  ('5bd4b4bd-27c8-5212-a4bc-8026b11f95d1'::uuid, 2, 'redaction', $exo${"titre":"Une ville romaine en Gaule","consigne":"Lis le document puis réponds en utilisant le vocabulaire du cours.","enonce":"**Document – Nemausus (Nîmes) au IIe siècle**\n\n> La ville a un plan régulier. On y trouve un forum avec un temple dédié au culte de l'empereur, des thermes, un amphithéâtre de plus de 20 000 places. Un aqueduc, qui franchit le Gardon par un pont, apporte l'eau. Une grande voie la relie à Rome et à l'Espagne. Les notables de la ville parlent latin et certains sont citoyens romains.\n\n1. Relève dans le document **quatre vecteurs de la romanisation**.\n2. Pourquoi les **élites locales** ont-elles intérêt à adopter le modèle romain ?\n3. Explique la phrase du cours : « Rome ne détruit pas les peuples conquis : elle en fait des Romains. »","bareme":[{"critere":"Quatre vecteurs relevés : ville et monuments, routes, latin, culte impérial","points":8},{"critere":"Intérêt des élites : droits, citoyenneté, diffusion du modèle","points":6},{"critere":"Explication de l'intégration des vaincus","points":6}],"dureeMin":11,"corrige":"1. Vecteurs de romanisation : la **ville** au plan régulier avec **forum, thermes, amphithéâtre, aqueduc** ; la **route** qui relie à Rome ; la **langue latine** ; le **culte impérial** (temple dédié à l'empereur) ; la **citoyenneté** de certains notables.\n2. Les élites locales y **gagnent des droits** : elles obtiennent progressivement la **citoyenneté romaine** (Ier-IIe siècles), des charges et du prestige. En retour, elles **diffusent** le modèle romain dans leur cité.\n3. Rome intègre les vaincus au lieu de les exterminer : elle leur donne ses villes, sa langue, son culte et, peu à peu, sa citoyenneté (jusqu'à l'**édit de Caracalla, 212**). Les Gaulois deviennent Gallo-Romains. Cette intégration, à son rythme et à ses conditions, explique la solidité de l'Empire et la **paix romaine**."}$exo$::jsonb),
  ('5bd4b4bd-27c8-5212-a4bc-8026b11f95d1'::uuid, 3, 'redaction', $exo${"titre":"Grandeur et fragilités de la paix romaine","consigne":"Rédige un développement organisé en deux ou trois parties, avec dates et exemples précis.","enonce":"**Sujet :** Comment Rome, cité du Latium, devient-elle maîtresse de la Méditerranée, qu'elle appelle *Mare Nostrum*, et quelles sont les **limites** de cette domination ?\n\n**Tu dois évoquer :** le passage de la République à l'Empire, la paix romaine et ses repères chiffrés, la romanisation et la citoyenneté, puis les fondements fragiles du système.","bareme":[{"critere":"De la République à l'Empire : conquêtes, guerres puniques, César, Auguste en 27 av. J.-C.","points":5},{"critere":"Paix romaine : durée, Trajan, 60 millions d'habitants","points":3},{"critere":"Romanisation et citoyenneté jusqu'à l'édit de Caracalla (212)","points":5},{"critere":"Limites : esclavage, limes, fiscalité, crise du IIIe siècle","points":5},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. D'une cité à un empire.** La **République** (509-27 av. J.-C.) repose sur le Sénat, les magistratures, les comices. Les conquêtes, dont les **guerres puniques** contre **Carthage**, enrichissent Rome mais la déchirent ; les guerres civiles mènent à la dictature de **César**, assassiné en **44**. En **27 av. J.-C.**, **Octave** devient **Auguste** : c'est le **Principat**.\n\n**II. La paix romaine et l'intégration.** De 27 av. J.-C. au IIe siècle, l'Empire vit en paix ; sous **Trajan** (98-117), il va de la Bretagne à l'Euphrate et compte environ **60 millions** d'habitants. La **romanisation** passe par la **ville** (forum, thermes, amphithéâtre, aqueducs), les **routes**, le **latin**, le **culte impérial** et les **élites locales**. La **citoyenneté** s'étend aux provinciaux (Ier-IIe siècles) puis à presque tous les hommes libres par l'**édit de Caracalla (212)**. Rome fait des vaincus des Romains.\n\n**III. Des fondements fragiles.** Le système repose sur l'**esclavage**, sur l'armée qui garde le **limes** et sur une **fiscalité lourde**. Au **IIIe siècle**, invasions, usurpations et crise monétaire ébranlent l'édifice.\n\n**Conclusion.** La réussite de Rome tient moins aux armes qu'à l'intégration des vaincus, mais elle repose sur des bases coûteuses."}$exo$::jsonb),
  ('5ed749ae-702f-5f8a-9c53-08b3913d13d6'::uuid, 1, 'redaction', $exo${"titre":"Constantin en quatre dates","consigne":"Pour chaque date, explique en une ou deux phrases ce qui se passe.","enonce":"Explique ce qui se passe à chacune de ces dates :\n\n1. **312**\n2. **313**\n3. **325**\n4. **330**\n5. Quelle différence y a-t-il entre ce que fait l'édit de Milan et ce que fait **Théodose** vers 380-392 ?","bareme":[{"critere":"Pont Milvius, édit de Milan, concile de Nicée, fondation de Constantinople","points":12},{"critere":"Liberté de culte (313) contre religion officielle (Théodose)","points":8}],"dureeMin":7,"corrige":"1. **312** : Constantin l'emporte à la bataille du **pont Milvius**.\n2. **313** : l'**édit de Milan** accorde la **liberté de culte** à tous, chrétiens compris.\n3. **325** : Constantin convoque le **concile de Nicée** pour trancher la querelle arienne sur la nature du Christ.\n4. **330** : fondation de **Constantinople** sur le site de Byzance.\n5. L'édit de Milan donne la **liberté de culte** mais **ne fait pas** du christianisme la religion officielle. C'est **Théodose**, vers **380-392**, qui fait du christianisme la **religion officielle** de l'Empire."}$exo$::jsonb),
  ('5ed749ae-702f-5f8a-9c53-08b3913d13d6'::uuid, 2, 'redaction', $exo${"titre":"Pourquoi Constantinople ?","consigne":"Observe les informations puis réponds en justifiant avec le cours.","enonce":"**Document – Le site de Byzance**\n\n> Byzance se dresse sur le détroit du Bosphore, qui sépare l'Europe de l'Asie et relie la mer Noire à la Méditerranée. Au IVe siècle, les frontières les plus menacées sont le Danube et l'Euphrate. Les provinces les plus riches et les plus peuplées sont en Orient : Égypte, Syrie, Asie Mineure.\n\n1. Relève **trois atouts** du site de Byzance.\n2. Explique pourquoi Constantin y fonde une nouvelle capitale en **330**.\n3. Que devient Constantinople après le partage de **395** ?","bareme":[{"critere":"Trois atouts relevés : entre Europe et Asie, détroits, proximité des frontières et des provinces riches","points":8},{"critere":"Explication : contrôle, réaction rapide, ressources","points":7},{"critere":"Capitale de l'empire d'Orient qui durera mille ans","points":5}],"dureeMin":10,"corrige":"1. Atouts : une position **entre Europe et Asie** ; le **contrôle des détroits** (Bosphore) ; la **proximité des frontières menacées** (Danube, Euphrate) ; la **proximité des riches provinces d'Orient**.\n2. Après la crise du IIIe siècle, l'Empire a besoin d'une capitale d'où l'empereur peut **réagir vite** aux attaques et **puiser dans les ressources** de l'Orient. Rome est loin des frontières et du cœur économique. Constantinople, fondée en **330**, permet de **contrôler** les échanges entre mer Noire et Méditerranée. C'est aussi une capitale nouvelle, chrétienne, au service d'un pouvoir renforcé.\n3. En **395**, l'Empire est partagé : Constantinople devient la **capitale de l'Empire d'Orient**, qui **durera mille ans** (jusqu'en 1453)."}$exo$::jsonb),
  ('5ed749ae-702f-5f8a-9c53-08b3913d13d6'::uuid, 3, 'redaction', $exo${"titre":"Refonder l'Empire au IVe siècle","consigne":"Rédige un développement organisé qui répond à la problématique, avec dates et exemples.","enonce":"**Document – Une inscription de l'arc de Constantin, Rome (315)**\n\n> « À l'empereur César Flavius Constantin […], parce que, par l'inspiration de la divinité et la grandeur de son esprit, il a vengé la République du tyran et de toute sa faction. »\n\n**Sujet :** Montre comment Constantin reconstruit l'Empire sur trois bases neuves : **un pouvoir renforcé**, **une religion soutenue**, **une capitale à l'Est**. Tu utiliseras le document.","bareme":[{"critere":"Contexte : crise du IIIe siècle, Dioclétien et la tétrarchie","points":4},{"critere":"Pouvoir renforcé : pont Milvius, règne seul dès 324, lecture du document","points":4},{"critere":"Religion : édit de Milan 313, soutien à l'Église, concile de Nicée 325","points":5},{"critere":"Constantinople (330) : atouts du site et partage de 395","points":4},{"critere":"Organisation, rédaction, distinction Constantin/Théodose","points":3}],"dureeMin":20,"corrige":"**Contexte.** Au **IIIe siècle**, l'Empire subit invasions, empereurs éphémères, effondrement monétaire. **Dioclétien** (284-305) établit la **tétrarchie** (quatre empereurs) et renforce l'administration.\n\n**I. Un pouvoir renforcé.** Constantin l'emporte au **pont Milvius (312)** ; l'arc de 315 présente sa victoire comme voulue par « la divinité » et comme une libération du « tyran » (Maxence) : c'est de la **propagande**. À partir de **324**, il règne **seul** : la tétrarchie n'a pas survécu.\n\n**II. Une religion soutenue.** L'**édit de Milan (313)** donne la liberté de culte à tous, chrétiens compris. Constantin **finance les églises**, **exempte le clergé**, arbitre les querelles et convoque le **concile de Nicée (325)** : l'Église et l'État se lient. Le christianisme passe de religion poursuivie à religion **protégée** — mais ce n'est **Théodose** qui en fera la religion officielle (380-392).\n\n**III. Une capitale à l'Est.** **Constantinople**, fondée en **330** sur le site de Byzance, entre Europe et Asie, contrôle les détroits, est proche des frontières menacées et des riches provinces d'Orient. En **395**, elle devient la capitale de l'Empire d'Orient, qui durera mille ans.\n\n**Conclusion.** L'Empire se refonde sur des bases nouvelles et chrétiennes."}$exo$::jsonb),
  ('e95ff08a-39a9-5560-951e-f5c0b7c79177'::uuid, 1, 'redaction', $exo${"titre":"Trois mondes autour d'une mer","consigne":"Réponds par un petit tableau ou des phrases complètes.","enonce":"1. Nomme les **trois civilisations** qui se partagent la Méditerranée au Moyen Âge et, pour chacune, **son ou ses centres**.\n2. Place dans l'ordre chronologique et explique en une phrase : **1099**, **1095**, **1291**, **1187**.\n3. Qu'est-ce que la **dhimma** ?","bareme":[{"critere":"Trois civilisations et leurs centres","points":6},{"critere":"Quatre dates remises dans l'ordre et expliquées","points":10},{"critere":"Définition de la dhimma","points":4}],"dureeMin":8,"corrige":"1. La **chrétienté latine** (centre : **Rome** ; Occident féodal) ; l'**Empire byzantin** (centre : **Constantinople**) ; l'**Islam** (centres : **Bagdad, Le Caire, Cordoue**).\n2. **1095** : à Clermont, le pape **Urbain II** appelle à délivrer Jérusalem. **1099** : la première croisade **prend Jérusalem** et fonde les États latins d'Orient. **1187** : **Saladin** reprend Jérusalem. **1291** : la chute d'**Acre** met fin à la présence latine.\n3. La **dhimma** est le statut qui **protège les non-musulmans** (juifs, chrétiens) en terre d'Islam, moyennant **un impôt** et un **statut inférieur**."}$exo$::jsonb),
  ('e95ff08a-39a9-5560-951e-f5c0b7c79177'::uuid, 2, 'redaction', $exo${"titre":"La croisade, guerre sainte et entreprise","consigne":"Lis le document puis réponds en justifiant avec le cours.","enonce":"**Document – Le discours d'Urbain II à Clermont (1095), d'après Foucher de Chartres**\n\n> « Que ceux qui étaient autrefois des brigands deviennent des soldats du Christ. […] Ceux qui étaient ici tristes et pauvres seront là-bas joyeux et riches. »\n\n1. Présente le document : auteur, date, lieu, objectif de l'appel.\n2. Relève dans le texte **un motif religieux** et **un motif matériel** de la croisade.\n3. Quels autres acteurs, selon le cours, trouvent un intérêt dans les croisades ? Pourquoi la **quatrième croisade** (1204) montre-t-elle que la croisade n'est pas qu'une guerre sainte ?","bareme":[{"critere":"Présentation : Urbain II, Clermont, 1095, délivrer Jérusalem","points":4},{"critere":"Un motif religieux et un motif matériel relevés et expliqués","points":6},{"critere":"Seigneurs sans terre, marchands, villes italiennes et comptoirs","points":5},{"critere":"1204 : pillage de Constantinople, chrétiens contre chrétiens","points":5}],"dureeMin":12,"corrige":"1. C'est l'appel du pape **Urbain II** à **Clermont** en **1095**, rapporté par le chroniqueur Foucher de Chartres. Il appelle les chrétiens d'Occident à **délivrer Jérusalem**.\n2. **Motif religieux** : devenir « soldats du Christ », mener une **guerre sainte** qui rachète les péchés. **Motif matériel** : les pauvres seront « là-bas joyeux et riches » : l'espoir de terres et de richesses.\n3. La croisade est aussi une entreprise de **seigneurs sans terre**, de **marchands** et de **villes italiennes** (Venise, Gênes, Pise) qui y gagnent des **comptoirs**. En **1204**, la quatrième croisade **pille Constantinople**, cité chrétienne : des chrétiens contre des chrétiens. L'appât du gain et les intérêts (notamment vénitiens) l'emportent sur le but religieux."}$exo$::jsonb),
  ('e95ff08a-39a9-5560-951e-f5c0b7c79177'::uuid, 3, 'redaction', $exo${"titre":"Se combattre sans cesser de se parler","consigne":"Rédige un développement organisé en deux parties, avec des exemples datés et localisés.","enonce":"**Sujet :** « Au Moyen Âge, la Méditerranée n'appartient plus à personne. Trois ensembles s'y font face, se combattent — et ne cessent jamais de se parler. »\n\nExplique cette phrase en montrant que la Méditerranée médiévale est à la fois un **espace de conflits** et un **espace de coexistence**.","bareme":[{"critere":"Présentation des trois civilisations et de leurs centres","points":3},{"critere":"Les croisades datées (1095, 1099, 1187, 1204, 1291)","points":5},{"critere":"La Reconquista (Tolède 1085, Las Navas 1212, Grenade 1492) et la Sicile","points":4},{"critere":"Coexistence : Sicile normande, Espagne des trois religions, États latins, dhimma","points":6},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**Introduction.** Trois ensembles : la **chrétienté latine** (Rome, Occident féodal), l'**Empire byzantin** (Constantinople), l'**Islam** (Bagdad, Le Caire, Cordoue), chacun se pensant au centre du monde.\n\n**I. Un espace de conflits.**\n- **Croisades** : appel d'Urbain II à Clermont (**1095**), prise de Jérusalem (**1099**) et fondation des États latins d'Orient, reprise par **Saladin (1187)**, pillage de Constantinople par la quatrième croisade (**1204**), chute d'**Acre (1291)**.\n- **Reconquista** en Espagne : Tolède (**1085**), Las Navas de Tolosa (**1212**), Grenade (**1492**).\n- Les **Normands** prennent le pouvoir en **Sicile**, île arabe.\n\n**II. Un espace de coexistence.**\n- En **Sicile normande**, chrétiens, musulmans et juifs cohabitent, commercent, se traduisent.\n- Dans l'**Espagne des trois religions**, même chose sous domination changeante.\n- Dans les **États latins**, les Francs vivent au contact des populations locales.\n- En terre d'Islam, la **dhimma** protège juifs et chrétiens, moyennant un impôt et un statut inférieur : une tolérance inégale.\n\n**Conclusion.** Guerre et échanges coexistent : la Méditerranée est une frontière disputée mais aussi un lieu de contact permanent."}$exo$::jsonb),
  ('044ba34c-8578-540a-9297-c74e8013df33'::uuid, 1, 'redaction', $exo${"titre":"Les outils du marchand","consigne":"Réponds par des phrases courtes et précises.","enonce":"1. Quelles cités italiennes dominent le grand commerce méditerranéen ? Qu'est-ce qu'un **fondouk** ?\n2. Explique à quoi sert chacune de ces innovations : la **lettre de change**, l'**assurance maritime**, la **commende**.\n3. D'où viennent les **chiffres dits arabes** ?","bareme":[{"critere":"Venise, Gênes, Pise et définition du fondouk","points":6},{"critere":"Rôle juste des trois innovations","points":9},{"critere":"Origine indienne transmise par le monde musulman","points":5}],"dureeMin":7,"corrige":"1. **Venise, Gênes et Pise**. Un **fondouk** est un **comptoir marchand** (entrepôt et logement) installé dans un port étranger, en Orient ou en Afrique du Nord.\n2. La **lettre de change** permet de **payer sans transporter d'or**. L'**assurance maritime** **répartit le risque** du naufrage. La **commende** **associe un bailleur de fonds** (qui avance l'argent) et **un voyageur** (qui part commercer).\n3. Les chiffres dits arabes viennent de l'**Inde** ; ils ont été **transmis par le monde musulman** et simplifient le calcul."}$exo$::jsonb),
  ('044ba34c-8578-540a-9297-c74e8013df33'::uuid, 2, 'redaction', $exo${"titre":"Un navire vénitien à Alexandrie","consigne":"Lis la situation puis réponds en utilisant le vocabulaire du cours.","enonce":"**Situation.** En 1250, Marco, marchand vénitien, s'associe à un riche banquier qui lui avance l'argent du voyage. Il charge à Venise des draps, du métal et du bois, et débarque à Alexandrie où il loge dans le comptoir des Vénitiens. Il y achète du poivre, de la soie et du sucre. Pour ne pas transporter son or, il paie avec un papier que le banquier honorera à Venise. Il fait assurer sa cargaison.\n\n1. Relève et **nomme** trois techniques marchandes utilisées par Marco.\n2. Que **vend** et qu'**achète** Marco ? Qu'en déduis-tu des productions de l'Occident et de l'Orient ?\n3. Pourquoi peut-on dire qu'un port comme Alexandrie est un lieu d'échanges au-delà des seules marchandises ?","bareme":[{"critere":"Commende, fondouk, lettre de change, assurance maritime identifiées","points":7},{"critere":"Ventes et achats classés et interprétés","points":6},{"critere":"Circulation des langues, monnaies, savoirs et mots","points":7}],"dureeMin":11,"corrige":"1. L'association avec le banquier est une **commende** ; le comptoir vénitien est un **fondouk** ; le papier de paiement est une **lettre de change** ; la cargaison est couverte par l'**assurance maritime** (trois suffisent).\n2. Marco **vend** des **draps, métaux, bois** et **achète** des **épices (poivre), soie, sucre**. L'Occident exporte des produits bruts ou artisanaux ; l'Orient fournit des produits de luxe venus d'Asie par les caravanes.\n3. Dans un port méditerranéen du XIIIe siècle, **on parle quatre langues et on change six monnaies** : des marchands de toutes origines s'y rencontrent. Y circulent aussi des **techniques** (papier, boussole, astrolabe), des **savoirs** (traductions d'Avicenne, d'Aristote) et des **mots** : douane, tarif, magasin, amiral viennent de l'arabe."}$exo$::jsonb),
  ('044ba34c-8578-540a-9297-c74e8013df33'::uuid, 3, 'redaction', $exo${"titre":"Marchandises, mots et savoirs","consigne":"Rédige un développement organisé en deux ou trois parties, avec des exemples précis.","enonce":"**Document – Quelques mots français et leur origine**\n\n| Mot français | Origine |\n|---|---|\n| amiral | arabe *amir al-* (chef de) |\n| douane | arabe *diwan* (registre) |\n| algèbre | arabe *al-jabr* |\n| magasin | arabe *makhazin* (entrepôts) |\n\n**Sujet :** Montre que la Méditerranée médiévale est un **espace de circulation** avant d'être une frontière : circulation des **marchandises**, des **techniques**, des **savoirs** et des **mots**.","bareme":[{"critere":"Commerce : cités italiennes, fondouks, produits échangés, caravanes","points":5},{"critere":"Outils du marchand et techniques venues d'Orient (papier, boussole, astrolabe, gouvernail)","points":4},{"critere":"Savoirs : Avicenne, Averroès, al-Khwarizmi ; traductions à Tolède, Palerme","points":5},{"critere":"Cultures et mots venus de l'arabe, exploitation du document","points":4},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. Les marchandises.** **Venise, Gênes et Pise** installent des **fondouks** dans les ports d'Orient et d'Afrique du Nord. Elles achètent **épices, soie, alun, sucre, esclaves** et vendent **draps, métaux, bois, armes** ; les caravanes relient ces ports à l'Asie et au Sahara. Le marchand dispose de la **lettre de change**, de la **comptabilité en partie double**, de l'**assurance maritime**, de la **commende** et des **chiffres dits arabes**.\n\n**II. Les techniques et les savoirs.** Passent en Occident le **papier**, la **boussole**, l'**astrolabe**, le **gouvernail d'étambot** ; des cultures comme le **coton, le sucre de canne, les agrumes**. Les savants du monde musulman — **Avicenne** (médecine), **Averroès** (commentaire d'Aristote), **al-Khwarizmi** (algèbre) — sont traduits de l'arabe au latin à **Tolède**, à **Palerme** et Salerne : l'Occident redécouvre **Aristote, Galien, Ptolémée**.\n\n**III. Les mots.** Le document montre que des mots du quotidien (**amiral, douane, algèbre, magasin**) viennent de l'arabe : les emprunts concernent la mer, le commerce, l'administration et la science, précisément les domaines de l'échange.\n\n**Conclusion.** Pendant qu'on se bat, on commerce, on traduit et on copie."}$exo$::jsonb),
  ('6dfdfe12-5572-5ecb-88c8-91ff017ba523'::uuid, 1, 'redaction', $exo${"titre":"Les grands voyages","consigne":"Réponds par des phrases complètes.","enonce":"1. Associe chaque navigateur à son exploit et à sa date : **Bartolomeu Dias**, **Christophe Colomb**, **Vasco de Gama**, **Magellan**.\n2. Cite **deux instruments ou navires** qui rendent ces voyages possibles et dis ce qu'ils apportent.\n3. Que décide le **traité de Tordesillas** (1494) ?","bareme":[{"critere":"Quatre navigateurs, exploits et dates exacts","points":10},{"critere":"Deux moyens techniques et leur apport","points":5},{"critere":"Partage du monde entre Castille et Portugal","points":5}],"dureeMin":8,"corrige":"1. **Dias (1487)** passe le **cap de Bonne-Espérance**. **Colomb (12 octobre 1492)**, pour la Castille, touche les **Antilles** en croyant avoir atteint l'Asie. **Vasco de Gama (1498)** atteint l'**Inde** par la mer. **Magellan (1519-1522)**, puis Elcano, réalise le **premier tour du monde**.\n2. La **caravelle** (légère, elle peut remonter au vent) ; la **boussole** (la direction même sans étoiles) ; l'**astrolabe** (la latitude) ; le **portulan** (les côtes et les caps). Deux suffisent.\n3. Le traité de **Tordesillas** trace une ligne dans l'Atlantique : l'**ouest à la Castille**, l'**est au Portugal** — d'où le **Brésil portugais**."}$exo$::jsonb),
  ('6dfdfe12-5572-5ecb-88c8-91ff017ba523'::uuid, 2, 'redaction', $exo${"titre":"Pourquoi prendre la mer ?","consigne":"Lis le document puis réponds en t'appuyant sur le cours.","enonce":"**Document – Journal de bord de Christophe Colomb (1492)**\n\n> « Vos Altesses, en tant que catholiques et princes ennemis de la secte de Mahomet, ont pensé m'envoyer, moi, Christophe Colomb, aux Indes […] pour voir de quelle manière on pourrait les convertir à notre sainte foi. » Et plus loin : « Je m'efforçais de savoir s'il y avait de l'or. »\n\n1. Pour quels souverains Colomb voyage-t-il ? Où croit-il aller ?\n2. Relève **deux motifs** des voyages dans le document et ajoute-en **un autre** tiré du cours.\n3. Explique pourquoi la **prise de Constantinople en 1453** pousse les Européens à chercher une route maritime vers l'Asie.","bareme":[{"critere":"Souverains de Castille et but : les Indes (l'Asie)","points":4},{"critere":"Deux motifs relevés (évangélisation, or) et un troisième du cours","points":9},{"critere":"Route de la soie contrôlée par les Ottomans après 1453","points":7}],"dureeMin":11,"corrige":"1. Colomb voyage pour les **souverains de Castille** (les Rois catholiques). Il croit aller aux **Indes**, c'est-à-dire en **Asie**, par l'ouest.\n2. Dans le document : l'**évangélisation** (« les convertir à notre sainte foi ») et la recherche de l'**or**. Du cours : la **curiosité savante** nourrie par l'humanisme et Ptolémée, ou la **rivalité** entre le Portugal et la Castille, ou les **épices**.\n3. Depuis la **prise de Constantinople par les Ottomans (1453)**, la **route de la soie** et des épices est **contrôlée par les Ottomans**, qui prélèvent des taxes. Les Européens cherchent donc à **atteindre directement l'Asie par la mer**, en contournant l'Afrique (Portugais) ou en traversant l'Atlantique (Colomb)."}$exo$::jsonb),
  ('6dfdfe12-5572-5ecb-88c8-91ff017ba523'::uuid, 3, 'redaction', $exo${"titre":"On ne découvre pas un monde par accident","consigne":"Rédige un développement organisé en trois parties, avec dates et exemples.","enonce":"**Sujet :** « On ne découvre pas un monde par accident : on l'atteint parce qu'un État paie, qu'une technique existe et qu'un profit est espéré. »\n\nEn t'appuyant sur le cours, explique cette phrase à propos de l'élargissement du monde à la fin du XVe siècle. Termine en montrant ce que révèle le **traité de Tordesillas**.","bareme":[{"critere":"Motifs : or, épices, 1453, évangélisation, curiosité, rivalité","points":5},{"critere":"Moyens techniques : caravelle, boussole, astrolabe, portulan","points":4},{"critere":"Voyages datés (Dias, Colomb, Gama, Magellan) et rôle des États","points":5},{"critere":"Tordesillas 1494 et sa signification","points":4},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. Un profit espéré et d'autres motifs.** L'**or** et les **épices** : depuis **1453**, les Ottomans contrôlent la route terrestre. S'y ajoutent l'**évangélisation**, la **curiosité savante** (humanisme, redécouverte de Ptolémée) et la **rivalité** entre **Portugal** et **Castille**.\n\n**II. Une technique qui existe.** La **caravelle**, légère, remonte au vent ; la **boussole** donne la direction ; l'**astrolabe** la latitude ; le **portulan** décrit côtes et caps.\n\n**III. Des États qui paient.** Le Portugal finance l'exploration de l'Afrique : **Dias** passe le cap de Bonne-Espérance (**1487**), **Vasco de Gama** atteint l'Inde (**1498**). La Castille finance **Colomb**, qui touche les Antilles le **12 octobre 1492**. L'expédition de **Magellan**, achevée par Elcano, fait le premier tour du monde (**1519-1522**).\n\n**Tordesillas (1494).** Une ligne dans l'Atlantique donne l'ouest à la Castille et l'est au Portugal (d'où le Brésil portugais). Deux États **s'attribuent des terres qu'ils n'ont pas vues** et des peuples qu'ils ne connaissent pas : l'exploration est déjà une **appropriation**."}$exo$::jsonb),
  ('29e7fa7d-d219-5286-8a54-ea6b252b1b4c'::uuid, 1, 'redaction', $exo${"titre":"Le commerce triangulaire","consigne":"Réponds par des phrases complètes.","enonce":"1. Décris les **trois étapes** du commerce triangulaire : trajet et cargaison de chacune.\n2. Combien d'Africains ont été **embarqués** et combien **débarqués vivants** du XVIe au XIXe siècle ?\n3. Qu'est-ce que le **Code noir** (1685) ? Donne une de ses dispositions.","bareme":[{"critere":"Trois étapes avec trajets et cargaisons","points":10},{"critere":"Chiffres : 12,5 millions embarqués, 10,7 millions débarqués","points":5},{"critere":"Définition du Code noir et une disposition","points":5}],"dureeMin":8,"corrige":"1. **Étape 1** : de Nantes, Liverpool ou Bordeaux vers l'**Afrique**, avec de la **pacotille** (tissus, armes, alcool, verroterie). **Étape 2** : de l'Afrique vers les **Amériques** — le **passage du milieu** —, avec des **captifs**. **Étape 3** : des Amériques vers l'**Europe**, avec **sucre, café, coton, indigo, tabac**.\n2. Environ **12,5 millions** d'Africains embarqués, environ **10,7 millions** débarqués vivants.\n3. Le **Code noir** (1685) fixe le **statut des esclaves** dans les colonies françaises. Il fait de l'esclave un **bien meuble**, **autorise les châtiments** et **encadre l'affranchissement** (une disposition suffit)."}$exo$::jsonb),
  ('29e7fa7d-d219-5286-8a54-ea6b252b1b4c'::uuid, 2, 'redaction', $exo${"titre":"Lire un tableau de la traite","consigne":"Exploite les chiffres du document puis réponds en justifiant.","enonce":"**Document – La traite atlantique en chiffres (estimations)**\n\n| | Nombre |\n|---|---|\n| Africains embarqués (XVIe-XIXe s.) | 12,5 millions |\n| Africains débarqués vivants | 10,7 millions |\n\n1. Calcule le nombre de captifs **morts pendant la traversée**, puis le **pourcentage** que cela représente des embarqués (arrondi à l'unité).\n2. Comment appelle-t-on cette traversée ? Quel siècle est le plus meurtrier ? Quels sont les principaux transporteurs ?\n3. Cite **deux formes de résistance** des esclaves et explique-les.","bareme":[{"critere":"Calcul juste : 1,8 million de morts, environ 14 %","points":6},{"critere":"Passage du milieu, XVIIIe siècle, Portugais et Brésiliens devant Britanniques et Français","points":7},{"critere":"Deux formes de résistance expliquées","points":7}],"dureeMin":12,"corrige":"1. 12,5 − 10,7 = **1,8 million** de captifs morts pendant la traversée. 1,8 ÷ 12,5 × 100 = **14,4 %**, soit environ **14 %** des embarqués.\n2. C'est le **passage du milieu**. Le siècle le plus meurtrier est le **XVIIIe siècle**. Les principaux transporteurs sont les **Portugais et les Brésiliens**, devant les **Britanniques et les Français**.\n3. Formes de résistance : le **marronnage** (la fuite, et la formation de communautés d'évadés) ; les **révoltes** armées, réprimées (et la révolution de Saint-Domingue, 1791-1804) ; le **sabotage** quotidien du travail et des outils. Deux suffisent."}$exo$::jsonb),
  ('29e7fa7d-d219-5286-8a54-ea6b252b1b4c'::uuid, 3, 'redaction', $exo${"titre":"Le sucre de Paris","consigne":"Rédige un développement organisé en trois parties, avec dates et chiffres.","enonce":"**Document – Une phrase du cours**\n\n> « Le sucre que l'on boit à Paris est produit par des hommes qui ne sont pas payés, sur une terre qui n'est pas la leur, à des milliers de kilomètres de leur naissance. »\n\n**Sujet :** Explique en quoi la traite atlantique est, du XVIe au XIXe siècle, **le cœur d'un nouveau circuit économique mondial**, puis montre comment ce système est **contesté** jusqu'à son abolition en France.","bareme":[{"critere":"Circuit triangulaire : trois étapes, trois profits, ports européens","points":5},{"critere":"Ampleur chiffrée de la traite","points":3},{"critere":"Économie de plantation et Code noir, lien avec la phrase du document","points":4},{"critere":"Résistances et étapes des abolitions (1791-1804, 1794, 1802, 1848)","points":6},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. Un circuit mondial.** Les navires partent de **Nantes, Bordeaux, Liverpool** avec de la pacotille vers l'**Afrique** ; ils y achètent des **captifs** qu'ils transportent aux **Amériques** (passage du milieu) ; ils rapportent en **Europe** sucre, café, coton, indigo, tabac. **Trois côtés, trois profits** : l'Afrique, l'Amérique et l'Europe sont liées. Environ **12,5 millions** d'Africains sont embarqués, **10,7 millions** débarqués vivants ; le XVIIIe siècle est le plus meurtrier.\n\n**II. La plantation.** Aux Antilles et au Brésil, l'**économie de plantation** repose sur le **travail forcé**. Le **Code noir (1685)** fait de l'esclave un **bien meuble**, autorise les châtiments. La phrase du document résume ce système : des hommes **non payés**, sur une terre **qui n'est pas la leur**, **déportés** loin de chez eux, produisent pour les consommateurs européens.\n\n**III. Résistances et abolitions.** **Marronnage**, **révoltes**, **sabotage**. La révolution de **Saint-Domingue (1791-1804)** fait naître **Haïti**. La France abolit l'esclavage une première fois en **1794**, **Bonaparte le rétablit en 1802**, l'abolition définitive date de **1848**.\n\n**Conclusion.** Plus grande déportation de l'histoire, la traite a enrichi l'Europe au prix de millions de vies."}$exo$::jsonb),
  ('97889f80-f987-5ac7-ac6b-8e7c3819f4c3'::uuid, 1, 'redaction', $exo${"titre":"Conquérants et échange colombien","consigne":"Réponds par des phrases complètes.","enonce":"1. Qui conquiert l'**Empire aztèque** et quand ? Qui conquiert l'**Empire inca** et quand ?\n2. Quelle est la **principale cause** de l'effondrement de la population amérindienne ?\n3. Cite **deux produits** passés d'Amérique en Europe et **deux** passés d'Europe en Amérique. Comment appelle-t-on ces échanges ?","bareme":[{"critere":"Cortés 1519-1521 et Pizarro 1532-1533","points":6},{"critere":"Les maladies importées (variole, rougeole, typhus)","points":5},{"critere":"Quatre produits bien orientés et le nom d'échange colombien","points":9}],"dureeMin":7,"corrige":"1. **Hernán Cortés** conquiert l'Empire **aztèque** en **1519-1521** ; **Francisco Pizarro** conquiert l'Empire **inca** en **1532-1533**.\n2. Les **microbes** importés par les Européens — **variole, rougeole, typhus** — tuent des populations **sans immunité** : la population indigène chute de 80 à 90 % en un siècle selon les estimations.\n3. D'Amérique vers l'Europe : **maïs, pomme de terre, tomate, cacao, tabac, haricot, piment**. D'Europe vers l'Amérique : **blé, canne à sucre, bœufs, chevaux, moutons**. On parle d'**échange colombien**."}$exo$::jsonb),
  ('97889f80-f987-5ac7-ac6b-8e7c3819f4c3'::uuid, 2, 'redaction', $exo${"titre":"L'argent de Potosí","consigne":"Lis le document puis réponds en utilisant le cours.","enonce":"**Document – Potosí, la montagne d'argent**\n\n> Découverte en 1545 dans les Andes, la mine de Potosí fait de la ville l'une des plus peuplées du monde. Des galions chargés d'argent partent chaque année pour Séville. Pourtant, la couronne espagnole fait plusieurs fois faillite au XVIe siècle.\n\n1. Où se trouve Potosí et quelle richesse en sort ? Vers où part-elle ?\n2. Qu'appelle-t-on la **révolution des prix** ? Qui en profite, qui en souffre ?\n3. Explique le paradoxe du document : pourquoi l'Espagne s'endette-t-elle **malgré** son argent ?","bareme":[{"critere":"Localisation, argent, transport vers Séville et l'Europe","points":5},{"critere":"Révolution des prix : hausse longue, rentiers appauvris, marchands favorisés","points":8},{"critere":"Paradoxe expliqué : métal qui ne reste pas, hausse des prix, dépenses","points":7}],"dureeMin":11,"corrige":"1. Potosí se trouve dans les **Andes** (Empire espagnol d'Amérique). Il en sort de l'**argent** (avec Zacatecas au Mexique), envoyé vers **Séville**, puis dans toute l'Europe.\n2. L'afflux de métal précieux américain provoque une **longue hausse des prix** au XVIe siècle : c'est la **révolution des prix**. Elle **appauvrit les rentiers** (leurs revenus fixes perdent de la valeur) et **favorise les marchands**, qui vendent plus cher.\n3. L'argent ne reste pas en Espagne : il sert à **payer des achats et des dépenses** (dont les guerres) et fait monter les prix. La couronne dépense plus qu'elle ne reçoit et **s'endette malgré son or** : la richesse minière ne crée pas à elle seule une économie solide."}$exo$::jsonb),
  ('97889f80-f987-5ac7-ac6b-8e7c3819f4c3'::uuid, 3, 'redaction', $exo${"titre":"Un choc des mondes très inégal","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Document – Bartolomé de Las Casas, Très brève relation de la destruction des Indes (1552)**\n\n> « Les chrétiens sont entrés parmi ces agneaux comme des loups, des tigres et des lions très cruels. […] Ils n'ont fait que les mettre en pièces, les tuer, les tourmenter. »\n\n**Sujet :** « L'ouverture atlantique n'est pas une rencontre : c'est une conquête. » Montre les **conséquences** des grandes découvertes pour l'**Amérique** et pour l'**Europe**, et le **débat moral** qu'elles suscitent.","bareme":[{"critere":"Conquêtes (Cortés, Pizarro) et facteurs hiérarchisés (armes, alliances, microbes)","points":5},{"critere":"Effondrement démographique chiffré","points":3},{"critere":"Échange colombien et révolution des prix","points":5},{"critere":"Controverse de Valladolid, Las Casas et Sepúlveda, exploitation du document","points":5},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. La destruction des empires amérindiens.** **Cortés** abat les **Aztèques** (1519-1521), **Pizarro** les **Incas** (1532-1533). Les **armes à feu** et les chevaux jouent un rôle réel mais limité ; les **alliances** avec des peuples soumis sont décisives militairement ; les **microbes** (variole, rougeole, typhus) sont **le plus meurtrier**. La population indigène chute de **80 à 90 %** en un siècle.\n\n**II. Des effets mondiaux.** L'**échange colombien** : maïs, pomme de terre, tomate, cacao passent en Europe ; blé, canne à sucre, chevaux, bœufs en Amérique — la pomme de terre nourrit l'Europe du XIXe siècle, le cheval transforme les plaines, sans que ce soit voulu. L'argent de **Potosí** et Zacatecas provoque la **révolution des prix**, qui appauvrit les rentiers et favorise les marchands ; l'Espagne s'endette malgré son or.\n\n**III. Un débat moral.** Dès **1511**, des religieux protestent. Le document de **Las Casas** dénonce la cruauté des conquérants (image des loups et des agneaux). En **1550-1551**, la **controverse de Valladolid** l'oppose à **Sepúlveda**, qui justifie la conquête. Le débat ne met pas fin à l'exploitation mais pose une question neuve : **l'humanité de l'autre**.\n\n(Critique attendue : Las Casas est un défenseur engagé, son texte vise à convaincre.)"}$exo$::jsonb),
  ('4bcb8f4e-c59a-5809-91d2-776d9e6feedb'::uuid, 1, 'redaction', $exo${"titre":"Humanistes et artistes","consigne":"Réponds par des phrases complètes.","enonce":"1. Définis l'**humanisme** et cite **deux humanistes** avec une de leurs œuvres ou un de leurs apports.\n2. Qui met au point l'**imprimerie** à caractères mobiles, où et quand ?\n3. Qu'est-ce que le **mécénat** ? Cite un mécène.","bareme":[{"critere":"Définition de l'humanisme et deux humanistes avec leur apport","points":9},{"critere":"Gutenberg, Mayence, vers 1450","points":6},{"critere":"Définition du mécénat et un exemple","points":5}],"dureeMin":7,"corrige":"1. L'**humanisme** est un courant qui **place l'homme au centre**, relit les textes grecs et latins **dans leur langue d'origine** et fait confiance à la **raison** et à l'**éducation**. Exemples : **Pétrarque** (inaugure le mouvement), **Érasme** (Nouveau Testament en grec), **Thomas More** (*L'Utopie*), **Rabelais** ou **Montaigne** (écrivent en français).\n2. **Gutenberg**, à **Mayence**, vers **1450**.\n3. Le **mécénat** est le **financement des artistes** par des princes, des papes ou des banquiers. Exemples : les **Médicis**, les papes, François Ier."}$exo$::jsonb),
  ('4bcb8f4e-c59a-5809-91d2-776d9e6feedb'::uuid, 2, 'redaction', $exo${"titre":"La machine qui change tout","consigne":"Lis le document puis réponds en justifiant avec le cours.","enonce":"**Document – L'imprimerie en Europe**\n\n> Vers 1450, un copiste met plusieurs mois à recopier une Bible. En 1500, environ 250 villes européennes ont un atelier d'imprimerie ; des millions de volumes circulent.\n\n1. Relève deux changements provoqués par l'imprimerie et ajoute-en un tiré du cours (prix, vitesse de diffusion).\n2. Pourquoi l'imprimerie est-elle un outil décisif pour les **humanistes** ?\n3. Explique la phrase du cours : « Sans l'imprimerie, la Réforme serait restée une querelle d'université allemande. »","bareme":[{"critere":"Changements : production massive, prix divisé par dix, diffusion rapide","points":6},{"critere":"Lien avec les humanistes : éditions de textes antiques, république des lettres","points":7},{"critere":"Explication de la phrase sur la Réforme","points":7}],"dureeMin":11,"corrige":"1. Le document montre la **multiplication des ateliers** (250 villes en 1500) et la circulation de **millions de volumes**, au lieu de copies manuscrites longues. Le cours ajoute que le **prix d'un livre est divisé par dix** et qu'une idée circule **en semaines et non en années**.\n2. Les humanistes veulent relire les textes antiques dans leur langue d'origine : l'imprimerie permet de **publier des éditions fiables** (Érasme, Nouveau Testament en grec) et de les **diffuser** partout. Elle nourrit la **république des lettres** qui correspond d'un bout à l'autre de l'Europe.\n3. En 1517, les **95 thèses** de Luther, imprimées et traduites, circulent en quelques semaines dans tout l'Empire. Sans l'imprimerie, cette critique serait restée un débat entre professeurs de Wittenberg ; grâce à elle, elle devient une **affaire européenne**."}$exo$::jsonb),
  ('4bcb8f4e-c59a-5809-91d2-776d9e6feedb'::uuid, 3, 'redaction', $exo${"titre":"L'homme au centre, le livre pour le dire","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Sujet :** Montre qu'entre le XIVe et le XVIe siècle, l'Europe connaît des **mutations** intellectuelles et artistiques, et explique comment elles **gagnent la France**.\n\n**Tu dois mobiliser :** l'humanisme et ses figures, l'imprimerie, la Renaissance artistique (innovations, artistes, mécènes), le rôle de François Ier.","bareme":[{"critere":"Humanisme : définition et figures (Pétrarque, Érasme, More, Rabelais, Montaigne)","points":4},{"critere":"Imprimerie : Gutenberg 1450 et ses effets","points":4},{"critere":"Renaissance artistique : perspective, anatomie, signature, artistes, mécénat","points":5},{"critere":"Passage en France : guerres d'Italie, François Ier, Collège de France 1530, Villers-Cotterêts 1539","points":5},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. L'humanisme.** Un courant qui remet l'**homme au centre**, relit les Anciens **dans leur langue**, fait confiance à la raison et à l'éducation. **Pétrarque** l'inaugure, **Érasme** publie un Nouveau Testament en grec, **Thomas More** *L'Utopie* ; **Rabelais** et **Montaigne** écrivent en français. Ils forment une **république des lettres**.\n\n**II. L'imprimerie et la Renaissance artistique.** **Gutenberg**, vers **1450** à Mayence, invente les caractères mobiles : millions de volumes, prix divisé par dix, idées diffusées en semaines. Les artistes redécouvrent l'**Antiquité**, inventent la **perspective linéaire**, étudient l'**anatomie**, **signent** leurs œuvres. **Florence, Rome, Venise** donnent le ton (Brunelleschi, Michel-Ange, Raphaël, Botticelli), grâce au **mécénat** des Médicis, des papes et des princes.\n\n**III. Le passage en France.** Les **guerres d'Italie** (1494-1559) font découvrir les palais italiens. **François Ier** attire **Léonard de Vinci** et bâtit **Chambord** ; il fonde le **Collège de France** (**1530**) et impose le **français** dans les actes officiels par l'ordonnance de **Villers-Cotterêts** (**1539**).\n\n**Conclusion.** Une manière neuve de penser, diffusée par une machine, transforme l'Europe."}$exo$::jsonb),
  ('e9917f09-c475-53ff-8a0a-430989127935'::uuid, 1, 'redaction', $exo${"titre":"Trois protestantismes","consigne":"Réponds par des phrases complètes ou un petit tableau.","enonce":"1. Pour chacun de ces réformateurs, donne **le lieu**, **la date** et **le courant né** : Luther, Calvin, Henri VIII.\n2. Cite **deux critiques** adressées à l'Église catholique au début du XVIe siècle.\n3. Qu'est-ce que le **concile de Trente** et quand se tient-il ?","bareme":[{"critere":"Trois réformateurs, lieux, dates et courants","points":9},{"critere":"Deux critiques précises","points":5},{"critere":"Concile de Trente : dates et rôle","points":6}],"dureeMin":7,"corrige":"1. **Luther** : Allemagne, **1517**, le **luthéranisme**. **Calvin** : Genève, *Institution de la religion chrétienne* en **1536**, le **calvinisme**. **Henri VIII** : Angleterre, Acte de suprématie en **1534**, l'**anglicanisme**.\n2. Critiques : le **train de vie du haut clergé** (luxe, cumul des bénéfices) ; l'**ignorance des curés** ; la **vente des indulgences** pour financer Saint-Pierre de Rome (deux suffisent).\n3. Le **concile de Trente** (**1545-1563**) est la réponse catholique : il **réaffirme les dogmes** contestés, **condamne les abus** et impose des **séminaires** pour former les prêtres."}$exo$::jsonb),
  ('e9917f09-c475-53ff-8a0a-430989127935'::uuid, 2, 'redaction', $exo${"titre":"L'édit de Nantes","consigne":"Lis le document puis réponds en t'appuyant sur le cours.","enonce":"**Document – Édit de Nantes, avril 1598 (extrait)**\n\n> « Pour ne laisser aucune occasion de troubles entre nos sujets, avons permis et permettons à ceux de la religion prétendue réformée vivre et demeurer par toutes les villes et lieux de notre royaume, sans être enquis, vexés ni molestés, ni astreints à faire chose pour le fait de la religion contre leur conscience. »\n\n1. Qui signe cet édit ? Que désigne l'expression « religion prétendue réformée » ?\n2. Quel **droit** l'édit accorde-t-il aux protestants ? Que leur accorde-t-il d'autre, selon le cours ?\n3. Replace l'édit dans son contexte : quelle période de troubles vient-il clore ? Cite un épisode marquant.","bareme":[{"critere":"Henri IV ; le protestantisme (calviniste)","points":4},{"critere":"Liberté de conscience et places de sûreté","points":8},{"critere":"Guerres de Religion 1562-1598 et Saint-Barthélemy 1572","points":8}],"dureeMin":10,"corrige":"1. L'édit est signé par le roi **Henri IV**. La « religion prétendue réformée » désigne le **protestantisme** (les calvinistes français), nommé ainsi par le pouvoir catholique.\n2. L'édit accorde la **liberté de conscience** : les protestants peuvent vivre dans le royaume sans être inquiétés ni forcés d'agir contre leur foi. Il leur accorde aussi des **places de sûreté** (villes fortifiées). Le catholicisme reste la religion du roi.\n3. Il met fin aux **guerres de Religion** (**1562-1598**) qui déchirent la France. Épisode marquant : la **Saint-Barthélemy** à Paris en **1572**, massacre de protestants."}$exo$::jsonb),
  ('e9917f09-c475-53ff-8a0a-430989127935'::uuid, 3, 'redaction', $exo${"titre":"La chrétienté occidentale se brise","consigne":"Rédige un développement organisé en trois parties, avec dates et exemples.","enonce":"**Sujet :** « Au XVIe siècle, l'unité religieuse de l'Occident vole en éclats. Ce n'est pas seulement une querelle de théologiens : c'est une affaire d'États, de guerres et de frontières. »\n\nExplique les **causes** de la division religieuse, les **réformes** protestantes et la **réponse catholique**, puis les **conflits** qui en découlent.","bareme":[{"critere":"Causes : abus du clergé, indulgences, humanisme","points":4},{"critere":"Trois protestantismes et leurs points communs (pape, sacrements, salut par la foi)","points":5},{"critere":"Réforme catholique : Trente, baroque, jésuites, Inquisition et Index","points":4},{"critere":"Conflits : Augsbourg 1555, guerres de Religion, Saint-Barthélemy, édit de Nantes","points":5},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. Les causes.** Le **train de vie** du haut clergé, l'**ignorance** des curés, la vente des **indulgences** pour financer Saint-Pierre de Rome. L'**humanisme** exige le retour aux textes et fournit les outils de la critique.\n\n**II. Les réformes protestantes.** **Luther** (Allemagne, 1517, luthéranisme), **Calvin** (Genève, 1536, calvinisme), **Henri VIII** (Angleterre, Acte de suprématie, 1534, anglicanisme). Tous récusent l'**autorité du pape** ; Luther et Calvin réduisent les sacrements à **deux**, refusent le culte des saints et affirment le **salut par la foi**. Une même Bible lue dans la langue de chacun rend l'unité impossible.\n\n**III. La réponse catholique et les guerres.** Le **concile de Trente** (1545-1563) réaffirme les dogmes, condamne les abus, crée les séminaires ; l'**art baroque** relance la foi par l'émotion ; les **jésuites** (1540) enseignent et évangélisent ; l'**Inquisition** et l'**Index** encadrent la pensée. Les guerres éclatent : dans l'Empire, la **paix d'Augsbourg (1555)** laisse le prince choisir la religion de ses sujets ; en France, les **guerres de Religion** (1562-1598), la **Saint-Barthélemy (1572)**, puis l'**édit de Nantes (1598)**.\n\n**Conclusion.** La religion devient une affaire d'États, et les frontières confessionnelles d'alors restent visibles."}$exo$::jsonb),
  ('2ff97d37-ecc8-548e-bb9c-6b7e7129ac98'::uuid, 1, 'redaction', $exo${"titre":"La doctrine de Luther","consigne":"Réponds par des phrases complètes.","enonce":"1. Qui est Martin Luther ? Que rédige-t-il en **1517** et contre quoi ?\n2. Explique les trois principes de sa doctrine : la **foi seule**, l'**Écriture seule**, le **sacerdoce universel**.\n3. Quels sont les **deux sacrements** conservés ?","bareme":[{"critere":"Luther moine augustin à Wittenberg, 95 thèses contre les indulgences","points":6},{"critere":"Trois principes expliqués","points":10},{"critere":"Baptême et eucharistie","points":4}],"dureeMin":7,"corrige":"1. Martin Luther (1483-1546) est un **moine augustin**, professeur à **Wittenberg**. En **1517**, il rédige ses **95 thèses** contre la vente des **indulgences**.\n2. **La foi seule** : le salut ne s'achète pas et ne se mérite pas par les œuvres, il vient de la foi. **L'Écriture seule** : la **Bible** fait autorité, non la tradition de l'Église. **Le sacerdoce universel** : **tout croyant est prêtre**, il n'a pas besoin d'intermédiaire.\n3. Le **baptême** et l'**eucharistie**."}$exo$::jsonb),
  ('2ff97d37-ecc8-548e-bb9c-6b7e7129ac98'::uuid, 2, 'redaction', $exo${"titre":"Luther à Worms","consigne":"Lis le document puis réponds en utilisant le cours.","enonce":"**Document – Luther devant la diète de Worms (1521)**\n\n> « À moins qu'on ne me convainque par le témoignage de l'Écriture ou par des raisons évidentes — car je ne crois ni au pape ni aux conciles seuls —, je suis lié par les textes de l'Écriture. […] Je ne puis ni ne veux rien révoquer. »\n\n1. Devant qui Luther parle-t-il ? Que lui demande-t-on ?\n2. Quel **principe** de sa doctrine apparaît dans ce texte ? Justifie par une citation.\n3. Que devient Luther après Worms ? En quoi la **traduction de la Bible** en allemand prolonge-t-elle ce texte ?","bareme":[{"critere":"Charles Quint, diète de Worms, demande de rétractation","points":5},{"critere":"L'Écriture seule, justifiée par une citation, rejet du pape","points":7},{"critere":"Mis au ban, caché à la Wartburg, traduction : chacun lit et juge","points":8}],"dureeMin":11,"corrige":"1. Luther parle devant l'empereur **Charles Quint**, à la **diète de Worms** en **1521**. On lui demande de **se rétracter**, c'est-à-dire de renier ses écrits (il a été excommunié en 1520 et a brûlé la bulle).\n2. C'est le principe de l'**Écriture seule** : « je suis lié par les textes de l'Écriture », « je ne crois ni au pape ni aux conciles seuls ». La Bible fait autorité, pas l'institution.\n3. Luther est **mis au ban de l'Empire** ; il est caché au château de la **Wartburg**, où il **traduit le Nouveau Testament en allemand**. Traduire la Bible, c'est permettre à chacun de **lire par lui-même**, donc de **juger par lui-même** sans passer par le clergé : c'est l'application concrète de l'Écriture seule et du sacerdoce universel."}$exo$::jsonb),
  ('2ff97d37-ecc8-548e-bb9c-6b7e7129ac98'::uuid, 3, 'redaction', $exo${"titre":"Un moine qui redessine l'Europe","consigne":"Rédige un développement organisé en trois parties, avec dates et exemples.","enonce":"**Sujet :** « Martin Luther ne voulait pas fonder une Église. Il voulait réformer la sienne. En vingt ans, son geste redessine la carte religieuse de l'Europe. »\n\nExplique cette phrase en présentant le **geste de 1517**, la **doctrine** et la **rupture** avec Rome, puis les **conséquences** politiques et sociales de la Réforme luthérienne.","bareme":[{"critere":"1517 : 95 thèses, rôle de l'imprimerie","points":4},{"critere":"Doctrine : trois principes, ce qui subsiste et ce qui est rejeté","points":5},{"critere":"Rupture : excommunication 1520, Worms 1521, Wartburg","points":4},{"critere":"Conséquences : princes et biens d'Église, guerre des paysans, paix d'Augsbourg 1555","points":5},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. Le geste de 1517.** Moine augustin et professeur à **Wittenberg**, Luther rédige ses **95 thèses** contre les indulgences. **Imprimées et traduites**, elles circulent en quelques semaines dans tout l'Empire : c'est le premier scandale de l'ère de l'imprimé. Il veut **réformer**, pas rompre.\n\n**II. Doctrine et rupture.** Trois principes : la **foi seule**, l'**Écriture seule**, le **sacerdoce universel**. Il garde **deux sacrements** (baptême, eucharistie) et rejette le culte des saints, le purgatoire, le célibat des prêtres, l'autorité du pape. Excommunié en **1520**, il **brûle la bulle** ; à la **diète de Worms (1521)**, il refuse de se rétracter devant **Charles Quint** ; mis au ban, il se cache à la **Wartburg** et traduit le Nouveau Testament en allemand.\n\n**III. Les conséquences.** Des **princes allemands** adoptent la Réforme, par conviction mais souvent pour **saisir les biens d'Église**. Lors de la **guerre des paysans** (1524-1525), Luther soutient leur écrasement : il refuse la révolution sociale. La **paix d'Augsbourg (1555)** fige le partage : **Nord luthérien, Sud catholique**.\n\n**Conclusion.** Un geste de réforme devient une rupture durable, qui s'appuie sur les princes et l'imprimerie."}$exo$::jsonb),
  ('ec702236-f6bb-568c-8747-da3844617b3e'::uuid, 1, 'redaction', $exo${"titre":"Léonard, peintre et savant","consigne":"Réponds par des phrases complètes.","enonce":"1. Dans l'atelier de quel maître Léonard de Vinci se forme-t-il, où et vers quand ? Qu'y apprend-on ?\n2. Cite **deux œuvres** de Léonard avec leur lieu ou leur date, et explique ce qu'est le **sfumato**.\n3. Quel roi l'accueille à la fin de sa vie ? Où et quand meurt-il ?","bareme":[{"critere":"Verrocchio, Florence, vers 1467, apprentissages multiples","points":6},{"critere":"Deux œuvres situées et définition du sfumato","points":8},{"critere":"François Ier, Clos Lucé à Amboise, 1519","points":6}],"dureeMin":7,"corrige":"1. Il entre vers **1467** dans l'atelier de **Verrocchio**, à **Florence**. On y apprend la **peinture, la sculpture, la mécanique, la fonte, la scénographie** : l'artiste est d'abord un technicien.\n2. **La Cène** (1495-1498, **Milan**) ; **La Joconde** (vers 1503-1519) ; la Vierge aux rochers. Le **sfumato** est un **fondu** qui **supprime les contours nets**.\n3. **François Ier** l'accueille au **Clos Lucé**, à **Amboise**, où il meurt en **1519**."}$exo$::jsonb),
  ('ec702236-f6bb-568c-8747-da3844617b3e'::uuid, 2, 'redaction', $exo${"titre":"Les carnets de Léonard","consigne":"Lis le document puis réponds en utilisant le cours.","enonce":"**Document – Une page des carnets de Léonard**\n\n> Sur une même feuille, écrite de droite à gauche, en miroir : le dessin d'une aile d'oiseau décomposée en articulations, le croquis d'une machine volante et, en marge, des notes sur la façon dont l'air résiste à l'aile. Léonard écrit ailleurs : « L'expérience ne se trompe jamais. »\n\n1. Quels **domaines du savoir** Léonard étudie-t-il ? Cite-en trois, avec un exemple chacun.\n2. Que montre cette page sur sa **méthode** ?\n3. La machine volante a-t-elle été construite ? Qu'en déduis-tu du rôle de ses carnets ?","bareme":[{"critere":"Trois domaines avec exemples (anatomie, vol des oiseaux, eau et lumière, mécanique)","points":7},{"critere":"Méthode : observer, dessiner, expérimenter, ne pas séparer art et science","points":7},{"critere":"Presque rien n'a été construit : carnets de recherche","points":6}],"dureeMin":10,"corrige":"1. **Anatomie** : une trentaine de dissections, le fœtus dans l'utérus. **Vol des oiseaux** : projets de machine volante. **Eau et lumière** : tourbillons, ombres, reflets. **Mécanique** : char d'assaut, pont mobile, scaphandre (trois suffisent).\n2. Léonard **observe** la nature (l'aile), la **dessine avec précision**, cherche à la **comprendre** (la résistance de l'air) et à l'**imiter** (la machine). Il fait confiance à l'**expérience**. Il **ne sépare pas l'art de la science** : le dessin est son outil de connaissance. C'est l'idéal humaniste.\n3. Non : **presque rien n'a été construit**. Ses carnets, des milliers de pages écrites en miroir, sont des **carnets de recherche** et de réflexion ; rien n'y est décoratif, mais ce sont des projets."}$exo$::jsonb),
  ('ec702236-f6bb-568c-8747-da3844617b3e'::uuid, 3, 'redaction', $exo${"titre":"Un symbole de l'humanisme","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Sujet :** En quoi **Léonard de Vinci** (1452-1519) est-il un **symbole de l'humanisme** et de la Renaissance ?\n\n**Tu dois montrer :** sa formation d'artiste-technicien, ses innovations de peintre, sa démarche de savant, et la place nouvelle de l'artiste auprès des princes.","bareme":[{"critere":"Formation chez Verrocchio : l'artiste technicien","points":3},{"critere":"Le peintre : œuvres, sfumato, composition géométrique","points":4},{"critere":"Le savant : domaines étudiés, carnets, observation","points":5},{"critere":"Les protecteurs (Sforza, Borgia, Florence, François Ier) et le nouveau statut de l'artiste","points":5},{"critere":"Lien explicite avec l'idéal humaniste, organisation","points":3}],"dureeMin":20,"corrige":"**I. Un artiste technicien.** Né près de Vinci, fils illégitime d'un notaire, Léonard entre vers **1467** dans l'atelier de **Verrocchio** à Florence, où l'on apprend peinture, sculpture, mécanique, fonte et scénographie.\n\n**II. Un peintre novateur.** **La Cène** (1495-1498, Milan), **La Joconde** (vers 1503-1519), la Vierge aux rochers. Il perfectionne le **sfumato** (fondu sans contours nets) et une **composition géométrique**. Il peint peu et laisse des œuvres inachevées.\n\n**III. Un savant.** Une trentaine de **dissections** (le fœtus dans l'utérus), l'étude du **vol des oiseaux**, de l'**eau** et de la **lumière**, de la **mécanique** (char d'assaut, pont mobile, scaphandre). Ses **carnets**, écrits en miroir, comptent des milliers de pages — mais presque rien n'a été construit. Il **refuse de séparer l'art de la science** : c'est l'idéal humaniste d'un homme qui observe le monde par la raison et l'expérience.\n\n**IV. L'artiste recherché.** Il sert **Ludovic Sforza** à Milan, **César Borgia**, la République de **Florence**, puis **François Ier**, qui l'installe au **Clos Lucé** à Amboise, où il meurt en **1519**. Les princes se disputent l'artiste : c'est **nouveau**.\n\n**Conclusion.** Léonard incarne l'humanisme : curiosité universelle et homme au centre du savoir."}$exo$::jsonb),
  ('1c755629-f226-50ce-b578-06890ec798e2'::uuid, 1, 'redaction', $exo${"titre":"Ce qu'absolu veut dire","consigne":"Réponds par des phrases complètes.","enonce":"1. D'où le roi absolu tient-il son pouvoir ? Cite **deux pouvoirs** du roi.\n2. Le pouvoir absolu est-il sans limite ? Cite **deux** choses qui le bornent.\n3. Que se passe-t-il en **1661** ? Et en **1682** ?","bareme":[{"critere":"Droit divin et deux pouvoirs du roi","points":6},{"critere":"Absolu n'est pas arbitraire : deux limites citées","points":7},{"critere":"1661 règne personnel ; 1682 la cour à Versailles","points":7}],"dureeMin":7,"corrige":"1. Le roi tient son pouvoir de **Dieu** : c'est le **droit divin**. Il **fait la loi**, **rend la justice** en dernier ressort, **lève l'impôt**, **décide de la guerre** (deux suffisent).\n2. Non, **absolu ne veut pas dire arbitraire**. Le pouvoir est borné par les **lois fondamentales** du royaume, les **coutumes** des provinces, les **privilèges** des corps et des villes.\n3. En **1661**, à la mort de Mazarin, **Louis XIV gouverne seul** : début du règne personnel. En **1682**, la **cour s'installe à Versailles**."}$exo$::jsonb),
  ('1c755629-f226-50ce-b578-06890ec798e2'::uuid, 2, 'redaction', $exo${"titre":"Les artisans de l'État","consigne":"Réponds aux questions en justifiant avec le cours.","enonce":"**Document – Chronologie**\n\n- 1598 : édit de Nantes\n- 1624-1642 : Richelieu principal ministre de Louis XIII\n- 1648-1653 : la Fronde\n- 1661 : mort de Mazarin\n\n1. Quel rôle joue **Henri IV** dans la construction de l'État ?\n2. Cite **deux mesures de Richelieu** qui renforcent le pouvoir royal.\n3. Qu'est-ce que la **Fronde** ? Quelles **leçons** Louis XIV en tire-t-il pour son règne personnel ?","bareme":[{"critere":"Henri IV : paix civile (édit de Nantes) et finances avec Sully","points":5},{"critere":"Deux mesures de Richelieu (places protestantes, intendants, Grands soumis)","points":6},{"critere":"Fronde définie et deux leçons tirées par Louis XIV","points":9}],"dureeMin":11,"corrige":"1. **Henri IV** rétablit la **paix civile** avec l'**édit de Nantes** (1598), qui met fin aux guerres de Religion, et redresse les **finances** avec **Sully**.\n2. **Richelieu** abat les **places fortes protestantes**, crée les **intendants** (agents du roi dans les provinces) et **soumet les Grands** (la haute noblesse) (deux suffisent).\n3. La **Fronde** (**1648-1653**) est une **révolte des parlements et des princes** contre le pouvoir royal, pendant la minorité de Louis XIV et le ministère de Mazarin. Leçons : **ne jamais laisser Paris décider** (d'où Versailles) et **ne jamais gouverner par un ministre principal** : en **1661**, Louis XIV gouverne seul, avec des conseils et des ministres bourgeois comme Colbert, et ne réunit plus les états généraux."}$exo$::jsonb),
  ('1c755629-f226-50ce-b578-06890ec798e2'::uuid, 3, 'redaction', $exo${"titre":"Gouverner, c'est aussi être vu","consigne":"Rédige un développement organisé en trois parties, avec dates et exemples précis.","enonce":"**Document – Louis XIV, Mémoires pour l'instruction du Dauphin (vers 1670)**\n\n> « Je résolus sur toutes choses de ne point prendre de premier ministre. […] Ces peuples sur qui nous régnons, ne pouvant pénétrer le fond des choses, règlent d'ordinaire leurs jugements sur ce qu'ils voient au-dehors. »\n\n**Sujet :** Explique comment, de la fin des guerres de Religion au règne personnel de Louis XIV, se construit la **monarchie absolue** en France, et pourquoi la **mise en scène** du pouvoir en fait partie.","bareme":[{"critere":"Définition de l'absolutisme et de ses limites","points":4},{"critere":"Étapes : Henri IV et Sully, Richelieu, Mazarin et la Fronde","points":5},{"critere":"Règne personnel 1661 : pas de premier ministre, conseils, Colbert, pas d'états généraux","points":4},{"critere":"Mise en scène : Versailles 1682, étiquette, symbole solaire, Académie ; lien avec le document","points":5},{"critere":"Organisation et rédaction","points":2}],"dureeMin":20,"corrige":"**I. Un pouvoir absolu, non arbitraire.** Le roi tient son pouvoir de **Dieu**, fait la loi, rend la justice, lève l'impôt, décide de la guerre. Mais il reste borné par les **lois fondamentales**, les **coutumes**, les **privilèges**.\n\n**II. Les étapes.** **Henri IV** rétablit la paix (**édit de Nantes, 1598**) et les finances avec **Sully**. **Richelieu**, sous Louis XIII, abat les places protestantes, crée les **intendants**, soumet les Grands. **Mazarin** poursuit malgré la **Fronde** (1648-1653). En **1661**, Louis XIV gouverne **seul** : le document confirme qu'il refuse tout **premier ministre**. Il ne réunit plus les **états généraux**, tient les **parlements** en lisière, s'appuie sur des conseils et des ministres bourgeois comme **Colbert**.\n\n**III. Être vu.** Le document explique que les peuples jugent « sur ce qu'ils voient au-dehors » : le pouvoir doit se **montrer**. **Versailles** (la cour s'y installe en **1682**) met la noblesse sous les yeux du roi ; l'**étiquette** rend la hiérarchie visible à chaque geste ; le **symbole solaire** et les **portraits** circulent dans toute l'Europe ; l'**Académie** et les **fêtes** servent le prestige.\n\n**Conclusion.** L'État centralise, taxe, surveille — et se met en scène."}$exo$::jsonb),
  ('472ea26f-1a12-5139-a8ee-7d869d746f28'::uuid, 1, 'redaction', $exo${"titre":"Le mercantilisme en trois idées","consigne":"Réponds à chaque question par une ou deux phrases précises, en utilisant le vocabulaire du cours.","enonce":"**Questions de cours sur Colbert et le mercantilisme**\n\n1. Quelle fonction Colbert occupe-t-il auprès de Louis XIV, et pendant quelles années ?\n2. Sur quel postulat repose le mercantilisme ? Quelle conséquence en tire-t-on pour le commerce extérieur ?\n3. Qu'est-ce qu'une manufacture royale ? Cite deux exemples en précisant ce qu'elles produisent.","bareme":[{"critere":"Fonction de Colbert (contrôleur général des finances) et dates 1665-1683","points":5},{"critere":"Postulat d'une richesse mondiale fixe et nécessité de vendre plus qu'on n'achète pour attirer l'or et l'argent","points":8},{"critere":"Définition de la manufacture royale et deux exemples justes avec leur production","points":7}],"dureeMin":7,"corrige":"1. Colbert est **contrôleur général des finances** de Louis XIV de **1665 à 1683**.\n2. Le mercantilisme repose sur l'idée que **la richesse du monde est fixe** : ce qu'un royaume gagne, un autre le perd. Il faut donc **vendre plus qu'on n'achète** pour attirer l'**or et l'argent** ; la **balance commerciale** devient une affaire d'État.\n3. Une manufacture royale est un **établissement de production privilégié et contrôlé par l'État**, soumis à des règlements stricts de fabrication pour garantir la qualité et favoriser l'export. Exemples : les **Gobelins** (tapisserie), **Saint-Gobain** (glaces), **Villeneuvette** (drap). Deux exemples suffisent."}$exo$::jsonb),
  ('472ea26f-1a12-5139-a8ee-7d869d746f28'::uuid, 2, 'redaction', $exo${"titre":"Le carnet d'un négociant marseillais","consigne":"Lis le document inventé, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Document – Notes (inventées) d'Étienne, négociant à Marseille, vers 1682**\n\n> « Les draps de Hollande me coûtent désormais bien plus cher à cause des nouveaux droits d'entrée : j'achète donc ceux de Villeneuvette. Les inspecteurs du roi vérifient la largeur et la qualité de chaque pièce. Mes balles de drap partent pour le Levant avec la compagnie du roi, et je fais passer mes marchandises de Bordeaux jusqu'à chez nous par le nouveau canal, sans faire le tour de l'Espagne. »\n\n1. Relève dans le document **trois moyens** de la politique de Colbert et nomme-les avec le vocabulaire du cours.\n2. Explique en quoi chacun de ces moyens sert l'idée mercantiliste.\n3. Quel aménagement désigne « le nouveau canal » ? Donne sa date d'achèvement et son intérêt.","bareme":[{"critere":"Trois moyens identifiés : tarifs douaniers, règlements de fabrication (ou manufacture royale), compagnie de commerce","points":6},{"critere":"Lien juste entre chaque moyen et l'objectif de vendre plus qu'on n'achète","points":8},{"critere":"Canal du Midi, achevé par Riquet en 1681, reliant l'Atlantique à la Méditerranée","points":6}],"dureeMin":11,"corrige":"1. Trois moyens :\n- les « nouveaux droits d'entrée » = les **tarifs douaniers**, relevés en **1664 et 1667** ;\n- les « inspecteurs du roi » qui vérifient les pièces = les **règlements de fabrication** très stricts (Villeneuvette est une **manufacture royale**) ;\n- « la compagnie du roi » vers le Levant = une **compagnie de commerce** (compagnie du Levant).\n2. - Les **tarifs douaniers** rendent les produits étrangers plus chers : on achète français, l'argent ne sort pas du royaume (protection de la production).\n- Les **règlements** garantissent la qualité, donc la réputation des produits français et **l'exportation**.\n- Les **compagnies de commerce** vendent au loin et rapportent des métaux précieux : on vend plus qu'on n'achète.\nTout tient dans l'idée : faire venir la richesse chez soi et empêcher qu'elle en sorte.\n3. C'est le **canal du Midi**, achevé par **Riquet en 1681** : il relie l'**Atlantique à la Méditerranée** et fait circuler les marchandises à l'intérieur du royaume sans contourner l'Espagne."}$exo$::jsonb),
  ('472ea26f-1a12-5139-a8ee-7d869d746f28'::uuid, 3, 'redaction', $exo${"titre":"Le colbertisme : réussite ou échec ?","consigne":"Rédige une réponse organisée (introduction courte, deux parties, conclusion d'une phrase) en t'appuyant sur des exemples précis du cours.","enonce":"**Sujet.** « Colbert a fait de l'économie un instrument de la puissance royale, mais sa politique s'est heurtée aux choix du roi lui-même. »\n\nEn t'appuyant sur le cours, montre :\n1. comment Colbert met l'économie au service de la puissance de l'État (idée mercantiliste, moyens, aménagement du royaume) ;\n2. quelles limites ruinent en partie ses efforts (guerres, fiscalité, révocation de l'édit de Nantes).\n\nTu préciseras aussi quel texte de 1685 organise le travail servile dans les colonies qui alimentent ce commerce.","bareme":[{"critere":"Idée mercantiliste expliquée (richesse fixe, balance commerciale)","points":3},{"critere":"Au moins trois moyens de Colbert précis (manufactures, règlements, tarifs 1664-1667, marine, compagnies)","points":5},{"critere":"Aménagement du royaume : canal du Midi, arsenaux de Rochefort et Toulon, routes et ports, Code noir de 1685","points":4},{"critere":"Les trois limites expliquées : coût des guerres, taille qui épargne nobles et clergé, départ des protestants en 1685","points":6},{"critere":"Organisation du devoir et conclusion qui répond au sujet","points":2}],"dureeMin":18,"corrige":"**Introduction** : sous Louis XIV, un État qui veut une grande armée a besoin d'argent ; Colbert, contrôleur général des finances (1665-1683), fait de l'économie un instrument de puissance : le **colbertisme**.\n\n**1. L'économie au service de l'État**\n- Idée **mercantiliste** : la richesse du monde est fixe ; il faut **vendre plus qu'on n'achète** pour attirer l'or et l'argent, la **balance commerciale** devient une affaire d'État.\n- Moyens : **manufactures royales** (Gobelins, Saint-Gobain, Villeneuvette), **règlements de fabrication** stricts pour la qualité et l'export, **tarifs douaniers** relevés en **1664 et 1667**, développement de la **marine** et de ses arsenaux, **compagnies de commerce** (Indes orientales, Indes occidentales, Levant).\n- Aménagement : routes et ports, arsenaux de **Rochefort** et **Toulon**, **canal du Midi** achevé par Riquet en **1681** (Atlantique-Méditerranée). Le **Code noir** (**1685**) organise le travail servile dans les colonies qui alimentent ce commerce.\n\n**2. Des limites qui viennent du roi et de la société**\n- Les **guerres** de Louis XIV engloutissent les recettes.\n- La **fiscalité** est injuste et peu productive : la **taille** pèse sur les paysans et **épargne nobles et clergé**.\n- La **révocation de l'édit de Nantes** (**1685**) fait partir des dizaines de milliers de **protestants**, souvent artisans et négociants, vers l'Angleterre, la Hollande et la Prusse : le royaume perd des savoir-faire et des capitaux.\n\n**Conclusion** : Colbert a doté la France d'outils durables (manufactures, marine, canal), mais la guerre, les privilèges fiscaux et l'intolérance religieuse ont limité ses résultats."}$exo$::jsonb),
  ('aeb8044a-72b1-5320-afb9-c47a697bfd6a'::uuid, 1, 'redaction', $exo${"titre":"Épée, robe et intendants","consigne":"Réponds précisément à chaque question en quelques lignes.","enonce":"**Questions de cours sur la monarchie absolue et la noblesse**\n\n1. Distingue la noblesse d'épée et la noblesse de robe (origine, source du prestige).\n2. Qu'est-ce que la vénalité des offices ? Quel avantage et quel inconvénient présente-t-elle pour le roi ?\n3. Qui sont les intendants, et pourquoi le roi ne les choisit-il pas dans la noblesse d'épée ?","bareme":[{"critere":"Distinction épée (ancienne, service militaire) / robe (plus récente, offices de justice et de finance souvent achetés)","points":7},{"critere":"Vénalité des offices définie, avec l'avantage (Trésor enrichi) et l'inconvénient (charges difficiles à révoquer)","points":7},{"critere":"Intendants : administrateurs des provinces choisis hors de l'épée pour dépendre du roi","points":6}],"dureeMin":7,"corrige":"1. La **noblesse d'épée** est **ancienne** : son prestige vient du **service militaire**. La **noblesse de robe** est **plus récente** : elle tient son rang des **offices de justice et de finance**, souvent **achetés**. Les deux se disputent la préséance, ce dont le roi tire parti.\n2. La **vénalité des offices** est la possibilité d'**acheter une charge publique**. Avantage : elle **enrichit le Trésor**. Inconvénient : elle crée des **propriétaires de charges difficiles à révoquer**, donc moins soumis au roi.\n3. Les **intendants** **administrent les provinces** au nom du roi. Ils sont choisis **hors de la noblesse d'épée** pour qu'ils **dépendent entièrement du roi** et soient révocables, au lieu d'avoir un pouvoir propre ; en face, les **gouverneurs** perdent l'essentiel de leur pouvoir réel."}$exo$::jsonb),
  ('aeb8044a-72b1-5320-afb9-c47a697bfd6a'::uuid, 2, 'redaction', $exo${"titre":"Un édit bloqué par le parlement","consigne":"Lis la situation, puis explique ce qui se passe en utilisant le vocabulaire du cours.","enonce":"**Situation (inventée), sous Louis XV.** Le roi veut créer un nouvel impôt et envoie son édit au parlement de Paris pour qu'il soit enregistré. Les magistrats, propriétaires de leur charge, rédigent un long texte critiquant l'édit et refusent de l'enregistrer. Quelques semaines plus tard, le roi se rend en personne au parlement et fait enregistrer l'édit sous ses yeux.\n\n1. Qu'est-ce qu'un parlement sous l'Ancien Régime ? Comment s'appelle le texte critique rédigé par les magistrats ?\n2. Comment s'appelle la séance où le roi impose l'enregistrement ?\n3. Pourquoi est-il difficile pour le roi de simplement renvoyer ces magistrats ?\n4. Comment évoluent ces conflits sous Louis XV et Louis XVI ?","bareme":[{"critere":"Parlement = cour de justice ; droit de remontrance qui retarde et critique","points":6},{"critere":"Lit de justice qui impose l'enregistrement","points":4},{"critere":"Vénalité : magistrats propriétaires de leur office, difficiles à révoquer","points":5},{"critere":"Conflits devenus une véritable opposition politique","points":5}],"dureeMin":10,"corrige":"1. Un **parlement** est une **cour de justice** qui enregistre les édits royaux. Le texte critique relève du **droit de remontrance** : les parlementaires peuvent **critiquer un édit et retarder** son enregistrement.\n2. Le roi répond par un **lit de justice** : il vient en personne **imposer l'enregistrement**.\n3. Les magistrats ont souvent **acheté leur charge** (**vénalité des offices**) : ils en sont **propriétaires**, ce qui les rend **difficiles à révoquer**. La vénalité enrichit le Trésor mais affaiblit l'autorité du roi sur ses officiers.\n4. Sous **Louis XV et Louis XVI**, ces conflits entre le roi et les parlements deviennent une **véritable opposition politique** à la monarchie absolue."}$exo$::jsonb),
  ('aeb8044a-72b1-5320-afb9-c47a697bfd6a'::uuid, 3, 'redaction', $exo${"titre":"Domestiquer les Grands sans les détruire","consigne":"Rédige un paragraphe argumenté d'une vingtaine de lignes, organisé en deux temps, avec des exemples précis du cours.","enonce":"**Sujet.** « Un noble ruiné à Versailles est moins dangereux qu'un noble puissant dans sa province. »\n\n1. Explique cette phrase en montrant comment le roi tient la noblesse : la cour, les intendants, les gouverneurs, la rivalité entre épée et robe.\n2. Montre ensuite les **limites** de la monarchie absolue face aux privilégiés : résistance des parlements, privilèges fiscaux, échec des réformateurs.\n3. Conclus en expliquant pourquoi Louis XVI convoque les états généraux en 1789.","bareme":[{"critere":"Rôle de la cour : pensions, charges, honneur d'approcher le roi","points":4},{"critere":"Intendants hors épée, gouverneurs affaiblis, rivalité épée/robe exploitée","points":4},{"critere":"Résistance des parlements : remontrances, lit de justice, opposition politique","points":4},{"critere":"Privilèges fiscaux intouchables et échec de réformateurs nommés (Machault, Turgot, Necker, Calonne)","points":5},{"critere":"Conclusion juste sur la convocation des états généraux en 1789","points":3}],"dureeMin":18,"corrige":"1. La monarchie absolue **n'écrase pas la noblesse** : elle **négocie, l'achète, la met en scène**. La **cour** de Versailles attache les Grands par les **pensions**, les **charges** et l'**honneur d'approcher le roi** : un noble qui dépense à la cour dépend du roi et quitte sa province, où il pourrait lever des fidèles. Les **intendants**, choisis **hors de la noblesse d'épée**, administrent les provinces ; les **gouverneurs** nobles perdent l'essentiel de leur pouvoir réel. Le roi joue aussi de la rivalité entre **épée** (ancienne, militaire) et **robe** (offices), qui se disputent la préséance.\n2. Les limites sont fortes. Les **parlements**, cours de justice, usent du **droit de remontrance** ; le roi riposte par le **lit de justice**, mais sous Louis XV et Louis XVI le conflit devient une **opposition politique**. La **vénalité des offices** a créé des officiers difficiles à révoquer. Surtout, la monarchie **ne peut pas toucher aux privilèges fiscaux** sans crise : **Machault d'Arnouville, Turgot, Necker, Calonne** échouent tous à réformer l'impôt.\n3. Faute de pouvoir réformer l'impôt, **Louis XVI convoque les états généraux en 1789** — et l'absolutisme y meurt. Le roi a domestiqué les Grands, mais pas leurs privilèges."}$exo$::jsonb),
  ('57cb7130-74e3-5fb5-8ea6-f6c33b3a884d'::uuid, 1, 'redaction', $exo${"titre":"Les grandes dates du modèle anglais","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Que pose la Grande Charte de 1215 ?\n2. De quelles chambres le Parlement anglais est-il composé, et quelle est son arme décisive ?\n3. Que se passe-t-il en 1649 ? en 1688 ?\n4. Que protège l'habeas corpus de 1679 ?","bareme":[{"critere":"Grande Charte : pas d'impôt sans l'accord des barons","points":4},{"critere":"Communes et Lords ; consentement à l'impôt","points":5},{"critere":"1649 exécution de Charles Ier ; 1688 Jacques II écarté au profit de Guillaume d'Orange","points":7},{"critere":"Habeas corpus : protection contre la détention arbitraire","points":4}],"dureeMin":7,"corrige":"1. La **Grande Charte** (1215) pose qu'il n'y a **pas d'impôt sans l'accord des barons**.\n2. Le Parlement a deux chambres : les **Communes** et les **Lords**. Son arme décisive est le **consentement à l'impôt**.\n3. En **1649**, le roi **Charles Ier** est **jugé et exécuté** après la guerre civile remportée par Cromwell. En **1688**, lors de la **Glorieuse Révolution**, le Parlement écarte **Jacques II**, catholique et autoritaire, et appelle **Guillaume d'Orange**.\n4. L'**habeas corpus** (1679) protège les sujets de la **détention arbitraire**."}$exo$::jsonb),
  ('57cb7130-74e3-5fb5-8ea6-f6c33b3a884d'::uuid, 2, 'redaction', $exo${"titre":"Le Bill of Rights expliqué à un Français","consigne":"Réponds aux questions en t'appuyant sur le cours et en justifiant.","enonce":"**Situation (inventée).** En 1690, Mathurin, marchand de La Rochelle, séjourne à Londres. Son hôte anglais lui explique : « Chez nous, depuis l'an dernier, le roi ne peut plus lever d'impôt ni entretenir une armée permanente sans le Parlement. »\n\n1. Quel texte de 1689 l'hôte évoque-t-il ? Dans quel contexte a-t-il été adopté ?\n2. Cite les autres règles que fixe ce texte.\n3. Compare avec la France de Louis XIV : pourquoi Mathurin peut-il être étonné ?","bareme":[{"critere":"Bill of Rights de 1689 relié à la Glorieuse Révolution de 1688","points":5},{"critere":"Règles citées : impôt et armée avec le Parlement, élections libres, parole libre des parlementaires, droit de pétition","points":8},{"critere":"Comparaison argumentée avec une monarchie française qui concentre le pouvoir dans les mains du roi","points":7}],"dureeMin":10,"corrige":"1. Il s'agit du **Bill of Rights** de **1689**. Il est adopté après la **Glorieuse Révolution** (**1688**) : le Parlement a écarté **Jacques II** et appelé **Guillaume d'Orange**, et fixe désormais les règles du pouvoir royal.\n2. Il pose que l'**impôt et l'armée permanente** sont impossibles **sans le Parlement**, que les **élections** sont **libres**, que la **parole des parlementaires** est **libre** et que la **pétition** est **un droit**.\n3. En France, le roi **concentre le pouvoir** : il gouverne sans avoir besoin de l'accord d'une assemblée pour lever l'impôt ou l'armée. En Angleterre, le souverain **règne avec le Parlement** : le pouvoir est **limité par la loi**. D'où l'étonnement de Mathurin : ce sont deux modèles opposés."}$exo$::jsonb),
  ('57cb7130-74e3-5fb5-8ea6-f6c33b3a884d'::uuid, 3, 'redaction', $exo${"titre":"Du roi absolu au roi sous la loi","consigne":"Rédige un développement organisé (introduction, deux ou trois parties, conclusion), appuyé sur des dates et des exemples précis.","enonce":"**Sujet.** Montre comment, entre 1215 et le XVIIIe siècle, l'Angleterre construit un régime où « le roi est sous la loi », et quelles limites ce régime garde.\n\nTu utiliseras :\n- la tradition ancienne (Grande Charte, Parlement) ;\n- la première révolution (Charles Ier, Cromwell, 1649, 1660) ;\n- la Glorieuse Révolution et le Bill of Rights ;\n- le fonctionnement du régime au XVIIIe siècle (ministres, cabinet, habeas corpus, suffrage).","bareme":[{"critere":"Tradition ancienne : Grande Charte et consentement à l'impôt par le Parlement","points":3},{"critere":"Première révolution : gouvernement sans Parlement, guerre civile, exécution de 1649, restauration de 1660","points":5},{"critere":"1688-1689 : Glorieuse Révolution et règles du Bill of Rights","points":5},{"critere":"Régime au XVIIIe : ministres soumis à la confiance des Communes, cabinet et Walpole, habeas corpus","points":4},{"critere":"Limite relevée : suffrage très restreint et inégal","points":3}],"dureeMin":20,"corrige":"**Introduction** : alors que la France concentre le pouvoir dans les mains du roi, l'Angleterre le **partage** : deux révolutions y installent un régime où le souverain **règne avec le Parlement**.\n\n**1. Une tradition ancienne** : la **Grande Charte** (1215) interdit l'impôt sans l'accord des barons ; le **Parlement**, avec les **Communes** et les **Lords**, tient le **consentement à l'impôt**, son arme décisive.\n\n**2. La première révolution** : **Charles Ier** gouverne **onze ans sans Parlement** et lève des taxes contestées ; la guerre civile est gagnée par **Cromwell** ; en **1649**, le roi est **jugé et exécuté**, ce qui stupéfie l'Europe. La république puis la dictature de Cromwell déçoivent, et la monarchie est **restaurée en 1660**. L'idée qu'un roi peut être jugé est née.\n\n**3. La Glorieuse Révolution** : en **1688**, le Parlement écarte **Jacques II** et appelle **Guillaume d'Orange** ; le **Bill of Rights** (**1689**) interdit impôt et armée permanente sans le Parlement, garantit des élections libres, la parole libre des parlementaires et le droit de pétition.\n\n**4. Le régime au XVIIIe siècle** : les **ministres**, choisis par le roi, doivent avoir la **confiance des Communes** ; le **cabinet** et le **Premier ministre** apparaissent avec **Walpole** ; l'**habeas corpus** (1679) protège de la détention arbitraire.\n\n**Limites** : le **suffrage** reste **très restreint et inégal** : ce n'est pas une démocratie.\n\n**Conclusion** : le principe est posé — **le pouvoir est limité par la loi** —, même si la participation politique reste réservée à une minorité."}$exo$::jsonb),
  ('7ac7a18a-e010-5345-af42-10d1f0472821'::uuid, 1, 'redaction', $exo${"titre":"Voltaire, Montesquieu, Locke","consigne":"Complète les informations demandées et réponds en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Pour chaque auteur, donne le titre de l'ouvrage étudié et sa date : Voltaire, Montesquieu, Locke.\n2. Que Voltaire admire-t-il en Angleterre ? Donne deux éléments.\n3. Quels sont les trois pouvoirs distingués par Montesquieu et leur fonction ?","bareme":[{"critere":"Trois œuvres et dates justes : Lettres philosophiques 1734, De l'esprit des lois 1748, Traité du gouvernement civil 1690","points":7},{"critere":"Deux éléments admirés par Voltaire (tolérance religieuse, liberté de commerce, considération des savants et négociants…)","points":5},{"critere":"Législatif, exécutif, judiciaire avec leur fonction","points":8}],"dureeMin":7,"corrige":"1. **Voltaire** : *Lettres philosophiques*, **1734** (après son exil anglais de 1726 à 1728). **Montesquieu** : *De l'esprit des lois*, **1748**. **Locke** : *Traité du gouvernement civil*, **1690**.\n2. Voltaire admire la **tolérance religieuse**, la **liberté de commerce**, la **considération pour les savants et les négociants**, un roi qui ne peut « faire de mal » (deux éléments attendus). Il vise en creux l'intolérance et l'absolutisme français.\n3. Le pouvoir **législatif** fait la loi ; l'**exécutif** l'applique ; le **judiciaire** la dit dans les litiges. Ils doivent être **distincts** pour que « le pouvoir arrête le pouvoir »."}$exo$::jsonb),
  ('7ac7a18a-e010-5345-af42-10d1f0472821'::uuid, 2, 'redaction', $exo${"titre":"Un livre brûlé à Paris","consigne":"Lis la situation et réponds en justifiant avec le cours.","enonce":"**Situation (inventée).** En 1734, dans un café parisien, Claudine lit en cachette un livre de Voltaire que les autorités viennent de condamner et de faire brûler. Son voisin s'étonne : « Pourquoi brûler un livre qui ne parle que de l'Angleterre ? »\n\n1. De quel livre s'agit-il ? Qu'y décrit Voltaire ?\n2. Réponds au voisin : pourquoi ce livre est-il vécu en France comme une attaque ?\n3. Par quels lieux et quels moyens ce type d'idées circule-t-il malgré la censure ? Cite au moins trois éléments, dont une grande entreprise éditoriale.","bareme":[{"critere":"Lettres philosophiques, description de l'Angleterre (tolérance, commerce, savants, pouvoir limité)","points":6},{"critere":"Explication de la critique en creux de la France (intolérance, entraves, mépris nobiliaire, absolutisme)","points":8},{"critere":"Lieux et moyens de diffusion dont l'Encyclopédie de Diderot et d'Alembert","points":6}],"dureeMin":10,"corrige":"1. Il s'agit des *Lettres philosophiques* (**1734**), écrites après l'exil de Voltaire en Angleterre (1726-1728). Il y décrit la **tolérance religieuse**, la **liberté de commerce**, la **considération pour savants et négociants** et un roi dont le pouvoir est limité.\n2. En décrivant l'Angleterre, Voltaire **critique la France en creux** : la tolérance anglaise fait voir l'**intolérance** française, la liberté de commerce les **entraves du royaume**, la considération pour les négociants le **mépris nobiliaire**, le roi limité l'**absolutisme**. La comparaison est vécue comme une **attaque** : le livre est condamné et brûlé.\n3. Les idées circulent par les **salons**, les **cafés**, les **académies**, les **correspondances**, et par l'**Encyclopédie** de **Diderot et d'Alembert** (1751-1772), malgré la censure."}$exo$::jsonb),
  ('7ac7a18a-e010-5345-af42-10d1f0472821'::uuid, 3, 'redaction', $exo${"titre":"L'Angleterre, une preuve pour les Lumières","consigne":"Rédige un développement argumenté et organisé, en citant auteurs, œuvres et dates.","enonce":"**Sujet.** « Ce que les Lumières empruntent à Londres, ce n'est pas une constitution : c'est une preuve qu'une alternative existe. »\n\n1. Montre ce que Locke, Voltaire et Montesquieu tirent chacun de l'exemple anglais.\n2. Explique en quoi la lecture de Montesquieu est « en partie idéalisée ».\n3. Montre comment ces idées se diffusent malgré la censure, puis explique la phrase du sujet.","bareme":[{"critere":"Locke : droits naturels, contrat, droit de résistance (1690)","points":4},{"critere":"Voltaire : Lettres philosophiques et critique en creux de la France","points":4},{"critere":"Montesquieu : séparation des pouvoirs, « le pouvoir arrête le pouvoir » (1748)","points":4},{"critere":"Idéalisation : le cabinet britannique mêle exécutif et législatif","points":3},{"critere":"Diffusion (salons, cafés, académies, Encyclopédie) et explication argumentée de la phrase","points":5}],"dureeMin":18,"corrige":"**1. Trois lectures de l'Angleterre**\n- **Locke**, *Traité du gouvernement civil* (**1690**), pose les fondations : les hommes ont des **droits naturels** que l'État ne crée pas mais **protège** ; le gouvernement naît d'un **contrat** et peut être **renversé** s'il les viole : le **droit de résistance** entre dans la pensée politique.\n- **Voltaire**, *Lettres philosophiques* (**1734**) : il admire la tolérance religieuse, la liberté de commerce, la considération pour savants et négociants, un roi qui ne peut « faire de mal » ; il vise en creux l'intolérance et l'absolutisme français. Le livre est condamné et brûlé.\n- **Montesquieu**, *De l'esprit des lois* (**1748**) : il en tire la **séparation des pouvoirs** (législatif, exécutif, judiciaire), distincts pour que « **le pouvoir arrête le pouvoir** ».\n\n**2. Une lecture idéalisée** : en réalité, le **cabinet britannique mêle exécutif et législatif** (les ministres doivent avoir la confiance des Communes). Mais cette lecture devient une **matrice politique**.\n\n**3. Diffusion et sens de la phrase** : salons, cafés, académies, correspondances et l'**Encyclopédie** de Diderot et d'Alembert (1751-1772) répandent ces idées malgré la censure. Les philosophes ne cherchent pas à copier les institutions anglaises telles quelles : l'Angleterre leur sert d'**argument**, la **preuve qu'un pouvoir limité est possible** sans ruiner l'ordre ni la prospérité."}$exo$::jsonb),
  ('8c3588f5-9360-5fc9-9624-7d473e4e61aa'::uuid, 1, 'redaction', $exo${"titre":"Les treize colonies en quelques dates","consigne":"Réponds à chaque question par une ou deux phrases précises.","enonce":"**Questions de cours**\n\n1. Entre quelles dates les treize colonies sont-elles fondées ? Donne deux traits de leurs institutions.\n2. Quelle guerre pousse Londres à taxer les colonies ? Cite deux taxes avec leur date.\n3. Que signifie le mot d'ordre *no taxation without representation* ?\n4. Que se passe-t-il le 4 juillet 1776 ?","bareme":[{"critere":"Fondation 1607-1732 et deux traits (assemblées élues, presse active)","points":5},{"critere":"Guerre de Sept Ans et deux taxes datées justes","points":5},{"critere":"Sens du slogan : pas d'impôt sans députés à Westminster","points":5},{"critere":"Déclaration d'indépendance rédigée par Jefferson","points":5}],"dureeMin":8,"corrige":"1. Les treize colonies sont fondées **entre 1607 et 1732**. Elles ont des **assemblées élues** et une **presse active** ; leur population se sent **anglaise**.\n2. La **guerre de Sept Ans** (1756-1763) a coûté cher à Londres. Taxes : **Sugar Act** (1764), **Stamp Act** (1765), **Townshend Acts** (1767), taxe sur le **thé** (1773) — deux attendues.\n3. « **Pas de taxation sans représentation** » : les colons n'ont **aucun député à Westminster**, ils refusent donc de payer des impôts votés sans eux. Ils réclament d'être traités comme des sujets britanniques.\n4. Le **4 juillet 1776**, le Congrès proclame la **Déclaration d'indépendance**, rédigée par **Jefferson** : tous les hommes sont créés égaux et dotés de droits inaliénables."}$exo$::jsonb),
  ('8c3588f5-9360-5fc9-9624-7d473e4e61aa'::uuid, 2, 'redaction', $exo${"titre":"La frise de l'indépendance","consigne":"Remets les événements dans l'ordre, puis réponds aux questions.","enonce":"**Document – Événements en désordre**\n\n- A. Victoire de Yorktown\n- B. Boston Tea Party\n- C. Constitution des États-Unis\n- D. Premiers combats à Lexington\n- E. Déclaration d'indépendance\n- F. Premier Congrès continental\n- G. Traité reconnaissant les États-Unis\n\n1. Classe les événements dans l'ordre chronologique en donnant la date de chacun.\n2. Quel pays européen aide les insurgés ? Cite deux acteurs de cette aide.\n3. Pourquoi peut-on dire que « le refus fabrique la nation américaine » ?","bareme":[{"critere":"Ordre chronologique juste (B, F, D, E, A, G, C)","points":6},{"critere":"Dates justes : 1773, 1774, 1775, 1776, 1781, 1783, 1787","points":5},{"critere":"Aide de la France avec deux acteurs (La Fayette, Rochambeau, flotte de Grasse)","points":4},{"critere":"Explication : demande d'égalité avec les sujets britanniques, refus de Londres, escalade vers l'indépendance","points":5}],"dureeMin":11,"corrige":"1. Ordre : **B** Boston Tea Party (**1773**) → **F** Premier Congrès continental (**1774**) → **D** combats de Lexington (**1775**) → **E** Déclaration d'indépendance (**4 juillet 1776**) → **A** Yorktown (**1781**) → **G** traité de Paris qui reconnaît les États-Unis (**1783**) → **C** Constitution (**1787**).\n2. La **France** soutient les insurgés : **La Fayette**, **Rochambeau**, la **flotte de Grasse** (deux attendus).\n3. En 1765, les colons ne demandent **pas l'indépendance** : ils veulent être traités comme des **sujets britanniques** et ne pas être taxés sans représentation. Londres refuse, répond à la Boston Tea Party par des **lois coercitives** ; l'escalade conduit aux combats puis à la Déclaration. C'est ce **refus** qui transforme des colons se sentant anglais en **nation américaine**."}$exo$::jsonb),
  ('8c3588f5-9360-5fc9-9624-7d473e4e61aa'::uuid, 3, 'redaction', $exo${"titre":"Une révolution au nom des libertés anglaises","consigne":"Rédige un développement organisé en trois temps, avec dates et exemples précis.","enonce":"**Sujet.** « Les treize colonies se révoltent au nom des libertés anglaises elles-mêmes. »\n\n1. Montre que les colons revendiquent d'abord des droits de sujets britanniques (institutions, rupture fiscale, slogan).\n2. Explique comment on passe de la protestation à l'indépendance (1773-1783).\n3. Présente le régime fondé en 1787 : ce qu'il doit aux Lumières, et sa grande limite.","bareme":[{"critere":"Colonies se sentant anglaises, assemblées élues, taxes après la guerre de Sept Ans","points":4},{"critere":"Slogan « pas de taxation sans représentation » relié au consentement à l'impôt","points":3},{"critere":"Escalade datée : Tea Party, lois coercitives, Congrès, Lexington, Déclaration, Yorktown, traité de 1783","points":5},{"critere":"Constitution de 1787 : fédéral, présidentiel, séparation des pouvoirs inspirée de Montesquieu","points":5},{"critere":"Limite : l'esclavage n'est pas aboli","points":3}],"dureeMin":20,"corrige":"**1. Des sujets britanniques qui réclament leurs droits**\nFondées entre **1607 et 1732**, les colonies ont des **assemblées élues**, une presse active, et leur population se sent **anglaise**. Après la **guerre de Sept Ans** (1756-1763), Londres les taxe : **Sugar Act** (1764), **Stamp Act** (1765), **Townshend Acts** (1767), **thé** (1773). Or elles n'ont **aucun député à Westminster** : « **no taxation without representation** » reprend le principe anglais du **consentement à l'impôt**. En 1765, on ne demande pas l'indépendance.\n\n**2. De la protestation à l'indépendance**\n**Boston Tea Party** (**1773**) puis **lois coercitives** ; **Premier Congrès continental** (**1774**) ; premiers combats à **Lexington** (**1775**) ; **Déclaration d'indépendance** le **4 juillet 1776**, rédigée par **Jefferson** (égalité, droits inaliénables). Victoire de **Yorktown** (**1781**) avec la **France** (La Fayette, Rochambeau, de Grasse) ; le traité de **1783** reconnaît les États-Unis. Le refus de Londres a fabriqué la nation.\n\n**3. Le régime de 1787**\nLa **Constitution** crée un régime **fédéral**, **présidentiel**, fondé sur la **séparation des pouvoirs** héritée de Montesquieu : c'est le **premier grand régime écrit inspiré des Lumières**. Limite majeure : l'**esclavage n'est pas aboli**, alors que les plantations du Sud en dépendent.\n\n**Conclusion** : née d'une revendication de libertés anglaises, la révolution américaine produit un modèle nouveau, mais inachevé."}$exo$::jsonb),
  ('4801649d-0d33-547a-b35c-c7b7211b029a'::uuid, 1, 'redaction', $exo${"titre":"Qui a découvert quoi ?","consigne":"Associe chaque savant à son apport et à sa date, puis réponds à la dernière question.","enonce":"**Questions de cours**\n\n1. Donne l'apport et la date de chacun de ces savants : Copernic, Galilée, Newton, Jenner.\n2. Quelle démarche défend Bacon ? Et Descartes ?\n3. Quelles institutions scientifiques sont fondées à Londres en 1660 et à Paris en 1666 ?","bareme":[{"critere":"Quatre apports datés justes (1543, 1610-1633, 1687, 1796)","points":8},{"critere":"Bacon induction à partir de l'expérience ; Descartes doute méthodique et déduction","points":6},{"critere":"Royal Society (1660) et Académie royale des sciences (1666)","points":6}],"dureeMin":7,"corrige":"1. **Copernic** place le **Soleil au centre** (**1543**). **Galilée** observe les **satellites de Jupiter** et les **phases de Vénus** et est **condamné en 1633** pour avoir défendu l'héliocentrisme. **Newton** énonce la **gravitation universelle** dans les *Principia* (**1687**), unifiant ciel et Terre. **Jenner** met au point la **vaccination antivariolique** (**1796**).\n2. **Bacon** défend l'**induction à partir de l'expérience** ; **Descartes** le **doute méthodique** et la **déduction**. Ensemble : hypothèse, expérience reproductible, formulation mathématique.\n3. La **Royal Society** de Londres (**1660**) et l'**Académie royale des sciences** de Paris (**1666**)."}$exo$::jsonb),
  ('4801649d-0d33-547a-b35c-c7b7211b029a'::uuid, 2, 'redaction', $exo${"titre":"Le cabinet de curiosités de Louise","consigne":"Lis la situation et réponds aux questions en utilisant le cours.","enonce":"**Situation (inventée), vers 1780.** Louise, fille d'un médecin de Rouen, possède chez elle un microscope, un baromètre et un thermomètre. Elle lit un mémoire publié par l'Académie des sciences et recopie des planches de l'*Encyclopédie* sur les métiers de la forge.\n\n1. Qu'est-ce que chacun de ses instruments permet d'observer ou de mesurer ?\n2. Quel est le rôle d'une académie des sciences et des journaux savants ?\n3. Que montrent les planches de l'*Encyclopédie* sur la conception du savoir au temps des Lumières ? Cite un savant des Lumières et son apport à l'appui.","bareme":[{"critere":"Microscope (infiniment petit), baromètre et thermomètre (pression et température mesurées)","points":6},{"critere":"Rôle des académies et journaux : publier, arbitrer, espace de discussion européen","points":6},{"critere":"Idée d'un savoir utile, illustrée par un savant (Buffon, Linné, Lavoisier ou Jenner) et son apport","points":8}],"dureeMin":11,"corrige":"1. Le **microscope** révèle l'**infiniment petit** ; le **baromètre** mesure la **pression** et le **thermomètre** la **température** : on ne se contente plus d'observer, on **mesure**.\n2. L'**Académie royale des sciences** (1666) **publie des mémoires** et **arbitre les querelles** ; les **journaux savants** créent un **espace de discussion européen**. La recherche s'organise.\n3. L'*Encyclopédie* consacre des milliers de planches aux **métiers** : pour les Lumières, **le savoir doit servir**. Exemples : **Lavoisier** fonde la **chimie moderne** et la **conservation de la matière** ; **Jenner** met au point la vaccination antivariolique en 1796 ; **Linné** classe les espèces ; **Buffon** écrit l'*Histoire naturelle* (un exemple attendu)."}$exo$::jsonb),
  ('4801649d-0d33-547a-b35c-c7b7211b029a'::uuid, 3, 'redaction', $exo${"titre":"La nature, un problème à résoudre","consigne":"Rédige un développement organisé en trois parties, appuyé sur des savants, des dates et des exemples.","enonce":"**Sujet.** « La nature n'est plus un livre à commenter : c'est un problème à résoudre, et la langue de la solution est mathématique. »\n\nMontre comment, du XVIe au XVIIIe siècle :\n1. les découvertes bouleversent la vision du monde ;\n2. une nouvelle méthode et de nouveaux instruments s'imposent ;\n3. la science s'organise et se veut utile.","bareme":[{"critere":"Révolution astronomique : Copernic, Kepler, Galilée condamné en 1633, Newton 1687","points":5},{"critere":"Méthode : Bacon, Descartes, expérience reproductible et formulation mathématique","points":4},{"critere":"Instruments et ce qu'ils révèlent (au moins trois)","points":3},{"critere":"Institutions : Royal Society, Académie royale des sciences, journaux savants","points":4},{"critere":"Science utile des Lumières : deux savants et l'Encyclopédie","points":4}],"dureeMin":20,"corrige":"**1. Une nouvelle vision du monde** : **Copernic** place le Soleil au centre (**1543**) ; **Kepler** montre des orbites **elliptiques** ; **Galilée** observe les satellites de Jupiter et les phases de Vénus et est **condamné en 1633** ; **Newton**, dans les *Principia* (**1687**), formule la **gravitation universelle** qui unifie ciel et Terre. La science cesse de commenter les Anciens pour interroger la nature.\n\n**2. Une méthode et des instruments** : **Bacon** prône l'**induction** à partir de l'expérience, **Descartes** le **doute méthodique** et la déduction. D'où la démarche : **hypothèse, expérience reproductible, formulation mathématique**. Les instruments élargissent le regard : **microscope** (infiniment petit), **télescope** (ciel), **baromètre** et **thermomètre** (mesures), **pompe à vide** (le vide, longtemps jugé impossible).\n\n**3. Une science organisée et utile** : **Royal Society** (1660), **Académie royale des sciences** (1666) qui publie et arbitre, **journaux savants** européens. Au XVIIIe siècle, la science veut servir : **Buffon** (*Histoire naturelle*), **Linné** (classification), **Lavoisier** (chimie moderne, conservation de la matière), **Jenner** (vaccination, 1796) ; l'**Encyclopédie** multiplie les planches sur les métiers.\n\n**Conclusion** : la phrase résume ce passage d'un savoir d'autorité à un savoir **expérimental et mathématique**."}$exo$::jsonb),
  ('87232a97-974d-5150-9f90-b8bf0aba8175'::uuid, 1, 'redaction', $exo${"titre":"Les ingrédients de la révolution industrielle","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Que sont les enclosures ? Quelle autre innovation agricole permet à la terre de produire chaque année ?\n2. Donne l'apport de Darby (1709) et celui de James Watt (1769).\n3. Quelle industrie est la première transformée par la mécanisation ? Cite deux machines.\n4. Quel ouvrage Adam Smith publie-t-il en 1776, et quelle doctrine en donne-t-il la théorie ?","bareme":[{"critere":"Enclosures définies et assolement sans jachère","points":5},{"critere":"Coke de Darby et machine à vapeur efficace de Watt","points":5},{"critere":"Textile et deux machines (navette volante, spinning jenny, water frame, mule-jenny)","points":5},{"critere":"La Richesse des nations et le libéralisme","points":5}],"dureeMin":8,"corrige":"1. Les **enclosures** sont des **parcelles regroupées et closes**, qu'on peut exploiter autrement. L'**assolement sans jachère** permet à la terre de produire chaque année.\n2. **Darby** utilise le **coke** (1709) : une fonte de qualité et bon marché. **James Watt** (1769) perfectionne la **machine à vapeur** : une vapeur assez efficace pour tout faire tourner.\n3. Le **textile**, notamment le coton. Machines : **navette volante** (tissage), **spinning jenny** (filature), **water frame**, **mule-jenny** (deux attendues).\n4. *Recherches sur la nature et les causes de la richesse des nations* (**1776**) : Adam Smith donne la théorie du **libéralisme**."}$exo$::jsonb),
  ('87232a97-974d-5150-9f90-b8bf0aba8175'::uuid, 2, 'redaction', $exo${"titre":"Thomas quitte son village pour la fabrique","consigne":"Lis le récit et réponds aux questions en t'appuyant sur le cours.","enonce":"**Récit (inventé), Angleterre, vers 1790.** Le seigneur du village de Thomas a regroupé et clos les champs ; il n'y a plus de travail pour tous. Thomas part pour une ville du Lancashire. Il entre dans une fabrique de coton où une machine à vapeur fait tourner des dizaines de métiers. On y commence à heure fixe, un contremaître surveille, et Thomas ne fait qu'une seule opération toute la journée.\n\n1. Quelle transformation agricole explique le départ de Thomas ? Pourquoi libère-t-elle des bras ?\n2. Pourquoi la machine à vapeur change-t-elle la localisation et le rythme de la production ?\n3. Relève trois changements dans l'organisation du travail à la fabrique.","bareme":[{"critere":"Enclosures et révolution agricole : moins de bras suffisent, exode vers la ville","points":6},{"critere":"Vapeur : énergie indépendante du vent, de l'eau et du muscle, production concentrée et continue","points":7},{"critere":"Trois changements : horaires imposés, surveillance, division des tâches (travail hors de la maison)","points":7}],"dureeMin":11,"corrige":"1. Ce sont les **enclosures** et plus largement la **révolution agricole** (assolement sans jachère, prairies artificielles, sélection du bétail, outils améliorés). La terre produit davantage : **moins de bras suffisent à nourrir plus de monde**, les autres partent en ville.\n2. La machine à vapeur (perfectionnée par **Watt** en 1769) fournit une **énergie qui ne dépend plus du vent, de l'eau ni du muscle** : la production peut **se concentrer où l'on veut** et **tourner toute l'année**.\n3. Le travail **quitte la maison pour la fabrique**, où l'on impose des **horaires**, une **surveillance** (le contremaître) et la **division des tâches** (une seule opération)."}$exo$::jsonb),
  ('87232a97-974d-5150-9f90-b8bf0aba8175'::uuid, 3, 'redaction', $exo${"titre":"Pourquoi l'Angleterre, pourquoi le XVIIIe siècle ?","consigne":"Rédige un développement organisé qui explique les causes de la révolution industrielle anglaise.","enonce":"**Sujet.** « La révolution industrielle ne commence pas avec une machine, mais avec un ensemble de conditions réunies dans l'Angleterre du XVIIIe siècle. »\n\nJustifie cette affirmation en montrant :\n1. le rôle de la révolution agricole et de la démographie ;\n2. le rôle du charbon, de la vapeur et du textile ;\n3. le rôle du cadre économique et institutionnel anglais.","bareme":[{"critere":"Révolution agricole détaillée et transition démographique (mortalité qui recule avant la natalité)","points":5},{"critere":"Coke 1709, Newcomen 1712, Watt 1769 et intérêt de la vapeur","points":4},{"critere":"Machines textiles et passage à la fabrique","points":3},{"critere":"Cadre favorable : empire, marine, banques et Bourse, brevets, canaux, aristocratie investisseuse","points":5},{"critere":"Libéralisme d'Adam Smith et conclusion sur la combinaison des conditions","points":3}],"dureeMin":20,"corrige":"**1. Agriculture et population** : **enclosures**, **assolement sans jachère**, prairies artificielles et sélection du bétail, herse et charrue améliorées. Moins de bras nourrissent plus de monde : la main-d'œuvre part en ville. La **transition démographique** commence : la **mortalité recule avant la natalité**, la population augmente (main-d'œuvre et consommateurs).\n\n**2. Énergie et textile** : le **coke** de **Darby** (**1709**) donne une fonte bon marché ; la machine de **Newcomen** (**1712**) épuise l'eau des mines ; celle de **Watt** (**1769**) fait tout tourner : énergie indépendante du vent, de l'eau et du muscle. Le **textile** se mécanise (**navette volante**, **spinning jenny**, **water frame**, **mule-jenny**) et le travail passe à la **fabrique** (horaires, surveillance, division des tâches).\n\n**3. Un cadre favorable** : l'**empire colonial** (débouchés, matières premières), la **marine marchande**, les **banques** et la **Bourse de Londres** (capital), les **brevets** qui protègent l'inventeur, **canaux et routes**, une **aristocratie qui investit** dans les mines au lieu de thésauriser. Le **libéralisme** d'**Adam Smith** (*La Richesse des nations*, **1776**) en donne la théorie.\n\n**Conclusion** : aucune machine seule n'explique le décollage ; c'est la **réunion** de ces conditions en Angleterre qui le rend possible."}$exo$::jsonb),
  ('9742df00-45f9-5596-b6e1-ac2ef492ab66'::uuid, 1, 'redaction', $exo${"titre":"Ce que paie un paysan en 1789","consigne":"Réponds précisément à chaque question.","enonce":"**Questions de cours**\n\n1. Quels sont les trois ordres de la société ? Lesquels sont privilégiés ?\n2. Pour chacun de ces bénéficiaires, donne un prélèvement payé par le paysan : le roi, l'Église, le seigneur.\n3. Que sont les banalités ?","bareme":[{"critere":"Clergé, noblesse (privilégiés) et tiers état (plus de 97 % de la population)","points":6},{"critere":"Un prélèvement juste pour le roi, l'Église et le seigneur","points":9},{"critere":"Banalités : obligation payante d'utiliser four, moulin ou pressoir du seigneur","points":5}],"dureeMin":6,"corrige":"1. Les trois ordres : le **clergé** (environ 130 000) et la **noblesse** (environ 350 000), qui sont **privilégiés** (exemptions fiscales, justice propre, honneurs réservés), et le **tiers état**, plus de **97 %** de la population, qui paie.\n2. Au **roi** : la **taille**, la **capitation** ou la **gabelle** sur le sel. À l'**Église** : la **dîme**. Au **seigneur** : le **cens**, les **banalités**, les **corvées** ou les droits de mutation.\n3. Les **banalités** sont l'**obligation payante d'utiliser le four, le moulin ou le pressoir du seigneur**."}$exo$::jsonb),
  ('9742df00-45f9-5596-b6e1-ac2ef492ab66'::uuid, 2, 'redaction', $exo${"titre":"Le budget de Jacques, laboureur","consigne":"Analyse la situation et réponds aux questions en utilisant le cours.","enonce":"**Situation (inventée), printemps 1789, dans le Bassin parisien.** Jacques, laboureur, vient de payer la taille au collecteur du roi, la dîme au curé, et son seigneur lui réclame un droit oublié depuis cinquante ans, retrouvé dans un vieux registre. La récolte de 1788 a été mauvaise et le prix du pain flambe.\n\n1. Comment s'appelle le fait, pour un seigneur, de faire revivre des droits tombés en désuétude ? Comment s'appelle le registre ?\n2. Pourquoi ces droits sont-ils « particulièrement mal supportés » ?\n3. Explique comment la situation de Jacques conduit aux événements de l'été 1789 dans les campagnes.","bareme":[{"critere":"Réaction seigneuriale et terrier (registre des droits seigneuriaux)","points":6},{"critere":"Explication : le seigneur prend sans rien rendre, pression cumulée des prélèvements","points":5},{"critere":"Enchaînement : récolte de 1788, hiver, prix du pain, émeutes, Grande Peur et terriers brûlés, 4 août","points":9}],"dureeMin":12,"corrige":"1. C'est la **réaction seigneuriale** : au XVIIIe siècle, certains seigneurs font revivre des **droits féodaux**. Le registre est le **terrier**, qui recense les droits et redevances dus au seigneur.\n2. Ils s'ajoutent à la **taille** royale et à la **dîme** : le paysan paie au roi, à l'Église et au seigneur. Surtout, ce que le paysan reproche au seigneur, ce n'est pas seulement de prendre, c'est de **prendre sans rien rendre**.\n3. En **1788**, mauvaises récoltes et hiver rigoureux ; au **printemps 1789**, le **prix du pain flambe** et provoque des **émeutes frumentaires**. En **juillet-août 1789**, la **Grande Peur** parcourt les campagnes : les paysans **brûlent les terriers**. La **nuit du 4 août 1789**, l'Assemblée **abolit les privilèges**."}$exo$::jsonb),
  ('9742df00-45f9-5596-b6e1-ac2ef492ab66'::uuid, 3, 'redaction', $exo${"titre":"Comprendre 1789 par les campagnes","consigne":"Rédige un développement argumenté en trois parties, avec des exemples précis du cours.","enonce":"**Sujet.** « Comprendre 1789 suppose de comprendre ce que vivent ces quatre Français sur cinq. »\n\n1. Présente la société d'ordres et les privilèges.\n2. Montre le poids des prélèvements sur les paysans et la diversité des campagnes françaises.\n3. Explique comment la crise de 1788-1789 transforme le mécontentement paysan en révolte, et ce qu'elle obtient.","bareme":[{"critere":"Trois ordres avec effectifs et contenu des privilèges","points":4},{"critere":"Prélèvements royaux, ecclésiastiques et seigneuriaux, réaction seigneuriale","points":5},{"critere":"Diversité régionale (Bassin parisien, Sud-Ouest, Ouest, montagne) et dépendance à la récolte","points":4},{"critere":"Chronologie 1788 → Grande Peur → 4 août 1789 bien expliquée","points":5},{"critere":"Organisation et conclusion qui répond au sujet","points":2}],"dureeMin":20,"corrige":"**1. La société d'ordres** : le **clergé** (130 000) et la **noblesse** (350 000) sont **privilégiés** : **exemptions fiscales**, **justice propre**, **honneurs réservés**. Le **tiers état**, plus de **97 %** de la population, **paie**. Quatre Français sur cinq vivent de la terre.\n\n**2. Des paysans pressurés, des campagnes inégales** : le paysan paie au **roi** (**taille**, **capitation**, **gabelle**), à l'**Église** (**dîme**), au **seigneur** (**cens**, **banalités** du four, du moulin et du pressoir, **corvées**, droits de mutation). La **réaction seigneuriale** qui ressuscite des droits oubliés est très mal supportée : le seigneur prend sans rien rendre. Les campagnes sont diverses : **grandes fermes céréalières** du **Bassin parisien**, **métayage** dans le **Sud-Ouest**, **bocages** de l'**Ouest**, **petite propriété** en **montagne**. Les progrès agricoles restent limités et la **subsistance dépend de la récolte** de l'année.\n\n**3. De la crise à la révolte** : **1788**, mauvaises récoltes et hiver rigoureux ; **printemps 1789**, flambée du prix du pain et **émeutes frumentaires** ; **juillet-août 1789**, la **Grande Peur** : les paysans brûlent les **terriers**. La **nuit du 4 août 1789**, les **privilèges sont abolis**.\n\n**Conclusion** : la Révolution n'est pas seulement parisienne : la colère paysanne contre les prélèvements et les privilèges en est un moteur décisif."}$exo$::jsonb),
  ('8ee512e1-b90b-5c96-ab68-71ae8071b8a8'::uuid, 1, 'redaction', $exo${"titre":"La ville au XVIIIe siècle en chiffres","consigne":"Réponds à chaque question en une ou deux phrases précises.","enonce":"**Questions de cours sur le monde urbain avant 1789**\n\n1. Quelle part des Français vit en ville ? Combien d'habitants compte Paris ?\n2. Pourquoi les ports de la façade atlantique s'enrichissent-ils ?\n3. À quel ordre appartient juridiquement la bourgeoisie ? Cite trois métiers bourgeois.\n4. Quelle dépense pèse le plus lourd dans le budget du peuple des villes ?","bareme":[{"critere":"Environ 20 % de citadins et près de 600 000 Parisiens","points":5},{"critere":"Commerce colonial et traite","points":4},{"critere":"Tiers état et trois métiers justes","points":6},{"critere":"Le pain, qui absorbe parfois la moitié du revenu","points":5}],"dureeMin":7,"corrige":"1. Environ **20 %** des Français vivent en ville. **Paris** compte **près de 600 000 habitants** ; Lyon, Marseille, Bordeaux et Nantes dépassent 50 000.\n2. Les ports atlantiques (Bordeaux, Nantes, La Rochelle) s'enrichissent du **commerce colonial** et de la **traite**.\n3. La bourgeoisie appartient juridiquement au **tiers état**. Métiers : **négociants**, **armateurs**, **manufacturiers**, **avocats**, **médecins**, **officiers** (trois attendus).\n4. Le **pain** : son prix **absorbe parfois la moitié du revenu** des compagnons et ouvriers."}$exo$::jsonb),
  ('8ee512e1-b90b-5c96-ab68-71ae8071b8a8'::uuid, 2, 'redaction', $exo${"titre":"Une soirée au café du Palais-Royal","consigne":"Lis la situation et réponds aux questions en utilisant le cours.","enonce":"**Situation (inventée), Paris, 1788.** Antoine, avocat au parlement, riche mais roturier, retrouve des amis au café. On y lit des journaux, on se passe un libelle clandestin qui critique la cour, puis certains partent pour une loge maçonnique. Antoine se plaint : « Mon voisin, fils de noble, obtient les honneurs sans rien avoir fait. »\n\n1. Qu'est-ce qui manque à Antoine, malgré sa fortune et ses compétences ? Que peut faire un bourgeois pour s'élever ?\n2. Relève les lieux et les supports où se forme l'opinion publique.\n3. Comment l'opinion urbaine se manifeste-t-elle en 1789 ?","bareme":[{"critere":"Le statut : juridiquement du tiers état ; achat d'offices, parfois de la noblesse ; rejet des privilèges","points":7},{"critere":"Lieux et supports : cafés, salons, loges, académies, cabinets de lecture, journaux, libelles","points":6},{"critere":"Cahiers de doléances les plus politiques et prise de la Bastille le 14 juillet","points":7}],"dureeMin":11,"corrige":"1. Il lui manque le **statut** : la bourgeoisie a la **fortune et les compétences**, mais reste **juridiquement dans le tiers état**. Un bourgeois peut **acheter des offices**, parfois **la noblesse**. Il supporte de plus en plus mal des **privilèges** jugés injustifiés : une société où le mérite s'arrête à la naissance finit par produire des gens qui veulent changer la règle.\n2. L'opinion se forme dans les **cafés** et les **salons** (discussion des idées des Lumières), les **loges maçonniques** et les **académies de province**, les **cabinets de lecture**, par les **journaux** et les **libelles clandestins**.\n3. En **1789**, les villes rédigent les **cahiers de doléances les plus politiques** ; à Paris, le peuple prend la **Bastille le 14 juillet**."}$exo$::jsonb),
  ('8ee512e1-b90b-5c96-ab68-71ae8071b8a8'::uuid, 3, 'redaction', $exo${"titre":"La ville, fabrique de la contestation","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Sujet.** « Les villes rassemblent moins d'un Français sur cinq, mais c'est là que se concentrent la richesse, l'information et la contestation. »\n\n1. Montre que la ville concentre la richesse (poids des villes, ports, bourgeoisie).\n2. Montre qu'elle concentre aussi la fragilité sociale.\n3. Montre qu'elle est le lieu de l'information et de la contestation, jusqu'en 1789.","bareme":[{"critere":"Poids urbain chiffré et richesse des ports atlantiques","points":3},{"critere":"Bourgeoisie : métiers, fortune sans statut, frustration face aux privilèges","points":5},{"critere":"Peuple des villes : pain, précarité, mendiants surveillés par la police","points":4},{"critere":"Lieux de l'opinion et diffusion de la critique","points":4},{"critere":"1789 : cahiers de doléances politiques et prise de la Bastille","points":4}],"dureeMin":20,"corrige":"**1. La richesse** : la France est peu urbaine (**20 %** de citadins) mais **Paris** a près de **600 000 habitants**, et Lyon, Marseille, Bordeaux, Nantes plus de 50 000. Les ports atlantiques s'enrichissent du **commerce colonial** et de la **traite**. La **bourgeoisie** monte : **négociants, armateurs, manufacturiers, avocats, médecins, officiers**. Elle a la fortune et les compétences mais reste dans le **tiers état** ; elle achète des offices, parfois la noblesse, et supporte mal les **privilèges**.\n\n**2. La fragilité** : compagnons et ouvriers dépendent du **prix du pain**, qui absorbe parfois **la moitié du revenu** ; domestiques, portefaix et petits métiers vivent dans la précarité ; la ville concentre **mendiants et malades**, surveillés par la **police du roi**. Une hausse du pain y devient vite une crise.\n\n**3. L'information et la contestation** : **cafés** et **salons** discutent les idées des Lumières ; **loges maçonniques** et **académies de province** tissent des réseaux ; **cabinets de lecture, journaux, libelles clandestins** font circuler la critique : c'est l'**opinion publique**. En **1789**, les villes rédigent les **cahiers de doléances les plus politiques** et Paris prend la **Bastille** le **14 juillet**.\n\n**Conclusion** : minoritaire, la ville réunit ceux qui ont les moyens, les idées et les raisons de contester."}$exo$::jsonb),
  ('d9cf3639-b19c-55c6-8014-782cfe4080cf'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire du risque","consigne":"Définis chaque mot en une phrase, puis réponds à la dernière question.","enonce":"**Questions de cours**\n\n1. Définis : aléa, vulnérabilité, risque, catastrophe, résilience.\n2. Classe ces exemples dans le bon type de risque (naturel, technologique, sanitaire, hybride) : une épidémie ; une crue ; l'accident de Fukushima en 2011 ; une explosion dans une usine chimique.","bareme":[{"critere":"Cinq définitions justes, dont risque = croisement aléa et vulnérabilité","points":12},{"critere":"Classement juste des quatre exemples","points":8}],"dureeMin":7,"corrige":"1. - **Aléa** : l'événement possible (séisme, cyclone, crue, accident industriel).\n- **Vulnérabilité** : la fragilité des populations et des biens exposés.\n- **Risque** : le **croisement** d'un aléa et d'une vulnérabilité.\n- **Catastrophe** : le risque **réalisé**.\n- **Résilience** : la capacité d'un territoire à **se relever**.\n2. Épidémie → **sanitaire** ; crue → **naturel** (hydrologique) ; Fukushima 2011 → **hybride** (un aléa naturel déclenche un accident technologique) ; explosion d'usine chimique → **technologique**."}$exo$::jsonb),
  ('d9cf3639-b19c-55c6-8014-782cfe4080cf'::uuid, 2, 'redaction', $exo${"titre":"Même séisme, deux bilans","consigne":"Compare les deux situations et réponds en utilisant le vocabulaire du cours.","enonce":"**Document – Deux séismes de même magnitude (situation inventée)**\n\n| | Ville A (pays riche) | Ville B (pays pauvre) |\n|---|---|---|\n| Constructions | Normes parasismiques | Maisons sans normes |\n| Alerte et exercices | Oui, réguliers | Non |\n| Secours | Organisés, rapides | Débordés |\n| Victimes | Quelques dizaines | Des dizaines de milliers |\n| Dégâts matériels | Très coûteux | Moins coûteux en valeur |\n\n1. L'aléa est-il le même dans les deux villes ? Qu'est-ce qui explique la différence de bilan ?\n2. Distingue, avec les exemples du tableau, prévision, prévention et gestion de crise.\n3. Pourquoi les pays du Nord concentrent-ils l'essentiel des dégâts matériels et ceux du Sud l'essentiel des victimes ?","bareme":[{"critere":"Aléa identique, différence de vulnérabilité : la différence est sociale et non géologique","points":6},{"critere":"Prévision, prévention et gestion de crise distinguées avec des exemples justes","points":8},{"critere":"Explication Nord (biens de grande valeur) / Sud (populations plus vulnérables)","points":6}],"dureeMin":12,"corrige":"1. Oui, l'**aléa** est le même (même magnitude). La différence tient à la **vulnérabilité** : constructions, préparation, secours. Comme entre le Japon et Haïti, **la différence n'est pas géologique, elle est sociale**.\n2. - **Prévision** : annoncer l'aléa (surveillance sismique, alerte).\n- **Prévention** : réduire la vulnérabilité (**normes parasismiques**, plans de prévention, zones inconstructibles, **exercices et éducation**).\n- **Gestion de crise** : **secours**, évacuation, information.\nLa ville A cumule les trois ; la ville B presque aucun.\n3. Dans le **Nord**, les biens exposés ont une grande valeur mais les populations sont protégées : beaucoup de **dégâts matériels**, peu de victimes. Au **Sud**, les populations sont **plus vulnérables** (constructions fragiles, moyens limités) : l'essentiel des **victimes**."}$exo$::jsonb),
  ('d9cf3639-b19c-55c6-8014-782cfe4080cf'::uuid, 3, 'redaction', $exo${"titre":"Un risque est toujours social","consigne":"Rédige un développement organisé et argumenté, avec des exemples précis du cours.","enonce":"**Sujet.** « Un séisme au milieu du Pacifique n'est pas un risque : c'est un phénomène. »\n\n1. Explique cette phrase à l'aide du vocabulaire du risque.\n2. Montre que l'exposition des sociétés aux risques augmente et qu'elle est inégale dans le monde.\n3. Montre comment les sociétés peuvent réduire les risques, en suivant le cycle de la prévision à la reconstruction, avec l'exemple de la France.","bareme":[{"critere":"Définitions mobilisées : sans enjeux humains, pas de risque","points":4},{"critere":"Types de risques dont l'exemple hybride de Fukushima","points":3},{"critere":"Exposition croissante : littoralisation, urbanisation, métropolisation ; contraste Nord/Sud","points":5},{"critere":"Cycle prévision, prévention, gestion de crise, reconstruction","points":5},{"critere":"Exemple français : PPR et indemnisation des catastrophes naturelles","points":3}],"dureeMin":20,"corrige":"**1.** Le **risque** naît du **croisement d'un aléa et d'une vulnérabilité**. Au milieu du Pacifique, il n'y a ni habitants ni biens exposés : l'aléa existe, mais pas le risque. Une **catastrophe** est un risque réalisé ; la **résilience**, la capacité à se relever. Le risque peut être **naturel**, **technologique**, **sanitaire** ou **hybride** (**Fukushima**, 2011 : un aléa naturel déclenche un accident nucléaire).\n\n**2.** L'exposition augmente avec la **littoralisation**, l'**urbanisation** et la **métropolisation** : les hommes s'installent là où l'aléa est fort (deltas, côtes cycloniques, versants instables). Elle est **inégale** : à magnitude égale, quelques dizaines de morts au **Japon**, des dizaines de milliers en **Haïti**. Les pays du **Sud** concentrent les **victimes**, ceux du **Nord** les **dégâts matériels**.\n\n**3.** Réduire le risque : **prévision** (surveillance sismique, alerte cyclonique), **prévention** (normes parasismiques, plans de prévention, zones inconstructibles, éducation), **gestion de crise** (secours, évacuation, information), **reconstruction**, qui peut réduire ou reproduire la vulnérabilité. En **France**, les **PPR** et le système d'**indemnisation des catastrophes naturelles** encadrent l'aménagement.\n\n**Conclusion** : on ne supprime pas l'aléa, mais on agit sur la vulnérabilité : le risque est une construction sociale."}$exo$::jsonb),
  ('1aadc75b-431f-5447-a6c4-b987df72bcdc'::uuid, 1, 'redaction', $exo${"titre":"Le mécanisme du changement climatique","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Quels gaz à effet de serre le cours cite-t-il, et quel effet leur concentration produit-elle ?\n2. Quelles sont les deux causes de la hausse du niveau marin ?\n3. Qu'est-ce que la salinisation ?\n4. Distingue adaptation et atténuation.","bareme":[{"critere":"Dioxyde de carbone et méthane, réchauffement de l'atmosphère","points":4},{"critere":"Dilatation de l'eau et fonte des glaces","points":5},{"critere":"Salinisation : avancée de l'eau salée dans nappes et sols","points":4},{"critere":"Adaptation locale (réduire les effets subis) / atténuation mondiale (réduire les émissions)","points":7}],"dureeMin":7,"corrige":"1. Le **dioxyde de carbone** et le **méthane** : leur concentration provoque le **réchauffement de l'atmosphère**.\n2. La **dilatation de l'eau** qui se réchauffe et la **fonte des glaces**.\n3. La **salinisation** est l'**avancée de l'eau salée** dans les **nappes** et les **sols**, qui les rend impropres à la culture.\n4. L'**adaptation** consiste à **réduire les effets subis** localement (digues, abris, alerte, cultures adaptées). L'**atténuation** consiste à **réduire les émissions** de gaz à effet de serre à l'échelle mondiale (accord de Paris, 2015)."}$exo$::jsonb),
  ('1aadc75b-431f-5447-a6c4-b987df72bcdc'::uuid, 2, 'redaction', $exo${"titre":"Le village de Rahima dans le delta","consigne":"Lis le témoignage inventé et réponds aux questions en t'appuyant sur le cours.","enonce":"**Témoignage (inventé) de Rahima, agricultrice au sud du Bangladesh**\n\n> « Mon père cultivait du riz ici. Aujourd'hui, l'eau du puits est salée et nos voisins ont transformé leurs rizières en bassins à crevettes. Le dernier cyclone a arraché les arbres de la mangrove qui nous protégeaient. Mon frère est parti chercher du travail à Dacca. Au village, on a construit un abri sur piliers et on essaie un riz qui supporte le sel. »\n\n1. Relève trois effets du changement climatique décrits par Rahima et explique leur cause.\n2. Pourquoi le delta du Gange-Brahmapoutre est-il particulièrement exposé ? Donne deux chiffres du cours.\n3. Classe les réponses évoquées par Rahima : s'agit-il d'adaptation ou d'atténuation ? Justifie.","bareme":[{"critere":"Trois effets expliqués : salinisation, cyclones et recul des mangroves, migrations vers Dacca","points":8},{"critere":"Exposition expliquée avec deux chiffres (170 millions, moins de 10 m d'altitude, moins de la moitié de la France)","points":6},{"critere":"Abri et riz tolérant au sel classés en adaptation, justifié","points":6}],"dureeMin":12,"corrige":"1. - **Salinisation** : l'eau salée avance avec la **hausse du niveau marin** ; les puits sont salés et les **rizières cèdent la place à l'aquaculture de crevettes**.\n- **Cyclones plus intenses** (atmosphère plus chaude) et **recul des mangroves des Sundarbans** : perte de la protection naturelle.\n- **Migrations climatiques** vers **Dacca**, l'une des villes les plus denses du monde.\n2. Le Bangladesh compte environ **170 millions** d'habitants sur **moins de la moitié de la superficie de la France**, en grande partie **sous 10 mètres d'altitude** : forte exposition, forte densité, faibles moyens.\n3. L'**abri anticyclonique** et le **riz tolérant au sel** relèvent de l'**adaptation** : ils réduisent les effets subis localement, sans réduire les émissions (ce serait l'atténuation)."}$exo$::jsonb),
  ('1aadc75b-431f-5447-a6c4-b987df72bcdc'::uuid, 3, 'redaction', $exo${"titre":"Le Bangladesh et la justice climatique","consigne":"Rédige un développement organisé en trois parties, appuyé sur l'exemple du cours.","enonce":"**Sujet.** « Le Bangladesh émet très peu et subit beaucoup. » Montre en quoi le delta du Gange-Brahmapoutre illustre les effets du changement climatique sur un territoire densément peuplé.\n\n1. Explique le mécanisme du changement climatique et ses conséquences.\n2. Montre les effets en chaîne sur le delta.\n3. Présente les réponses aux différentes échelles et explique la notion de justice climatique.","bareme":[{"critere":"Mécanisme : gaz à effet de serre, hausse du niveau marin, cyclones, salinisation","points":4},{"critere":"Caractéristiques du territoire chiffrées (170 millions, altitude, superficie)","points":3},{"critere":"Effets en chaîne : inondations, érosion, Sundarbans, rizières, migrations vers Dacca","points":5},{"critere":"Adaptation locale et atténuation mondiale (Paris 2015, GIEC)","points":5},{"critere":"Justice climatique expliquée","points":3}],"dureeMin":20,"corrige":"**1. Le mécanisme** : la concentration de **gaz à effet de serre** (dioxyde de carbone, méthane) réchauffe l'atmosphère. La **dilatation de l'eau** et la **fonte des glaces** font **monter le niveau marin** ; une atmosphère plus chaude rend les **cyclones plus intenses** et les **moussons plus irrégulières** ; l'eau salée avance : **salinisation**.\n\n**2. Un delta en première ligne** : le Bangladesh, environ **170 millions** d'habitants sur moins de la moitié de la France, en grande partie **sous 10 m**. Une élévation d'un mètre menacerait une part importante des terres cultivées et des millions de personnes. Effets : **inondations** et **cyclones du golfe du Bengale**, **érosion des côtes**, **recul des mangroves des Sundarbans**, **rizières remplacées par l'aquaculture de crevettes**, **migrations climatiques** qui gonflent **Dacca**.\n\n**3. Répondre** : **adaptation** locale (digues, abris anticycloniques, alerte précoce, **riz tolérant au sel**, maisons sur pilotis, **mangroves replantées**) ; **atténuation** mondiale : réduire les émissions (**accord de Paris**, 2015 ; rapports du **GIEC**).\nLa **justice climatique** : le Bangladesh **émet très peu** de gaz à effet de serre mais **subit fortement** les effets ; il dépend de décisions prises surtout par les gros émetteurs.\n\n**Conclusion** : le changement climatique frappe partout, mais pas également."}$exo$::jsonb),
  ('7f9f4c6f-c662-500b-b570-3b0701cfd1fc'::uuid, 1, 'redaction', $exo${"titre":"L'Amazonie en quelques repères","consigne":"Réponds à chaque question en une ou deux phrases précises.","enonce":"**Questions de cours**\n\n1. Donne la superficie de l'Amazonie, le nombre de pays concernés et la part brésilienne.\n2. Quels sont les deux rôles environnementaux majeurs de la forêt ?\n3. Quelles sont la première et la deuxième cause de déforestation ?\n4. Qu'est-ce qu'un conflit d'usage ?","bareme":[{"critere":"5,5 millions de km², neuf pays, 60 % au Brésil","points":5},{"critere":"Stockage du carbone et évapotranspiration qui alimente les pluies (ou biodiversité)","points":5},{"critere":"Élevage bovin puis soja","points":5},{"critere":"Définition du conflit d'usage","points":5}],"dureeMin":7,"corrige":"1. Environ **5,5 millions de km²**, sur **neuf pays**, dont **60 %** au **Brésil**.\n2. Elle **stocke** une quantité considérable de **carbone** et, par l'**évapotranspiration**, **alimente les pluies** d'une bonne partie du continent ; elle abrite aussi une part majeure de la **biodiversité** terrestre.\n3. L'**élevage bovin** est la **première** cause, la culture du **soja** le deuxième front.\n4. Un **conflit d'usage** oppose des acteurs qui veulent **utiliser autrement un même espace** (exploiter ou préserver la forêt, par exemple)."}$exo$::jsonb),
  ('7f9f4c6f-c662-500b-b570-3b0701cfd1fc'::uuid, 2, 'redaction', $exo${"titre":"Une route dans la forêt","consigne":"Lis la situation et réponds aux questions en utilisant le cours.","enonce":"**Situation (inventée).** Dans l'État du Pará, une nouvelle piste est ouverte depuis une grande route. En quelques années, de part et d'autre, des parcelles sont défrichées en « arêtes de poisson » : des colons pauvres venus du Nordeste s'installent, puis de grands éleveurs rachètent les terres pour y mettre des bœufs. Plus loin, des orpailleurs creusent le lit d'une rivière. Une communauté autochtone voisine proteste.\n\n1. Pourquoi les routes jouent-elles un rôle clé dans la déforestation ?\n2. Identifie quatre acteurs de la situation et l'intérêt de chacun.\n3. Quelle pollution l'orpaillage provoque-t-il ?","bareme":[{"critere":"Routes qui ouvrent la forêt, recul en arêtes de poisson le long des routes","points":5},{"critere":"Quatre acteurs avec leur intérêt (colons, éleveurs/agro-industrie, orpailleurs, peuples autochtones)","points":10},{"critere":"Pollution au mercure","points":5}],"dureeMin":10,"corrige":"1. Les **routes**, à commencer par la **Transamazonienne**, **ouvrent la forêt** : elle recule le long des routes, **en arêtes de poisson**, ferme après ferme.\n2. - **Colons pauvres venus du Nordeste** : **survivre**.\n- **Grands propriétaires, agro-industrie** (éleveurs) : **valoriser la terre** ; l'**élevage bovin** est la première cause de déforestation.\n- **Orpailleurs** : **extraire** l'or.\n- **Peuples autochtones** : garder des **terres reconnues, mais mal protégées**.\n(L'État fédéral et les ONG cherchent à préserver et arbitrer.)\n3. L'orpaillage **pollue au mercure** les rivières."}$exo$::jsonb),
  ('7f9f4c6f-c662-500b-b570-3b0701cfd1fc'::uuid, 3, 'redaction', $exo${"titre":"Exploiter ou préserver l'Amazonie ?","consigne":"Rédige un développement organisé en trois parties, avec des exemples et des chiffres du cours.","enonce":"**Sujet.** L'Amazonie : une ressource majeure sous pression. Montre :\n1. ce que représente la forêt amazonienne ;\n2. les pressions qu'elle subit et les conflits d'acteurs qu'elles provoquent ;\n3. les outils d'un développement durable et leurs résultats.","bareme":[{"critere":"Repères chiffrés et rôles (biodiversité, carbone, évapotranspiration)","points":4},{"critere":"Au moins quatre pressions dont élevage et soja, et déforestation cumulée de plus de 17 %","points":5},{"critere":"Acteurs et violence du conflit (Chico Mendes, 1988)","points":4},{"critere":"Outils de protection (aires protégées, satellite, moratoire, agroforesterie…)","points":5},{"critere":"Résultats variables selon les politiques fédérales","points":2}],"dureeMin":20,"corrige":"**1. Une forêt d'importance mondiale** : **5,5 millions de km²** sur neuf pays, **60 %** au Brésil ; une part majeure de la **biodiversité** terrestre ; un **stock de carbone** considérable ; l'**évapotranspiration** alimente les pluies d'une bonne partie du continent.\n\n**2. Des pressions et des conflits** : **élevage bovin** (première cause), **soja** (deuxième front), exploitation forestière légale et illégale, **orpaillage** (mercure), **barrages** comme **Belo Monte**, **routes** comme la Transamazonienne. La déforestation cumulée dépasse **17 %** du massif. Acteurs : agro-industrie (valoriser), colons du Nordeste (survivre), orpailleurs et firmes minières (extraire), **peuples autochtones** (terres reconnues mais mal protégées), ONG et État fédéral (préserver, arbitrer). La violence du conflit : l'assassinat de **Chico Mendes** en **1988**.\n\n**3. Vers un développement durable** : **aires protégées** et **terres indigènes**, **surveillance satellitaire** en temps quasi réel, **moratoire sur le soja** et certification du bois (action par la demande), **agroforesterie**, écotourisme et produits de la forêt, qui valorisent la **forêt debout**. Les résultats **varient selon les politiques fédérales** : forte baisse dans les années 2000, remontée, puis nouveau recul.\n\n**Conclusion** : l'Amazonie est un conflit d'usage frontal entre exploitation et préservation."}$exo$::jsonb),
  ('9043c580-74d5-5c0e-816e-6ef231d7e5ff'::uuid, 1, 'redaction', $exo${"titre":"L'Arctique, un milieu qui fond","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. À quelle vitesse l'Arctique se réchauffe-t-il par rapport au reste de la planète ?\n2. Qu'est-ce que le pergélisol ? Quelles sont deux conséquences de son dégel ?\n3. Quelles sont les deux routes maritimes arctiques et le long de quelles côtes passent-elles ?","bareme":[{"critere":"Deux à quatre fois plus vite","points":4},{"critere":"Pergélisol défini et deux conséquences (routes et bâtiments déstabilisés, méthane libéré)","points":8},{"critere":"Route maritime du Nord (côtes russes) et passage du Nord-Ouest (Canada)","points":8}],"dureeMin":6,"corrige":"1. L'Arctique se réchauffe **deux à quatre fois plus vite** que le reste de la planète.\n2. Le **pergélisol** est un **sol gelé en permanence**. Son dégel **déstabilise routes et bâtiments** et **libère du méthane**, qui accélère le réchauffement : une boucle qui s'auto-entretient.\n3. La **route maritime du Nord** longe les **côtes russes** ; le **passage du Nord-Ouest** longe le **Canada**."}$exo$::jsonb),
  ('9043c580-74d5-5c0e-816e-6ef231d7e5ff'::uuid, 2, 'redaction', $exo${"titre":"Un armateur hésite","consigne":"Lis la situation et aide l'armateur à décider, en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Un armateur doit envoyer un porte-conteneurs de Rotterdam à Shanghai. Son adjoint, Lars, propose la route maritime du Nord plutôt que le canal de Suez.\n\n1. Quel gain de distance cette route offre-t-elle, selon le cours ?\n2. Quels inconvénients l'armateur doit-il prendre en compte ?\n3. Pourquoi la fonte de la banquise rend-elle cette route possible, et pourquoi ce même phénomène inquiète-t-il ?\n4. Au-delà du transport, quelles ressources rendent l'Arctique attractif ? Cite-en trois.","bareme":[{"critere":"Environ un tiers de distance en moins par rapport à Suez","points":4},{"critere":"Inconvénients : usage saisonnier, assurances coûteuses, brise-glaces","points":5},{"critere":"Fonte de la banquise : accès ouvert, mais milieu fragile et réchauffement accéléré","points":5},{"critere":"Trois ressources : pétrole et gaz, minerais et terres rares, pêche","points":6}],"dureeMin":11,"corrige":"1. La route maritime du Nord fait gagner **environ un tiers** de distance par rapport à Suez entre l'Europe et l'Asie orientale.\n2. Son usage reste **saisonnier** et **coûteux** : **assurances** élevées et besoin de **brise-glaces**.\n3. La surface d'été de la **banquise** a perdu une large part depuis 1979 : l'eau libre ouvre la route. Mais c'est le signe d'un milieu **extrême et vulnérable** : le dégel du pergélisol libère du méthane et accélère le réchauffement ; la toundra se régénère lentement. Ce qui menace le milieu le rend, paradoxalement, plus accessible.\n4. Ressources : **pétrole et gaz** (part significative des réserves non découvertes), **minerais** et **terres rares**, **pêche** (zones qui remontent vers le nord)."}$exo$::jsonb),
  ('9043c580-74d5-5c0e-816e-6ef231d7e5ff'::uuid, 3, 'redaction', $exo${"titre":"L'Arctique, espace fragile et convoité","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Sujet.** « Ce que la fonte ouvre, ce ne sont pas seulement des routes : c'est un espace où les frontières restent à négocier. »\n\nMontre :\n1. que l'Arctique est un milieu fragile ;\n2. qu'il devient un espace attractif (ressources, routes) ;\n3. que sa gouvernance met en jeu de nombreux acteurs et des règles internationales.","bareme":[{"critere":"Fragilité : réchauffement 2 à 4 fois plus rapide, banquise, pergélisol et méthane, toundra","points":5},{"critere":"Ressources : hydrocarbures, minerais et terres rares, pêche","points":3},{"critere":"Routes : Nord et Nord-Ouest, gain et limites","points":4},{"critere":"Acteurs : huit États du Conseil de l'Arctique, Inuits représentés, Chine « État proche »","points":5},{"critere":"Montego Bay et plateau continental pour les fonds marins","points":3}],"dureeMin":20,"corrige":"**1. Un milieu fragile** : l'Arctique se réchauffe **deux à quatre fois plus vite** que la planète ; la **banquise** d'été a perdu une large part depuis 1979 ; le dégel du **pergélisol** déstabilise routes et bâtiments et libère du **méthane**, boucle qui s'auto-entretient ; la **toundra** a des écosystèmes simples, lents à se régénérer.\n\n**2. Un espace attractif** : **pétrole et gaz** (part significative des réserves non découvertes), **minerais et terres rares**, **pêche** qui remonte vers le nord. La **route maritime du Nord** (côtes russes) réduit d'environ **un tiers** le trajet Europe-Asie par rapport à Suez ; le **passage du Nord-Ouest** (Canada) s'ouvre aussi. Leur usage reste saisonnier et coûteux (assurances, brise-glaces).\n\n**3. Une gouvernance à négocier** : les **huit États** arctiques — Russie, Canada, États-Unis, Danemark via le Groenland, Norvège, Islande, Suède, Finlande — coopèrent au **Conseil de l'Arctique**, où les **peuples autochtones**, dont les **Inuits**, sont représentés. La **Chine** se déclare « **État proche de l'Arctique** ». Les revendications sur les fonds marins s'arbitrent selon la convention de **Montego Bay** et la règle du **plateau continental**.\n\n**Conclusion** : la fonte transforme un milieu menacé en frontière disputée."}$exo$::jsonb),
  ('2dfa078f-f914-5195-a3c6-4ec964cbcd24'::uuid, 1, 'redaction', $exo${"titre":"La France, puissance maritime","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Quel est le rang mondial de la zone économique exclusive française, sa superficie approximative, et la part due aux outre-mer ?\n2. Cite deux ressources valorisées dans les outre-mer, en précisant le territoire.\n3. Qu'est-ce que le Conservatoire du littoral ? Et Natura 2000 ?","bareme":[{"critere":"Deuxième ZEE du monde, environ 10,2 millions de km², plus de 96 % grâce aux outre-mer","points":7},{"critere":"Deux ressources localisées (Kourou en Guyane, nickel calédonien…)","points":6},{"critere":"Conservatoire (achat foncier) et Natura 2000 (réseau européen)","points":7}],"dureeMin":7,"corrige":"1. La ZEE française est la **deuxième du monde**, environ **10,2 millions de km²**, dont **plus de 96 %** grâce aux **outre-mer**.\n2. Exemples : le **centre spatial de Kourou** en **Guyane**, le **nickel** de **Nouvelle-Calédonie**, la **banane et la canne** aux Antilles, la **pêche**, le **tourisme** balnéaire et de nature, les **énergies renouvelables insulaires** (deux attendus).\n3. Le **Conservatoire du littoral** est un établissement public qui **achète des espaces côtiers** pour les soustraire au marché et les protéger. **Natura 2000** est un **réseau européen d'espaces protégés**."}$exo$::jsonb),
  ('2dfa078f-f914-5195-a3c6-4ec964cbcd24'::uuid, 2, 'redaction', $exo${"titre":"Trois territoires sous pression","consigne":"Analyse chaque situation et réponds en utilisant le cours.","enonce":"**Document – Trois situations (inventées)**\n\n- **A.** En Martinique, Hugo, maraîcher, ne peut plus cultiver certains légumes racines : le sol de sa parcelle est contaminé par un pesticide utilisé autrefois dans les bananeraies.\n- **B.** En Guyane, des gendarmes découvrent un chantier d'orpaillage clandestin au bord d'une rivière.\n- **C.** Sur une côte basse de métropole, une commune voit ses dunes reculer tandis que les lotissements s'étendent vers la plage.\n\n1. Identifie la pression en jeu dans chaque situation.\n2. Pour la situation C, explique la phrase : « Un littoral attire parce qu'il est beau ; il se dégrade parce qu'il attire. »\n3. Propose, pour la situation C, deux outils de protection du cours et explique leur rôle.","bareme":[{"critere":"A chlordécone, B orpaillage illégal, C artificialisation et érosion côtière","points":6},{"critere":"Explication du cercle attractivité-dégradation des littoraux","points":6},{"critere":"Deux outils adaptés et expliqués (loi Littoral, Conservatoire du littoral, gestion intégrée…)","points":8}],"dureeMin":12,"corrige":"1. **A** : pollution durable des sols antillais au **chlordécone**. **B** : **orpaillage illégal** en Guyane. **C** : **artificialisation des sols** et **étalement urbain** sur le littoral, avec **érosion côtière** (risque de submersion sur une côte basse).\n2. Les littoraux sont parmi les espaces **les plus valorisés** (tourisme, résidences) : ils attirent habitants et constructions. Cette pression **dégrade** ce qui fait leur attrait (dunes, paysages). Toute la politique de protection tient dans ce cercle.\n3. Outils possibles : la **loi Littoral** encadre l'urbanisme en bord de mer ; le **Conservatoire du littoral** achète des terrains pour les soustraire au marché ; la **gestion intégrée des zones côtières** coordonne les usages ; **Natura 2000** protège à l'échelle européenne (deux attendus). La protection réussit mieux quand elle est aussi un **projet économique local**."}$exo$::jsonb),
  ('2dfa078f-f914-5195-a3c6-4ec964cbcd24'::uuid, 3, 'redaction', $exo${"titre":"Valoriser et protéger les espaces français","consigne":"Rédige un développement organisé en trois parties, avec des exemples métropolitains et ultramarins.","enonce":"**Sujet.** « Grâce à ses outre-mer, la France est présente sur tous les océans et abrite une biodiversité exceptionnelle. Cette richesse est aussi une responsabilité. »\n\nMontre :\n1. la richesse des espaces français ;\n2. les pressions et les risques qu'ils subissent ;\n3. les outils de protection, et à quelle condition ils réussissent.","bareme":[{"critere":"ZEE chiffrée et milieux remarquables (récifs, forêt guyanaise, TAAF)","points":4},{"critere":"Valorisation des outre-mer et de la métropole (littoraux, montagnes)","points":4},{"critere":"Pressions localisées (artificialisation, érosion, chlordécone, orpaillage, coraux) et risques","points":5},{"critere":"Outils de protection (parcs, Conservatoire, Natura 2000, lois Littoral et Montagne, gestion intégrée)","points":5},{"critere":"Condition de réussite : un projet économique local associant les habitants","points":2}],"dureeMin":20,"corrige":"**1. Une géographie exceptionnelle** : la ZEE française est la **deuxième du monde** (environ **10,2 millions de km²**), à plus de **96 %** grâce aux **outre-mer**. Milieux remarquables : **récifs** de Nouvelle-Calédonie et de Polynésie, **forêt guyanaise**, **Terres australes et antarctiques**. On valorise : pêche, tourisme, **spatial à Kourou**, **nickel** calédonien, banane et canne, énergies renouvelables insulaires ; en métropole, **littoraux et montagnes**, les espaces les plus valorisés.\n\n**2. Des pressions et des risques** : **artificialisation** et **étalement urbain**, surtout sur les littoraux ; **érosion côtière** et **submersion** des côtes basses ; **chlordécone** aux Antilles ; **orpaillage illégal** en Guyane ; **blanchissement des coraux** dans le Pacifique et l'océan Indien. Les risques y sont majeurs : cyclones, séismes, volcanisme, submersion. Un littoral attire parce qu'il est beau et se dégrade parce qu'il attire.\n\n**3. Protéger** : **parcs nationaux** et **parcs naturels marins**, **Conservatoire du littoral** (achat foncier), **Natura 2000** (échelle européenne), lois **Littoral** et **Montagne** (urbanisme), **gestion intégrée des zones côtières**. La protection **réussit quand elle est aussi un projet économique local** : sans les habitants, elle est mal acceptée.\n\n**Conclusion** : la richesse des espaces français impose de concilier valorisation et protection."}$exo$::jsonb),
  ('d4c7ac00-ce2a-5f8d-b206-1d5fa66043ee'::uuid, 1, 'redaction', $exo${"titre":"Les trois régimes démographiques","consigne":"Réponds à chaque question de façon précise.","enonce":"**Questions de cours**\n\n1. Décris la natalité, la mortalité et l'évolution de la population dans chacun des trois régimes de la transition démographique.\n2. Comment s'appelle l'écart entre natalité et mortalité ?\n3. Quel est le seuil de renouvellement des générations ?","bareme":[{"critere":"Trois régimes décrits correctement, dont la mortalité qui chute d'abord pendant la transition","points":12},{"critere":"Accroissement naturel","points":4},{"critere":"Environ 2,1 enfants par femme","points":4}],"dureeMin":6,"corrige":"1. - **Régime ancien** : natalité **forte**, mortalité **forte**, population **stable**.\n- **Transition** : natalité **encore forte**, la mortalité **chute d'abord** : la population **explose**.\n- **Régime moderne** : natalité **basse**, mortalité **basse**, population **stable, voire en déclin**.\n2. C'est l'**accroissement naturel**.\n3. Environ **2,1 enfants par femme**."}$exo$::jsonb),
  ('d4c7ac00-ce2a-5f8d-b206-1d5fa66043ee'::uuid, 2, 'redaction', $exo${"titre":"Deux pyramides, deux défis","consigne":"Lis la description des deux pyramides des âges et réponds en utilisant le cours.","enonce":"**Document – Deux pyramides décrites**\n\n- **Pays A** : une base très large qui se rétrécit vite vers le haut, en forme de triangle ; une femme a en moyenne plus de 4 enfants.\n- **Pays B** : une base étroite, un sommet large ; une fécondité de 1,3 enfant par femme ; un creux marqué chez les personnes nées pendant une guerre.\n\n1. Identifie, pour chaque pays, sa situation dans la transition et une région du monde qui lui correspond selon le cours.\n2. Que traduit le creux de la pyramide B ?\n3. Donne deux défis du pays A et deux défis du pays B.","bareme":[{"critere":"A en pleine transition (Afrique subsaharienne), B post-transitionnel (Europe, Japon, Corée du Sud)","points":6},{"critere":"Creux = événement passé (guerre, crise ou politique)","points":4},{"critere":"Deux défis de la jeunesse pour A (nourrir, scolariser, soigner, employer)","points":5},{"critere":"Deux défis du vieillissement pour B (retraites et santé, dépendance, main-d'œuvre, territoires)","points":5}],"dureeMin":11,"corrige":"1. **Pays A** : **en pleine transition**, fécondité élevée, population très jeune, croissance rapide : **Afrique subsaharienne**. **Pays B** : **post-transitionnel**, fécondité **sous le seuil de renouvellement** (2,1), vieillissement, parfois déclin : **Europe**, **Japon**, **Corée du Sud**.\n2. Une pyramide se lit comme une biographie collective : le creux traduit un **événement passé** — ici une **guerre** (ce peut être aussi une crise ou une politique).\n3. **Pays A** : **nourrir** (sécurité alimentaire), **scolariser** (écoles, enseignants), **soigner**, **employer** des millions d'arrivants sur le marché du travail (deux attendus). **Pays B** : financer **retraites et santé**, la **dépendance**, la **pénurie de main-d'œuvre**, la **désertification** de territoires (deux attendus)."}$exo$::jsonb),
  ('d4c7ac00-ce2a-5f8d-b206-1d5fa66043ee'::uuid, 3, 'redaction', $exo${"titre":"Huit milliards d'humains, deux problèmes opposés","consigne":"Rédige un développement organisé en trois parties, en mobilisant le vocabulaire démographique.","enonce":"**Sujet.** « Certains pays doivent scolariser une jeunesse nombreuse ; d'autres financer une vieillesse qui s'allonge. »\n\n1. Explique à l'aide du modèle de la transition démographique pourquoi les trajectoires sont différentes.\n2. Montre les défis d'une population jeune et les deux issues possibles.\n3. Montre les défis du vieillissement et les réponses possibles.","bareme":[{"critere":"Modèle de transition en trois régimes et accroissement naturel","points":4},{"critere":"Contraste Afrique subsaharienne / Europe, Japon, Corée du Sud, seuil de 2,1","points":4},{"critere":"Défis de la jeunesse et dividende démographique ou chômage, informalité, migrations","points":5},{"critere":"Défis du vieillissement avec les réponses associées","points":5},{"critere":"Organisation et conclusion","points":2}],"dureeMin":20,"corrige":"**1. Des étapes différentes de la transition** : au **régime ancien**, natalité et mortalité fortes, population stable ; pendant la **transition**, la **mortalité chute d'abord** alors que la natalité reste forte : la population explose ; au **régime moderne**, les deux sont basses. L'écart s'appelle l'**accroissement naturel**. L'**Afrique subsaharienne** est en pleine transition (fécondité élevée, population très jeune) ; l'**Europe**, le **Japon**, la **Corée du Sud** sont post-transitionnels, sous le **seuil de 2,1 enfants par femme**, et vieillissent. La population mondiale approche **8 milliards**.\n\n**2. Les défis de la jeunesse** : **nourrir**, **scolariser**, **soigner**, **employer** des millions d'arrivants par an. Deux issues : le **dividende démographique** si la jeunesse est **bien formée et employée** (les actifs nombreux face aux inactifs) ; sinon **chômage**, **informalité**, **migrations**.\n\n**3. Les défis du vieillissement** : financer **retraites et santé** → **allonger la vie active** ; la **dépendance** → développer les **métiers du grand âge** ; la **pénurie de main-d'œuvre** → **immigration**, **automatisation** ; la **désertification** de territoires → **politiques d'attractivité**.\n\n**Conclusion** : la croissance mondiale cache deux problèmes opposés, liés au moment où chaque pays se trouve dans sa transition."}$exo$::jsonb),
  ('ad73844b-2c72-55cb-b3ad-beda315db5b3'::uuid, 1, 'redaction', $exo${"titre":"Mesurer le développement","consigne":"Réponds à chaque question en une ou deux phrases précises.","enonce":"**Questions de cours**\n\n1. Pour chacun de ces indicateurs, dis ce qu'il mesure et quelle est sa limite : le PIB par habitant, l'IDH, l'indice de Gini.\n2. Qu'est-ce que l'IDH ajusté aux inégalités ?\n3. Qu'est-ce que le secteur informel ?","bareme":[{"critere":"Trois indicateurs définis avec leur limite","points":12},{"critere":"IDH ajusté : l'IDH corrigé par les inégalités","points":4},{"critere":"Secteur informel : activités non déclarées, sans protection ni cotisation","points":4}],"dureeMin":7,"corrige":"1. - Le **PIB par habitant** mesure la **richesse produite** ; il ne dit rien de son **partage**.\n- L'**IDH** combine **revenu**, **espérance de vie** et **éducation** ; il ne dit rien des **écarts internes** au pays.\n- L'indice de **Gini** mesure l'**inégalité des revenus** ; il **ignore le niveau absolu** de richesse.\n2. L'**IDH ajusté aux inégalités** est l'IDH **corrigé** par la mesure des inégalités : il baisse d'autant plus que le pays est inégalitaire.\n3. Le **secteur informel** regroupe les **activités non déclarées**, **sans protection sociale ni cotisation** (ni fiscalité)."}$exo$::jsonb),
  ('ad73844b-2c72-55cb-b3ad-beda315db5b3'::uuid, 2, 'redaction', $exo${"titre":"Deux géants, deux inégalités","consigne":"Utilise le tableau et le cours pour répondre aux questions.","enonce":"**Document – Brésil et Inde (données du cours)**\n\n| | Brésil | Inde |\n|---|---|---|\n| Population | Environ 215 millions | Plus de 1,4 milliard |\n| Urbanisation | Plus de 85 % | Majoritairement rurale |\n| Moteur économique | Agriculture exportatrice | Services et numérique |\n\n1. Quel est le pays le plus peuplé du monde ? Lequel des deux est le plus urbanisé ?\n2. Compare la nature des inégalités dans les deux pays, avec un exemple pour chacun.\n3. Quel héritage historique pèse sur chaque pays ?\n4. Explique la phrase : « Au Brésil, l'inégalité se voit d'un mur à l'autre d'une même ville ; en Inde, elle se lit aussi dans la naissance. »","bareme":[{"critere":"Inde la plus peuplée, Brésil plus urbanisé (plus de 85 %)","points":4},{"critere":"Inégalités sociales et spatiales au Brésil (favelas, Nordeste) / revenus, castes, genre, région en Inde (Kerala, Bihar)","points":7},{"critere":"Héritages : esclavage et question foncière / système des castes","points":4},{"critere":"Explication juste de la phrase","points":5}],"dureeMin":11,"corrige":"1. L'**Inde**, avec plus de **1,4 milliard** d'habitants, est le pays **le plus peuplé du monde**. Le **Brésil** est le plus urbanisé (**plus de 85 %** de citadins).\n2. Au **Brésil**, les inégalités sont **sociales et spatiales** : **favelas** contre **quartiers fermés**, **Sudeste riche** contre **Nordeste pauvre**. En **Inde**, elles portent sur les **revenus**, mais aussi sur les **castes**, le **genre** et la **région** : le **Kerala** est avancé, le **Bihar** en retard.\n3. Brésil : l'**esclavage** et la **question foncière**. Inde : le **système des castes**.\n4. Au Brésil, l'inégalité est **visible dans l'espace urbain** : des quartiers riches fermés côtoient des favelas. En Inde, elle dépend aussi de la **caste de naissance**, héritée, en plus des revenus. Les programmes de transferts sociaux ont fait reculer la pauvreté brésilienne dans les années 2000, sans supprimer ces écarts."}$exo$::jsonb),
  ('ad73844b-2c72-55cb-b3ad-beda315db5b3'::uuid, 3, 'redaction', $exo${"titre":"Le développement avance, l'écart demeure","consigne":"Rédige un développement organisé en trois parties, en comparant le Brésil et l'Inde.","enonce":"**Sujet.** « Le développement y avance, l'écart y demeure. » Montre, en comparant le Brésil et l'Inde :\n1. comment on mesure le développement et pourquoi il faut plusieurs indicateurs ;\n2. en quoi les deux pays diffèrent (population, économie, nature des inégalités) ;\n3. ce qu'ils ont en commun.","bareme":[{"critere":"Indicateurs (PIB/hab, IDH, Gini, IDH ajusté) et intérêt de les croiser","points":4},{"critere":"Différences chiffrées : population, urbanisation, moteur économique","points":4},{"critere":"Nature des inégalités et héritages de chaque pays","points":5},{"critere":"Au moins quatre points communs (croissance irrégulière, bidonvilles, informel, dépendance, environnement)","points":5},{"critere":"Recul de la pauvreté mentionné et conclusion qui répond au sujet","points":2}],"dureeMin":20,"corrige":"**Introduction** : le Brésil et l'Inde sont deux **puissances émergentes du G20** ; tous deux ont fait reculer la pauvreté, tous deux restent profondément inégalitaires.\n\n**1. Mesurer** : le **PIB par habitant** (richesse produite, pas son partage), l'**IDH** (revenu, espérance de vie, éducation, pas les écarts internes), l'indice de **Gini** (inégalité des revenus, pas le niveau absolu), l'**IDH ajusté aux inégalités** (le premier corrigé par le second). Il faut les croiser pour voir à la fois le niveau et le partage.\n\n**2. Deux géants différents** : Brésil, environ **215 millions** d'habitants, **plus de 85 %** d'urbains, **agriculture exportatrice** puissante ; inégalités **sociales et spatiales** (favelas/quartiers fermés, Sudeste/**Nordeste**), héritage de l'**esclavage** et de la **question foncière** ; les **transferts sociaux** ont fait reculer la pauvreté dans les années 2000. Inde : plus de **1,4 milliard**, le plus peuplé du monde, **majoritairement rurale**, moteur des **services** et du **numérique**, faible industrialisation de masse ; inégalités de revenus mais aussi de **castes**, de **genre** et de **région** (Kerala/Bihar).\n\n**3. Des points communs** : croissance **forte mais irrégulière** ; mégapoles à **bidonvilles** (Rio, São Paulo, Bombay, Delhi) ; secteur **informel** énorme ; **dépendance** aux ressources et exportations, donc aux cours mondiaux ; forte **pression environnementale** (déforestation, pollution).\n\n**Conclusion** : la richesse progresse, mais sa répartition reste très inégale, pour des raisons différentes dans chaque pays."}$exo$::jsonb),
  ('1923e92a-6b02-5285-88c6-adb89805bcbd'::uuid, 1, 'redaction', $exo${"titre":"Le Japon en quatre chiffres","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Donne quatre chiffres qui décrivent la population japonaise : population totale et son évolution, part des 65 ans et plus, espérance de vie, indice de fécondité.\n2. Pourquoi dit-on que le Japon est « le laboratoire mondial du vieillissement » ?\n3. Le Japon compense-t-il son vieillissement par une forte immigration ? Justifie.","bareme":[{"critere":"Quatre chiffres justes (124 millions en baisse depuis 2010, près de 29 %, plus de 84 ans, environ 1,3)","points":10},{"critere":"Laboratoire : il vit déjà ce que d'autres anticipent","points":4},{"critere":"Non : immigration longtemps très faible, ouverture prudente","points":6}],"dureeMin":6,"corrige":"1. Environ **124 millions** d'habitants, **en baisse depuis 2010** ; près de **29 %** ont **65 ans ou plus** ; espérance de vie de **plus de 84 ans** ; indice de fécondité d'environ **1,3** enfant par femme.\n2. Parce que ce que d'autres pays **anticipent**, le Japon **le vit déjà** : c'est le pays le plus âgé du monde.\n3. **Non** : l'**immigration** y a été **longtemps très faible**, sans apport compensatoire, et l'ouverture aux travailleurs étrangers reste **prudente**."}$exo$::jsonb),
  ('1923e92a-6b02-5285-88c6-adb89805bcbd'::uuid, 2, 'redaction', $exo${"titre":"Un village qui se vide","consigne":"Lis la situation et réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Dans une préfecture rurale du Japon, l'école du village de Mme Sato a fermé l'an dernier. La moitié des maisons sont vides. Sa fille, 34 ans, vit à Tokyo : elle travaille beaucoup, son loyer est très cher, et elle repousse le projet d'avoir un enfant. À la maison de retraite voisine, un robot aide les soignants à soulever les résidents.\n\n1. Relève deux causes de la faible natalité japonaise présentes dans la situation.\n2. Relève trois conséquences du vieillissement.\n3. Quelle réponse au vieillissement la situation montre-t-elle ? Cite deux autres réponses du cours. Ont-elles inversé la tendance ?","bareme":[{"critere":"Deux causes : coût du logement, difficulté de concilier travail et famille (maternité reportée)","points":6},{"critere":"Trois conséquences : fermeture d'écoles, villages fantômes, concentration à Tokyo (ou dépendance)","points":6},{"critere":"Robotique, deux autres réponses justes et constat qu'aucune n'a inversé la tendance","points":8}],"dureeMin":11,"corrige":"1. Le **coût du logement** (loyer très cher à Tokyo) et la **difficulté à concilier travail et famille** : les **maternités sont reportées**. (La précarité de l'emploi des jeunes est une autre cause.)\n2. **Fermeture d'écoles** faute d'élèves ; **villages fantômes** dans les campagnes et préfectures périphériques ; **concentration** dans la mégalopole de **Tokyo** pendant que le reste du pays se vide ; poids de la **dépendance** (maison de retraite).\n3. La **robotique** et l'**automatisation**, notamment dans les soins. Autres réponses : **emploi des seniors** (souvent au-delà de 70 ans), **travail des femmes** encouragé, **ouverture prudente** aux travailleurs étrangers, **politiques familiales** (crèches, aides à la garde), **revitalisation rurale** (deux attendues). **Aucune n'a inversé la tendance** à ce jour."}$exo$::jsonb),
  ('1923e92a-6b02-5285-88c6-adb89805bcbd'::uuid, 3, 'redaction', $exo${"titre":"Réussir sa santé, échouer à faire naître","consigne":"Rédige un développement organisé en trois parties, avec des chiffres et des exemples précis.","enonce":"**Sujet.** « Une société peut réussir sa santé publique et échouer à faire naître : le Japon montre que les deux ne vont pas de soi ensemble. »\n\nMontre :\n1. les causes du vieillissement japonais ;\n2. ses conséquences économiques, sociales et territoriales ;\n3. les réponses apportées et leurs limites.","bareme":[{"critere":"Chiffres clés du vieillissement","points":3},{"critere":"Causes : longévité (alimentation, santé) et faible natalité (logement, éducation, conciliation, précarité, immigration faible)","points":5},{"critere":"Conséquences économiques et sociales (main-d'œuvre, retraites, dépendance, marché intérieur)","points":4},{"critere":"Conséquences territoriales (écoles, villages fantômes, Tokyo)","points":3},{"critere":"Réponses et constat qu'aucune n'inverse la tendance","points":5}],"dureeMin":20,"corrige":"**Introduction** : environ **124 millions** d'habitants, **en baisse depuis 2010**, près de **29 %** de 65 ans et plus : le Japon est le laboratoire mondial du vieillissement.\n\n**1. Les causes** : une **espérance de vie exceptionnelle** (plus de **84 ans**) grâce à l'**alimentation** et au **système de santé** — la santé publique est une réussite ; une **fécondité** d'environ **1,3** : le **coût du logement et de l'éducation** freine la natalité, la **difficulté de concilier travail et famille** fait reporter les maternités, la **précarité de l'emploi des jeunes** recule l'âge au mariage ; une **immigration longtemps très faible** n'apporte aucune compensation.\n\n**2. Les conséquences** : **pénurie de main-d'œuvre** (soins, logistique, bâtiment) ; poids des **retraites** et de la **dépendance**, charge budgétaire croissante ; **rétraction du marché intérieur** ; sur le territoire, **fermeture d'écoles**, **villages fantômes** dans les campagnes, **concentration dans la mégalopole de Tokyo** tandis que le reste du pays se vide.\n\n**3. Les réponses et leurs limites** : **robotique et automatisation** (notamment dans les soins), **emploi des seniors** au-delà de 70 ans, **travail des femmes**, **ouverture prudente** aux étrangers, **politiques familiales** (crèches, aides à la garde), **revitalisation rurale**. **Aucune n'a inversé la tendance** à ce jour.\n\n**Conclusion** : vivre longtemps ne suffit pas à renouveler une population ; le Japon annonce les défis d'autres pays riches."}$exo$::jsonb),
  ('112922bd-10ff-540c-8d02-3c9072661973'::uuid, 1, 'redaction', $exo${"titre":"La population française aujourd'hui","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Combien d'habitants compte la France ? Quel est son indice de fécondité ? Quelle part de la population a plus de 65 ans ?\n2. Quel est désormais le principal moteur de la croissance démographique française ?\n3. Qu'est-ce que la diagonale des faibles densités ? Qu'est-ce que la périurbanisation ?","bareme":[{"critere":"Environ 68 millions, environ 1,6 enfant par femme, plus de 21 % de plus de 65 ans","points":7},{"critere":"Le solde migratoire, l'accroissement naturel se réduisant","points":5},{"critere":"Diagonale (Nord-Est au Massif central, en perte) et périurbanisation définies","points":8}],"dureeMin":7,"corrige":"1. La France compte environ **68 millions** d'habitants ; la **fécondité**, longtemps la plus élevée d'Europe, est descendue autour de **1,6** enfant par femme ; les plus de 65 ans représentent **plus de 21 %**, en hausse.\n2. Le **solde migratoire**, car l'**accroissement naturel** se réduit fortement.\n3. La **diagonale des faibles densités** est une bande peu peuplée qui va du **Nord-Est au Massif central** (et au Sud-Ouest), qui **perd** des habitants. La **périurbanisation** est l'**extension de l'habitat et des activités au-delà des limites de la ville**."}$exo$::jsonb),
  ('112922bd-10ff-540c-8d02-3c9072661973'::uuid, 2, 'redaction', $exo${"titre":"Trois territoires, trois trajectoires","consigne":"Analyse chaque situation inventée et réponds en utilisant le cours.","enonce":"**Document – Trois territoires (situations inventées)**\n\n- **A.** Une commune de la couronne d'une grande métropole de l'Ouest : +12 % d'habitants en dix ans, lotissements neufs, bouchons chaque matin.\n- **B.** Un bourg du Massif central : la population baisse, le dernier médecin part à la retraite sans successeur.\n- **C.** Un quartier d'une grande ville où le chômage est deux fois plus élevé que dans le reste de l'agglomération.\n\n1. Pour chaque territoire, décris sa dynamique démographique et explique-la avec le cours.\n2. Quelle inégalité illustre le territoire B ? Et le territoire C ?\n3. Propose, pour B et pour C, un dispositif public du cours adapté.","bareme":[{"critere":"A : gain des métropoles et couronnes, périurbanisation ; B : diagonale des faibles densités, perte","points":6},{"critere":"C : inégalités entre quartiers d'une même ville","points":3},{"critere":"B désert médical (inégalité de santé) ; C inégalité de revenus/emploi","points":5},{"critere":"Dispositifs adaptés : ZRR ou Maisons France Services pour B ; politique de la ville et quartiers prioritaires pour C","points":6}],"dureeMin":12,"corrige":"1. **A** : les **grandes métropoles et leurs couronnes** gagnent des habitants ; c'est la **périurbanisation**, qui étale la ville au-delà de ses limites (d'où les trajets). **B** : bourg de la **diagonale des faibles densités**, qui **perd** des habitants : on quitte une région quand on n'y voit pas d'avenir professionnel. **C** : dans une même ville, des quartiers concentrent les difficultés.\n2. **B** illustre une inégalité de **santé** : un **désert médical**. **C** illustre une inégalité de **revenus** entre **quartiers d'une même ville**.\n3. **B** : **zones de revitalisation rurale**, **Maisons France Services** pour l'accès aux services publics. **C** : **politique de la ville** et **quartiers prioritaires**. Objectif affiché : la **cohésion des territoires**."}$exo$::jsonb),
  ('112922bd-10ff-540c-8d02-3c9072661973'::uuid, 3, 'redaction', $exo${"titre":"Une population qui se redistribue","consigne":"Rédige un développement organisé en trois parties, avec des exemples et des chiffres.","enonce":"**Sujet.** « La population française croît encore, mais lentement — et surtout elle se redistribue. »\n\nMontre :\n1. les grandes évolutions démographiques de la France ;\n2. les dynamiques territoriales et les inégalités qu'elles révèlent (métropole et outre-mer) ;\n3. les politiques publiques qui cherchent à y répondre.","bareme":[{"critere":"Évolutions : 68 millions, fécondité 1,6, accroissement naturel en baisse, solde migratoire moteur, plus de 21 % de 65 ans","points":5},{"critere":"Territoires gagnants et perdants, périurbanisation","points":4},{"critere":"Inégalités de revenus, logement, santé, scolaires, et outre-mer","points":5},{"critere":"Au moins trois dispositifs publics expliqués","points":4},{"critere":"Objectif de cohésion des territoires et conclusion","points":2}],"dureeMin":20,"corrige":"**1. Une croissance lente** : environ **68 millions** d'habitants ; fécondité descendue autour de **1,6** ; l'**accroissement naturel** se réduit fortement et le **solde migratoire** devient le principal moteur ; les plus de 65 ans dépassent **21 %** et augmentent.\n\n**2. Une redistribution inégale** : gains sur les **littoraux atlantique et méditerranéen**, dans le **Sud-Ouest**, les **grandes métropoles** et leurs couronnes ; pertes dans la **diagonale des faibles densités** (Nord-Est → Massif central) et les **anciennes régions industrielles**. La **périurbanisation** étale les villes. On quitte une région faute d'avenir professionnel. Inégalités : **revenus** (métropoles/territoires en déprise, et entre quartiers d'une même ville), **logement** (cherté des zones tendues), **santé** (**déserts médicaux**), **scolaires** (poids de l'origine sociale), et dans les **outre-mer** : **chômage élevé, jeunesse nombreuse, coût de la vie**.\n\n**3. Les politiques** : **politique de la ville** et **quartiers prioritaires** ; **zones de revitalisation rurale** ; **Maisons France Services** ; **Action cœur de ville** et **Petites villes de demain** pour les villes moyennes ; aménagement **numérique** et **transports du quotidien** pour désenclaver.\n\n**Conclusion** : l'enjeu n'est plus seulement le nombre d'habitants mais leur répartition ; l'objectif affiché est la **cohésion des territoires**."}$exo$::jsonb),
  ('a0e2ce8a-947b-5ae8-b6cf-1685a6e997c5'::uuid, 1, 'redaction', $exo${"titre":"Les mots des migrations","consigne":"Définis chaque terme en une phrase, puis réponds à la dernière question.","enonce":"**Questions de cours**\n\n1. Définis : migrant, réfugié, demandeur d'asile, déplacé interne, diaspora.\n2. Combien de personnes vivent hors de leur pays de naissance, et quelle part de l'humanité cela représente-t-il ?","bareme":[{"critere":"Cinq définitions justes, dont la convention de Genève de 1951 pour le réfugié","points":14},{"critere":"Environ 281 millions, un peu plus de 3 %","points":6}],"dureeMin":7,"corrige":"1. - **Migrant** : personne qui **change de pays de résidence**.\n- **Réfugié** : il **fuit des persécutions** ; son statut est défini par la **convention de Genève** de **1951**.\n- **Demandeur d'asile** : il **attend la décision** sur sa demande de protection.\n- **Déplacé interne** : il fuit mais **reste dans son pays**, sans franchir de frontière internationale.\n- **Diaspora** : population **dispersée** qui **garde des liens** avec son territoire d'origine.\n2. Environ **281 millions** de personnes, soit **un peu plus de 3 %** de l'humanité : la migration internationale est minoritaire, mais décisive."}$exo$::jsonb),
  ('a0e2ce8a-947b-5ae8-b6cf-1685a6e997c5'::uuid, 2, 'redaction', $exo${"titre":"L'argent d'Ousmane","consigne":"Lis la situation et réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Ousmane, infirmier diplômé, a quitté son pays d'Afrique de l'Ouest pour travailler dans un hôpital européen. Chaque mois, il envoie une partie de son salaire à sa famille. Dans sa ville natale, l'hôpital manque d'infirmiers. Son cousin, lui, est parti travailler dans un pays voisin, sur le même continent.\n\n1. Comment appelle-t-on l'argent envoyé par Ousmane ? Pourquoi est-il important pour les pays de départ ?\n2. Quel coût la situation montre-t-elle pour le pays de départ ?\n3. Qu'apporte Ousmane au pays d'arrivée ?\n4. Le départ du cousin est-il exceptionnel ? Justifie avec le cours.","bareme":[{"critere":"Remises, parfois supérieures à l'aide publique au développement","points":5},{"critere":"Fuite des cerveaux","points":4},{"critere":"Apports au pays d'arrivée : main-d'œuvre, rajeunissement, cotisations","points":5},{"critere":"Non : un migrant sur deux reste dans sa région, flux Sud-Sud plus nombreux que Sud-Nord","points":6}],"dureeMin":10,"corrige":"1. Ce sont des **remises** migratoires. Elles sont **massives**, parfois **supérieures à l'aide publique au développement** : elles font vivre des familles et des régions entières.\n2. La **fuite des cerveaux** : le pays perd des personnes **qualifiées** (ici un infirmier), dont son hôpital manque.\n3. Au pays d'arrivée, il apporte une **main-d'œuvre**, contribue au **rajeunissement** de la population et paie des **cotisations**. Pour lui, une **mobilité sociale** est possible, mais discrimination et précarité sont fréquentes.\n4. **Non** : **un migrant sur deux** se déplace **à l'intérieur de sa propre région du monde** ; les flux **Sud-Sud** sont **plus nombreux** que les flux Sud-Nord."}$exo$::jsonb),
  ('a0e2ce8a-947b-5ae8-b6cf-1685a6e997c5'::uuid, 3, 'redaction', $exo${"titre":"Une migration minoritaire mais décisive","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Sujet.** Les migrations internationales : qui part, d'où, vers où, et pourquoi ?\n\n1. Présente les causes des migrations et nuance l'idée que « ce sont les plus pauvres qui partent le plus loin ».\n2. Montre les effets des migrations pour les pays de départ, les pays d'arrivée et les migrants.\n3. Présente les routes dangereuses et les politiques de contrôle, et leurs effets.","bareme":[{"critere":"Causes économiques et contraintes, souvent mêlées ; coût de la migration","points":4},{"critere":"Flux Sud-Sud majoritaires et chiffres généraux","points":3},{"critere":"Effets pour les trois acteurs, apports et coûts","points":5},{"critere":"Au moins trois routes et leur dangerosité","points":4},{"critere":"Contrôles (Frontex, murs) qui allongent et renchérissent les trajets sans les supprimer","points":4}],"dureeMin":20,"corrige":"**Introduction** : environ **281 millions** de personnes vivent hors de leur pays de naissance, un peu plus de **3 %** de l'humanité.\n\n**1. Pourquoi partir ?** Migrations **économiques** (écarts de revenus, emploi, études) et **contraintes** (guerres, persécutions, catastrophes, dégradation de l'environnement), qui **se mêlent souvent**. Le statut de **réfugié** est défini par la **convention de Genève** (1951). La migration **coûte cher** : **ce ne sont pas les plus pauvres qui partent le plus loin**. Un migrant sur deux reste dans sa région : les flux **Sud-Sud** dépassent les flux Sud-Nord.\n\n**2. Les effets** : pour le **pays de départ**, des **remises** massives (parfois plus que l'aide au développement) mais la **fuite des cerveaux** ; pour le **pays d'arrivée**, main-d'œuvre, **rajeunissement**, cotisations, mais des **débats politiques** sur l'intégration ; pour le **migrant**, une **mobilité sociale** possible mais **discrimination** et **précarité** fréquentes.\n\n**3. Routes et frontières** : la **Méditerranée centrale**, la plus meurtrière ; **Balkans** et **Manche**, passages surveillés ; la frontière **Mexique-États-Unis**, désert et murs ; le **golfe d'Aden**, traversées et détentions. Les États durcissent les contrôles — **Frontex**, murs, clôtures —, ce qui **allonge et renchérit** les trajets **sans les supprimer**.\n\n**Conclusion** : minoritaire, la migration internationale transforme pourtant les sociétés de départ comme d'arrivée."}$exo$::jsonb),
  ('4edd000e-886b-5be1-bd03-ea4e756328e1'::uuid, 1, 'redaction', $exo${"titre":"Le tourisme, première mobilité","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Qu'est-ce qui fait qu'un voyageur est un touriste ?\n2. Combien d'arrivées touristiques internationales compte-t-on par an avant la pandémie ? Quel poids le tourisme a-t-il dans le PIB mondial ?\n3. Quelles régions captent l'essentiel des arrivées ?\n4. Qu'est-ce que le surtourisme ?","bareme":[{"critere":"Au moins une nuitée hors de son environnement habituel","points":5},{"critere":"Plus d'un milliard d'arrivées ; environ un dixième du PIB mondial, effets indirects compris","points":5},{"critere":"Europe, Amérique du Nord, Asie orientale","points":5},{"critere":"Surtourisme : fréquentation excessive qui dégrade le lieu et la vie des habitants","points":5}],"dureeMin":6,"corrige":"1. Un touriste passe **au moins une nuitée hors de son environnement habituel** (sinon c'est un excursionniste).\n2. **Plus d'un milliard** d'arrivées internationales par an avant la pandémie ; le tourisme pèse environ **un dixième du PIB mondial**, effets indirects compris.\n3. L'**Europe**, l'**Amérique du Nord** et l'**Asie orientale**.\n4. Le **surtourisme** est une **fréquentation excessive** des sites les plus visités, qui **dégrade le lieu** et la **vie des habitants** (prix immobiliers, éviction)."}$exo$::jsonb),
  ('4edd000e-886b-5be1-bd03-ea4e756328e1'::uuid, 2, 'redaction', $exo${"titre":"Yellowstone ou Burj Khalifa ?","consigne":"Compare les deux destinations à l'aide du cours.","enonce":"**Situation (inventée).** Léna hésite entre deux voyages : un circuit dans l'Ouest des États-Unis (Yellowstone, Grand Canyon, Las Vegas) ou un séjour à Dubaï (Burj Khalifa, îles artificielles, centres commerciaux climatisés). Pour aller à Dubaï, elle prendra un vol Emirates qui fait escale avant de continuer vers l'Asie pour d'autres passagers.\n\n1. Sur quelles ressources repose l'attractivité de chaque destination ?\n2. Quel rôle joue Emirates pour Dubaï ?\n3. Pourquoi Dubaï investit-il autant dans le tourisme ?\n4. Explique la phrase : « Les États-Unis mettent en tourisme ce qu'ils ont ; Dubaï met en tourisme ce qu'il construit. »","bareme":[{"critere":"États-Unis : atouts existants (nature, patrimoine) ; Dubaï : équipements créés de toutes pièces","points":6},{"critere":"Emirates : hub au carrefour Europe-Asie-Afrique","points":4},{"critere":"Diversification hors de la rente pétrolière et image","points":4},{"critere":"Explication de la phrase avec ancienneté et tourisme intérieur","points":6}],"dureeMin":10,"corrige":"1. Les **États-Unis** s'appuient sur des **atouts existants** et diversifiés : **nature** (Yellowstone, Grand Canyon) et **patrimoine** urbain ou de loisirs (New York, Las Vegas, Orlando). **Dubaï** est une destination **créée de toutes pièces** : **Burj Khalifa**, **îles artificielles**, centres commerciaux **climatisés**, **hôtellerie de luxe**.\n2. **Emirates** fait de Dubaï un **hub aérien** au **carrefour Europe-Asie-Afrique** : les correspondances amènent des voyageurs, dont certains s'arrêtent.\n3. Pour **diversifier** son économie **hors de la rente pétrolière**, et pour son **image**.\n4. Les États-Unis sont un espace touristique **ancien** qui valorise ses ressources ; le **tourisme intérieur** y est **massif** et le tourisme n'est qu'une activité parmi d'autres. Dubaï a **construit en trente ans** ses attractions, avec un tourisme intérieur faible : l'offre est **fabriquée**."}$exo$::jsonb),
  ('4edd000e-886b-5be1-bd03-ea4e756328e1'::uuid, 3, 'redaction', $exo${"titre":"Deux manières de fabriquer une destination","consigne":"Rédige un développement organisé en trois parties, en comparant les États-Unis et Dubaï.","enonce":"**Sujet.** Comparez les mobilités touristiques aux États-Unis et à Dubaï.\n\n1. Présente le poids et la géographie du tourisme mondial.\n2. Compare les deux modèles (ancienneté, ressources, sites, tourisme intérieur, transport, objectifs).\n3. Montre ce que le tourisme apporte aux territoires et ce qu'il leur coûte, dans les deux cas.","bareme":[{"critere":"Définition, milliard d'arrivées, dixième du PIB, concentration géographique","points":4},{"critere":"Comparaison complète des deux modèles avec exemples de sites","points":6},{"critere":"Apports : emplois, devises, patrimoine, aménagements","points":3},{"critere":"Coûts : surtourisme, prix immobiliers, artificialisation, eau et énergie (dessalement, climatisation, parcs)","points":5},{"critere":"Main-d'œuvre immigrée du Golfe et conclusion","points":2}],"dureeMin":20,"corrige":"**1. Une industrie mondiale** : un touriste passe au moins **une nuitée** hors de chez lui ; **plus d'un milliard** d'arrivées internationales avant la pandémie ; environ **un dixième du PIB mondial** ; l'essentiel des arrivées va vers l'**Europe**, l'**Amérique du Nord** et l'**Asie orientale**.\n\n**2. Deux modèles opposés** : les **États-Unis** sont un espace touristique **ancien** qui valorise des atouts **existants** — **New York, Yellowstone, Grand Canyon, Orlando, Floride, Californie, Las Vegas** —, avec un **tourisme intérieur massif**, des hubs aéroportuaires mondiaux ; le tourisme y est **une activité parmi d'autres**. **Dubaï** a construit en **trente ans** une destination **créée de toutes pièces** — **Burj Khalifa**, îles artificielles, centres commerciaux climatisés, luxe —, avec peu de tourisme intérieur, grâce au **hub d'Emirates** (Europe-Asie-Afrique), pour **diversifier** hors du pétrole et soigner son **image**. Les premiers mettent en tourisme ce qu'ils ont, Dubaï ce qu'il construit.\n\n**3. Effets sur les territoires** : apports — **emplois**, **devises**, **rénovation du patrimoine**, aménagements. Coûts — **surtourisme** dans les sites les plus fréquentés, **hausse des prix immobiliers** et éviction des habitants, **artificialisation des littoraux**, forte **consommation d'eau et d'énergie** (**dessalement** et **climatisation** à Dubaï, **fréquentation des parcs** aux États-Unis). Dans le Golfe, la **main-d'œuvre immigrée** travaille souvent dans des conditions dénoncées par les ONG.\n\n**Conclusion** : deux chemins différents vers une même dépendance aux flux touristiques, avec des coûts environnementaux et sociaux."}$exo$::jsonb),
  ('96cafc7e-c18b-5699-b777-565c317a5a4b'::uuid, 1, 'redaction', $exo${"titre":"Les trois routes de la Méditerranée","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Qu'est-ce qu'une interface en géographie ? Pourquoi la Méditerranée en est-elle une ?\n2. Décris le tracé des trois routes migratoires méditerranéennes.\n3. Combien de disparitions ont été recensées en Méditerranée depuis 2014 ?","bareme":[{"critere":"Interface définie et appliquée (contact entre rives aux revenus de 1 à 10)","points":6},{"critere":"Trois routes avec leur tracé juste","points":9},{"critere":"Plus de 30 000 disparitions","points":5}],"dureeMin":7,"corrige":"1. Une **interface** est une **zone de contact entre deux espaces différents**, lieu d'échanges. La Méditerranée met en contact une rive **Nord** (Union européenne : population vieillissante, revenus élevés, stabilité) et des rives **Sud et Est** (populations jeunes, chômage élevé, pays parfois déstabilisés), dont les revenus par habitant varient **de un à dix**.\n2. - Route **occidentale** : du **Maroc vers l'Espagne**, et les **Canaries**.\n- Route **centrale** : de la **Libye et la Tunisie vers l'Italie et Malte**.\n- Route **orientale** : de la **Turquie vers la Grèce**, puis les **Balkans**.\n3. **Plus de 30 000 disparitions** depuis 2014."}$exo$::jsonb),
  ('96cafc7e-c18b-5699-b777-565c317a5a4b'::uuid, 2, 'redaction', $exo${"titre":"Les acteurs d'une traversée","consigne":"Lis la situation et réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Un bateau surchargé quitte la côte libyenne, organisé par des passeurs qui ont fait payer chaque place très cher. En mer, il est repéré par un avion de surveillance européen ; un navire d'ONG porte secours aux passagers, puis attend plusieurs jours qu'un État côtier accepte le débarquement.\n\n1. Sur quelle route migratoire se trouve ce bateau ? Pourquoi est-elle dangereuse ?\n2. Identifie cinq acteurs de la situation et le rôle de chacun.\n3. Pourquoi dit-on que « fermer une route, c'est en ouvrir une autre » ?\n4. Les pays du Sud de la Méditerranée ne sont-ils que des pays de départ ? Justifie.","bareme":[{"critere":"Route centrale, la plus meurtrière","points":3},{"critere":"Cinq acteurs justes avec leur rôle (migrants, passeurs, Frontex/garde-côtes, ONG, États côtiers, UE)","points":8},{"critere":"Report des flux vers des routes souvent plus dangereuses","points":4},{"critere":"Pays de départ, de transit et de plus en plus d'accueil","points":5}],"dureeMin":12,"corrige":"1. La route **centrale** (Libye et Tunisie vers l'Italie et Malte), **la plus meurtrière**.\n2. - **Migrants et réfugiés** : ceux qui traversent.\n- **Passeurs** : ils **organisent** et **exploitent**.\n- **Frontex** et les **garde-côtes** : ils **contrôlent**.\n- **ONG de sauvetage** : elles **secourent**, et sont parfois **entravées**.\n- **États côtiers** : ils **négocient les débarquements**.\n(L'**Union européenne** finance aussi des accords avec la Turquie ou la Libye.)\n3. Les itinéraires se déplacent selon les contrôles : quand une route est surveillée, les flux **se reportent sur une autre**, **souvent plus dangereuse**.\n4. **Non** : ils sont à la fois pays de **départ**, de **transit** et, de plus en plus, d'**accueil**."}$exo$::jsonb),
  ('96cafc7e-c18b-5699-b777-565c317a5a4b'::uuid, 3, 'redaction', $exo${"titre":"Mobilités choisies, mobilités contraintes","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Sujet.** « Le même bassin porte des mobilités choisies et des mobilités contraintes. » Montre que la Méditerranée est à la fois une interface d'échanges et l'une des frontières les plus meurtrières du monde.\n\n1. Explique les contrastes entre les rives.\n2. Présente les routes migratoires, leurs acteurs et leurs dangers.\n3. Montre les autres mobilités et échanges qui traversent ce bassin.","bareme":[{"critere":"Contrastes démographiques et économiques entre les rives (un à dix)","points":4},{"critere":"Trois routes et leur déplacement selon les contrôles, 30 000 disparitions","points":5},{"critere":"Acteurs et leurs rôles, accords de l'UE","points":4},{"critere":"Tourisme (première destination), commerce (Suez, Gibraltar, grands ports), coopérations","points":5},{"critere":"Conclusion qui distingue mobilités choisies et contraintes","points":2}],"dureeMin":20,"corrige":"**1. Une interface de contrastes** : les revenus par habitant varient **de un à dix**. Rive **Nord** (UE) : population **vieillissante**, revenus élevés, stabilité. Rives **Sud et Est** : populations **jeunes**, **chômage élevé**, pays parfois déstabilisés (**Syrie, Libye, Sahel**). L'écart démographique et économique alimente les mobilités.\n\n**2. Des mobilités contraintes** : route **occidentale** (Maroc → Espagne, Canaries), **centrale** (Libye, Tunisie → Italie, Malte), **orientale** (Turquie → Grèce, Balkans). Fermer une route en ouvre une autre, souvent plus dangereuse : **plus de 30 000 disparitions** depuis 2014. Acteurs : migrants et réfugiés, **passeurs** qui organisent et exploitent, **garde-côtes** et **Frontex** qui contrôlent, **ONG de sauvetage** parfois entravées, **États côtiers** qui négocient les débarquements, **Union européenne** qui finance des accords avec la **Turquie** ou la **Libye**. Les pays du Sud sont pays de départ, de transit et d'accueil.\n\n**3. Des mobilités choisies et des échanges** : la Méditerranée est la **première destination touristique du monde** ; le **commerce** passe par **Suez**, **Gibraltar** et des ports comme **Tanger Med**, **Algésiras**, **Le Pirée** ; les **coopérations culturelles** (universités, festivals) relient les rives.\n\n**Conclusion** : touristes et marchandises circulent librement, tandis que les migrants affrontent des routes de plus en plus dangereuses : c'est une interface très inégale."}$exo$::jsonb),
  ('fc1cc4e3-d1f4-5586-8d21-13751f2eaef4'::uuid, 1, 'redaction', $exo${"titre":"Se déplacer tous les jours","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Quel est le premier motif de déplacement quotidien des Français ? Qu'est-ce qu'un navetteur ?\n2. Pourquoi la voiture domine-t-elle dans les espaces peu denses ?\n3. Comment qualifie-t-on l'organisation du réseau de transport français ? Donne un exemple.\n4. Quelle priorité fixe la loi d'orientation des mobilités de 2019 ?","bareme":[{"critere":"Domicile-travail et définition du navetteur","points":5},{"critere":"Absence d'alternative en transports collectifs, distances allongées par la périurbanisation","points":5},{"critere":"Réseau radial centré sur Paris avec un exemple","points":5},{"critere":"Priorité aux transports du quotidien plutôt qu'aux grands projets","points":5}],"dureeMin":7,"corrige":"1. Le **domicile-travail**. Un **navetteur** fait **chaque jour** le trajet **domicile-travail** entre deux communes ; les navetteurs franciliens ont des trajets parmi les plus longs d'Europe.\n2. Parce qu'il n'y a **pas d'alternative** en transports collectifs dans les espaces peu denses, et que la **périurbanisation** a **allongé les distances**.\n3. Un réseau **radial**, **centré sur Paris** : autoroutes, LGV et réseau ferré convergent vers la capitale (le **TGV** met Lyon à deux heures, Marseille à trois ; les **transversales** restent lentes).\n4. La loi de **2019** donne la priorité aux **transports du quotidien** plutôt qu'aux grands projets."}$exo$::jsonb),
  ('fc1cc4e3-d1f4-5586-8d21-13751f2eaef4'::uuid, 2, 'redaction', $exo${"titre":"Deux trajets pour aller travailler","consigne":"Compare les deux situations inventées et réponds en utilisant le cours.","enonce":"**Situation (inventée).**\n- **Inès** vit dans le centre d'une grande métropole : elle va au travail en tramway ou en vélo en libre-service.\n- **Julien** habite un village périurbain à 40 km de son travail : pas de gare, pas de bus, il fait 80 km en voiture par jour. Quand le prix du carburant augmente, son budget est déséquilibré.\n\n1. Quelle inégalité d'accès illustre cette comparaison ?\n2. Comment appelle-t-on la situation de Julien ? Pourquoi est-elle un enjeu politique ?\n3. Propose trois leviers du cours qui pourraient améliorer la situation de Julien, et explique-les.","bareme":[{"critere":"Inégalité métropoles (offre variée) / espaces ruraux et périurbains (souvent une seule route)","points":5},{"critere":"Vulnérabilité à la mobilité, sensibilité au prix des carburants, ressort de mouvements sociaux","points":6},{"critere":"Trois leviers adaptés et expliqués (covoiturage, petites lignes, télétravail, RER métropolitains…)","points":9}],"dureeMin":11,"corrige":"1. Une **inégalité d'accès** aux transports : les **métropoles** offrent **métros, tramways, RER, vélos en libre-service** ; les espaces **ruraux et périurbains** n'ont **souvent qu'une seule route**.\n2. Julien est en situation de **vulnérabilité à la mobilité** : ménage **contraint à de longs trajets en voiture**, **très sensible au prix des carburants**. C'est un **ressort des mouvements sociaux récents**.\n3. Leviers possibles (trois attendus) :\n- **Covoiturage** : partager les frais sur les trajets domicile-travail.\n- **Réouverture de petites lignes** ferroviaires : **désenclaver**.\n- **Télétravail** : **moins de trajets** sans nouvelle infrastructure.\n- **RER métropolitains** et transports en commun structurants vers la couronne.\n- À long terme, **réduire l'artificialisation** pour raccourcir les distances."}$exo$::jsonb),
  ('fc1cc4e3-d1f4-5586-8d21-13751f2eaef4'::uuid, 3, 'redaction', $exo${"titre":"Aménager pour les mobilités du quotidien","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Sujet.** « En France, c'est le déplacement quotidien qui structure l'aménagement du territoire. »\n\n1. Présente les mobilités quotidiennes et leurs causes.\n2. Montre les effets de l'organisation du réseau et les inégalités d'accès.\n3. Présente les leviers pour « aménager autrement ».","bareme":[{"critere":"Motifs (travail, études, achats et loisirs), périurbanisation, voiture, navetteurs","points":4},{"critere":"Réseau radial, TGV, transversales lentes, effet d'exclusion des territoires non desservis","points":5},{"critere":"Inégalités d'accès et vulnérabilité à la mobilité","points":4},{"critere":"Au moins quatre leviers expliqués","points":5},{"critere":"Loi d'orientation des mobilités de 2019","points":2}],"dureeMin":20,"corrige":"**1. Des mobilités quotidiennes massives** : le **domicile-travail** est le premier motif, suivi du **domicile-études** et des **achats et loisirs**, en hausse avec la **périurbanisation**. Celle-ci **allonge les distances** : beaucoup d'actifs travaillent hors de leur commune et la **voiture** domine faute d'alternative. Les **navetteurs franciliens** ont des trajets parmi les plus longs d'Europe.\n\n**2. Un réseau en étoile, des inégalités** : le réseau est **radial**, centré sur **Paris** (autoroutes, LGV, voies ferrées) ; le **TGV** met Lyon à deux heures, Marseille à trois, mais les **transversales** de province à province sont lentes. Une LGV décide aussi des villes qu'elle **ne dessert pas** : elle met à l'écart des territoires. Les **métropoles** ont métros, tramways, RER, vélos ; les espaces **ruraux et périurbains** souvent une seule route. D'où la **vulnérabilité à la mobilité** des ménages dépendants de la voiture et du prix des carburants, ressort de mouvements sociaux récents.\n\n**3. Aménager autrement** : **transports en commun structurants** et **RER métropolitains** ; **covoiturage** et **plans vélo** ; **réouverture de petites lignes** ; **télétravail** ; **réduction de l'artificialisation** pour raccourcir les distances à terme. La **loi d'orientation des mobilités de 2019** donne la priorité aux **transports du quotidien** plutôt qu'aux grands projets.\n\n**Conclusion** : l'aménagement passe des grands axes vers Paris aux besoins quotidiens des habitants."}$exo$::jsonb),
  ('f837d9fe-6056-5ec1-bb02-8fdac417942b'::uuid, 1, 'redaction', $exo${"titre":"Les milieux d'Afrique australe","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Quelle est la ressource qui limite le plus l'aménagement en Afrique australe ? Comment évoluent les précipitations d'est en ouest ?\n2. Localise trois milieux de la région (désert, savane, delta…).\n3. Associe une production minière à chacun de ces pays : Afrique du Sud, Botswana, Zambie, Namibie.","bareme":[{"critere":"L'eau ; précipitations décroissantes d'est en ouest, sécheresses récurrentes","points":6},{"critere":"Trois milieux correctement localisés","points":6},{"critere":"Quatre associations justes (or/platine/chrome/charbon, diamants, cuivre, uranium)","points":8}],"dureeMin":7,"corrige":"1. L'**eau**. Les **précipitations décroissent d'est en ouest**, avec une forte variabilité d'une année à l'autre et des **sécheresses récurrentes**.\n2. Exemples : déserts du **Namib** et du **Kalahari** à l'**ouest** ; savanes du **veld** à l'**intérieur** ; hauts plateaux tempérés en Afrique du Sud intérieure ; façade **méditerranéenne** autour du **Cap** ; zone tropicale humide et delta de l'**Okavango** au **nord** (trois attendus).\n3. **Afrique du Sud** : or, platine, chrome, charbon. **Botswana** : **diamants**. **Zambie** : **cuivre**. **Namibie** : **uranium**."}$exo$::jsonb),
  ('f837d9fe-6056-5ec1-bb02-8fdac417942b'::uuid, 2, 'redaction', $exo${"titre":"Le Cap et le « jour zéro »","consigne":"Lis la situation et réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (à partir d'un fait réel).** En 2018, après plusieurs années de sécheresse, la ville du Cap annonce un compte à rebours vers le « jour zéro », le jour où l'eau ne coulerait plus aux robinets. Les habitants doivent réduire fortement leur consommation.\n\n1. Pourquoi une telle crise est-elle possible en Afrique australe ?\n2. Explique la phrase : « Ici, aménager, c'est d'abord transporter l'eau. » Cite deux types d'aménagements hydrauliques.\n3. Quel grand projet alimente le Gauteng en eau ?\n4. Cite deux autres fragilités des milieux d'Afrique australe.","bareme":[{"critere":"Eau ressource limitante, forte variabilité, sécheresses récurrentes","points":5},{"critere":"Explication et deux aménagements (barrages, transferts, dessalement, irrigation)","points":6},{"critere":"Lesotho Highlands Water Project","points":3},{"critere":"Deux autres fragilités (érosion, braconnage, pollutions minières, dépendance au charbon)","points":6}],"dureeMin":10,"corrige":"1. En Afrique australe, l'**eau** est presque partout la **ressource limitante** : la **variabilité interannuelle** des pluies est forte et les **sécheresses sont récurrentes**.\n2. Toutes les activités (villes, mines, agriculture commerciale) en dépendent : aménager, c'est **amener l'eau là où on en a besoin**. Aménagements : **barrages**, **transferts entre bassins**, **dessalement**, **irrigation** (deux attendus).\n3. Le **Lesotho Highlands Water Project**, système de barrages et de transferts.\n4. L'**érosion des sols** (agriculture fragilisée), le **braconnage** (rhinocéros, éléphants), les **pollutions minières** (eaux acides, métaux lourds), la **dépendance au charbon** (vulnérabilité au changement climatique) — deux attendues."}$exo$::jsonb),
  ('f837d9fe-6056-5ec1-bb02-8fdac417942b'::uuid, 3, 'redaction', $exo${"titre":"Valoriser des milieux contraignants","consigne":"Rédige un développement organisé en trois parties, avec des exemples localisés.","enonce":"**Sujet.** Comment les sociétés d'Afrique australe aménagent-elles et valorisent-elles des milieux contrastés où l'eau commande tout ?\n\n1. Présente la diversité des milieux et la contrainte de l'eau.\n2. Montre comment ces milieux sont valorisés et aménagés.\n3. Présente les fragilités et les conflits liés à ces aménagements.","bareme":[{"critere":"Milieux localisés et contrainte hydrique expliquée","points":4},{"critere":"Activités de valorisation : mines, agriculture commerciale et vivrière, tourisme, pêche (Benguela)","points":5},{"critere":"Grands aménagements : eau (Lesotho), corridors vers les ports, centrales au charbon","points":5},{"critere":"Fragilités (crise du Cap 2018, érosion, braconnage, pollution, charbon)","points":4},{"critere":"Conflit entre aires protégées et populations riveraines","points":2}],"dureeMin":20,"corrige":"**1. Des milieux contrastés** : déserts du **Namib** et du **Kalahari** à l'ouest, savanes du **veld**, hauts plateaux tempérés, façade **méditerranéenne** du Cap, zone tropicale humide et delta de l'**Okavango** au nord. Les pluies **décroissent d'est en ouest**, varient beaucoup d'une année à l'autre ; l'**eau** est la ressource limitante.\n\n**2. Valoriser et aménager** : **mines** (or, platine, chrome, charbon en Afrique du Sud ; diamants au Botswana ; cuivre en Zambie ; uranium en Namibie) ; **agriculture commerciale** (vignobles du Cap, agrumes, canne, élevage extensif) face à une **agriculture vivrière** fragile ; **tourisme** de safari (**Kruger, Chobe, Etosha, Okavango**) et littoral ; **pêche** grâce au courant de **Benguela**. Aménager, c'est d'abord **transporter l'eau** : barrages, transferts (**Lesotho Highlands Water Project** pour le **Gauteng**), dessalement, irrigation. Les **corridors de transport** relient les mines aux ports (**Durban, Richards Bay, Walvis Bay, Maputo, Beira**). L'électricité sud-africaine vient surtout de centrales au **charbon**, avec de fortes coupures.\n\n**3. Fragilités et conflits** : **sécheresses** (crise du **Cap** en **2018** et le « jour zéro »), **érosion des sols**, **braconnage** des rhinocéros et éléphants, **pollutions minières**, **dépendance au charbon** face au changement climatique. Les **aires protégées**, très étendues, entrent parfois en **conflit** avec les besoins des **populations riveraines**.\n\n**Conclusion** : la valorisation est réelle, mais toujours suspendue à l'eau."}$exo$::jsonb),
  ('c8362455-18b6-520a-b812-4d9810fa2ce2'::uuid, 1, 'redaction', $exo${"titre":"Une région d'écarts","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Classe ces pays en trois groupes selon leur niveau de développement : Afrique du Sud, Botswana, Malawi, Mozambique, Namibie, Zimbabwe.\n2. Qu'était l'apartheid ? Donne ses dates.\n3. Que se passe-t-il en 1994 ?\n4. Qu'est-ce que la SADC ?","bareme":[{"critere":"Trois groupes justes (Afrique du Sud / Botswana, Namibie / Mozambique, Malawi, Zimbabwe)","points":6},{"critere":"Apartheid défini, 1948-1991","points":6},{"critere":"Élection de Nelson Mandela, démocratie","points":4},{"critere":"SADC : organisation d'intégration régionale","points":4}],"dureeMin":7,"corrige":"1. **Afrique du Sud** : pays le plus industrialisé du continent, une large part du PIB régional. **Botswana** et **Namibie** : revenu par habitant **intermédiaire**. **Mozambique**, **Malawi**, **Zimbabwe** : **parmi les pays les plus pauvres du monde**.\n2. L'**apartheid** (**1948-1991**) était un régime de **ségrégation légale** en Afrique du Sud : **séparation des populations**, inégalité d'accès à la **terre**, à l'**école**, à l'**emploi**.\n3. En **1994**, **Nelson Mandela** est élu président : c'est l'arrivée de la **démocratie**.\n4. La **SADC** est l'organisation d'**intégration régionale** des États d'Afrique australe : elle crée un **marché élargi**."}$exo$::jsonb),
  ('c8362455-18b6-520a-b812-4d9810fa2ce2'::uuid, 2, 'redaction', $exo${"titre":"La géographie de l'apartheid","consigne":"Lis la situation et réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Thabo, 17 ans, vit dans un township à la périphérie de Johannesburg. Chaque matin, il fait plus d'une heure de trajet pour rejoindre son lycée. Son grand-père n'avait pas le droit d'habiter en centre-ville. À quelques kilomètres, des résidences sécurisées sont entourées de hauts murs.\n\n1. Qu'est-ce qu'un township ? D'où vient-il ?\n2. Pourquoi, trente ans après 1994, la géographie de la ville reste-t-elle marquée par la ségrégation ?\n3. Cite trois défis communs aux pays d'Afrique australe.","bareme":[{"critere":"Township : quartier périphérique pauvre hérité de la ségrégation","points":5},{"critere":"Explication : ségrégation légale abolie mais géographie durable, pays parmi les plus inégalitaires","points":7},{"critere":"Trois défis communs justes","points":8}],"dureeMin":10,"corrige":"1. Un **township** est un **quartier périphérique pauvre**, **hérité de la ségrégation** de l'**apartheid** (1948-1991), qui séparait légalement les populations.\n2. L'apartheid a pris fin et **Nelson Mandela** a été élu en **1994**, mais **une ségrégation peut être abolie en un jour ; sa géographie met des générations à s'effacer**. L'Afrique du Sud reste **parmi les pays les plus inégalitaires du monde** : townships face aux **quartiers fermés**, **chômage élevé**, **question foncière non résolue**.\n3. Défis communs : **chômage des jeunes** massif, économie **informelle**, **dépendance aux matières premières** (donc aux cours mondiaux), **endettement et corruption**, épidémie de **VIH** qui a pesé sur l'espérance de vie, réseaux d'**électricité et d'eau** insuffisants (trois attendus)."}$exo$::jsonb),
  ('c8362455-18b6-520a-b812-4d9810fa2ce2'::uuid, 3, 'redaction', $exo${"titre":"Une région à plusieurs vitesses","consigne":"Rédige un développement organisé en trois parties, avec des exemples précis.","enonce":"**Sujet.** Quels défis la transition et le développement posent-ils à des pays d'Afrique australe inégalement développés ?\n\n1. Montre les écarts de développement dans la région.\n2. Explique le poids de l'héritage sud-africain.\n3. Présente les défis communs et les leviers de développement.","bareme":[{"critere":"Trois niveaux de pays et IDH échelonnés","points":4},{"critere":"Apartheid (1948-1991), 1994, inégalités persistantes (townships, chômage, foncier)","points":5},{"critere":"Défis communs (au moins quatre)","points":4},{"critere":"Leviers : SADC, ZLECAf, investissements, solaire et éolien, industrialisation","points":5},{"critere":"Exemple du Botswana et conclusion","points":2}],"dureeMin":20,"corrige":"**1. Des écarts** : l'**Afrique du Sud**, pays le plus industrialisé du continent, concentre une large part du PIB régional (industrie, mines, finance, services) ; le **Botswana** et la **Namibie** ont un revenu intermédiaire ; le **Mozambique**, le **Malawi** et le **Zimbabwe** sont parmi les plus pauvres du monde. Les **IDH** s'échelonnent en conséquence.\n\n**2. L'héritage sud-africain** : l'**apartheid** (**1948-1991**) a imposé une **ségrégation légale** (séparation des populations, inégal accès à la terre, à l'école, à l'emploi). Depuis **1994** et l'élection de **Nelson Mandela**, le pays est démocratique mais reste **parmi les plus inégalitaires du monde** : **townships** face aux quartiers fermés, chômage élevé, **question foncière** non résolue. Une ségrégation s'abolit en un jour, sa géographie met des générations à s'effacer.\n\n**3. Défis et leviers** : défis — **chômage des jeunes**, **informel**, **dépendance aux matières premières**, **endettement et corruption**, **VIH**, réseaux d'**électricité et d'eau** insuffisants. Leviers — intégration régionale par la **SADC**, **zone de libre-échange continentale africaine**, **investissements chinois et européens** dans les infrastructures, transition vers le **solaire** et l'**éolien** pour sortir du charbon, **industrialisation, formation, gouvernance**. Le **Botswana** est cité comme exemple de **rente minière bien administrée**.\n\n**Conclusion** : la région avance à plusieurs vitesses ; la gouvernance et l'intégration régionale conditionnent le rattrapage."}$exo$::jsonb),
  ('2d1756e1-21f4-5d4b-9059-10e1605c5e9c'::uuid, 1, 'redaction', $exo${"titre":"Les mobilités en Afrique australe","consigne":"Réponds à chaque question en une ou deux phrases.","enonce":"**Questions de cours**\n\n1. Quelle activité a organisé les premières grandes migrations de travail ? Où, et depuis quand ?\n2. Quel pays est aujourd'hui le principal pôle d'attraction migratoire, et quelle métropole concentre cette attraction ?\n3. Qu'est-ce que les remises ? Pour quels pays sont-elles une ressource essentielle ?","bareme":[{"critere":"Mines d'or et de diamants du Witwatersrand depuis la fin du XIXe siècle","points":7},{"critere":"Afrique du Sud et Johannesburg","points":6},{"critere":"Remises définies, Lesotho et Zimbabwe","points":7}],"dureeMin":6,"corrige":"1. L'**exploitation minière** : les mines d'**or et de diamants** du **Witwatersrand**, depuis la **fin du XIXe siècle**, attirent une main-d'œuvre du Lesotho, du Mozambique, du Malawi et du Zimbabwe, par le système du **travail migrant** et des **compounds**.\n2. L'**Afrique du Sud** ; la métropole régionale est **Johannesburg**.\n3. Les **remises** sont l'**argent envoyé par les membres des diasporas** à leur famille restée au pays. Elles sont une ressource essentielle pour le **Lesotho** et le **Zimbabwe**."}$exo$::jsonb),
  ('2d1756e1-21f4-5d4b-9059-10e1605c5e9c'::uuid, 2, 'redaction', $exo${"titre":"Farai à Johannesburg","consigne":"Lis la situation et réponds aux questions en t'appuyant sur le cours.","enonce":"**Situation (inventée).** Farai a quitté le Zimbabwe pour Johannesburg. Il vit dans un quartier informel sans raccordement régulier à l'eau ni à l'électricité et vend des objets sur un marché. Une partie de ce qu'il gagne part chaque mois vers sa mère. Sa sœur, elle, fait régulièrement la route entre les deux pays pour acheter et revendre des marchandises.\n\n1. Pourquoi l'Afrique du Sud attire-t-elle des migrants comme Farai ? Dans quels secteurs travaillent-ils ?\n2. Pourquoi l'urbanisation se fait-elle souvent par des quartiers informels ?\n3. Quelle mobilité pratique la sœur de Farai ? Qui l'exerce surtout ?\n4. Explique la phrase : « Un pays peut être en même temps la terre promise d'une région et un territoire où l'on redoute celui qui arrive. »","bareme":[{"critere":"Pôle d'attraction régional ; migrants dans l'informel et les services","points":5},{"critere":"Manque de logements abordables, difficultés d'accès à l'eau, l'électricité, les transports","points":4},{"critere":"Commerce transfrontalier informel, très féminin, le long des corridors","points":4},{"critere":"Violences xénophobes de 2008 et 2015 liées à la concurrence pour l'emploi","points":7}],"dureeMin":12,"corrige":"1. L'**Afrique du Sud** est le **principal pôle d'attraction** régional (surtout pour les Zimbabwéens et les Mozambicains) : migrants économiques et demandeurs d'asile. Ils alimentent le **secteur informel** et les **services** ; l'économie **dépend d'eux**.\n2. Faute de **logements abordables**, l'urbanisation rapide se fait par des **quartiers informels**, avec des **difficultés d'accès à l'eau, à l'électricité et aux transports**.\n3. Le **commerce transfrontalier informel**, **très féminin**, le long des **corridors**.\n4. L'Afrique du Sud attire toute la région, mais la **concurrence pour l'emploi** crée des **tensions sociales** : des **violences xénophobes** ont éclaté en **2008** et en **2015**."}$exo$::jsonb),
  ('2d1756e1-21f4-5d4b-9059-10e1605c5e9c'::uuid, 3, 'redaction', $exo${"titre":"Des territoires transformés par les mobilités","consigne":"Rédige un développement organisé en trois parties, avec des exemples localisés.","enonce":"**Sujet.** « En Afrique australe, les mobilités ont bâti les villes minières, vidé des campagnes et fait vivre des familles entières par les transferts d'argent. »\n\nMontre :\n1. l'héritage des migrations minières ;\n2. le rôle actuel de l'Afrique du Sud et l'urbanisation rapide ;\n3. la diversité des autres mobilités et ce qu'elles apportent.","bareme":[{"critere":"Witwatersrand, travail migrant et compounds, pays d'origine, peuplement","points":4},{"critere":"Afrique du Sud pôle d'attraction, Johannesburg, dépendance aux migrants, xénophobie 2008 et 2015","points":5},{"critere":"Urbanisation par quartiers informels, villes citées, campagnes qui se vident","points":4},{"critere":"Tourisme, mobilités étudiantes, diasporas et remises, commerce transfrontalier","points":5},{"critere":"Conclusion qui reprend les trois effets du sujet","points":2}],"dureeMin":20,"corrige":"**1. Un héritage minier** : depuis la **fin du XIXe siècle**, les mines d'**or et de diamants** du **Witwatersrand** attirent une main-d'œuvre du **Lesotho**, du **Mozambique**, du **Malawi** et du **Zimbabwe**, organisée par le **travail migrant** et les **compounds**. Cette circulation ancienne explique encore la géographie du peuplement : elle a **bâti les villes minières**.\n\n**2. L'Afrique du Sud, pôle d'attraction** : elle attire migrants économiques et demandeurs d'asile, surtout du **Zimbabwe** et du **Mozambique** ; **Johannesburg** est la métropole régionale. Les migrants alimentent l'**informel** et les **services**, mais la concurrence pour l'emploi provoque des **violences xénophobes** (**2008**, **2015**). L'urbanisation est rapide — **Johannesburg, Le Cap, Durban**, et **Luanda, Maputo, Lusaka** — souvent par des **quartiers informels**, faute de logements abordables, avec un accès difficile à l'eau, à l'électricité, aux transports. Les **campagnes se vident** de leurs actifs.\n\n**3. D'autres mobilités** : le **tourisme international** fait vivre des régions entières autour des **parcs** et du **littoral** ; les **mobilités étudiantes** vont vers les universités sud-africaines ; les **diasporas** envoient des **remises**, ressource essentielle pour le **Lesotho** ou le **Zimbabwe** ; le **commerce transfrontalier informel**, très féminin, anime les **corridors**.\n\n**Conclusion** : les mobilités ont façonné les villes, vidé les campagnes et font vivre des familles : elles sont au cœur des mutations de la région."}$exo$::jsonb),
  ('ebcfe609-313e-5a5b-99c2-5283b2d070c1'::uuid, 1, 'traduction', $exo${"titre":"Six cas, cinq déclinaisons","consigne":"Réponds à chaque question avec précision, en employant le vocabulaire du cours.","enonce":"1. Donne la fonction principale de chacun des **six cas** latins.\n2. À quelle déclinaison appartient chacun de ces noms ? Justifie par le nominatif et le génitif singulier : *rosa, rosae* ; *consul, consulis* ; *res, rei* ; *templum, templi* ; *manus, manus*.\n3. Énonce la **règle du neutre**. Pourquoi un mot terminé en **-a** peut-il poser problème ?","bareme":[{"critere":"Fonctions des six cas exactes (nominatif, vocatif, accusatif, génitif, datif, ablatif)","points":8},{"critere":"Cinq noms rangés dans la bonne déclinaison avec leur marque","points":7},{"critere":"Règle du neutre énoncée et ambiguïté du -a expliquée","points":5}],"dureeMin":8,"corrige":"1. **Nominatif** : sujet, attribut. **Vocatif** : interpellation. **Accusatif** : COD, but du mouvement. **Génitif** : complément du nom. **Datif** : COI, attribution. **Ablatif** : moyen, manière, lieu d'où l'on vient.\n2. *rosa, rosae* : **1re** déclinaison (-a, -ae). *consul, consulis* : **3e** (génitif en -is). *res, rei* : **5e** (-es, -ei). *templum, templi* : **2e**, neutre (-um, -i). *manus, manus* : **4e** (-us, -us).\n3. Au neutre, **le nominatif et l'accusatif sont toujours identiques**, et le **pluriel** se termine par **-a**. Un mot en -a peut donc être un **féminin singulier** (1re déclinaison, comme *rosa*) ou un **neutre pluriel** (comme *templa*) : c'est le **verbe** qui tranche."}$exo$::jsonb),
  ('ebcfe609-313e-5a5b-99c2-5283b2d070c1'::uuid, 2, 'traduction', $exo${"titre":"Des roses pour le maître","consigne":"Applique la méthode de traduction du cours : analyse d'abord, traduis ensuite.","enonce":"**Phrase à traduire**\n\n> *Puellae rosas domino dant.*\n\n**Lexique et terminaisons utiles**\n- *puella, ae* (f.) : la jeune fille — 1re déclinaison : nominatif pluriel **-ae**, génitif et datif singulier **-ae**\n- *rosa, ae* (f.) : la rose — accusatif pluriel **-as**\n- *dominus, i* (m.) : le maître — datif singulier **-o**\n- *dant* : ils/elles donnent (3e personne du **pluriel**)\n\n1. Applique la méthode du cours étape par étape : repère le verbe, puis le nominatif, puis l'accusatif, puis les autres compléments.\n2. *Puellae* peut être un nominatif pluriel, un génitif singulier ou un datif singulier. Quel indice permet de trancher ?\n3. Donne ta traduction.","bareme":[{"critere":"Méthode suivie dans l'ordre : verbe, nominatif, accusatif, compléments","points":6},{"critere":"Puellae identifié comme nominatif pluriel grâce à l'accord avec dant","points":5},{"critere":"Rosas COD à l'accusatif et domino COI au datif identifiés","points":4},{"critere":"Traduction juste et correcte en français","points":5}],"dureeMin":10,"corrige":"1. **Verbe** : *dant*, 3e personne du pluriel (« ils/elles donnent »), en fin de proposition. **Nominatif** : le sujet doit être au pluriel pour s'accorder avec *dant* → *puellae* (nominatif pluriel). **Accusatif** : *rosas* (accusatif pluriel) → COD. **Autres compléments** : *domino*, datif singulier → COI, attribution (« au maître »).\n2. Le **verbe** tranche : *dant* est au pluriel, il lui faut un sujet au nominatif pluriel. Or aucun autre mot de la phrase ne peut l'être ; *puellae* est donc le **nominatif pluriel** (et non un génitif ou un datif singulier).\n3. **Traduction** : « Les jeunes filles donnent des roses au maître. » (« les roses » est accepté)."}$exo$::jsonb),
  ('ebcfe609-313e-5a5b-99c2-5283b2d070c1'::uuid, 3, 'traduction', $exo${"titre":"Deux phrases, deux pièges en -a","consigne":"Analyse chaque mot (cas, nombre, fonction) avant de traduire, puis justifie tes choix.","enonce":"**Phrases à traduire**\n\n> 1. *Puella verba consulis audit.*\n> 2. *Domini templa rosis ornant.*\n\n**Lexique et terminaisons utiles**\n- *puella, ae* (f.) : la jeune fille (1re décl.) — *rosa, ae* (f.) : la rose ; ablatif pluriel **-is**\n- *verbum, i* (n.) : la parole — *templum, i* (n.) : le temple (2e décl., neutres) ; nominatif et accusatif pluriel **-a**\n- *dominus, i* (m.) : le maître (2e décl.) ; nominatif pluriel **-i**\n- *consul, consulis* (m.) : le consul (3e décl.)\n- *audit* : il/elle entend (singulier) — *ornant* : ils/elles ornent (pluriel)\n\n1. Dans la phrase 1, *puella* et *verba* se terminent tous deux par **-a**. Lequel est le sujet ? Justifie par la règle du neutre et par le verbe.\n2. Analyse *consulis* et donne sa fonction.\n3. Dans la phrase 2, analyse *domini*, *templa* et *rosis*.\n4. Traduis les deux phrases.\n5. En une ou deux phrases, explique pourquoi traduire dans l'ordre des mots aurait conduit à un contresens.","bareme":[{"critere":"Phrase 1 : puella sujet (féminin singulier, accord avec audit), verba neutre pluriel COD","points":5},{"critere":"Consulis génitif singulier, complément du nom de verba","points":3},{"critere":"Phrase 2 : domini nominatif pluriel, templa accusatif neutre pluriel, rosis ablatif de moyen","points":5},{"critere":"Deux traductions justes et en bon français","points":5},{"critere":"Explication : la terminaison, et non la place, donne la fonction","points":2}],"dureeMin":16,"corrige":"1. *verba* est un **neutre pluriel** (*verbum, i*, n.) : au neutre, nominatif et accusatif sont identiques et le pluriel est en -a. *puella* est un **féminin singulier** de la 1re déclinaison. Le **verbe** *audit* est au **singulier** : son sujet est donc *puella*. *verba*, pluriel, ne peut pas être sujet d'un verbe singulier : c'est l'**accusatif**, **COD**.\n2. *consulis* : **génitif singulier** de *consul* (3e déclinaison, génitif en -is) → **complément du nom** *verba* (« les paroles du consul »).\n3. *domini* : **nominatif pluriel** (2e décl.), sujet de *ornant* (pluriel). *templa* : neutre pluriel, nominatif ou accusatif ; le sujet étant déjà *domini*, c'est l'**accusatif**, **COD**. *rosis* : **ablatif pluriel** → complément de **moyen** (« avec des roses »).\n4. Phrase 1 : « **La jeune fille entend les paroles du consul.** » Phrase 2 : « **Les maîtres ornent les temples de roses** » (ou « avec des roses »).\n5. En latin, c'est la **terminaison** qui dit la fonction, pas la place du mot. Traduire dans l'ordre aurait pu faire de *verba* un sujet ou lire *templa* comme un féminin singulier : on aurait deviné au lieu d'analyser."}$exo$::jsonb),
  ('17840e75-285b-5a4f-8200-93ae94fce9fa'::uuid, 1, 'traduction', $exo${"titre":"Reconnaître les constructions","consigne":"Réponds à chaque question avec précision.","enonce":"1. Après quels types de verbes trouve-t-on une **proposition infinitive** ? À quels cas et mode sont son sujet et son verbe ? Traduis *Dico Marcum venire*.\n2. Qu'est-ce qu'un **ablatif absolu** ? Traduis *urbe capta* de façon correcte en français.\n3. Donne la forme et le sens de chacun des quatre participes du cours, avec l'exemple de *amare* (aimer).\n4. Que signifie *Carthago delenda est* ? Quelle forme verbale y est employée, et qu'exprime-t-elle ?","bareme":[{"critere":"Proposition infinitive : verbes de parole, pensée, perception ; sujet à l'accusatif, verbe à l'infinitif ; traduction juste","points":6},{"critere":"Ablatif absolu défini (nom + participe à l'ablatif, sans lien grammatical) et bien traduit","points":5},{"critere":"Quatre participes avec forme et sens exacts","points":5},{"critere":"Adjectif verbal en -ndus exprimant l'obligation, traduction juste","points":4}],"dureeMin":8,"corrige":"1. Après les verbes de **parole**, de **pensée** et de **perception**. Le sujet de la subordonnée est à l'**accusatif**, le verbe à l'**infinitif**. *Dico Marcum venire* : « **Je dis que Marcus vient.** »\n2. Un **nom et un participe à l'ablatif**, **sans lien grammatical** avec la principale. *Urbe capta* (« la ville ayant été prise ») se traduit par un complément circonstanciel : « **après la prise de la ville** », jamais mot à mot.\n3. **Présent actif** en -ns, -ntis : *amans*, « aimant ». **Parfait passif** en -tus, -a, -um : *amatus*, « ayant été aimé ». **Futur actif** en -turus : *amaturus*, « devant aimer ». **Adjectif verbal** en -ndus : *amandus*, « qui doit être aimé ».\n4. « **Carthage doit être détruite** » : c'est l'**adjectif verbal** (*delenda*), qui exprime l'**obligation**. C'est la formule de Caton, répétée à la fin de chacun de ses discours."}$exo$::jsonb),
  ('17840e75-285b-5a4f-8200-93ae94fce9fa'::uuid, 2, 'traduction', $exo${"titre":"Trois phrases, trois architectures","consigne":"Pour chaque phrase, nomme la construction, justifie ce qui permet de la reconnaître, puis traduis.","enonce":"**Phrases**\n\n> 1. *Puto consulem venire.*\n> 2. *Urbe capta, milites gaudent.*\n> 3. *Milites tam fortes sunt ut vincant.*\n\n**Lexique**\n- *puto* : je pense — *consul, consulis* (m.) : le consul ; *consulem* est l'accusatif — *venire* : venir (infinitif)\n- *urbs, urbis* (f.) : la ville ; *urbe* est l'ablatif — *capta* : participe parfait passif de *capere*, prendre\n- *miles, militis* (m.) : le soldat ; *milites* est le nominatif pluriel — *gaudent* : ils se réjouissent\n- *tam* : si, tellement — *fortes* : courageux — *sunt* : ils sont — *vincant* : subjonctif présent de *vincere*, vaincre (3e pers. du pluriel)\n\n1. Phrase 1 : quelle construction ? Justifie et traduis.\n2. Phrase 2 : nomme la construction de *urbe capta*, dis pourquoi il ne faut pas la traduire mot à mot, et traduis la phrase.\n3. Phrase 3 : *ut* + subjonctif exprime-t-il ici le **but** ou la **conséquence** ? Justifie et traduis.","bareme":[{"critere":"Phrase 1 : proposition infinitive reconnue (verbe de pensée, accusatif + infinitif) et bien traduite","points":6},{"critere":"Phrase 2 : ablatif absolu reconnu et rendu par un complément circonstanciel","points":6},{"critere":"Phrase 3 : conséquence justifiée par tam dans la principale, traduction « si… que »","points":6},{"critere":"Français correct dans les trois traductions","points":2}],"dureeMin":12,"corrige":"1. **Proposition infinitive** : *puto* est un verbe de **pensée** ; il est suivi d'un **accusatif** (*consulem*) et d'un **infinitif** (*venire*). Il ne faut pas chercher de COD mais une subordonnée. Traduction : « **Je pense que le consul vient.** »\n2. *Urbe capta* est un **ablatif absolu** : un nom (*urbe*) et un participe (*capta*) à l'ablatif, **sans lien grammatical** avec la principale (*milites gaudent*). Le mot à mot (« la ville ayant été prise ») sonne faux : le français le rend par un complément circonstanciel. Traduction : « **Après la prise de la ville, les soldats se réjouissent.** »\n3. **Conséquence** : l'adverbe *tam* (« si ») **annonce** la subordonnée dans la principale ; pour le but, rien ne l'annoncerait. Traduction : « **Les soldats sont si courageux qu'ils sont vainqueurs** » (ou « qu'ils vainquent »)."}$exo$::jsonb),
  ('17840e75-285b-5a4f-8200-93ae94fce9fa'::uuid, 3, 'traduction', $exo${"titre":"Le récit d'une victoire","consigne":"Analyse chaque construction, justifie ton identification, puis propose une traduction complète en bon français.","enonce":"**Texte**\n\n> *Hostibus victis, Caesar dicit Romam liberam esse. Milites tam fortes erant ut urbem caperent. Cum Marcus aeger esset, non venit.*\n\n**Lexique**\n- *hostis, hostis* (m.) : l'ennemi ; *hostibus* est l'ablatif pluriel — *victis* : participe parfait passif de *vincere*, vaincre (ablatif pluriel)\n- *dicit* : il dit — *Roma, ae* (f.) : Rome ; *Romam* est l'accusatif — *liberam* : libre (accusatif) — *esse* : être (infinitif)\n- *miles, militis* (m.) : le soldat — *tam* : si — *fortes* : courageux — *erant* : ils étaient\n- *urbem* : accusatif de *urbs*, la ville — *caperent* : subjonctif imparfait de *capere*, prendre (3e pers. du pluriel)\n- *cum* : conjonction — *aeger* : malade — *esset* : subjonctif imparfait de *esse* — *non venit* : il n'est pas venu\n\n1. Nomme et justifie la construction de *Hostibus victis*, puis celle de *Romam liberam esse*.\n2. Dans la deuxième phrase, *ut* + subjonctif exprime-t-il le but ou la conséquence ? Justifie.\n3. Dans la troisième phrase, que peut exprimer *cum* + subjonctif ? Quel sens retiens-tu ici, et pourquoi ?\n4. Traduis tout le texte.","bareme":[{"critere":"Hostibus victis : ablatif absolu justifié (nom + participe à l'ablatif, sans lien grammatical)","points":4},{"critere":"Romam liberam esse : proposition infinitive après verbe de parole, accusatif + infinitif","points":4},{"critere":"Ut de conséquence justifié par tam dans la principale","points":4},{"critere":"Cum + subjonctif : circonstance, cause ou opposition ; cause retenue et justifiée par le contexte","points":3},{"critere":"Traduction complète, juste, sans mot à mot pour l'ablatif absolu","points":5}],"dureeMin":18,"corrige":"1. *Hostibus victis* : **ablatif absolu**, un nom (*hostibus*) et un participe parfait passif (*victis*) à l'ablatif, **sans lien grammatical** avec la principale ; mot à mot « les ennemis ayant été vaincus », à rendre par un complément circonstanciel (« après la défaite des ennemis », « une fois les ennemis vaincus »). *Romam liberam esse* : **proposition infinitive** après *dicit*, verbe de **parole** : sujet à l'**accusatif** (*Romam*), verbe à l'**infinitif** (*esse*), attribut accordé (*liberam*). On ne cherche pas de COD mais une subordonnée : « que Rome est libre ».\n2. **Conséquence** : *tam* (« si ») dans la principale **annonce** la subordonnée. Pour un but, rien ne serait annoncé.\n3. *Cum* + subjonctif peut exprimer la **circonstance**, la **cause** ou l'**opposition** ; c'est le **contexte** qui tranche. Ici, la maladie de Marcus explique qu'il ne soit pas venu : sens de **cause** (« comme », « parce que »).\n4. **Traduction** : « **Après la défaite des ennemis, César dit que Rome est libre. Les soldats étaient si courageux qu'ils prirent la ville. Comme Marcus était malade, il n'est pas venu.** » (« une fois les ennemis vaincus » et « qu'ils s'emparèrent de la ville » sont acceptés)."}$exo$::jsonb),
  ('972e6722-ddbf-53e9-bd45-abda95f05477'::uuid, 1, 'traduction', $exo${"titre":"Les institutions de Rome","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu'est-ce que le *cursus honorum* ? Cite ses quatre étapes dans l'ordre.\n2. Pour le **Sénat**, les **comices** et les **tribuns de la plèbe**, dis qui y siège et quel est leur pouvoir.\n3. Que signifie **SPQR** et que dit cette formule ?\n4. Donne la date et l'événement : l'assassinat de César ; la fondation du principat.","bareme":[{"critere":"Cursus honorum défini, questure, édilité, préture, consulat dans l'ordre","points":5},{"critere":"Sénat, comices, tribuns : composition et pouvoir justes","points":7},{"critere":"SPQR développé et équilibre Sénat / peuple expliqué","points":4},{"critere":"15 mars 44 av. J.-C. et 27 av. J.-C. (Auguste)","points":4}],"dureeMin":7,"corrige":"1. Le *cursus honorum* est la **carrière des magistratures** romaines, parcourue dans un ordre fixe : **questure, édilité, préture, consulat**.\n2. **Sénat** : les anciens magistrats ; il donne l'orientation politique. **Comices** : le peuple assemblé ; ils votent les lois et élisent les magistrats. **Tribuns de la plèbe** : élus de la plèbe ; ils disposent du **droit de veto**.\n3. **SPQR** = *Senatus PopulusQue Romanus*, « le Sénat et le peuple romain » : la formule dit l'**équilibre revendiqué** entre le Sénat et le peuple.\n4. **15 mars 44 av. J.-C.** (les ides de mars) : César est assassiné. **27 av. J.-C.** : **Auguste** fonde le principat."}$exo$::jsonb),
  ('972e6722-ddbf-53e9-bd45-abda95f05477'::uuid, 2, 'traduction', $exo${"titre":"La République restaurée ?","consigne":"Lis le document, puis réponds aux questions en t'appuyant sur le cours.","enonce":"**Document – Auguste parle de lui-même** (*Res Gestae*, 34, traduction)\n\n> « Lors de mes sixième et septième consulats, après avoir éteint les guerres civiles, alors que j'étais maître de tout par le consentement universel, j'ai transféré la république de mon pouvoir à l'arbitrage du Sénat et du peuple romain. […] Depuis ce temps, j'ai surpassé tout le monde en autorité, mais je n'ai pas eu plus de pouvoir que ceux qui furent mes collègues dans chaque magistrature. »\n\n1. Replace ce texte dans la chronologie du cours : quelle crise précède, et quel régime Auguste fonde-t-il en 27 av. J.-C. ?\n2. Relève deux éléments du texte par lesquels Auguste affirme respecter les institutions républicaines.\n3. D'après le cours, que fait réellement l'Empire des formes républicaines ?\n4. Pourquoi le cours parle-t-il d'un « chef-d'œuvre de communication politique » à propos de la formule *Res publica restituta* ?","bareme":[{"critere":"Guerres civiles du Ier siècle av. J.-C. et principat fondé en 27 av. J.-C.","points":4},{"critere":"Deux éléments relevés (retour au Sénat et au peuple, magistratures, pas plus de pouvoir que ses collègues)","points":5},{"critere":"L'Empire garde les formes républicaines et en vide le contenu","points":5},{"critere":"Explication de la formule comme communication politique, texte lu avec recul critique","points":6}],"dureeMin":11,"corrige":"1. Au **Ier siècle av. J.-C.**, les **guerres civiles** minent la République ; César est assassiné le 15 mars 44 av. J.-C. En **27 av. J.-C.**, **Auguste** fonde le **principat**.\n2. Auguste dit avoir **transféré la république à l'arbitrage du Sénat et du peuple romain** (l'équilibre de *SPQR*) ; il se présente comme un **magistrat** parmi d'autres (consulats, collègues) et affirme **n'avoir pas eu plus de pouvoir** que ses collègues.\n3. L'Empire **garde les formes républicaines** (Sénat, magistratures, vocabulaire) **et en vide le contenu** : le pouvoir réel est concentré entre les mains d'Auguste.\n4. *Res publica restituta*, « la République restaurée », présente comme un retour à la tradition ce qui est en réalité un **changement de régime**. Auguste le dit lui-même : il a **surpassé tout le monde en autorité**. La formule rassure et légitime un pouvoir nouveau sous des apparences anciennes : c'est pourquoi le cours invite à la lire comme de la **communication politique**, et non comme une description fidèle."}$exo$::jsonb),
  ('972e6722-ddbf-53e9-bd45-abda95f05477'::uuid, 3, 'traduction', $exo${"titre":"Ce que Rome nous a laissé","consigne":"Rédige un développement organisé d'une vingtaine de lignes, appuyé sur des exemples précis du cours.","enonce":"**Sujet.** « Le Sénat et le peuple romain » : Rome se présentait comme une communauté de citoyens équilibrée.\n\nEn t'appuyant sur le cours, montre :\n1. comment les **institutions** de la République organisent cet équilibre revendiqué ;\n2. que la **société** romaine reste pourtant profondément inégalitaire et hiérarchisée (au moins trois notions) ;\n3. comment cet équilibre est vidé de son contenu au passage à l'**Empire** ;\n4. ce que Rome a malgré tout **légué** à nos sociétés.","bareme":[{"critere":"Institutions décrites avec précision : cursus honorum, Sénat, comices, tribuns et veto, SPQR","points":5},{"critere":"Au moins trois notions sociales justes (patriciens/plébéiens, patronus/cliens, esclavage, materfamilias, mos maiorum)","points":5},{"critere":"Passage à l'Empire daté et analysé (guerres civiles, 44 et 27 av. J.-C., formes gardées et vidées)","points":4},{"critere":"Héritage : droit romain, langues romanes, urbanisme, Cicéron, Tacite","points":4},{"critere":"Développement organisé et argumenté","points":2}],"dureeMin":20,"corrige":"1. **Les institutions** : la carrière politique suit le *cursus honorum* (questure, édilité, préture, consulat). Le **Sénat**, formé d'anciens magistrats, donne l'orientation politique ; les **comices**, le peuple assemblé, votent les lois et élisent ; les **tribuns de la plèbe**, élus de la plèbe, disposent d'un **droit de veto**. La formule *SPQR* (*Senatus PopulusQue Romanus*) dit cet **équilibre revendiqué** entre Sénat et peuple.\n2. **Une société hiérarchisée** : le corps civique est divisé entre **patriciens et plébéiens** ; le **clientélisme** (*patronus / cliens*) lie protection et soutien ; l'**esclavage** est massif, au cœur de l'économie et de la maison ; la **materfamilias** a un statut respecté mais **aucun droit politique** ; le **mos maiorum**, coutume des ancêtres, est la norme suprême et favorise la tradition.\n3. **Vers l'Empire** : au Ier siècle av. J.-C., les guerres civiles minent la République ; César est assassiné aux ides de mars (15 mars 44 av. J.-C.) ; en 27 av. J.-C., **Auguste** fonde le principat. L'Empire **garde les formes républicaines et en vide le contenu** ; la formule *Res publica restituta* est un chef-d'œuvre de communication politique.\n4. **L'héritage** : le **droit romain** irrigue nos codes civils ; le latin a donné les **langues romanes** ; l'**urbanisme** (forum, thermes, aqueducs) ; la rhétorique de **Cicéron** et l'historiographie de **Tacite** structurent notre manière d'argumenter et d'écrire l'histoire.\n\n**Conclusion attendue** : l'équilibre de *SPQR* est davantage revendiqué que réel, mais Rome a laissé des outils durables."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
