  RAISE NOTICE '404 : % sujets au catalogue (attendu : 357)', n;
  IF n < 357 THEN
    RAISE WARNING '404 : il manque des sujets — des fiches ont-elles changé d''identifiant ?';
  END IF;
END $$;
